#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Custom allocator to manage memory efficiently
void* custom_alloc(size_t size) {
    // Allocate memory using the system's default allocator
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Record structure with a single int value
typedef struct {
    int value;
} record;

// Function to create and persist records
int create_records(int num_records, char* filename) {
    // Initialize the arrays and the record array
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    // Allocate memory for the arrays and the record array
    if (!(offsets = (long*)custom_alloc(num_records * sizeof(long)))) return 1;
    if (!(keys = (int*)custom_alloc(num_records * sizeof(int)))) return 1;
    if (!(records = (record*)custom_alloc(num_records * sizeof(record)))) return 1;

    // Initialize the arrays and the record array
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100; // Random value within a specified range
    }

    // Write the records to the file-based database
    FILE* file = fopen(filename, "wb");
    if (!file) return 1;

    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }

    fclose(file);

    // Free the allocated memory
    custom_free(offsets);
    custom_free(keys);
    custom_free(records);

    return 0;
}

int main() {
    srand(time(NULL)); // Initialize random number generation

    int num_records = 10000; // Number of records to create
    char* filename = "records.dat"; // File-based database name

    if (create_records(num_records, filename)) {
        printf("Error creating and persisting records.\n");
    } else {
        printf("Records created and persisted successfully.\n");
    }

    return 0;
}
