#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LINES 10000

int main(int argc, char **argv) {
    int opt;
    bool count = false;
    bool stats = false;
    bool output = false;
    bool manpage = false;
    FILE *output_file = NULL;
    const char *log_level = "INFO";

    while ((opt = getopt(argc, argv, "cs:o:m:l:")) != -1) {
        switch (opt) {
            case 'c':
                count = true;
                break;
            case 's':
                stats = true;
                break;
            case 'o':
                output_file = fopen(optarg, "w");
                if (!output_file) {
                    fprintf(stderr, "Error opening file for writing\n");
                    return 1;
                }
                output = true;
                break;
            case 'm':
                manpage = true;
                break;
            case 'l':
                log_level = optarg;
                break;
        }
    }

    if (!strcmp(argv[optind], "-h") || !strcmp(argv[optind], "--help")) {
        printf("Usage: %s [-c|--count] [-s|--stats] [-o|--output file] [-m|--manpage] [--log-level level]\n", argv[0]);
        return 0;
    }

    if (!argv[optind + 1]) {
        fprintf(stderr, "Error: No input file specified\n");
        return 1;
    }

    FILE *input_file = fopen(argv[optind + 1], "r");
    if (!input_file) {
        fprintf(stderr, "Error opening file for reading\n");
        return 1;
    }

    unsigned int lines = 0;
    unsigned int words = 0;
    unsigned long long chars = 0;

    char line[MAX_LINES * sizeof(char)];
    while (fgets(line, MAX_LINES * sizeof(char), input_file) && lines < MAX_LINES) {
        chars += strlen(line);
        if (!strchr(line, '\n')) {
            // handle non-terminated lines
            chars++;
        }
        words += count_words(line);
        lines++;
    }

    fclose(input_file);

    if (output_file) {
        fprintf(output_file, "Total Lines: %u\n", lines);
        fprintf(output_file, "Total Words: %u\n", words);
        fprintf(output_file, "Total Characters: %llu\n", chars);
        if (stats) {
            fprintf(output_file, "Statistics:\n");
            fprintf(output_file, "\tLines: %u\n", lines);
            fprintf(output_file, "\tWords: %u\n", words);
            fprintf(output_file, "\tCharacters: %llu\n", chars);
        }
    } else {
        printf("Total Lines: %u\n", lines);
        printf("Total Words: %u\n", words);
        printf("Total Characters: %llu\n", chars);
        if (stats) {
            printf("Statistics:\n");
            printf("\tLines: %u\n", lines);
            printf("\tWords: %u\n", words);
            printf("\tCharacters: %llu\n", chars);
        }
    }

    fclose(output_file);

    return 0;
}

unsigned int count_words(const char *str) {
    unsigned int count = 0;
    while (*str != '\0') {
        if (*str == ' ' || *str == '\n' || *str == '\t') {
            if (*(str + 1) != ' ' && *(str + 1) != '\n' && *(str + 1) != '\t') {
                count++;
            }
            str += 1;
        } else {
            str += 1;
        }
    }
    return count;
}
