#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_HOSTS 100
#define MAX_LOGS 100

typedef struct {
    char hostname[50];
    char log_path[200];
} Config;

Config config[MAX_HOSTS];

void *parse_config_file(void *arg) {
    FILE *file = (FILE *)arg;
    int i = 0;
    while(fscanf(file, "%49s %199s", config[i].hostname, config[i].log_path) == 2) {
        i++;
    }
    return NULL;
}

void *append_to_log_file(void *arg) {
    Config *config_ptr = (Config *)arg;
    FILE *file = fopen(config_ptr->log_path, "a");
    if(file != NULL) {
        struct hostent *host_entry;
        struct in_addr ip;
        int status = gethostbyname(config_ptr->hostname, strlen(config_ptr->hostname), 0, &host_entry, (struct sockaddr_in *)&ip);
        if(status == 0) {
            char buffer[20];
            inet_ntop(AF_INET, &(host_entry->h_addr), buffer, sizeof(buffer));
            fprintf(file, "%s\n", buffer);
        } else {
            fprintf(file, "Failed to resolve %s: %s\n", config_ptr->hostname, strerror(errno));
        }
        fclose(file);
    } else {
        printf("Error opening log file: %s\n", strerror(errno));
    }
}

int main() {
    pthread_t threads[100];
    FILE *file = fopen("config.txt", "r");
    if(file != NULL) {
        int i = 0;
        parse_config_file(&file);
        for(i = 0; i < MAX_HOSTS && config[i].hostname[0] != '\0'; i++) {
            pthread_create(&threads[i], NULL, append_to_log_file, &config[i]);
        }
        for(i = 0; i < MAX_HOSTS; i++) {
            pthread_join(threads[i], NULL);
        }
        fclose(file);
    } else {
        printf("Error opening config file: %s\n", strerror(errno));
    }
    return 0;
}
