#include <string.h>

int largest_integer_in_file(char *filename) {
    int min_range = atoi(argv[3]);
    int max_range = atoi(argv[4]);

    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return 1;
    }

    long num_entries = 0;
    size_t array_size = 0;
    int *array = NULL;

    while (fscanf(file, "%d\n", &i) == 1) {
        if (i >= min_range && i <= max_range) {
            if (num_entries >= array_size) {
                array_size *= 2;
                array = realloc(array, array_size * sizeof(int));
            }
            if (array[num_entries++] != i) { // ignore duplicate entries
                array[num_entries - 1] = i;
            }
        } else {
            while (fscanf(file, "%d\n", &i) == 1 && i < min_range || i > max_range);
        }
    }

    fclose(file);

    if (num_entries > 0) {
        int largest = array[0];
        for (int i = 1; i < num_entries; i++) {
            if (array[i] > largest)
                largest = array[i];
        }
        printf("Largest integer in file: %d\n", largest);
    } else {
        printf("No valid integers found.\n");
    }

    free(array);
    return 0;
}
