#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define LOG_MAX_SIZE 1024
#define LOG_FLUSH_INTERVAL 10 // seconds
#define MAX_LOG_LEVELS 5
#define DEBUG 0
#define INFO 1
#define WARN 2
#define ERROR 3

typedef enum {
    OFF,
    DEBUG,
    INFO,
    WARN,
    ERROR
} log_level;

typedef struct {
    char message[LOG_MAX_SIZE];
    time_t timestamp;
    int level;
} log_entry;

log_entry* logs = NULL;
int log_count = 0;
FILE* log_file = NULL;

void init_log(void) {
    if (logs == NULL) {
        logs = malloc(sizeof(log_entry*) * LOG_MAX_SIZE);
        log_file = fopen("log.txt", "w");
        if (log_file == NULL)
            perror("Error opening log file");
    }
}

void log_message(int level, const char* format, ...) {
    va_list args;
    va_start(args, format);

    log_entry* entry = &logs[log_count++ % LOG_MAX_SIZE];
    strcpy(entry->message, format);
    vsprintf(entry->message + strlen(entry->message), format, args);
    entry->timestamp = time(NULL);
    entry->level = level;

    if (log_file) {
        fprintf(log_file, "%s [%s] - %s\n", 
            ctime(&entry->timestamp), log_level_to_string(level), entry->message);
        fflush(log_file);

        if (++log_count > LOG_MAX_SIZE)
            rotate_logs();
    }
}

void rotate_logs(void) {
    FILE* temp_file = fopen("log.txt.temp", "w");
    if (temp_file == NULL)
        perror("Error opening temporary log file");

    int i;
    for (i = 0; i < log_count - LOG_MAX_SIZE; i++) {
        fprintf(temp_file, "%s\n", logs[i]->message);
        free(logs[i]);
    }

    fclose(temp_file);

    rename("log.txt.temp", "log.txt");
}

const char* log_level_to_string(int level) {
    switch (level) {
    case DEBUG:
        return "DEBUG";
    case INFO:
        return "INFO";
    case WARN:
        return "WARNING";
    case ERROR:
        return "ERROR";
    default:
        return "UNKNOWN";
    }
}

void flush_logs(void) {
    fflush(log_file);
}
