#include <openssl/ssl.h>
#include <openssl/aes.h>
#include <stdio.h>

void* cipher_init(const char *mode, const char *padding) {
    EVP_CIPHER_CTX *ctx;
    switch (strcmp(mode, "CBC")) {
        case 0:
            ctx = EVP_CIPHER_CTX_new();
            EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
            break;
        case 1: // GCM
            ctx = EVP_CIPHER_CTX_new();
            EVP_CipherInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL);
            break;
        case 2: // CTR
            ctx = EVP_CIPHER_CTX_new();
            EVP_CipherInit_ex(ctx, EVP_aes_256_ctr(), NULL, NULL, NULL);
            break;
        default:
            return NULL; // invalid mode
    }
    switch (strcmp(padding, "PKCS#7")) {
        case 0:
            EVP_CipherPadding_set(ctx, EVP_PADDING_PKCS7);
            break;
        default:
            return NULL; // invalid padding
    }
    return ctx;
}

void cipher_free(void *ctx) {
    if (!ctx) return;
    EVP_CIPHER_CTX_free((EVP_CIPHER_CTX*) ctx);
}

int main() {
    void *cipher = cipher_init("GCM", "PKCS#7");
    if (!cipher) printf("Error initializing cipher.\n");
    else {
        // Use the initialized cipher
        cipher_free(cipher);
    }
}
