import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;
import java.util.stream.Collectors;

public String generateReport(Pokemon pokemon) {
    StringBuilder report = new StringBuilder();

    // Retrieve the Pokemon's name from an external API endpoint
    HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("https://pokemon-api.com/pokemon/name"))
            .header("Content-Type", "application/json")
            .build();
    HttpClient client = HttpClient.newHttpClient();
    int retryCount = 0;
    while (true) {
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() == 200) {
                pokemon.setName(response.body());
                break;
            } else if (retryCount < 3) {
                // Exponential backoff for retry
                try {
                    Thread.sleep((int) Math.pow(2, retryCount) * 1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                retryCount++;
            } else {
                throw new RuntimeException("Failed to retrieve Pokémon name after 3 retries");
            }
        } catch (IOException | InterruptedException e) {
            // Handle network errors
            if (retryCount < 3) {
                try {
                    Thread.sleep((int) Math.pow(2, retryCount) * 1000);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                retryCount++;
            } else {
                throw new RuntimeException("Failed to retrieve Pokémon name after 3 retries");
            }
        }
    }

    // Determine the weaknesses, resistances, and immunities based on the Pokemon's types
    report.append("Pokémon Name: ").append(pokemon.getName()).append("\n");
    for (String type : pokemon.getTypes()) {
        switch (type) {
            case "Fire":
                report.append("Weaknesses: Fire\n").append("Resistances: Water, Grass\n").append("Immunities: None\n");
                break;
            // Add more cases for other Pokémon types
            default:
                report.append("Unknown Type: ").append(type).append("\n");
        }
    }

    return report.toString();
}
