#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    void* module;
} Algorithm;

void** algorithms = NULL;
int algorithm_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Algorithm get_algorithm(const char* name) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < algorithm_count; i++) {
        if (strcmp(algorithms[i]->name, name) == 0) {
            Algorithm algo = *algorithms[i];
            pthread_mutex_unlock(&mutex);
            return algo;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void load_algorithms(const char* directory) {
    // Load built-in algorithms
    // ...

    // Dynamically load modules from the specified directory
    DIR* dir = opendir(directory);
    if (dir != NULL) {
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

            // Load the module and add it to the list
            void* module = dlopen(directory, RTLD_LAZY);
            Algorithm algo;
            algo.name = ent->d_name;
            algo.module = module;
            algorithms = (void**)realloc(algorithms, (algorithm_count + 1) * sizeof(void*));
            algorithms[algorithm_count++] = &algo;

            dlclose(module); // Decrement the module reference count
        }
        closedir(dir);
    }

    // Sort the list of algorithms by priority and name
}

void unload_algorithms() {
    for (int i = 0; i < algorithm_count; i++) {
        dlclose(algorithms[i]->module);
    }
    free(algorithms);
}

