#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define POOL_SIZE 1000
#define MAX_CONCURRENT_THREADS 500
#define LOGGING_ENABLED 1

typedef struct {
    int count;
    pthread_mutex_t mutex;
} resource_pool_t;

resource_pool_t pool = {POOL_SIZE, PTHREAD_MUTEX_INITIALIZER};

void init_resource_pool(resource_pool_t* p) {
    if (p->count < POOL_SIZE) {
        printf("Pool initialization failed. Insufficient resources.\n");
        exit(-1);
    }
}

int allocate_resource(resource_pool_t* p) {
    int result = -1;
    pthread_mutex_lock(&p->mutex);
    if (p->count > 0) {
        p->count--;
        result = 1;
    } else {
        printf("Resource allocation failed. Pool exhausted.\n");
    }
    pthread_mutex_unlock(&p->mutex);
    return result;
}

int deallocate_resource(resource_pool_t* p) {
    int result = -1;
    pthread_mutex_lock(&p->mutex);
    if (p->count < POOL_SIZE) {
        p->count++;
        result = 1;
    } else {
        printf("Resource deallocation failed. Pool full.\n");
    }
    pthread_mutex_unlock(&p->mutex);
    return result;
}

void destroy_resource_pool(resource_pool_t* p) {
    if (p->count > 0) {
        printf("Pool destruction failed. Insufficient resources left.\n");
        exit(-1);
    }
}

int get_available_resources(const resource_pool_t* p) {
    return p->count;
}

void* thread_function(void* arg) {
    int allocated = -1;
    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        if (allocate_resource(&pool) == 1) {
            printf("Resource allocated.\n");
            allocated = 1;
            break;
        }
    }
    if (allocated) {
        // Perform operations on the resource
        for (int j = 0; j < 10; j++) {
            printf("Operation %d executed successfully.\n", j);
        }
        deallocate_resource(&pool);
        printf("Resource deallocated.\n");
    } else {
        printf("Allocation failed. Exiting thread.\n");
    }
    return NULL;
}

int main() {
    int threads = MAX_CONCURRENT_THREADS;
    pthread_t* threads_array = (pthread_t*)malloc(threads * sizeof(pthread_t));

    for (int i = 0; i < threads; i++) {
        pthread_create(&threads_array[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < threads; i++) {
        pthread_join(threads_array[i], NULL);
    }

    destroy_resource_pool(&pool);

    return 0;
}

