use json::{JsonValue, error::Error as JsonError};
use std::{fs::File, io::Write, path::PathBuf};

#[derive(Debug)]
struct Config {
    // Add new config options here:
    foo: String,
    bar: u32,
}

impl Config {
    fn from_json(json: &JsonValue) -> Result<Self, JsonError> {
        let foo = json.get("foo").and_then(|v| v.as_str()).map_or_else(|| Err(JsonError::new("missing 'foo' field")), |s| Ok(s.to_string()));
        let bar = json.get("bar").and_then(|v| v.as_u64()).map_or_else(|| Err(JsonError::new("missing 'bar' field")), |u| Ok(u as u32));

        foo.and_then(|f| bar.map(move |b| Config { foo: f, bar: b }))
    }
}

#[derive(Debug)]
enum LogLevel {
    Error,
    Warning,
    Info,
    Debug,
}

impl Default for LogLevel {
    fn default() -> Self {
        LogLevel::Error
    }
}

struct Compiler {
    config: Config,
    log_level: LogLevel,
}

impl Compiler {
    fn new(path: &str) -> Result<Self, std::io::Error> {
        let mut file = File::open(PathBuf::from(path))?;
        let mut contents = String::new();
        file.read_to_string(&mut contents)?;
        let json = JsonValue::from_str(&contents).map_err(|e| e.into())?;
        let config = Config::from_json(&json)?;
        let log_level = LogLevel::default();

        Ok(Compiler { config, log_level })
    }

    fn compile(&self) {
        // Implementation left out for brevity
    }
}

fn main() {
    let mut compiler = Compiler::new("path/to/config.json").unwrap();
    compiler.compile();
}
