#include "sandesh.pb.h"

class SandeshClient {
public:
    SandeshClient(const std::string& endpoint) : endpoint_(endpoint), connected_(false) {}

    void setRequestHeaders(const std::map<std::string, std::string>& headers) { request_headers_ = headers; }

    void setTimeout(int timeout) { timeout_ = timeout; }

    bool connect() {
        if (connected_) return true;
        // Establish connection to the external API service
        connected_ = true;
        return connected_;
    }

    void disconnect() {
        if (!connected_) return;
        // Close the connection to the external API service
        connected_ = false;
    }

    void sendRequest(const std::string& request_data) {
        if (!connect()) return;

        auto request = SandeshRequest::parse(request_data);

        if (request) {
            // Send the request asynchronously
            std::thread([this, request]() {
                sendRequestAsync(*request);
            }).detach();

            // Check for timeout
            if (timeout_) {
                std::this_thread::sleep_for(std::chrono::milliseconds(timeout_));
                if (!connect()) return;
            }

            // Wait for the response
            waitResponse();
        }
    }

private:
    void sendRequestAsync(const SandeshRequest& request) {
        try {
            // Send the request to the external API service
            // ...
        } catch (const std::exception& e) {
            handleRequestError(e);
        }
    }

    void waitResponse() {
        std::unique_lock<std::mutex> lock(mutex_);
        cond_.wait(lock, [this]() { return connected_; });
        lock.unlock();
    }

    void handleRequestError(const std::exception& e) {
        // Handle request error
        // ...
    }

private:
    std::string endpoint_;
    std::map<std::string, std::string> request_headers_;
    int timeout_;
    bool connected_;
    std::mutex mutex_;
    std::condition_variable cond_;
};

int main() {
    SandeshClient client("https://example.com/api");

    // Set the request headers
    client.setRequestHeaders({{"X-API-KEY", "your_api_key"} });

    // Set the timeout
    client setTimeout(500);

    // Send a request
    std::string request_data = "...";
    client.sendRequest(request_data);

    return 0;
}
