using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

public async Task<(List<ProcessedItem>, PaginationMetadata)> ProcessPaginatedDataAsync(
    string query,
    SqlConnection connection,
    int pageNumber,
    int pageSize,
    Func<Item, bool> filter = null)
{
    var items = new List<ProcessedItem>();
    var totalRecords = 0;

    try
    {
        using (var command = new SqlCommand(query, connection))
        {
            command.CommandType = System.Data.CommandType.Text;

            // Add filtering logic if a predicate is provided
            if (filter != null)
            {
                command.Parameters.AddWithValue("@Filter", filter);
            }

            // Set pagination parameters
            command.Parameters.AddWithValue("@PageNumber", pageNumber);
            command.Parameters.AddWithValue("@PageSize", pageSize);

            using (var reader = await command.ExecuteReaderAsync())
            {
                while await reader.ReadAsync())
                {
                    var item = new ProcessedItem();
                    // Process the item data here...
                    items.Add(item);
                }

                totalRecords = (int)reader RecordsAffected;
            }
        }
    }
    catch (Exception ex)
    {
        // Handle exceptions and failures gracefully
        // Log errors, raise notifications, or retry operations as needed
    }

    var paginationMetadata = new PaginationMetadata(totalRecords, pageNumber, pageSize);

    return (items, paginationMetadata);
}
