import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/resources")
public class ResourceController {

    @Value("${cache.enabled:true}")
    private boolean cacheEnabled;

    private final ResourceRepository resourceRepository;
    private final MessageBroker messageBroker;
    private final DistributedCache distributedCache;

    public ResourceController(ResourceRepository resourceRepository, 
                               MessageBroker messageBroker, 
                               DistributedCache distributedCache) {
        this.resourceRepository = resourceRepository;
        this.messageBroker = messageBroker;
        this.distributedCache = distributedCache;
    }

    @GetMapping
    public List<Resource> getResources() {
        return resourceRepository.findAll();
    }

    @PostMapping
    public Resource createResource(@RequestBody Resource resource) {
        return resourceRepository.save(resource);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Resource> updateResource(@PathVariable Long id, 
                                                      @RequestBody JsonPatch patch) {
        Optional<Resource> existingResource = resourceRepository.findById(id);

        if (existingResource.isPresent()) {
            Resource resourceToUpdate = existingResource.get();
            PatchApplier.apply(patch, resourceToUpdate);

            // Cache the updated resource
            distributedCache.put(id, resourceToUpdate);

            return ResponseEntity.ok(resourceToUpdate);
        } else {
            return ResponseEntity.notFound().build();
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteResource(@PathVariable Long id) {
        if (resourceRepository.existsById(id)) {
            // Remove the resource from cache
            distributedCache.remove(id);

            resourceRepository.deleteById(id);

            return ResponseEntity.noContent().build();
        } else {
            return ResponseEntity.notFound().build();
        }
    }

    @PostMapping("/batch")
    public void batchUpdateResources(@RequestBody List<BatchUpdateRequest> requests) {
        messageBroker.send(requests);
    }
}
