using System.Xml.XPath;

public class DirectoryManager
{
    public static List<string> ProcessDirectoryAndEnvironment(string directoryName, string xmlString, string elementName)
    {
        // Initialize logger and XPathDocument
        var logger = new Logger();
        var document = new XmlDocument();
        document.LoadXml(xmlString);

        try
        {
            // Find the first matching element in the XML
            var element = document.SelectNodes($"//{elementName}").FirstOrDefault();

            if (element == null)
            {
                // Create a new directory if no matching element is found
                Directory.CreateDirectory(directoryName);
                logger.Log("Directory created successfully");

                // Update environment variable with the same name as the directory
                Environment.SetEnvironmentVariable(directoryName, Path.Combine(Environment.CurrentDirectory, directoryName));
                logger.Log($"Environment variable '{directoryName}' updated successfully");
            }
            else
            {
                // Get a list of paths corresponding to each matching element
                var paths = (from XmlNode node in document.SelectNodes($"//{elementName}") select node.InnerText).ToList();
                return paths;
            }
        }
        catch (Exception ex)
        {
            logger.LogError("Error occurred while processing directory and environment", ex);
            throw;
        }
    }
}

public class Logger
{
    public void Log(string message)
    {
        // Implement logging mechanism here
        Console.WriteLine(message);
    }

    public void LogError(string message, Exception ex)
    {
        // Implement error logging mechanism here
        Console.WriteLine($"Error: {message} - {ex.Message}");
    }
}
