import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class Md5HashUtility {
    private static final int MAX_HASH_LENGTH = 32;
    private static final String ALGORITHM_MD5 = "MD5";
    private static final String DEFAULT_MAX_HASH_LENGTH = "32";

    private boolean debugLoggingEnabled;
    private Integer maxHashLength;

    public Md5HashUtility() {
        this.debugLoggingEnabled = false;
        this.maxHashLength = Integer.parseInt(DEFAULT_MAX_HASH_LENGTH);
    }

    public Md5HashUtility(boolean debugLoggingEnabled, int maxHashLength) {
        this.debugLoggingEnabled = debugLoggingEnabled;
        this.maxHashLength = maxHashLength;
    }

    public String process(String... inputs) throws Exception {
        List<byte[]> hashInputs = new ArrayList<>();
        for (String input : inputs) {
            byte[] inputBytes = input.getBytes();
            MessageDigest md5 = getMessageDigest();
            byte[] hashInput = md5.digest(inputBytes);
            hashInputs.add(hashInput);
        }

        String concatenatedHash;
        try {
            concatenatedHash = bytesToHexString(mergeHashes(hashInputs));
        } catch (Exception e) {
            throw new Exception("Failed to generate MD5 hash: " + e.getMessage(), e);
        }

        if (concatenatedHash.length() > maxHashLength) {
            concatenatedHash = truncateHash(concatenatedHash);
        }

        return concatenatedHash;
    }

    private MessageDigest getMessageDigest() throws NoSuchAlgorithmException {
        // Add your version validation checks here
        // For example, using an external data source:
        // VersionChecker checker = new VersionChecker();
        // int requiredVersion = checker.getVersion();
        // while (requiredVersion < 1.2) {
        //     // Perform retry logic with exponential backoff
        // }
        return MessageDigest.getInstance(ALGORITHM_MD5);
    }

    private byte[] mergeHashes(List<byte[]> hashInputs) throws Exception {
        MessageDigest md5 = getMessageDigest();
        for (byte[] input : hashInputs) {
            md5.update(input);
        }
        return md5.digest();
    }

    private String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private String truncateHash(String hash) {
        // Implement your custom logic to trim the hash while preserving uniqueness
        // For example, using a rolling checksum:
        int rollingChecksum = 0;
        for (int i = 0; i < Math.min(hash.length(), maxHashLength); i++) {
            rollingChecksum += (hash.charAt(i) & 0xff);
        }
        return hash.substring(rollingChecksum % hash.length());
    }

    public static void main(String[] args) {
        Md5HashUtility utility = new Md5HashUtility(true, Integer.parseInt("32"));
        String concatenatedHash;
        try {
            concatenatedHash = utility.process("input1", "input2", "input3");
            System.out.println(concatenatedHash);
        } catch (Exception e) {
            // Handle the exception
        }
    }
}
