function processUserRequest() {
    $request = $_REQUEST;
    $subAction = $request['sub_action'];
    $id = (isset($request['id'])) ? $request['id'] : null;
    $name = (isset($request['name'])) ? $request['name'] : null;
    $email = (isset($request['email'])) ? $request['email'] : null;
    $password = (isset($request['password'])) ? $request['password'] : null;
    $page = (isset($request['page'])) ? $request['page'] : 1;
    $limit = (isset($request['limit'])) ? $request['limit'] : 10;

    switch ($subAction) {
        case 'create':
            if (!isset($name) || !isset($email)) {
                return json_encode(array('status' => 'error', 'message' => 'Name and email are required'));
            }
            if (strlen($name) > 50) {
                return json_encode(array('status' => 'error', 'message' => 'Name must be 50 characters or less'));
            }
            if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
                return json_encode(array('status' => 'error', 'message' => 'Invalid email format'));
            }
            if (getUserByEmail($email) !== false) {
                return json_encode(array('status' => 'error', 'message' => 'Email already exists'));
            }
            $stmt = db()->prepare("INSERT INTO users SET name = ?, email = ?, password = ?");
            $stmt->execute(array($name, $email, $password));
            break;
        case 'update':
            if (!isset($id)) {
                return json_encode(array('status' => 'error', 'message' => 'ID is required'));
            }
            if (!isset($name) && !isset($email) && !isset($password)) {
                return json_encode(array('status' => 'error', 'message' => 'At least one field must be updated'));
            }
            $stmt = db()->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
            if ($stmt->execute(array($name, $email, $password, $id))) {
                return json_encode(array('status' => 'success', 'message' => 'User updated'));
            } else {
                return json_encode(array('status' => 'error', 'message' => 'Error updating user'));
            }
        case 'delete':
            if (!isset($id)) {
                return json_encode(array('status' => 'error', 'message' => 'ID is required'));
            }
            $stmt = db()->prepare("UPDATE users SET deleted_at = NOW() WHERE id = ?");
            if ($stmt->execute(array($id))) {
                return json_encode(array('status' => 'success', 'message' => 'User deleted'));
            } else {
                return json_encode(array('status' => 'error', 'message' => 'Error deleting user'));
            }
        default:
            return json_encode(array('status' => 'error', 'message' => 'Invalid sub-action'));
    }

    $stmt = db()->prepare("SELECT * FROM users LIMIT ?, ?");
    if ($stmt->execute(array(($page - 1) * $limit, $limit))) {
        $users = $stmt->fetchAll();
        return json_encode(array('status' => 'success', 'message' => 'Users retrieved', 'data' => $users));
    } else {
        return json_encode(array('status' => 'error', 'message' => 'Error retrieving users'));
    }
}
