public MoSTState loadMoSTStateFromDisk(String filePath) {
    ObjectInputStream ois = null;
    try {
        File file = new File(filePath);
        if (file.exists() && file.isFile()) {
            ois = new ObjectInputStream(new FileInputStream(file));
            return (MoSTState) ois.readObject();
        }
    } catch (IOException | ClassNotFoundException e) {
        // Handle error
        System.out.println("Error loading MoST state from disk: " + e.getMessage());
    } finally {
        if (ois != null) {
            try {
                ois.close();
            } catch (IOException ignored) {}
        }
    }
    return null;
}
