public class UserManager : IdentityUserManager<IdentityUser>
{
    private readonly IUserLockoutService _userLockoutService;
    private readonly IAuthenticationService _authenticationService;
    private readonly ICachingService _cachingService;
    private readonly IRoleService _roleService;
    private readonly IPassRecoveryService _passRecoveryService;

    public UserManager(IUserStore<IdentityUser> userStore, 
                       IUoWFactory uowFactory, 
                       IUserLockoutService userLockoutService,
                       IAuthenticationService authenticationService, 
                       ICachingService cachingService, 
                       IRoleService roleService, 
                       IPassRecoveryService passRecoveryService)
        : base(userStore, uowFactory)
    {
        _userLockoutService = userLockoutService;
        _authenticationService = authenticationService;
        _cachingService = cachingService;
        _roleService = roleService;
        _passRecoveryService = passRecoveryService;
    }

    public async Task<IActionResult> LoginAsync(LoginModel model)
    {
        if (!ModelState.IsValid) return BadRequest(ModelState);

        var user = await UserStore.FindByNameAsync(model.Username);
        if (user == null || !await UserStore.VerifyPasswordAsync(user, model.Password))
            throw new Exception("Invalid username or password");

        var authenticationResult = await _authenticationService.SignInAsync(user);
        if (!authenticationResult.Succeeded)
            throw new Exception(authenticationResult.Reason);

        return RedirectToAction("Index", "Home");
    }

    public async Task<IActionResult> RegisterAsync(RegisterModel model)
    {
        if (!ModelState.IsValid) return BadRequest(ModelState);

        var user = await UserStore.FindByNameAsync(model.Username);
        if (user != null) throw new Exception("Username already exists");

        var passwordValidator = new PasswordValidator();
        if (!passwordValidator.Validate(model.Password)) 
            throw new Exception("Password is not valid");

        await UserStore.CreateAsync(new IdentityUser { Username = model.Username, Email = model.Email });
        await UserStore.AddToRoleAsync(await UserStore.FindByNameAsync(model.Username), "DefaultRole");
    }

    public async Task<IActionResult> LoginGoogleAsync(LoginModel model)
    {
        var googleOptions = new GoogleAuthenticationOptions();
        if (!await _authenticationService.SignInWithGoogleAsync(googleOptions, model))
            throw new Exception("Failed to login with Google");

        return RedirectToAction("Index", "Home");
    }

    public async Task<IActionResult> LoginFacebookAsync(LoginModel model)
    {
        var facebookOptions = new FacebookAuthenticationOptions();
        if (!await _authenticationService.SignInWithFacebookAsync(facebookOptions, model))
            throw new Exception("Failed to login with Facebook");

        return RedirectToAction("Index", "Home");
    }

    public async Task<IActionResult> ChangePasswordAsync(ChangePasswordModel model)
    {
        var user = await UserStore.FindByNameAsync(User.Identity.Name);
        if (!await UserStore.ChangePasswordAsync(user, model.OldPassword, model.NewPassword))
            throw new Exception("Failed to change password");

        return RedirectToAction("Index", "Home");
    }

    public async Task<IActionResult> UpdateProfileAsync(UpdateProfileModel model)
    {
        var user = await UserStore.FindByNameAsync(User.Identity.Name);
        if (!await UserStore.UpdateAsync(user, model.Username, model.Email))
            throw new Exception("Failed to update profile");

        return RedirectToAction("Index", "Home");
    }

    public async Task<IActionResult> LogoutAsync()
    {
        await _authenticationService.SignOutAsync();
        return RedirectToAction("Index", "Home");
    }
}
