function executeTests(label, f, module, config = {}) {
  const { concurrency } = config;
  concurrency = concurrency || 4;

  require(module);

  try {
    const testResults = [];
    const testsToRun = [];

    for (const test of Object.keys(f)) {
      testsToRun.push({ name: test, duration: null });
    }

    async function runTests() {
      let currentConcurrency = 0;
      let runningTests = new Map();

      async function runTest(test) {
        try {
          const startTime = process.memoryUsage().heapUsed;
          await f[test]();
          const endTime = process.memoryUsage().heapUsed;

          testResults.push({
            name: test,
            duration: Date.now() - (startTime / 1024 / 1024),
            passed: true,
          });
        } catch (error) {
          testResults.push({
            name: test,
            duration: null,
            passed: false,
            error,
          });

          await blueslip.reset();
        }

        currentConcurrency -= 1;

        if (currentConcurrency < 0) {
          throw new Error("Concurrency limit exceeded");
        }
      }

      async function runConcurrently() {
        while (testsToRun.length > 0 && currentConcurrency < concurrency) {
          const test = testsToRun.shift();
          runningTests.set(test.name, runTest(test));
          currentConcurrency += 1;
        }

        await Promise.all([...runningTests.values()]);
      }

      await runConcurrently();

      for (const result of testResults) {
        if (!result.passed) {
          console.error(`Test "${result.name}" failed: ${result.error}`);
        }
      }

      const report = {
        total: testsToRun.length,
        passed: testResults.filter((test) => test.passed).length,
        failed: testResults.filter((test) => !test.passed).length,
        duration: Date.now() - (process.memoryUsage().heapUsed / 1024 / 1024),
      };

      await sendReport(report);

      return report;
    }

    runTests();
  } catch (error) {
    console.error(`Error running tests: ${error}`);
  }
}

