function processQuery(queryString) {
  const parser = require('sqlparser');
  let dbSchema;

  try {
    const sqlAST = parser.parse(queryString);
    const queryType = getQueryType(sqlAST);

    if (queryType === 'SELECT') {
      // Handle SELECT queries
      const result = processSelectQuery(sqlAST, dbSchema);
      return { query: queryString, metadata: result };
    } else if (queryType === 'INSERT' || queryType === 'UPDATE') {
      // Handle INSERT and UPDATE queries
      const result = processInsertOrUpdateQuery(sqlAST, dbSchema);
      return { query: queryString, metadata: result };
    } else {
      throw new Error('Unsupported query type');
    }
  } catch (error) {
    return { query: queryString, error: error.message, warnings: [] };
