function renderFooterScripts(scripts) {
  const footerHtml = '';

  for (const script of scripts) {
    if (!script.key || typeof script.key !== 'string') {
      console.error('Invalid script key:', script);
      continue;
    }

    if (!['text/javascript', 'module'].includes(script.type)) {
      console.error('Unsupported script type:', script);
      continue;
    }

    if (typeof script.innerHTML !== 'string' || !script.innerHTML.trim()) {
      console.error('Invalid script innerHTML:', script);
      continue;
    }

    footerHtml += `<script ${script.type} src="${script.key}.js">${script.innerHTML}</script>\n`;
  }

  return footerHtml ? `<footer>${footerHtml}</footer>` : '';
}
