    auto it = fields.begin();
    while (it != fields.end()) {
        if (cachedFieldNames.find(*it) != cachedFieldNames.end() &&
            optimizedFieldNames.count(*it)) {
            // Field name is cached and matches an optimized field name
            sendRefreshMessage(resourceId, *it);
        } else {
            // Fetch field metadata from external API
