import java.util.*;
import java.time.*;

public class TransactionProcessor {
    private static final int TIME_WINDOW = 60; // 1 minute
    private static final long MAX_USER_SPEND = 1000000; // $1 million

    private Map<String, UserTransaction> userTransactions;
    private Map<String, Long> totalSpendMap;
    private Map<String, Instant> lastUpdateMap;

    public TransactionProcessor() {
        userTransactions = new HashMap<>();
        totalSpendMap = new HashMap<>();
        lastUpdateMap = new HashMap<>();

        new Thread(new Runnable() {
            @Override
            public void run() {
                // periodic task to persist data to external store
                while (true) {
                    try {
                        TimeUnit.MINUTES.sleep(5);
                        persistData();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }).start();
    }

    public Map<String, Long> processTransactions(List<Transaction> transactions) throws InterruptedException {
        for (Transaction transaction : transactions) {
            String userID = transaction.getUserID();
            Instant timestamp = transaction.getTimestamp();

            if (!lastUpdateMap.containsKey(userID)) {
                lastUpdateMap.put(userID, timestamp);
            } else {
                long timeDiff = Duration.between(lastUpdateMap.get(userID), timestamp).toMillis() / 1000;
                if (timeDiff > TIME_WINDOW) {
                    updateTotalSpendForUser(userID);
                }
            }

            if (!userTransactions.containsKey(userID)) {
                userTransactions.put(userID, new UserTransaction());
            }
            userTransactions.get(userID).addTransaction(transaction.getAmount());

            totalSpendMap.putIfAbsent(userID, 0L);
            totalSpendMap.put(userID, totalSpendMap.getOrDefault(userID, 0L) + transaction.getAmount());
        }

        return getActiveUserTransactions();
    }

    private void updateTotalSpendForUser(String userID) {
        // fetch external data for user
        UserData userData = fetchDataFromExternalStore(userID);
        long newTotalSpend = totalSpendMap.getOrDefault(userID, 0L) + userData.getTotalSpent();

        if (newTotalSpend > MAX_USER_SPEND) {
            // log warning and adjust spend accordingly
            System.out.println("User " + userID + "'s spend exceeds limit. Adjusting to $" + MAX_USER_SPEND);
            totalSpendMap.put(userID, MAX_USER_SPEND);
        } else {
            totalSpendMap.put(userID, newTotalSpend);
        }
    }

    private void persistData() throws InterruptedException {
        // periodically persist data to external store
        for (Map.Entry<String, UserTransaction> entry : userTransactions.entrySet()) {
            String userID = entry.getKey();
            UserTransaction userTransaction = entry.getValue();

            // fetch external data for user
            UserData userData = fetchDataFromExternalStore(userID);

            // update total spend and persist
            long newTotalSpend = userData.getTotalSpent() + userTransaction.getSum();
            userData.setTotalSpent(newTotalSpend);
            userData.setLastUpdated(LocalDate.now());

            // log query performance metrics
            System.out.println("Processed user " + userID + "'s transactions. Total spend: $" + newTotalSpend);
        }
    }

    private Map<String, Long> getActiveUserTransactions() {
        Map<String, Long> activeTransactions = new HashMap<>();

        for (Map.Entry<String, UserTransaction> entry : userTransactions.entrySet()) {
            String userID = entry.getKey();
            long sum = entry.getValue().getSum();

            if (sum > 0) {
                activeTransactions.put(userID, sum);
            }
        }

        return activeTransactions;
    }

    private class UserTransaction {
        private double sum;

        public void addTransaction(double amount) {
            sum += amount;
        }

        public double getSum() {
            return sum;
        }
    }
}
