        logger = new Logger();
        healthMonitor = new HealthMonitoringService();
        resourceMonitor = new ResourceMonitor();
        random = new Random();

        Thread thread = new Thread(() -> {
            try {
                while (true) {
                    assessLoadAndResourceUtilization();
                    manageServices();
                    Thread.sleep(5000);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        thread.start();
    }

    private void assessLoadAndResourceUtilization() {
        // Monitor system-wide CPU and memory usage
        // Enforce strict thresholds to ensure the application remains responsive under peak loads
    }

    private void manageServices() {
        int activeInstances = 0;
        for (int i = 0; i < MAX_INSTANCES; i++) {
            ServiceInstance instance = new ServiceInstance();
            if (shouldStartService(instance)) {
                startService(instance);
                activeInstances++;
            } else if (shouldStopService(instance)) {
                stopService(instance);
                activeInstances--;
            }
        }

        // Ensure at most three services are active simultaneously
        while (activeInstances > MAX_ACTIVE_INSTANCES) {
            ServiceInstance instance = executor.take();
            stopService(instance);
            activeInstances--;
        }
    }

    private boolean shouldStartService(ServiceInstance instance) {
        double load = getSystemLoad();
        double cpuUtilization = getCpuUtilization();
        if (random.nextDouble() < 0.5 && load < 0.8 && cpuUtilization < 0.9) {
            return true;
        }
        return false;
    }

    private boolean shouldStopService(ServiceInstance instance) {
        double load = getSystemLoad();
        double cpuUtilization = getCpuUtilization();
        if (random.nextDouble() > 0.7 || load > 0.95 || cpuUtilization > 0.98) {
            return true;
        }
        return false;
    }

    private void startService(ServiceInstance instance) {
        try {
            Thread.sleep(random.nextInt(10) * 1000); // Randomized delay between 1 and 10 seconds
            executor.submit(instance);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void stopService(ServiceInstance instance) {
        try {
            executor.execute(() -> {
                try {
                    instance.stop();
                    logger.log("Stopped service " + instance.getServiceName());
                } catch (Exception e) {
                    logger.error("Error stopping service " + instance.getServiceName(), e);
                }
            });
        } catch (RejectedExecutionException e) {
            // Service is already stopped or not eligible for shutdown
        }
    }

    private double getSystemLoad() {
        // Calculate system load based on CPU and memory usage
        return 0.5; // Example value
    }

    private double getCpuUtilization() {
        // Calculate CPU utilization based on thread pool metrics
        return 0.8; // Example value
    }
}

