import requests
import time
import json
from typing import Dict, Any

class WeatherCache:
    def __init__(self, max_age_seconds: int):
        self.cache: Dict[str, Dict[str, Any]] = {}
        self.max_age_seconds = max_age_seconds

    def get(self, city: str) -> Dict[str, Any]:
        if city in self.cache and time.time() - self.cache[city]['timestamp'] <= self.max_age_seconds:
            return self.cache[city]
        else:
            return None

    def set(self, city: str, data: Dict[str, Any]):
        self.cache[city] = {'data': data, 'timestamp': time.time()}

class WeatherAPIs:
    def __init__(self):
        self.api_urls = {
            'weather': 'https://api.weather.com/weather',
            'wind_speed': 'https://api.wind.speed.com/wind-speed',
            'precipitation': 'https://api.precipitation.com/precipitation'
        }
        self.api_rate_limits: Dict[str, int] = {'weather': 100, 'wind_speed': 50, 'precipitation': 200}
        self.api_timeout: float = 30
        self.api_retries: int = 3

    def fetch(self, city: str, api_url: str) -> Dict[str, Any]:
        attempts = 0
        while attempts < self.api_retries:
            try:
                response = requests.get(api_url, timeout=self.api_timeout)
                response.raise_for_status()
                return json.loads(response.text)
            except (requests.exceptions.RequestException, json.JSONDecodeError):
                if attempts >= self.api_retries - 1:
                    raise
                time.sleep(1)  # wait before retrying

def update_weather_cache(api: WeatherAPIs, cache: WeatherCache, city: str):
    weather_data = api.fetch(city, api.api_urls['weather'])
    wind_speed_data = api.fetch(city, api.api_urls['wind_speed'])
    precipitation_data = api.fetch(city, api.api_urls['precipitation'])

    if not all((weather_data, wind_speed_data, precipitation_data)):
        raise Exception("Failed to fetch data for city")

    cache.set(city, {'weather': weather_data, 'wind_speed': wind_speed_data, 'precipitation': precipitation_data})

def purge_cache(cache: WeatherCache):
    current_time = time.time()
    outdated_entries = [entry for entry in cache.cache.values() if current_time - entry['timestamp'] > cache.max_age_seconds]
    for entry in outdated_entries:
        del cache.cache[entry['city']]
