class RandomStringGenerator {
    public static function generateRandomString($length, $characterSet) {
        if (!in_array($characterSet, ['abcdefghijklmnopqrstuvwxyz', 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', '0123456789'])) {
            return 'Invalid character set. Please use one of: a-z, A-Z, 0-9';
        }

        $randomBytes = random_bytes($length);
        return implode('', array_map('chr', unpack('C*', $randomBytes)));
    }
}

class ConfigReader {
    public static function readConfigFile($directory, $filename) {
        if (!file_exists($directory . '/' . $filename)) {
            return 'File not found';
        }

        try {
            $contents = file_get_contents($directory . '/' . $filename);
            return $contents;
        } catch (Exception $e) {
            return 'Error reading file: ' . $e->getMessage();
        }
    }
}

class WebServiceEndpoint {
    public function generateRandomStringAndReadConfig($request) {
        try {
            $randomString = RandomStringGenerator::generateRandomString((int)$request['length'], $request['characterSet']);
            $configContents = ConfigReader::readConfigFile($request['directory'], $request['filename']);

            // Use Fractal for serialization
            $serializer = new JsonSerializer();
            $transformer = new TransformerAbstract();
            $fractal = new League\Fractal\Fractal();
