function fetchAndSaveCertificate(request) {
  const { privateKeyLocation, certificateLocation } = request;
  let pemData = '';

  try {
    const privateKeyStream = fs.createReadStream(privateKeyLocation);
    const certificateStream = fs.createReadStream(certificateLocation);

    privateKeyStream.on('data', (chunk) => {
      pemData += chunk.toString();
    });
    privateKeyStream.on('end', () => {
      certificateStream.on('data', (chunk) => {
        pemData += chunk.toString();
      });
      certificateStream.on('end', () => {
        const cache = new Map();
        cache.set('certificate', pemData);

        // log to external logging service
        const logger = new Logger({
          level: 'info',
          // configure logging service API
        });
        logger.log(`Certificate fetched and saved: ${pemData}`);
      });
    });

  } catch (err) {
    console.error(`Error fetching certificate: ${err.message}`);
    return { error: err.code, message: err.message };
  }
}
