    char* label;
    struct transition* transitions;
} state;

typedef struct transition {
    int to_state;
    struct transition* next;
} transition;

state* create_states(int states[], int num_states, const state* fsa, int last_state) {
    state* head = NULL;
    state* current = NULL;

    for (int i = 0; i < num_states; i++) {
        state* new_state = malloc(sizeof(state));
        if (!new_state) return NULL;

        new_state->id = states[i];
        new_state->label = strdup(fsa[i].label);
        new_state->transitions = fsa[i].transitions;

        if (head == NULL) head = current = new_state;
        else {
            current->next = new_state;
            current = new_state;
        }
    }

    current->next = NULL;

    return head;
}
