        // Validate recent packet count
        recent_count++;
        if (recent_count > 10) {
            recent_count = 0;
        }

        // Validate checksum and update maximum value
        int checksum_val = atoi(pkts[i].checksum);
        if (checksum_val > max_checksum) {
            max_checksum = checksum_val;
            latest_packet = pkts[i];
        }
    }

    return &latest_packet;
}

