        packets[count++] = new_pkt;
        if (count >= 100) {
            // Handle packet processing and update maximum checksum value
            Packet* result = process_packets(packets, count);
            printf("Maximum checksum: %d, Sequence number: %d\n", atoi(result->checksum), result->seq_num);

            // Reset packet buffer for next batch
            count = 0;
        }
    }

