using System;
using System.Threading;
using Microsoft.Xna.Framework;

public sealed class DynamicValueGenerator
{
    private readonly object _lock = new object();
    private float _minValue;
    private float _maxValue;
    private bool _inclusiveMax;

    public DynamicValueGenerator(float minValue, float maxValue, bool inclusiveMax)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentException("Min value must be less than max value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
        _inclusiveMax = inclusiveMax;
    }

    public float GetRandomFloat()
    {
        Random random = new Random(Thread.CurrentThread.ManagedThreadId);
        return (float)random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomInt()
    {
        Random random = new Random(Thread.CurrentThread.ManagedThreadId);
        return random.Next((int)(_inclusiveMax ? _maxValue : _maxValue - 1)) + (int)_minValue;
    }

    public Vector3 GetRandomVector3()
    {
        float x = GetRandomFloat();
        float y = GetRandomFloat();
        float z = GetRandomFloat();
        return new Vector3(x, y, z);
    }

    public Color GetRandomColor()
    {
        float r = GetRandomFloat();
        float g = GetRandomFloat();
        float b = GetRandomFloat();
        return new Color(r, g, b);
    }

    public override string ToString()
    {
        return $"[{_minValue},{_inclusiveMax ? _maxValue : _maxValue - 0.0001f})";
    }
}
