        char* new_str = (char*)malloc((size_limit + 1) * sizeof(char));
        memcpy(new_str, str, strlen(str));
        new_str[size_limit] = '\0';
        return new_str;
    } else {
        return NULL;
    }
}

Node* traverse_dom(Node* node, const char* selector, void (*callback)(const Node*, int)) {
    if (node == NULL) {
        return NULL;
    }

    if (callback(node->value, 0) > 0) {
        callback(node->value, strlen(node->value));
    }

    Node* current = node;
    while (current != NULL) {
        Node* next = current->next;
        current->next = traverse_dom(current->next, selector, callback);
        current = next;
    }
}

