typedef struct {
    char* line;
    int fields;
} Line;

void process_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    Line* lines = NULL;
    int line_count = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        size_t len = strlen(buffer);
        if (buffer[len - 1] == '\n') {
            buffer[--len] = '\0';
        }

        Line* new_line = (Line*)malloc(sizeof(Line));
        new_line->line = strdup(buffer);
        new_line->fields = 0;

        // Find the last two numeric fields
        int i = 0;
        char* token = strtok(buffer, " ");
        while (token) {
            if (i >= 2) break;
            int num = atoi(token);
            if (num > 0) {
                new_line->fields++;
                i++;
            }
            token = strtok(NULL, " ");
        }

        // Print the line contents
        printf("%s,", buffer);

        // Free allocated memory
        free(new_line->line);
        free(new_line);

        line_count++;
    }

    fclose(file);

    // Handle system dependencies and theme bitmap recycling
    if (theme_bitmap_recycled()) {
        theme_bitmap = NULL;
    }

    // Initialize default theme directory if not already set
    char* theme_dir = get_default_theme_directory();
    if (!theme_dir) {
        theme_dir = "path/to/default/theme";
        set_default_theme_directory(theme_dir);
    }

    // Manage caching and parse PNG file from cache root directory
    char* cache_root_dir = get_cache_root_directory();
    if (cache_root_dir && !parse_png_file(cache_root_dir, "theme.png")) {
        printf("Error parsing PNG file\n");
    }

    // Log any issues encountered during execution
    log_execution();

    printf("\nProcessed %d lines.\n", line_count);
}

int main() {
    process_file("config.txt");
    return 0;
}
