                    var samplesPerPixel = tiffReader.GetSamplesPerPixel(stripIndex);
                    var extraSamplesCount = tiffReader.GetExtraSamplesCount(stripIndex);

                    for (int sampleIndex = 0; sampleIndex < samplesPerPixel; sampleIndex++)
                    {
                        try
