                            var identifier = CalculateSampleIdentifier(tiffReader, stripIndex, sampleIndex);
                            metadata.SampleIdentifiers ??= new string[metadata.SampleIdentifiers?.Length ?? 0];
                            metadata.SampleIdentifiers = metadata.SampleIdentifiers.Concat(new[] { identifier }).ToArray();
