#define MAX_FILENAME_LENGTH 255
#define FILE_TYPE_PATTERN "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

char* generateUniqueFileName(char* originalFilename) {
    char* newFilename = (char*)malloc(MAX_FILENAME_LENGTH * sizeof(char));
    int filenameLength = strlen(originalFilename);

    // Initialize random number generator
    srand(time(NULL));

    for (int i = 0; i < filenameLength; i++) {
        if (originalFilename[i] == '.') { // File extension found, modify it
            char* fileTypePattern = strstr(FILE_TYPE_PATTERN, &originalFilename[i]);
            int fileTypeLength = strlen(fileTypePattern);

            // Generate random characters for new file type
            for (int j = 0; j < fileTypeLength; j++) {
                newFilename[filenameLength + j] = fileTypePattern[j];
            }

            // Append a random number of digits to the filename
            int digitCount = rand() % 5 + 1;
            for (int k = 0; k < digitCount; k++) {
                newFilename[filenameLength + fileTypeLength + k] = '0' + rand() % 10;
            }

            break;
        } else if (originalFilename[i] == ' ') { // Space found, replace it with a dash
            newFilename[filenameLength - i - 1] = '-';
        } else {
            newFilename[filenameLength - i - 1] = originalFilename[i];
        }
    }

    // Check for uniqueness and append sequential number if necessary
    int filenameCount = 0;
    char* uniqueFilename = (char*)malloc(MAX_FILENAME_LENGTH * sizeof(char));

    do {
        sprintf(uniqueFilename, "%s%d", newFilename, ++filenameCount);

        FILE* logFile = fopen("file_transform_log.txt", "a");
        fprintf(logFile, "Transformed file: %s -> %s\n", originalFilename, uniqueFilename);
        fclose(logFile);

    } while (strlen(uniqueFilename) > MAX_FILENAME_LENGTH || (FILE* fileHandle = fopen(uniqueFilename, "r")) != NULL);

    free(newFilename);
    return uniqueFilename;
}

int main() {
    char* originalFileName = "my_file.txt";
    printf("%s\n", generateUniqueFileName(originalFileName));
    return 0;
}
