int convertAndSerialize(const char* jpegFilePath, const char* pdfOutputPath, unsigned char** bufferPtr) {
    FILE* jpegFile = fopen(jpegFilePath, "rb");
    if (!jpegFile) {
        fprintf(stderr, "Error opening JPEG file: %s\n", strerror(errno));
        return 1;
    }

    // Convert JPEG to PDF
    int result = convert_jpg_to_pdf(jpegFile, &bufferPtr);
    if (result != 0) {
        fprintf(stderr, "Conversion failed: %d\n", result);
        fclose(jpegFile);
        free(*bufferPtr);
        *bufferPtr = NULL;
        return 1;
    }

    fclose(jpegFile);

    // Serialize PDF into buffer
    FILE* pdfFile = fopen(pdfOutputPath, "wb");
    if (!pdfFile) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        free(*bufferPtr);
        *bufferPtr = NULL;
        return 1;
    }

    fseeko(pdfFile, 0, SEEK_END);
    int fileSize = ftello(pdfFile);

    if (fileSize > *bufferPtr->size) {
        // Adjust buffer size and retry serialization
        unsigned char* newBuffer = realloc(*bufferPtr, fileSize + 1);
        if (!newBuffer) {
            fprintf(stderr, "Failed to allocate memory for PDF serialization.\n");
            fclose(pdfFile);
            free(*bufferPtr);
            *bufferPtr = NULL;
            return 1;
        }
        *bufferPtr = newBuffer;

        fseeko(pdfFile, 0, SEEK_SET);
        fwrite(*bufferPtr->data, 1, fileSize, pdfFile);
    } else {
        fseeko(pdfFile, 0, SEEK_SET);
        fwrite(*bufferPtr->data, 1, fileSize, pdfFile);
    }

    fclose(pdfFile);

    return 0;
}
