#include <signal.h>
#include <string.h>
#include <time.h>

int execute_command(const char* cmd, int timeout, const char** envp) {
    pid_t child_pid;
    struct sigaction sa;

    if (!cmd || strlen(cmd) == 0) return -1; // handle null or empty command string

    // fork a child process to execute the command
    child_pid = fork();
    if (child_pid < 0) return -1; // handle fork failure

    if (child_pid == 0) {
        // child process executes the command
        execle("/bin/sh", "/bin/sh", "-c", cmd, NULL, envp);
        _exit(127); // handle execle failure
    } else {
        // parent process monitors resource usage and adjusts timeout
        sa.sa_handler = SIG_IGN;
        sigaction(SIGCHLD, &sa, NULL);

        FILE* fp = fopen("/proc/self/stat", "r");
        if (!fp) return -1; // handle file access failure

        int cpu_usage = 0, mem_usage = 0;

        while (1) {
            sleep(1); // adjust this value for desired resource monitoring frequency

            // read CPU and memory usage
            char line[1024];
            fgets(line, sizeof(line), fp);
            sscanf(line, "%*d %d %*d", &cpu_usage);
            int mem_line[3];
            int bytes_read = 0;
            while (bytes_read < sizeof(line)) {
                bytes_read += fscanf(fp, "%d %d %d", &mem_line[0], &mem_line[1], &mem_line[2]);
            }
            sscanf(line, "%*d %d", &mem_usage);

            if (cpu_usage > 50 || mem_usage > 500) { // adjust these values for desired resource limits
                kill(child_pid, SIGTERM); // terminate the command if it exceeds limits
                waitpid(child_pid, NULL, 0); // clean up resources
                return 0; // timeout or exceeded resource limit
            }

            // update timeout based on resource consumption
            timeout -= (cpu_usage + mem_usage) / 100;

            if (timeout <= 0) { // command exceeds initial timeout
                kill(child_pid, SIGTERM); // terminate the command
                waitpid(child_pid, NULL, 0); // clean up resources
                return 0; // timeout exceeded
            }
        }

        int status;
        waitpid(child_pid, &status, 0);

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        } else {
            return -1; // command execution error
        }
    }
}
