    public List<(string message, bool isError)> DecodeBase64Messages(string input)
    {
        var messages = new List<(string message, bool isError)>();

        foreach (var base64Message in input.Split(_delimiterBytes))
        {
            if (string.IsNullOrEmpty(base64Message))
                continue;

            try
            {
                using var tripleDES = TripleDESCryptoServiceProvider.Create();
                tripleDES.Key = Encoding.ASCII.GetBytes(_key);
                tripleDES.IV = _iv;

                using var stream = new MemoryStream(Encoding.UTF8.GetBytes(base64Message));
                using var cryptoStream = new CryptoStream(stream, tripleDES.CreateDecryptor(), CryptoStreamMode.Read);

                byte[] decryptedBytes;
                using (var ms = new MemoryStream())
                {
                    cryptoStream.CopyTo(ms);
                    ms.Position = 0;
                    decryptedBytes = ms.ToArray();
                }

                // Validate integrity of decrypted data
                if (!ValidateData(decryptedBytes))
                {
                    messages.Add((base64Message, true));
                    continue;
                }

                _messageCount++;

                if (_messageCount % 100 == 0)
                {
                    // Rotate key and IV every 100 messages
                    _key = GetNewKey();
                    _iv = GetNewIV();
                }

                messages.Add((Encoding.UTF8.GetString(decryptedBytes), false));
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error decoding message: {ex.Message}");
                messages.Add((base64Message, true));
            }
        }

        return messages;
