public class LogProcessor
{
    public Dictionary<string, int> ProcessLogFile(string filePath)
    {
        Dictionary<string, int> errorFrequency = new Dictionary<string, int>();

        using (StreamReader reader = new StreamReader(filePath))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                string[] logEntryParts = line.Split(new char[] { ';', ',', ' ' }, StringSplitOptions.RemoveEmptyEntries);
                if (logEntryParts.Length >= 2 && logEntryParts[0].StartsWith("ERR"))
                {
                    string errorCode = logEntryParts[1];
                    if (!errorFrequency.ContainsKey(errorCode))
                    {
                        errorFrequency.Add(errorCode, 0);
                    }
                    errorFrequency[errorCode]++;
                }
            }
        }

        return errorFrequency;
    }
}
