import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.Set;

public class DeserializationService {
    private static final Set<Class<?>> TRUSTED_CLASSES = ...; // Initialize the set of trusted classes

    public static <T> T deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            String errorMessage = "Unknown class: " + e.getName();
            throw new RuntimeException(errorMessage);
        }
    }

    public static <T> T deserialize(byte[] data, Class<T> expectedClass) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return ois.readObject();
        } catch (ClassNotFoundException e) {
            String errorMessage = "Unknown class: " + e.getName() + ". Expected: " + expectedClass.getName();
            throw new RuntimeException(errorMessage);
        }
    }

    public static void registerTrustedClass(Class<?> clazz) {
        TRUSTED_CLASSES.add(clazz);
    }
}
