const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const { promisify } = require('util');
const exec = promisify(spawn);

async function processDirectory(dirPath, config) {
  const commands = [];
  const fileCache = {};

  // Define command sequences based on file attributes and user configurations
  fs.readdirSync(dirPath).forEach((file) => {
    const filePath = path.join(dirPath, file);
    const stats = fs.statSync(filePath);

    if (stats.isFile()) {
      if (!config.fileTypes.includes(path.extname(file))) return;

      // Assemble command sequence based on file type and configuration
      let commandsForFile = config.commandSequences.find((seq) => seq.types.includes(path.extname(file)));
      if (!commandsForFile) throw new Error(`No command sequence found for file ${file}`);

      // Add commands to the sequence, ensuring sequential execution
      commands.push(...commandsForFile.map((cmd) => async () => {
        try {
          await exec(cmd, { cwd: dirPath });
        } catch (err) {
          console.error(err);
          throw err;
        }
      }));
    }
  });

  // Execute command sequences in parallel, caching results where possible
  const promise = Promise.resolve();

  for (const cmd of commands) {
    promise = promise.then((prevResult) => {
      return Promise.all(cmd.map((c) => c()));
    }).then((results) => {
      fileCache = { ...fileCache, ...results };
    });
  }

  // Wait for all command sequences to complete
  await promise;

  // Log and cache the final results
  console.log('File processing completed:', JSON.stringify(fileCache));
}

// Example configuration object
const config = {
  fileTypes: ['.txt', '.js'],
  commandSequences: [
    {
      types: ['.txt'],
      commands: ['grep -i keyword', 'sort']
    },
    {
      types: ['.js'],
      commands: ['jshint', 'jscs']
    }
  ]
};

processDirectory('/path/to/files', config);
