use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;

struct DirectoryManager {
    config_cache: Arc<Mutex<HashMap<String, String>>>,
    max_retries: u32,
    retry_backoff: f64,
}

impl DirectoryManager {
    fn new(max_retries: u32, retry_backoff: f64) -> Self {
        DirectoryManager {
            config_cache: Arc::new(Mutex::new(HashMap::new())),
            max_retries,
            retry_backoff,
        }
    }

    fn create_directory(&self, path: &str) {
        let mut retries = 0;
        let mut backoff_time = 0.5; // initial backoff time
        while retries < self.max_retries {
            if !Path::new(path).exists() {
                if fs::create_dir_all(path).is_err() {
                    thread::sleep(std::time::Duration::from_millis(backoff_time as u64));
                    backoff_time *= 2.0;
                    retries += 1;
                } else {
                    self.config_cache.lock().unwrap().insert(String::from(path), String::new());
                    break;
                }
            } else {
                self.config_cache.lock().unwrap().insert(String::from(path), String::new());
                break;
            }
        }
    }

    fn update_config(&self, path: &str) {
        self.config_cache.lock().unwrap().insert(String::from(path), String::new());
    }
}
