import json
import threading

class EntityRegistry:
    def __init__(self):
        self._registry = {}
        self._lock = threading.Lock()

    def register_factory(self, entity_type, factory_func):
        with self._lock:
            if entity_type not in self._registry:
                self._registry[entity_type] = factory_func

    def deserialize_entity(self, json_data, version):
        try:
            return self._deserialize_entity(json_data, version)
        except KeyError as e:
            print(f"Warning: Incompatible version {version} for entity type {e}. Fallback to default behavior.")
            return None

    def _deserialize_entity(self, json_data, version):
        if not json_data:
            return None

        try:
            entity_type = json_data['type']
            factory_func = self._registry.get(entity_type)
            if not factory_func:
                raise KeyError(f"Unknown entity type: {entity_type}")

            return factory_func(json_data, version)
        except Exception as e:
            print(f"Error deserializing entity: {e}")
            return None

    def serialize_entity(self, entity):
        if not entity:
            return None

        try:
            return json.dumps({'type': type(entity).__name__, 'data': entity})
        except Exception as e:
            print(f"Error serializing entity: {e}")
            return None


class EntityFactory:
    @staticmethod
    def from_json(json_data, version):
        pass  # implement factory logic here


# Example usage:
registry = EntityRegistry()

class Person(EntityFactory):
    @staticmethod
    def from_json(json_data, version):
        if version == 'v1':
            return PersonV1(**json_data['data'])
        elif version == 'v2':
            return PersonV2(**json_data['data'])
        else:
            raise ValueError(f"Unsupported version: {version}")

class PersonV1:
