entity_v1 = registry.serialize_entity(PersonV1('John', 30))
print(json.loads(entity_v1))  # Output: {'type': 'person', 'data': {'name': 'John', 'age': 30}}

entity_v2 = registry.deserialize_entity(entity_v1, 'v2')
print(type(entity_v2))  # Output: PersonV2
