int find_largest(int* arr, int size) {
    if (size <= 0) {
        return -1;
    }

    int max_val = *arr;
    for (int i = 1; i < size; i++) {
        if (*arr++ > max_val) {
            max_val = *arr;
        }
    }

    return max_val;
}

void print_largest(int* arr, int size) {
    int largest = find_largest(arr, size);
    printf("Largest integer in the array: %d\n", largest);
}

