class CryptoCipher {
public:
    CryptoCipher();
    ~CryptoCipher();

    static EVP_CIPHER* getEVPCipher();

    int setCipherMode(int mode);

    // Methods for generating random numbers
    void seedRandomGenerator(unsigned long long seed);
    int generateRandomInt(int min, int max);
    double generateRandomDouble(double min, double max);

private:
    static int activeCipherMode;
    MT19937Ar mt;

};

CryptoCipher::CryptoCipher() {
    activeCipherMode = 0; // Default mode is DES in ECB
}

CryptoCipher::~CryptoCipher() {}

EVP_CIPHER* CryptoCipher::getEVPCipher() {
    switch (activeCipherMode) {
        case 1:
            return EVP_des_ede();
        case 2:
            return EVP_des_ede3();
        default:
            return EVP_des_ecb();
    }
}

int CryptoCipher::setCipherMode(int mode) {
    if (mode >= 0 && mode <= 2)
        activeCipherMode = mode;
    else
        return -1; // Invalid mode

    return 0; // Successful mode change
}

void CryptoCipher::seedRandomGenerator(unsigned long long seed) {
    mt.seed(seed);
}

int CryptoCipher::generateRandomInt(int min, int max) {
    return mt.extractInteger(min, max);
}

double CryptoCipher::generateRandomDouble(double min, double max) {
    return (double)mt.extractInteger(min, max) / ((max - min) + 1.0);
}

int CryptoCipher::CryptoCipher::activeCipherMode = 0;
