// Structure to represent a named semaphore
typedef struct {
    sem_t* semaphore;
    char name[20];
} Semaphore;

// Function to create a new semaphore with the given name and initial value
int create_semaphore(const char* name, int value) {
    // Initialize the semaphore structure
    Semaphore* sem = malloc(sizeof(Semaphore));
    strcpy(sem->name, name);
    sem->semaphore = sem_open(name, O_CREAT | O_EXCL, 0644, value);
    if (sem->semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(sem);
        return -1;
    }
    return 0;
}

// Function to delete a named semaphore
int delete_semaphore(const char* name) {
    Semaphore* sem = malloc(sizeof(Semaphore));
    strcpy(sem->name, name);
    int status = sem_close(sem->semaphore);
    if (status == -1) {
        perror("Failed to close semaphore");
        free(sem);
        return -1;
    }
    free(sem);
    return 0;
}

// Function to handle failed operations and log errors
void log_error(const char* message, int code) {
    FILE* file = fopen(LOG_FILE, "a+");
    if (file != NULL) {
        fprintf(file, "[%s] Error: %d - %s\n", localtime(), code, message);
