using System;

public class RandomRangeGenerator
{
    private readonly float _min;
    private readonly float _max;

    public RandomRangeGenerator(float min, float max)
    {
        _min = min;
        _max = max;
    }

    public float GenerateRandomFloat()
    {
        return _min + (float)(Math.Random() * (_max - _min));
    }

    public int GenerateRandomInt()
    {
        var randomFloat = GenerateRandomFloat();
        return (int)((randomFloat - _min) / (_max - _min) * (1 << 31) + 0.5f);
    }

    public override string ToString()
    {
