#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*ErrorCallback)(const char *);

char **traverse_directories(const char *path, int max_depth, int follow_symlinks, ErrorCallback error_cb) {
    DIR *dir;
    struct dirent *ent;
    char **files = NULL;
    int file_count = 0;
    int current_depth = 0;

    dir = opendir(path);
    if (dir == NULL) {
        error_cb("Failed to open directory");
        return NULL;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char *file_path = (char *)malloc(strlen(path) + strlen(ent->d_name) + 2);
        sprintf(file_path, "%s/%s", path, ent->d_name);

        if (follow_symlinks && S_ISLNK(stat(file_path)->st_mode)) {
            // Handle symbolic link
            char *real_path = realpath(file_path, NULL);
            if (real_path) {
                file_path = real_path;
            } else {
                free(real_path);
                error_cb("Failed to resolve symbolic link");
                return NULL;
            }
        }

        if (current_depth < max_depth) {
            int new_depth = current_depth + 1;

            char *new_file_path = (char *)malloc(strlen(file_path) + 2);
            strcpy(new_file_path, file_path);

            while (*file_path != '\0' && *file_path != '/') {
                file_path++;
            }
            strcpy(new_file_path + strlen(new_file_path), file_path);

            files = realloc(files, (file_count + 1) * sizeof(char *));
            files[file_count] = new_file_path;
            file_count++;

            free(file_path);
            file_path = new_file_path;

            current_depth = new_depth;
        } else {
            error_cb("Directory traversal exceeds maximum depth");
            return NULL;
        }
    }

    closedir(dir);

    if (file_count == 0) {
        free(files);
        return NULL;
    }

    char **result = (char **)malloc((file_count + 1) * sizeof(char *));
    memcpy(result, files, file_count * sizeof(char *));
    result[file_count] = NULL;

    free(files);

    return result;
}

