typedef struct {
    int id;
    long timestamp;
    char status;
} DataPacket;

void manageDataPackets(DataPacket **packets, int *size, time_t currentTime) {
    // Remove packets that have exceeded the expiration time
    for (int i = 0; i < *size; i++) {
        if (difftime(currentTime, packets[i]->timestamp) > 3600) {
            memmove(&packets[i], &packets[i + 1], (*size - i - 1) * sizeof(DataPacket *));
            *size -= 1;
            i--;
        }
    }

    // Update packet statuses
    for (int i = 0; i < *size; i++) {
        if (difftime(currentTime, packets[i]->timestamp) <= 3600) {
            // Update status logic here
            packets[i]->status = 'U'; // Update the status to 'U' for example
        }
    }

    // Add new packets
    DataPacket *newPackets = realloc(NULL, sizeof(DataPacket *));
    int newSize = 1;
    while (1) {
        printf("Enter a unique ID (-1 to stop): ");
        int id;
        scanf("%d", &id);
        if (id == -1)
            break;

        DataPacket *newPacket = malloc(sizeof(DataPacket));
        newPacket->id = id;
        time_t timestamp = time(NULL); // Get current system time
        printf("Enter a status (- to ignore): ");
        char status;
        scanf("%c", &status);
        newPacket->timestamp = timestamp;
        newPacket->status = status;

        if (*size > 0) {
            *packets = realloc(*packets, sizeof(DataPacket *) * ((*size) + (newSize)));
            packets[*size] = newPacket;
            (*size)++;
        } else {
            *packets = malloc(sizeof(DataPacket *));
            *packets = newPacket;
            *size++;
        }
    }

    free(newPackets);
}
