        return -3; // error renaming file
    }

    // spawn a background process to execute a specified command using fork and wait
    int pid = fork();
    if (pid == 0) { // child process
        execlp("/path/to/command", "command", NULL);
        perror("Error executing the command");
        return -4; // error executing command
    } else if (pid > 0) {
        wait(NULL); // wait for child process to finish
    }

    return 0; // both file processing and command execution successful
}
