class AES256CBC {
public:
    void init(const std::string& password) {
        const char* key = deriveKey(password);
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_CipherInit(ctx, &AES_256_CBC, (const unsigned char*)key, NULL, 1);
        iv_len = 16;
        key_len = 32;
    }

private:
    const char* deriveKey(const std::string& password) {
        unsigned char hash[SHA_DIGEST_LENGTH];
        SHA_CTX ctx;
        SHA_Init(&ctx);
        SHA_Update(&ctx, (const void*)password.c_str(), password.size());
        SHA_Final(&ctx, hash);
        return (char*)hash;
    }
};

class SandeshClientWithAES256CBC : public sandesh::SandeshClient {
public:
    SandeshClientWithAES256CBC(const AES256CBC& aes) : aes_(aes) {}

protected:
    virtual int connect() override {
        // Use AES-256-CBC for encryption
        // ...
    }

private:
    AES256CBC aes_;
};

class ConnectionPool {
public:
    void addConnection(sandesh::SandeshClient* client) {
        connections_.push_back(client);
    }

    sandesh::SandeshClient* getConnection() {
        if (connections_.empty()) return nullptr;
        sandesh::SandeshClient* client = connections_.front();
        connections_.pop_front();
        return client;
    }

private:
    std::deque<sandesh::SandeshClient*> connections_;
};

int main() {
    AES256CBC aes;
    aes.init("my_secret_password");

    SandeshClientWithAES256CBC client(aes);
    ConnectionPool pool;

    // Initialize the connection pool
    for (int i = 0; i < 5; i++) {
        pool.addConnection(&client);
    }

