    if (!response.isOk()) {
        // Handle error
    } else {
        // Handle success
    }

    // Shutdown the connection pool and cipher
    while (pool.getConnection() != nullptr) {
        // Clean up connections
    }
    EVP_CIPHER_CTX_free(aes.getCTX());

    return 0;
}

