#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef enum {
    CRCFLAG_VALID,
    CRCFLAG_INVALID
} CRC_INDICATION_REL8_TAG;

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int crc_flag;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pool[MAX_STRUCTURES];
int num_allocated = 0;

void* create_nfapi_crc_indication_pdu(int num_structures) {
    NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
    int i, err;

    for (i = 0; i < num_structures; i++) {
        RX_UE_INFORMATION_TAG rx_ue_info;
        CRC_INDICATION_REL8_TAG crc_tag;
        NFAPI_CRC_INDICATION_PDU_T* structure;

        if ((structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            err = 1;
            break;
        }

        pthread_mutex_lock(&lock);

        if (num_allocated < MAX_STRUCTURES) {
            pool[num_allocated] = structure;
            num_allocated++;
        } else {
            free(structure);
            structure = NULL;
        }

        pthread_mutex_unlock(&lock);

        rx_ue_info.rnti = rand() % 1000;
        crc_tag = (rand() % 2 == 0) ? CRCFLAG_VALID : CRCFLAG_INVALID;
        structure->rx_ue_info = rx_ue_info;
        structure->crc_flag = crc_tag;

        if (structures == NULL) {
            structures = structure;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = structures;
            while (current != NULL && current->next == NULL) {
                current->next = structure;
                structure = current;
                current = current->next;
            }
        }

        if (err) {
            free(structure);
            for (int j = 0; j < i; j++) {
                free(pool[j]);
            }
            return structures;
        }
    }

    for (i = 0; i < num_structures - 1; i++) {
        pool[i]->next = pool[i + 1];
    }
    pool[num_structures - 1]->next = NULL;

    return structures;
}

void log_creation_info(NFAPI_CRC_INDICATION_PDU_T* structures, int num_structures) {
    if (structures == NULL)
        printf("Error creating NFAPI CRC Indication PDU: No structures allocated.\n");
    else
        printf("Created %d NFAPI CRC Indication PDU structures.\n", num_structures);
}

int main() {
    int num_structures = 100;
    NFAPI_CRC_INDICATION_PDU_T* structures = create_nfapi_crc_indication_pdu(num_structures);
    log_creation_info(structures, num_structures);

    return 0;
}
