void manage_memory(int num_records, int max_value, int seed) {
    // Initialize random number generator
    srand(seed);

    // Allocate memory for arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
        keys[i] = rand() % max_value;
        records[i].value = rand() % max_value;
    }

    // Read sequence of integers from standard input
    int n;
    printf("Enter a sequence of integers (terminate with 0): ");
    int* input_keys = (int*)malloc(sizeof(int));
    *input_keys = 0;
    while ((n = getchar()) != '\n' && n != EOF) {
        if (*input_keys == 0) {
            break;
        }
        *(++input_keys) = n - '0';
    }

    int max_key = 0;
    for (int i = 0; i < input_keys - 1; i++) {
        if (*(input_keys + i) > max_key)
            max_key = *(input_keys + i);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(input_keys);
}

int main() {
    manage_memory(10, 100, 42);
    return 0;
