typedef struct {
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
    void* routing_rules;
} NetworkConfig;

typedef struct {
    int count;
    NetworkConfig** configs;
} NetworkConfigCollection;

NetworkConfigCollection* create_collection() {
    NetworkConfigCollection* collection = (NetworkConfigCollection*)malloc(sizeof(NetworkConfigCollection));
    if (!collection) {
        return NULL;
    }
    collection->count = 0;
    collection->configs = NULL;
    return collection;
}

int add_config(NetworkConfigCollection* collection, char* ip, char* subnet_mask, char* gateway, void* routing_rules) {
    NetworkConfig* config = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    if (!config) {
        return -1; // Memory allocation failed
    }
    strcpy(config->ip, ip);
    strcpy(config->subnet_mask, subnet_mask);
    strcpy(config->gateway, gateway);
    config->routing_rules = routing_rules;

    collection->configs = (NetworkConfig**)realloc(collection->configs, (collection->count + 1) * sizeof(NetworkConfig*));
    if (!collection->configs) {
        free(config);
        return -1; // Memory allocation failed
    }
    collection->configs[collection->count] = config;
    collection->count++;

    return 0; // Success
}

int delete_config(NetworkConfigCollection* collection, int index) {
    if (index < 0 || index >= collection->count) {
        return -1; // Invalid index
    }
    free(collection->configs[index]);
    for (int i = index; i < collection->count - 1; i++) {
        collection->configs[i] = collection->configs[i + 1];
    }
    collection->count--;

    return 0; // Success
}

NetworkConfig* get_config(NetworkConfigCollection* collection, int index) {
    if (index < 0 || index >= collection->count) {
        return NULL; // Invalid index
    }
    return collection->configs[index];
}

void free_collection(NetworkConfigCollection* collection) {
    for (int i = 0; i < collection->count; i++) {
        free(collection->configs[i]);
    }
    free(collection->configs);
    free(collection);
}
