// Define a structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Function to initialize and persist records in a file-based database
void process_records(int num_records) {
    // Dynamically allocate memory for arrays of 'long' offsets and 'int' keys
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
    }

    // Dynamically allocate memory for an array of 'record' structures
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Initialize the record array and persist each record in a file-based database
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        sem_wait(semaphore);
        // Write the record to the file-based database
        FILE* f = fopen("records.txt", "a");
        fwrite(&records[i], sizeof(Record), 1, f);
        fclose(f);
        sem_post(semaphore);
    }

    // Free allocated memory and close the log file
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int num_records = 10000; // Replace with your desired number of records

    // Initialize a semaphore for concurrency management
    sem_id = sem_open("semaphore", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, 1);

    if (sem_id < 0) {
        perror("sem_open");
        exit(EXIT_FAILURE);
    }

    process_records(num_records);

    // Close the semaphore and remove it
    sem_close(sem_id);
    sem_unlink("semaphore");

    return 0;
}
