#define MAX_LINE_LENGTH 256
#define MAX_FILES 20
#define MAX_SKIP_SUBSTRINGS 100

typedef struct {
    char* filename;
    bool exists;
    FILE* file;
} ConfigFile;

void print_usage() {
    printf("Usage: config_processor [-i files] [-cs] [-o output_file]\n");
}

int main(int argc, char** argv) {
    int opt;
    char input_files[MAX_FILES][256];
    int num_input_files = 0;
    bool count_non_empty_lines = false;
    bool skip_substrings = false;
    char* output_file = NULL;

    while ((opt = getopt(argc, argv, "i:cs:o:")) != -1) {
        switch (opt) {
            case 'i':
                sscanf(getopt_arg(optarg), "%s", input_files[num_input_files]);
                num_input_files++;
                break;
            case 'c':
                count_non_empty_lines = true;
                break;
            case 's':
                skip_substrings = true;
                break;
            case 'o':
                output_file = optarg;
                break;
            case '?':
                print_usage();
                return 1;
            default:
                break;
        }
    }

    if (num_input_files > MAX_FILES) {
        printf("Error: Maximum number of input files exceeded.\n");
        return 1;
    }

    for (int i = 0; i < num_input_files; i++) {
        ConfigFile* file = malloc(sizeof(ConfigFile));
        file->filename = input_files[i];
        file->exists = access(input_files[i], F_OK) == -1;
        if (!file->exists) {
            printf("Error: File '%s' does not exist.\n", input_files[i]);
            continue;
        }
        file->file = fopen(input_files[i], "r");
        if (file->file == NULL) {
            printf("Error: Unable to open file '%s'.\n", input_files[i]);
            free(file);
            continue;
        }

        char skip_substrings_str[MAX_SKIP_SUBSTRINGS][256];
        int num_skip_substrings = 0;

        // Process lines
        while (fgets(buffer, MAX_LINE_LENGTH + 1, file->file)) {
            if (count_non_empty_lines && !strstrip(buffer) || strlen(buffer) <= 1) continue;
            if (skip_substrings) {
                bool skip_line = false;
                for (int j = 0; j < num_skip_substrings; j++) {
                    if (strstr(strcasestr(buffer, skip_substrings_str[j])) != NULL) {
                        skip_line = true;
                        break;
                    }
                }
                if (skip_line) continue;
            }

            // Write processed line to output file
        }

        fclose(file->file);
        free(file);
    }

    return 0;
}

