} sensor_data;

void process_temperature_readings(int num_readings, const char **sensor_ids, double *temperatures) {
    // Dynamically allocate memory for arrays
    sensor_data *data = (sensor_data *)malloc(num_readings * sizeof(sensor_data));
    char **unique_sensor_ids = (char **)malloc(num_readings * sizeof(char *));

    // Initialize arrays and validate sensor IDs
    for (int i = 0; i < num_readings; i++) {
        strcpy(data[i].sensor_id, sensor_ids[i]);
        unique_sensor_ids[i] = data[i].sensor_id;

        // Validate sensor ID length
        if (strlen(sensor_ids[i]) > MAX_LENGTH) {
            printf("Invalid sensor ID: %s\n", sensor_ids[i]);
            return; // Exit on error
        }
    }

    // Implement linear interpolation algorithm
    for (int i = 1; i < num_readings - 1; i++) {
        double prev_temp = temperatures[i-1];
        double next_temp = temperatures[i+1];
        double prev_time = data[i-1].timestamp;
        double next_time = data[i+1].timestamp;

        for (int j = i; j < i + (next_time - prev_time) / 1000.0; j++) {
            time_t timestamp = prev_time + (j-i)*((next_time - prev_time) / 1000.0);
            double temperature = prev_temp + ((next_temp-prev_temp)*(j-i))/1000.0;

            // Handle interpolation out-of-range
            if (temperature > 50 || temperature < 0) {
                j++; // Skip and move to next iteration
                continue;
            }

            data[j].timestamp = timestamp;
            data[j].temperature = temperature;
        }
    }

    // Integrate with external time-series database
    // ...

    // Free allocated memory
    free(data);
    for (int i = 0; i < num_readings; i++) {
        free(unique_sensor_ids[i]);
    }
    free(unique_sensor_ids);

    return;
}

int main() {
    int num_readings = MAX_READINGS;
    const char **sensor_ids = (const char **)malloc(num_readings * sizeof(const char *));
    double *temperatures = (double *)malloc(num_readings * sizeof(double));

    // Initialize sensor IDs and temperatures
    for (int i = 0; i < num_readings; i++) {
        sprintf(sensor_ids[i], "Sensor_%d", i);
        temperatures[i] = (double)(rand() % 100); // Random temperature values
    }

    process_temperature_readings(num_readings, sensor_ids, temperatures);

    return 0;
}
