            try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec("your_command", null, targetDir).getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            } catch (IOException e) {
                // Handle IOException
                System.err.println("Error executing command: " + e.getMessage());
            }
        } finally {
            // Memory Cleanup
            offsetValues = null;
            keys = null;

            // Record Pool Management
            for (Record record : records) {
                record.close();
            }
            records.clear();
        }
    }

    private static class Record {
        int value;
        public Record(int value) {
            this.value = value;
        }
        public void close() {
            // Close the record resource
        }
    }
