#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a struct for observations
typedef struct {
    float temperature;
    char *weather_condition;
    time_t timestamp;
} Observation;

// Define the log format
#define LOG_FORMAT "Timestamp: %ld, Temperature: %.2f, Weather Condition: %s\n"

// Create a dynamic array to store observations
Observation **observations = NULL;
size_t observation_count = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void *threadsafe_log(void *arg) {
    Observation *observation = (Observation *) arg;
    pthread_mutex_lock(&log_mutex);
    printf(LOG_FORMAT, observation->timestamp, observation->temperature, observation->weather_condition);
    pthread_mutex_unlock(&log_mutex);
}

int read_csv_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening CSV file");
        return -1;
    }

    // Read the CSV file and store observations in a dynamic array
    Observation **observations = realloc(NULL, sizeof(Observation *));
    size_t observation_count = 0;

    char line[1024];
    while (fgets(line, 1024, file)) {
        Observation *observation = (Observation *)malloc(sizeof(Observation));
        // Parse the CSV line and populate the observation struct
        observation->temperature = atof(strtok(line, ","));
        observation->weather_condition = strtok(NULL, ",");
        observation->timestamp = atol(strtok(NULL, ","));

        observations = realloc(observations, sizeof(Observation *) * (observation_count + 1));
        observations[observation_count++] = observation;
    }

    fclose(file);

    return observation_count;
}

void process_observations(size_t count) {
    // Process each observation concurrently
    pthread_t threads[count];
    for (size_t i = 0; i < count; i++) {
        Observation *observation = observations[i];
        pthread_create(&threads[i], NULL, threadsafe_log, observation);
    }

    for (size_t i = 0; i < count; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    size_t count = read_csv_file("data.csv");
    process_observations(count);

    return 0;
}
