#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    time_t timestamp;
    int status;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->packets = (DataPacket*)calloc(initial_capacity, sizeof(DataPacket));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void free_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; i++) {
        free(array->packets[i].timestamp);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_packet(DynamicArray* array, DataPacket packet) {
    if (array->size == array->capacity) {
        // Double the capacity and resize the array
        array->capacity *= 2;
        array->packets = (DataPacket*)realloc(array->packets, array->capacity * sizeof(DataPacket));
    }
    array->packets[array->size] = packet;
    array->size++;
    return 0;
}

int remove_outdated_packets(DynamicArray* array, time_t expiration_time) {
    for (size_t i = 0; i < array->size; i++) {
        if ((array->packets[i].timestamp + array->packets[i].status) <= expiration_time) {
            // Remove the outdated packet
            memmove(&array->packets[i], &array->packets[i+1], (array->size - i - 1) * sizeof(DataPacket));
            array->size--;
            i--; // Decrement i to recheck this packet again
        }
    }
    return 0;
}

int update_packet_status(DynamicArray* array, int packet_id, int new_status) {
    for (size_t i = 0; i < array->size; i++) {
        if (array->packets[i].id == packet_id) {
            // Update the packet's status
            array->packets[i].status = new_status;
            return 0;
        }
    }
    return -1; // Packet not found
}

int compact_array(DynamicArray* array) {
    size_t new_capacity = array->size * 2;
    DataPacket* new_packets = (DataPacket*)calloc(new_capacity, sizeof(DataPacket));
    for (size_t i = 0; i < array->size; i++) {
        new_packets[i] = array->packets[i];
    }
    free(array->packets);
    array->packets = new_packets;
    array->capacity = new_capacity;
    return 0;
}

void* get_packet_buffer(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    void* buffer = array->packets;
    pthread_mutex_unlock(&array->mutex);
    return buffer;
}

int batch_process_packets(DynamicArray* array, int num_operations) {
    for (int i = 0; i < num_operations; i++) {
        // Perform some operations on the packets...
        add_packet(array, /* packet */);
        remove_outdated_packets(array, /* expiration_time */);
        update_packet_status(array, /* packet_id */, /* new_status */);
    }
    return 0;
}

int main() {
    DynamicArray* array = init_dynamic_array(10);
    // Add packets, remove outdated ones, and update statuses...
    batch_process_packets(array, 5);
    free_dynamic_array(array);
    return 0;
}
