#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <thread>

// Custom hashing function for generating unique 'int' keys
uint32_t hash_function(uint64_t index) {
    return (index * 1103515245 + 12345) % 2147483647;
}

// Thread-safe random number generator for populating record array
uint16_t get_random(uint16_t min, uint16_t max) {
    static uint16_t seed = 0;
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
    seed = (seed * 1103515245 + 12345) % 2147483647;
    return min + (max - min) * (uint16_t)(seed / 65536.0);
}

// Function to manage memory for multiple arrays
void* record_manager(int num_records, int num_offsets, int range_min, int range_max) {
    // Initialize arrays with dynamic memory allocation
    long** offsets = (long**)malloc(num_offsets * sizeof(long*));
    int* keys = (int*)malloc(num_offsets * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation error
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize 'int' keys array with unique values generated by custom hashing function
    for (int i = 0; i < num_offsets; i++) {
        keys[i] = hash_function(i);
    }

    // Populate record array with unique 'int' values within the specified range using thread-safe random number generator
    for (int i = 0; i < num_records; i++) {
        int value = get_random(range_min, range_max);
        records[i].key = keys[i % num_offsets];
        records[i].active = true;
        records[i].offset = (long)malloc(sizeof(long));
        *records[i].offset = (long)value;
    }

    // Return a pointer to the record array while maintaining ownership semantics
    return records;
}

// Record structure definition
typedef struct {
    int key;
    bool active;
    long* offset;
} record;

