#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define CYCLE_DETECTION_THRESHOLD 10

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    int crcflag; // randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int count = 0;

void* allocate_node() {
    return malloc(sizeof(Node));
}

void free_node(void* node) {
    free(node);
}

void insert_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*)allocate_node();
    new_node->data = new_data;
    new_node->next = (*head_ref);
    *head_ref = new_node;
    count++;
}

int check_cycle(Node* node, Node** visited) {
    if (node == NULL)
        return 0;

    Node* current = node;
    while (current != NULL) {
        if ((*visited)[current] == 1)
            return 1; // cycle detected
        (*visited)[current] = 1;
        current = current->next;
    }
    return 0;
}

void serialize_list(Node* head, FILE* file) {
    while (head != NULL) {
        fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        head = head->next;
    }
}

int deserialize_list(Node** head_ref, FILE* file) {
    Node* new_node = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        new_node = (Node*)allocate_node();
        new_node->data = data;
        if (*head_ref == NULL)
            *head_ref = new_node;
        else {
            Node* current = *head_ref;
            while (current->next != NULL)
                current = current->next;
            current->next = new_node;
        }
    }
}

void real_time_monitoring() {
    pthread_mutex_lock(&lock);
    if (count > MAX_LIST_SIZE) {
        // trigger alert
        printf("List size exceeded the maximum threshold\n");
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    FILE* file = fopen("data.txt", "wb+");
    Node* head_ref = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;

    while (1) {
        // generate random data
        // ...

        pthread_mutex_lock(&lock);
        insert_node(&head_ref, data);
        real_time_monitoring();
        pthread_mutex_unlock(&lock);

        if (count > CYCLE_DETECTION_THRESHOLD) {
            Node* visited = malloc(sizeof(Node*) * count);
            for (int i = 0; i < count; i++) {
                visited[i] = NULL;
            }

            for (Node* node = head_ref; node != NULL; node = node->next) {
                if (check_cycle(node, &visited)) {
                    // cycle detected, handle error
                    printf("Cycle detected in the list\n");
                    break;
                }
            }

            free(visited);
        }
    }

    fclose(file);

    return 0;
}
