            allocated_size = 1;
            input_array = (int*)malloc(allocated_size * sizeof(int));
        } else {
            input_array = realloc(input_array, (allocated_size + 1) * sizeof(int));
        }
        input_array[allocated_size - 1] = temp;
        allocated_size++;
    }

    // Code for task 3: find and print the largest integer in the array.
    int find_largest_integer(int* arr, size_t size) {
        if (size == 0) return -1;
        int max = arr[0];
        for (int i = 1; i < size; i++) {
            if (arr[i] > max) max = arr[i];
        }
        return max;
    }

    printf("%d\n", find_largest_integer(input_array, allocated_size));

    // Code to handle memory deallocation.
    free(input_array);

    return (NFAPI_CRC_INDICATION_PDU_T){0};
}
