#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TEMPERATURE_READINGS 1000
#define MAX_SENSOR_IDS 100
#define QUALITY_FLAG_SIZE sizeof(char)
#define DATA_LIMIT (1 * 1024 * 1024) // 1 MB

typedef enum {
    GOOD,
    FAIR,
    POOR
} quality_flags;

typedef struct {
    float temperature;
    char sensor_id;
    quality_flags quality;
} measurement_t;

void process_temperature_data(float* temperatures, char** sensor_ids, enum quality_flags* quality_flags, int num_measurements) {
    // Dynamic memory allocation and initialization
    int total_elements = num_measurements * 3;
    void* data = malloc(total_elements * sizeof(*temperatures));
    if (!data) {
        printf("Memory allocation failed.\n");
        return;
    }

    measurement_t* measurements = (measurement_t*) data;

    // Measurement struct management
    int i;
    for (i = 0; i < num_measurements; i++) {
        measurements[i].temperature = temperatures[i];
        strcpy(&measurements[i].sensor_id, sensor_ids[i]);
        measurements[i].quality = quality_flags[i];
    }

    // Quality filtering
    float moving_average = 0.0;
    int filtered_measurements = 0;
    for (i = 0; i < num_measurements; i++) {
        if (measurements[i].quality > GOOD) {
            moving_average += measurements[i].temperature;
            filtered_measurements++;
        }
    }

    if (filtered_measurements > 0) {
        moving_average /= filtered_measurements;
    } else {
        // Handle edge case where all data is low quality
        printf("All data points are low quality.\n");
        return;
    }

    // Moving average calculation
    float window_average = 0.0;
    for (i = 0; i < num_measurements; i++) {
        if (i >= filtered_measurements) {
            continue;
        }
        window_average += measurements[i].temperature;
    }
    window_average /= filtered_measurements;

    // Error handling and integration
    FILE* log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        printf("Error opening log file.\n");
        return;
    }

    fprintf(log_file, "Temperature: %f\n", moving_average);
    fclose(log_file);

    free(data);
}
