typedef enum {
    EVENT_TYPE_NETWORK_ERROR,
    EVENT_TYPE_SERVER_RESPONSE,
    EVENT_TYPE_CLIENT_DISCONNECT,
    EVENT_TYPE_UNKNOWN
} EventType;

// Union to store event data
union EventData {
    int networkError;
    char* serverResponse;
    int clientDisconnect;
};

// Custom NetworkEvent structure
typedef struct {
    time_t timestamp;
    EventType type;
    union EventData data;
} NetworkEvent;

// Function to manage a dynamically allocated array of custom NetworkEvent structures
NetworkEvent** manageEvents(int N) {
    // Initialize the array with N events, each containing a Timestamp, EventType, and EventData
    NetworkEvent** events = (NetworkEvent**)calloc(N, sizeof(NetworkEvent*));

    int uniqueEvents = 0;
    srand(time(NULL));  // Seed the random number generator

    // Populate the array with N events
    for(int i = 0; i < N; i++) {
        events[i] = (NetworkEvent*)malloc(sizeof(NetworkEvent));

        // Randomly select an event type and populate the corresponding EventData
        EventType type;
        if(rand() % 3 == 0) {
            type = EVENT_TYPE_NETWORK_ERROR;
            events[i]->data.networkError = rand();
        } else if(rand() % 2 == 0) {
            type = EVENT_TYPE_SERVER_RESPONSE;
            events[i]->data.serverResponse = (char*)malloc(64);
            sprintf(events[i]->data.serverResponse, "Server response: %d", i);
        } else {
            type = EVENT_TYPE_CLIENT_DISCONNECT;
            events[i]->data.clientDisconnect = rand();
        }

        // Set the event timestamp and type
        events[i]->timestamp = time(NULL);
        events[i]->type = type;
    }

    return events;
}

// Function to release dynamically allocated memory for NetworkEvent structures
void freeEvents(NetworkEvent** events, int N) {
    for(int i = 0; i < N; i++) {
        if(events[i]->data.serverResponse)
            free(events[i]->data.serverResponse);
        free(events[i]);
    }
    free(events);
}

int main() {
    // Example usage
    int N = 10;
    NetworkEvent** events = manageEvents(N);

    // Process the events...

    freeEvents(events, N);

    return 0;
}
