typedef struct {
    int phich_config;
    int ue_id;
    char* dl_mch_data_tag;
} LTE_PHY_LAYER_CONTROL_MESSAGE;

LTE_PHY_LAYER_CONTROL_MESSAGE* lte_phy_layer_control_messages[MAX_MESSAGES];
int message_count = 0;

void* create_message_thread(void* args) {
    int message_idx = *(int*)args;
    LTE_PHY_LAYER_CONTROL_MESSAGE* message = (LTE_PHY_LAYER_CONTROL_MESSAGE*)malloc(sizeof(LTE_PHY_LAYER_CONTROL_MESSAGE));

    if (!message) {
        // Handle memory allocation failure
        printf("Memory allocation failed for message %d\n", message_idx);
        return NULL;
    }

    int phich_config = 0; // fetch from external data source
    int ue_id = 0; // fetch from external data source

    char* dl_mch_data_tag = (char*)malloc(MAX_BUFFER_SIZE);
    if (!dl_mch_data_tag) {
        // Handle memory allocation failure
        printf("Memory allocation failed for message %d\n", message_idx);
        free(message);
        return NULL;
    }

    // Set PHICH_CONFIGURATION, UE_ID, and DL_MCH_DATA_TAG fields
    message->phich_config = phich_config;
    message->ue_id = ue_id;
    message->dl_mch_data_tag = dl_mch_data_tag;

    lte_phy_layer_control_messages[message_idx] = message;
    message_count++;

    return NULL;
}

void destroy_message(LTE_PHY_LAYER_CONTROL_MESSAGE* message) {
    if (!message)
        return;

    free(message->dl_mch_data_tag);
    free(message);
}

void init_lte_phy_layer_control_messages() {
    for (int i = 0; i < MAX_MESSAGES; i++) {
        lte_phy_layer_control_messages[i] = NULL;
    }
}

void* lte_phy_layer_control_message_thread(void* args) {
    int operation_type = *(int*)args;

    if (operation_type == 1) {
        // Single message creation
        int message_idx = message_count++;
        pthread_t thread;
        int* idx = &message_idx;
        pthread_create(&thread, NULL, create_message_thread, idx);
        pthread_join(thread, NULL);
    } else {
        // Batch message creation
        for (int i = 0; i < 100; i++) {
            pthread_t thread;
            int* idx = &i;
            pthread_create(&thread, NULL, create_message_thread, idx);
            pthread_join(thread, NULL);
        }
    }

    return NULL;
}

