typedef struct {
    unsigned int data;
    float cqi;
} PDSCH_STRUCT;

typedef struct {
    DL_FRAME_HEADER frame_header;
    PDSCH_STRUCT pdsch_symbol;
    char *pdsch_data;
    float cqi;
} LTE_DL_FRAME_STRUCT;

void custom_hash_function(const char *str, unsigned int *hash) {
    int i;
    unsigned int temp = 0;
    for(i = 0; i < strlen(str); i++) {
        temp = (temp << 4) ^ (unsigned int)(str[i]);
    }
    *hash = temp;
}

LTE_DL_FRAME_STRUCT **initializeDynamicFrameArray(int length, char characterSet[], int *hashValue) {
    LTE_DL_FRAME_STRUCT **frames = (LTE_DL_FRAME_STRUCT **)malloc(length * sizeof(LTE_DL_FRAME_STRUCT *));
    if(frames == NULL) return NULL;

    for(int i = 0; i < length; i++) {
        frames[i] = (LTE_DL_FRAME_STRUCT *)malloc(sizeof(LTE_DL_FRAME_STRUCT));
        if(frames[i] == NULL) {
            free(frames);
            return NULL;
        }

        DL_FRAME_HEADER frame_header;
        frame_header.header = rand();
        frame_header.symbol = characterSet[rand() % strlen(characterSet)];

        PDSCH_STRUCT pdsch_symbol;
        pdsch_symbol.data = rand();
        pdsch_symbol.cqi = (float)rand() / RAND_MAX;

        frames[i]->frame_header = frame_header;
        frames[i]->pdsch_symbol = pdsch_symbol;

        char *random_string = (char *)malloc((rand() % 10) + 1);
        if(random_string == NULL) {
            free(frames[i]);
            free(frames);
            return NULL;
        }

        for(int j = 0; j < strlen(random_string); j++) {
            random_string[j] = characterSet[rand() % strlen(characterSet)];
        }
        random_string[(rand() % 10)] = '\0';

        frames[i]->pdsch_data = random_string;

        float cqi = (float)rand() / RAND_MAX;
        frames[i]->cqi = cqi;

        custom_hash_function(random_string, hashValue);
    }

    return frames;
}

