```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the maximum memory limit
#define MAX_MEMORY 1024 * 1024 * 100 // 100MB

// Function to dynamically allocate and manage record arrays
Record** manageMemory(int* n, int maxMemory) {
    Record** records = NULL;
    if (*n > 0 && *n <= (maxMemory / sizeof(Record))) {
        records = (Record**)malloc(*n * sizeof(Record*));
        for (int i = 0; i < *n; i++) {
            records[i] = malloc(sizeof(Record));
        }
    } else if (*n > 0) {
        // Reduce n to fit within the allowed limit
        int newN = maxMemory / sizeof(Record);
        *n = newN;
        records = (Record**)malloc(newN * sizeof(Record*));
        for (int i = 0; i < newN; i++) {
            records[i] = malloc(sizeof(Record));
        }
    } else {
        // Handle edge case: invalid input size
        printf("Invalid input size. Aborting.\n");
    }
    return records;
}

// Function to populate and log record generation
void generateRecords(int* n, Record** records, FILE* logFile) {
    if (records != NULL) {
        for (int i = 0; i < *n; i++) {
            records[i]->offset = (long)(rand() % 10000000); // Generate random offset
            records[i]->key = rand() % 100 - 50; // Generate random key and value
            records[i]->value = rand() % 101 - 50;
            fprintf(logFile, "Record %d: offset=0x%x, key=%d, value=%d\n", i, records[i]->offset, records[i]->key, records[i]->value);
        }
    }
}

// Function to free allocated memory
void freeMemory(int* n, Record** records) {
    if (records != NULL) {
        for (int i = 0; i < *n; i++) {
            free(records[i]);
        }
        free(records);
    }
}

// API function to query record count
int getRecordCount(Record** records) {
    return (records == NULL) ? 0 : sizeof(*records);
}

// API function to iterate over records in reverse order
void iterateRecords(int* n, Record** records) {
    if (records != NULL) {
        for (int i = *n - 1; i >= 0; i--) {
            printf("Record %d: offset=0x%x, key=%d, value=%d\n", i, records[i]->offset, records[i]->key, records[i]->value);
        }
    }
}

int main() {
    int n = 100;
    Record** records = NULL;
    FILE* logFile = fopen("record_generation.log", "w");
    if (records == NULL) {
        // Dynamically allocate and manage record arrays
        records = manageMemory(&n, MAX_MEMORY);
    }
    generateRecords(&n, records, logFile);
    iterateRecords(&n, records);
    freeMemory(&n, records);
    return 0;
}
