typedef struct {
    int count;
    time_t last_query;
} query_limit_t;

query_limit_t query_limit = { 0, 0 };

void set_query_limit(int count, time_t interval) {
    query_limit.count = count;
    query_limit.last_query = time(NULL) - (int)interval;
}

char* resolve_hostname(char* hostname) {
    struct hostent *he;
    char buffer[1024];
    int len;

    if ((he = gethostbyname(hostname)) == NULL) {
        return "Error: Hostname not found";
    }

    inet_ntop(AF_INET, (struct in_addr*) he->h_addr, buffer, sizeof(buffer));
    len = strlen(buffer);
    char* ip = malloc(len + 1);
    strcpy(ip, buffer);

    if (query_limit.count > 0) {
        time_t current_time = time(NULL);
        if ((current_time - query_limit.last_query) / 86400 >= query_limit.count) {
            set_query_limit(0, 0);
        } else {
            query_limit.count--;
        }
    }

    return ip;
}

