#define MAX_OFFSET 10000

typedef struct {
    long offset;
    int key;
} record;

record* generate_records(int num_offsets, int num_keys, int num_records) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for arrays
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    int* keys = (int*)malloc(num_keys * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    // Generate unique keys
    int key_count = 1;
    for (int i = 0; i < num_keys; i++) {
        keys[i] = key_count++;
    }

    // Generate offsets
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % MAX_OFFSET;
    }

    // Integrate with external key generation service
    int* cached_keys = (int*)malloc(num_keys * sizeof(int));
    int cache_size = 10;
    int cache_index = 0;

    for (int i = 0; i < num_records; i++) {
        long offset = offsets[rand() % num_offsets];
        int key = keys[rand() % num_keys];

        if (key_count > num_keys) {
            key = cached_keys[cache_index++ % cache_size];
        } else {
            key = key_count++;
        }

        records[i].offset = offset;
        records[i].key = key;
    }

    // Return pointer to record array
    return records;
}

void free_memory(record* records, long* offsets, int* keys) {
    if (records != NULL) {
        free(records);
    }
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
}
