#define MAX_INTS 1000
#define RANGE_MIN 1
#define RANGE_MAX 10000

int* process_stream(int sock, int* size) {
    int i = 0;
    int ints[MAX_INTS];
    while (i < *size && read(sock, &ints[i], sizeof(int)) > 0) {
        if (ints[i] < RANGE_MIN || ints[i] > RANGE_MAX) {
            // Handle invalid integer
            printf("Invalid integer: %d\n", ints[i]);
            free(ints);
            return NULL;
        }
        i++;
    }

    int* valid_ints = (int*)malloc((i + 1) * sizeof(int));
    for (int j = 0; j < i; j++) {
        valid_ints[j] = ints[j];
    }
    valid_ints[i] = 0;

    free(ints);
    *size = i;
    return valid_ints;
}

void print_largest_integer(int* valid_ints, int size) {
    if (size == 0) {
        printf("No valid integers processed.\n");
    } else {
        int max = valid_ints[0];
        for (int i = 1; i < size; i++) {
            if (valid_ints[i] > max) {
                max = valid_ints[i];
            }
        }
        printf("Largest integer: %d\n", max);
    }
}
