#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SESSIONS 1000

typedef struct {
    int data;
} NFAPI_DL_FRAMEINFO;

struct session_pool {
    int max_sessions;
    int num_active_sessions;
    NFAPI_DL_FRAMEINFO **sessions;
    pthread_mutex_t lock;
};

session_pool *init_session_pool(int max_sessions) {
    session_pool *pool = (session_pool *)malloc(sizeof(session_pool));
    pool->max_sessions = max_sessions;
    pool->num_active_sessions = 0;
    pool->sessions = (NFAPI_DL_FRAMEINFO **)calloc(max_sessions, sizeof(NFAPI_DL_FRAMEINFO *));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void shutdown_session_pool(session_pool *pool) {
    for (int i = 0; i < pool->num_active_sessions; i++) {
        free(pool->sessions[i]);
    }
    free(pool->sessions);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_session(session_pool *pool, NFAPI_DL_FRAMEINFO *info) {
    if (pool->num_active_sessions >= pool->max_sessions) {
        return -1; // Session limit exceeded
    }

    info = malloc(sizeof(NFAPI_DL_FRAMEINFO));
    if (info == NULL) {
        return -2; // Memory allocation failure
    }

    pthread_mutex_lock(&pool->lock);
    pool->sessions[pool->num_active_sessions++] = info;
    pthread_mutex_unlock(&pool->lock);

    return 0; // Session added successfully
}

int remove_session(session_pool *pool, int session_id) {
    if (session_id >= pool->num_active_sessions || session_id < 0) {
        return -1; // Invalid session ID
    }

    pthread_mutex_lock(&pool->lock);
    free(pool->sessions[session_id]);
    for (int i = session_id; i < pool->num_active_sessions - 1; i++) {
        pool->sessions[i] = pool->sessions[i + 1];
    }
    pool->num_active_sessions--;
    pthread_mutex_unlock(&pool->lock);

    return 0; // Session removed successfully
}

int get_num_active_sessions(session_pool *pool) {
    return pool->num_active_sessions;
}
