#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16

typedef struct {
    char hostname[MAX_HOSTNAME];
    u_char ip_address[MAX_IP_ADDRESS];
} HostInfo;

HostInfo* dns_resolve(char* hostname) {
    HostInfo* result = (HostInfo*)malloc(sizeof(HostInfo));
    strcpy(result->hostname, hostname);

    // Perform DNS resolution
    struct hostent* hostinfo = gethostbyname(hostname);
    if (!hostinfo) {
        free(result);
        return NULL;
    }

    inet_ntop(AF_INET, hostinfo->h_addr_list[0], (char*)result->ip_address, MAX_IP_ADDRESS);
    return result;
}

int main() {
