typedef struct {
    int key;
    long offset;
} record_t;

record_t* manage_records(int numRecords, int minValue, int maxValue, int unique) {
    // Allocate memory for the arrays
    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));
    long* offsets = (long*)malloc(numRecords * sizeof(long));

    if (!records || !offsets) {
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < numRecords; i++) {
        record_t* record = &records[i];
        long offset = (long)i * 100 + rand() % 10;
        int key = unique ? (rand() % (maxValue - minValue)) + minValue : i;

        // Initialize the record
        record->key = key;
        record->offset = offset;

        // Update the offset array
        offsets[i] = offset;
    }

    // Serialize and store the data
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        free(records);
        free(offsets);
        return NULL;
    }

    fwrite(&numRecords, sizeof(int), 1, file);
    fwrite(records, sizeof(record_t), numRecords, file);
    fwrite(offsets, sizeof(long), numRecords, file);

    fclose(file);

    // Deallocate memory
    free(records);
    free(offsets);

    return records;
}
