#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    double value;
} entry_t;

typedef struct {
    entry_t** entries;
    int size;
    int capacity;
} collection_t;

void init_collection(collection_t* coll) {
    coll->size = 0;
    coll->capacity = 10; // initial capacity
    coll->entries = malloc(coll->capacity * sizeof(entry_t*));
}

int insert_entry(collection_t* coll, char* key, double value) {
    if (coll->size >= coll->capacity) {
        // resize the collection
        int new_capacity = coll->capacity * 2;
        entry_t** new_entries = realloc(coll->entries, new_capacity * sizeof(entry_t*));
        if (!new_entries) return -1; // memory allocation failure

        coll->capacity = new_capacity;
        coll->entries = new_entries;
    }

    entry_t* new_entry = malloc(sizeof(entry_t));
    if (!new_entry) return -1; // memory allocation failure

    new_entry->key = strdup(key);
    new_entry->value = value;

    coll->entries[coll->size] = new_entry;
    coll->size++;

    return 0;
}

int update_entry(collection_t* coll, char* key, double value) {
    for (int i = 0; i < coll->size; i++) {
        if (strcmp(coll->entries[i]->key, key) == 0) {
            coll->entries[i]->value = value;
            return 0;
        }
    }

    return -1; // not found
}

int remove_entry(collection_t* coll, char* key) {
    for (int i = 0; i < coll->size; i++) {
        if (strcmp(coll->entries[i]->key, key) == 0) {
            free(coll->entries[i]->key);
            free(coll->entries[i]);
            memmove(&coll->entries[i], &coll->entries[i + 1], (coll->size - i - 1) * sizeof(entry_t*));
            coll->size--;
            return 0;
        }
    }

    return -1; // not found
}

double search_entry(collection_t* coll, char* key) {
    for (int i = 0; i < coll->size; i++) {
        if (strcmp(coll->entries[i]->key, key) == 0) {
            return coll->entries[i]->value;
        }
    }

    return -1.0; // not found
}

void free_collection(collection_t* coll) {
    for (int i = 0; i < coll->size; i++) {
        free(coll->entries[i]->key);
        free(coll->entries[i]);
    }

    free(coll->entries);
}
