    // Initialize the dynamic array to store messages
    ltePHYControlMessage** message_array = (ltePHYControlMessage**)malloc(10000 * sizeof(ltePHYControlMessage*));

    // Initialize the external message processing service queue
    pthread_mutex_init(&service_queue_mutex, NULL);
    pthread_cond_init(&service_queue_cond, NULL);

    int i;
    for(i=0; i<10000; i++) {
        message_array[i] = (ltePHYControlMessage*)malloc(sizeof(ltePHYControlMessage));
    }

