    int max_messages_per_second = 1000;
    int retransmit_count = 0;

    while(1) {
        // Monitor system load and adjust resource usage dynamically
        if(system_load > 80) {
            // Adjust message processing rate based on system load
            max_messages_per_second *= 2;
        } else if(system_load < 20) {
            // Adjust message processing rate based on system load
            max_messages_per_second /= 2;
        }

        // Process incoming control messages from the external service
        while(1) {
            pthread_mutex_lock(&service_queue_mutex);
            if(service_queue_size > 0) {
