typedef struct {
    int key;
    long offset;
} record_t;

void process_records(int num_records) {
    // Allocate memory for and initialize arrays
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100;
        records[i].offset = (long)rand();
        keys[i] = rand() % 100;
        offsets[i] = (long)rand();
    }

    // Initialize random seed for global uniqueness
    int seed = time(NULL);
    srand(seed);

    // Enforce global uniqueness of random values
    for (int i = 0; i < num_records - 1; i++) {
        while (records[i].key == records[i + 1].key) {
            records[i + 1].key = rand() % 100;
        }
    }

    // Free memory
    free(records);
    free(offsets);
    free(keys);

    // Write records to file
    FILE* f = fopen("records.txt", "w");
    for (int i = 0; i < num_records; i++) {
        fprintf(f, "%d %ld\n", records[i].key, records[i].offset);
    }
    fclose(f);
}

int main() {
    process_records(100000);
    return 0;
