#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SEMAPHORES 1000
#define SEMAPHORE_NAME_MAX_LENGTH 32

typedef struct {
    char name[SEMAPHORE_NAME_MAX_LENGTH];
    int value;
} SemaphoreRecord;

SemaphoreRecord *semaphores = NULL;
int semaphore_count = 0;

// Function to create a new semaphore with the given name and initial value
int create_semaphore(const char *name, int value) {
    if (semaphore_count >= MAX_SEMAPHORES) {
        return -1; // Error: Too many semaphores created
    }

    SemaphoreRecord *new_semaphore = (SemaphoreRecord *)malloc(sizeof(SemaphoreRecord));
    strcpy(new_semaphore->name, name);
    new_semaphore->value = value;

    semaphores = realloc(semaphores, sizeof(SemaphoreRecord) * ++semaphore_count);
    semaphores[semaphore_count - 1] = new_semaphore;

    return semaphore_count - 1; // Success: Return the index of the created semaphore
}

// Function to delete a semaphore by its name
int delete_semaphore(const char *name) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i]->name, name) == 0) {
            free(semaphores[i]);
            semaphores[i] = semaphores[--semaphore_count];
            return 1; // Success: Semaphore deleted
        }
    }

    return -1; // Error: Semaphore not found
}

// Function to get the value of a semaphore by its name
int get_semaphore_value(const char *name) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i]->name, name) == 0) {
            return semaphores[i]->value;
        }
    }

    return -1; // Error: Semaphore not found
}

// Function to set the value of a semaphore by its name
int set_semaphore_value(const char *name, int value) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i]->name, name) == 0) {
            semaphores[i]->value = value;
            return 1; // Success: Value set
        }
    }

    return -1; // Error: Semaphore not found
}

// Function to handle system monitoring and logging
void *monitoring_thread(void *arg) {
    while (1) {
        // Monitor semaphore operations and log relevant information
        printf("Semaphore operations monitored.\n");
        sleep(5); // Simulate monitoring interval
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread;

    if (pthread_create(&monitor_thread, NULL, monitoring_thread, NULL) != 0) {
        return -1; // Error: Monitoring thread creation failed
    }

    // Example usage:
    int semaphore_index = create_semaphore("my_semaphore", 500);
    if (semaphore_index < 0) {
        printf("Error: Semaphore creation failed.\n");
    } else {
        printf("Semaphore created successfully.\n");

        int value = get_semaphore_value("my_semaphore");
        if (value >= 0) {
            printf("Initial semaphore value: %d\n", value);
        }

        set_semaphore_value("my_semaphore", 800);
        value = get_semaphore_value("my_semaphore");
        if (value >= 0) {
            printf("Semaphore value updated to: %d\n", value);
        }
    }

    // Shutdown procedure
    pthread_join(monitor_thread, NULL);

    for (int i = 0; i < semaphore_count; i++) {
        free(semaphores[i]);
    }
    free(semaphores);

    return 0;
}
