    int value;
} record_t;

void process_records(int num_records) {
    // Allocate memory for offset, key, and record arrays
    long* offsets = (long*) aligned_malloc(num_records * sizeof(long), 16);
    int* keys = (int*) aligned_malloc(num_records * sizeof(int), 4);
    record_t* records = (record_t*) aligned_malloc(num_records * sizeof(record_t), 8);

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = (long) i;
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;

        if (i > 0 && keys[i] == keys[i - 1]) {
            keys[i]++;
        }
    }

    // Integrate with external data storage system
    FILE* file = fopen("data.txt", "wb");
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(record_t), 1, file);
    }
    fclose(file);

    // Handle memory leaks
    aligned_free(offsets);
    aligned_free(keys);
    aligned_free(records);
}

void* aligned_malloc(size_t size, size_t alignment) {
    size_t overhead = (size + alignment - 1) & ~(alignment - 1);
    void* ptr = malloc(overhead);
    return ptr;
}

void aligned_free(void* ptr) {
    free(ptr);
}
