#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <rand.h>

#define MAX_RECORDS 10000000
#define RAND_RANGE 1000

typedef struct {
    int key;
    long offset;
} record_t;

void init_arrays(int num_records, long** offsets, int** keys) {
    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = rand() % RAND_RANGE;
        (*keys)[i] = rand() % RAND_RANGE;
    }
}

void persist_records(int num_records, record_t* records) {
    FILE* file = fopen("records.txt", "w");
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d %ld\n", records[i].key, records[i].offset);
    }
    fclose(file);
}

void init_and_persist(int num_records) {
    long* offsets;
    int* keys;

    init_arrays(num_records, &offsets, &keys);

    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % RAND_RANGE;
        while (i > 0 && records[i].key == records[i-1].key) {
            records[i].key = rand() % RAND_RANGE;
        }
        records[i].offset = offsets[i];
    }

    persist_records(num_records, records);

    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char** argv) {
    int num_records = atoi(argv[1]);
    init_and_persist(num_records);
    return 0;
}
