#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>

// Define a structure for network device context
typedef struct {
    void* buffer; // packet buffer
    int config_params; // configuration parameters for network interfaces
} NetworkContext;

// Define a union-find data structure to manage disjoint pairs of network contexts
typedef struct {
    int* parent;
    int* rank;
} UnionFind;

void init_contexts(NetworkContext** contexts, int num_contexts) {
    // Allocate memory for each context and initialize configuration parameters
    for (int i = 0; i < num_contexts; i++) {
        contexts[i] = malloc(sizeof(NetworkContext));
        if (!contexts[i]) {
            perror("Memory allocation failed");
            exit(1);
        }
        contexts[i]->buffer = NULL;
        contexts[i]->config_params = 0;
    }
}

int find(UnionFind* uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void union_sets(UnionFind* uf, int x, int y) {
    int root_x = find(uf, x);
    int root_y = find(uf, y);
    if (root_x != root_y) {
        if (uf->rank[root_x] < uf->rank[root_y])
            uf->parent[root_x] = root_y;
        else if (uf->rank[root_x] > uf->rank[root_y])
            uf->parent[root_y] = root_x;
        else {
            uf->parent[root_y] = root_x;
            uf->rank[root_x]++;
        }
    }
}

int count_disjoint_pairs(NetworkContext** contexts, int num_contexts) {
    UnionFind uf;
    uf.parent = calloc(num_contexts, sizeof(int));
    uf.rank = calloc(num_contexts, sizeof(int));

    for (int i = 0; i < num_contexts; i++)
        uf.parent[i] = i;

    for (int i = 0; i < num_contexts; i++) {
        for (int j = i + 1; j < num_contexts; j++) {
            // Perform union operation on disjoint pairs
            if (find(&uf, i) != find(&uf, j)) {
                printf("Disjoint pair found: %d and %d\n", i, j);
                int time_taken = usleep(100000); // simulate latency in milliseconds
                printf("Time taken to check pair: %d ms\n", time_taken / 1000);
                union_sets(&uf, i, j);
            }
        }
    }

    free(uf.parent);
    free(uf.rank);

    return uf->rank[0] - 1; // count of disjoint pairs
}

int main() {
    int num_contexts = 5;
    NetworkContext* contexts = NULL;

    init_contexts(&contexts, num_contexts);

    int disjoint_pairs = count_disjoint_pairs(contexts, num_contexts);

    printf("Number of disjoint pairs: %d\n", disjoint_pairs);

    for (int i = 0; i < num_contexts; i++)
        free(contexts[i]);

    return 0;
}
