#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int priority;
    int data;
    struct Node* next;
} Node;

Node* queue = NULL;
int size = 0;

void enqueue(int priority, int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->priority = priority;
    newNode->data = data;
    newNode->next = queue;
    queue = newNode;
}

int dequeue() {
    if (queue == NULL) {
        printf("Queue is empty\n");
        return -1; // or any error value
    }
    int data = queue->data;
    Node* temp = queue;
    queue = queue->next;
    free(temp);
    size--;
    return data;
}

int isEmpty() {
    return (queue == NULL) ? 1 : 0;
}

int front() {
