typedef enum {
    ESTABLISHED,
    CLOSE_WAIT,
    LAST_ACK
} ConnectionState;

typedef struct {
    int conn_id;
    time_t timestamp;
    char remote_ip[16];
    char local_ip[16];
    uint16_t remote_port, local_port;
    ConnectionState state;
} ConnectionStateStruct;

struct {
    pthread_mutex_t lock;
    ConnectionStateStruct** states;
    size_t capacity;
    size_t count;
} connection_manager;

void* allocate_connection_state(size_t size) {
    return malloc(size);
}

void free_connection_state(void* ptr) {
    free(ptr);
}

int init_connection_manager() {
    pthread_mutex_init(&connection_manager.lock, NULL);
    connection_manager.states = (ConnectionStateStruct**)malloc(sizeof(ConnectionStateStruct*) * 10);
    connection_manager.capacity = 10;
    connection_manager.count = 0;
    return 0;
}

void add_connection_state(ConnectionState state) {
    ConnectionStateStruct* new_state = allocate_connection_state(sizeof(ConnectionStateStruct));
    // ... initialize state fields
    pthread_mutex_lock(&connection_manager.lock);
    if (connection_manager.count == connection_manager.capacity) {
        connection_manager.states = realloc(connection_manager.states, sizeof(ConnectionStateStruct*) * (connection_manager.capacity *= 2));
    }
    connection_manager.states[connection_manager.count++] = new_state;
    pthread_mutex_unlock(&connection_manager.lock);
}

void remove_connection_state(int conn_id) {
    pthread_mutex_lock(&connection_manager.lock);
    for (size_t i = 0; i < connection_manager.count; ++i) {
        if (connection_manager.states[i]->conn_id == conn_id) {
            free(connection_manager.states[i]);
            memmove(connection_manager.states + i, connection_manager.states + i + 1, sizeof(ConnectionStateStruct*) * (connection_manager.count - i));
            connection_manager.count--;
            break;
        }
    }
    pthread_mutex_unlock(&connection_manager.lock);
}

void log_connection_state(int conn_id) {
    // ... use existing logging framework
}
