NFAPI_CRC_INDICATION_PDU_T* process_nfaapi_and_find_max(int N) {
    NFAPI_CRC_INDICATION_PDU_T* nfaapis = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        nfaapis[i].RX_UE_INFORMATION_TAG = i;
        nfaapis[i].RNTI = rand() % 100;

        if ((nfaapis[i].CRCFLAG = rand() % 2) == 1) {
            nfaapis[i].CRCFLAG = 0;
        }
    }

    int* integers = (int*)malloc(1024 * sizeof(int));
    FILE* file = fopen("data.txt", "r");
    if (!file) {
        printf("Failed to open data file.\n");
        return NULL;
    }

    int count = 0;
    int integer;
    while (fscanf(file, "%d\n", &integer) == 1) {
        integers[count] = integer;
        count++;
    }

    fclose(file);

    if (count > 1024) {
        printf("Array too large.\n");
        return NULL;
    }

    int largest_integer = find_largest_integer(integers, count);

    free(integers);
    free(nfaapis);

    return NULL;
}

int find_largest_integer(int* integers, int count) {
    if (count == 0) {
        return INT_MAX;
    }

    int largest = integers[0];
    for (int i = 1; i < count; i++) {
        if (integers[i] > largest) {
            largest = integers[i];
        }
    }

    return largest;
}
