};

struct CRC_INDICATION_REL8_TAG {
    int CRCflag;
};

void xml2NFAPI_CRC_INDICATION_PDU_T(const char* filename, int num_structures) {
    xmlDocPtr doc = NULL;
    xmlNodePtr root = NULL;
    xmlAttrPtr attr = NULL;

    for(int i=0; i<num_structures; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *nfacrc = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_TAG));

        // Read XML
        doc = xmlReadFile(filename, NULL, XML_PARSE_NOERROR | XML_PARSE_NOWARNING);
        if (doc == NULL) {
            free(nfacrc);
            continue;
        }

        root = xmlDocGetRootElement(doc);
        attr = xmlGetProp(root, "tile-size");
        if(attr != NULL) {
            // Populate NFAPI_CRC_INDICATION_PDU_T structure
            strcpy(nfacrc->RX_UE_INFORMATION_TAG, (char*)xmlNodeGetContent(attr));
            nfacrc->RNTI = atoi(xmlNodeGetContent(attr));

            attr = xmlGetProp(root, "camera-speed");
            if(attr != NULL) {
                nfacrc->CRCFLAG = (struct CRC_INDICATION_REL8_TAG*)malloc(sizeof(struct CRC_INDICATION_REL8_TAG));
                nfacrc->CRCFLAG->CRCflag = atoi(xmlNodeGetContent(attr));
            }
        }

        // Free XML
        xmlFreeDoc(doc);
    }
}
