// Define a measurement structure with timestamp, sensor_id, and value
typedef struct {
    long timestamp;
    int sensor_id;
    float value;
} measurement;

// Function to manage memory allocation for arrays of 'long' timestamp values,
// 'float' sensor readings, and 'measurement' structures
int* manage_memory(int n_timestamps, int n_sensors, int** measurements, 
                    int* active_measurements, int* max_active_measurements) {
    // Initialize variables
    int i;
    measurement* temp_meas = NULL;
    long* timestamps = (long*)malloc(n_timestamps * sizeof(long));
    float* sensor_readings = (float*)malloc(n_sensors * sizeof(float));

    // Check if memory allocation was successful
    if (timestamps == NULL || sensor_readings == NULL) {
        return -1;  // Memory allocation failed
    }

    // Initialize active_measurements and max_active_measurements
    *active_measurements = 0;
    *max_active_measurements = n_timestamps;

    // Allocate memory for the measurements array
    *measurements = (int**)malloc(n_timestamps * sizeof(int*));
    if (*measurements == NULL) {
        free(timestamps);
        free(sensor_readings);
        return -1;  // Memory allocation failed
    }

    // Initialize the first timestamp and sensor reading
    timestamps[0] = 0;
    for (i = 0; i < n_sensors; i++) {
        sensor_readings[i] = 0.0f;
    }

    // Dynamically allocate memory for each measurement structure
    temp_meas = (measurement*)malloc(n_timestamps * sizeof(measurement));
    if (temp_meas == NULL) {
        free(timestamps);
        free(sensor_readings);
        free(*measurements);
        return -1;  // Memory allocation failed
    }

    // Copy data into the measurement structures
    for (i = 0; i < n_timestamps; i++) {
        temp_meas[i].timestamp = timestamps[i];
        temp_meas[i].sensor_id = i;
        temp_meas[i].value = sensor_readings[i];
    }

    // Store the timestamp, sensor reading, and measurement in the array
    for (i = 0; i < n_timestamps; i++) {
        (*measurements)[i] = &temp_meas[i];
    }

    return 0;  // Memory allocation successful
}
