void resize_records(data_record ***records, int *count) {
    *count *= 2;
    data_record **new_records = realloc(*records, sizeof(data_record *) * (*count));
    if (!new_records) {
        printf("Error: Unable to allocate memory for records.\n");
        exit(1);
    }
    *records = new_records;
}

int find_key_index(data_record **records, int count, int key) {
    for (int i = 0; i < count; i++) {
        if (records[i]->key == key) {
            return i;
        }
    }
    return -1;
}

data_record *create_new_record(int new_key) {
    data_record *new_rec = malloc(sizeof(data_record));
    if (!new_rec) {
        printf("Error: Unable to allocate memory for new record.\n");
        exit(1);
    }
    new_rec->key = new_key;
    new_rec->value = (double)rand() / RAND_MAX;
    new_rec->offset = (long)rand();
    return new_rec;
}

void free_records(data_record **records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(records);
}

int main() {
    srand(time(NULL));

    int record_count = 10;
    data_record **records = malloc(sizeof(data_record *) * record_count);
    if (!records) {
        printf("Error: Unable to allocate memory for records.\n");
        exit(1);
    }

    for (int i = 0; i < record_count; i++) {
        int new_key = rand();
        data_record *new_rec = create_new_record(new_key);
        while (find_key_index(records, i + 1, new_key) != -1) {
            new_key = rand();
            new_rec = create_new_record(new_key);
        }
        records[i] = new_rec;
    }

    int max_count = record_count;
    for (; ; ) {
        printf("Enter an option: \n");
        printf("1. Add a record\n");
        printf("2. Remove a record\n");
        printf("3. Check memory usage\n");
        printf("4. Exit the program\n");

