        scanf("%d", &option);

        if (option == 1) {
            int new_key = rand();
            data_record *new_rec = create_new_record(new_key);
            while (find_key_index(records, max_count + 1, new_key) != -1) {
                new_key = rand();
                new_rec = create_new_record(new_key);
            }
            records[max_count] = new_rec;
            max_count++;
        } else if (option == 2) {
