import subprocess
from cryptography.fernet import Fernet

def process_kickstart_config(params, append_sections):
    # Validate required fields in the parameter dictionary
    if 'Kickstart_file' not in params or 'Encryption_key' not in params:
        raise ValueError("Missing required field")

    kickstart_file = params['Kickstart_file']
    encryption_key = Fernet.generate_key()
    encrypted_password = encrypt_password(params.get('Password', ''), encryption_key)

    # Replace placeholders with actual values
    for placeholder, value in params.items():
        if placeholder.startswith('PLACEHOLDER_'):
            replace_placeholder(kickstart_file, placeholder[10:], value)

    # Append additional sections
    append_to_kickstart_file(kickstart_file, append_sections)

    # Add a new line with the encrypted password
    add_encrypted_password(kickstart_file, encrypted_password)

def replace_placeholder(file_path, placeholder, value):
    subprocess.run(['sed', '-i', f's/{placeholder}/{value}/g', file_path])

def encrypt_password(password, key):
    if not password:
        return ""

    cipher_suite = Fernet(key)
    cipher_text = cipher_suite.encrypt(password.encode())
    return cipher_text.decode()

def add_encrypted_password(file_path, encrypted_password):
    subprocess.run(['sed', '-i', f'/$/a{encrypted_password}\\n"', file_path])

def append_to_kickstart_file(file_path, sections):
    for section in sections:
        subprocess.run(['sed', '-i', f'a\\n{section}\\n', file_path])
