typedef struct {
    uint8_t *data;
    size_t len;
} u_char_array;

int dns_resolve(char* hostname, int max_addresses, u_char_array** result) {
    int ret = 0;
    int timeout = 1000; // adjust this value to suit your needs
    int num_addresses = 0;
    struct addrinfo hints, *res;
    char ipstr[INET6_ADDRSTRLEN];

    // Set up the DNS lookup hint structure
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC; // IPv4 and IPv6

    // Perform the DNS resolution
    int rv = getaddrinfo(hostname, NULL, &hints, &res);
    if (rv != 0) {
        ret = -1;
        goto cleanup;
    }

    // Iterate over the resolved addresses
    for (; res; res = res->ai_next) {
        char* ip = inet_ntop(res->ai_family, &((struct sockaddr_in*)res->ai_addr)->sin_addr, ipstr, sizeof(ipstr));

        // Limit the number of IP addresses returned
        if (num_addresses >= max_addresses) {
            break;
        }

        // Dynamically allocate memory for the IP address
        u_char_array* addr = (u_char_array*)malloc(sizeof(u_char_array));
        addr->data = (uint8_t*)ip;
        addr->len = strlen(ip);
        (*result)[num_addresses] = addr;
        num_addresses++;
    }

    // Cleanup and free any allocated resources
    cleanup:
    freeaddrinfo(res);
    return ret;
}
