int* read_and_validate_input(int* count) {
    int* valid_integers = NULL;
    int total_count = 0;

    while (1) {
        double num;
        if (scanf("%lf", &num) != 1) {
            break; // Malformed input or end of file
        }

        if (isnan(num)) {
            break; // Floating-point number indicating the end of input
        }

        int integer = (int) num;

        if (integer >= -1000 && integer <= 1000) {
            total_count++;

            if (valid_integers == NULL) {
                valid_integers = (int*) malloc(total_count * sizeof(int));
            } else {
                int* new_valid_integers = (int*) realloc(valid_integers, total_count * sizeof(int));
                valid_integers = new_valid_integers;
            }

            valid_integers[total_count - 1] = integer;
        }
    }

    if (valid_integers == NULL) {
        return NULL; // No valid integers found
    } else {
        return valid_integers;
    }
}

void print_largest_integer(int* valid_integers, int count) {
    int largest = INT_MIN;

    for (int i = 0; i < count; i++) {
        if (valid_integers[i] > largest) {
            largest = valid_integers[i];
        }
    }

    printf("The largest integer is: %d\n", largest);
}

void free_valid_integers(int* valid_integers, int count) {
    if (valid_integers != NULL) {
        free(valid_integers);
    }
}

