        if (!records) {
            return NULL; // Handle error: Memory allocation failed
        }

        total_bytes += max_records * sizeof(Record);

        for (int i = 0; i < max_records; i++) {
            records[i].key = i;

            // Allocate buffer space to store random offset values
            if (i >= current_buffer_index && buffer_bytes + sizeof(int) > max_memory_usage) {
                freeBuffer();
                current_buffer_index = 0;
                buffer_bytes = 0;
                records_allocated = 0;
            }

            int* offset_ptr = &records[i].offset;

            // Allocate memory for the offset value
            if (i >= records_allocated && !mallocOffset(offset_ptr, max_offset_range)) {
                freeRecords(&records);
                return NULL; // Handle error: Memory allocation failed
            }

            records_allocated = i + 1;
        }
    }

    // Update buffer bytes based on the size of offset values
    buffer_bytes += sizeof(int) * records_allocated;

    return records;
}

void freeRecords(Record** records) {
    if (*records) {
        for (int i = 0; i < records_allocated; i++) {
            if (i >= current_buffer_index && i < records_allocated - 1) {
                // Free buffer space and the offset value
                free(&(*records)[i].offset);
            }
        }

        free(*records);
        *records = NULL;
    }
}

