// Define a struct for sensor events
typedef struct {
    int id;
    double reading;
    struct tm *time_info;
} SensorEvent;

// Function to process sensor events from a JSON file
void process_sensor_events(int num_events, FILE *events_file) {
    // Allocate memory for arrays
    SensorEvent **events = (SensorEvent **)malloc(num_events * sizeof(SensorEvent *));
    int *sensor_ids = (int *)malloc(num_events * sizeof(int));
    double *readings = (double *)malloc(num_events * sizeof(double));
    struct tm **time_info = (struct tm **)malloc(num_events * sizeof(struct tm));

    // Initialize arrays
    for (int i = 0; i < num_events; i++) {
        sensor_ids[i] = -1;
        readings[i] = -999.9;
        time_info[i] = NULL;
    }

    // Read JSON file and parse events
    json_object *json_file = json_load_file(events_file, 0);
    if (json_file == NULL) {
        printf("Failed to load JSON file.\n");
        return;
    }

    int i = 0;
    while (i < num_events && json_object_object_iterate(json_file)) {
        json_object *event_json = json_object_object_get(json_file, "events");
        if (event_json == NULL) {
            break;
        }

        json_object *sensor_event_json = json_object_array_get_idx(event_json, i);
        if (sensor_event_json == NULL) {
            break;
        }

        sensor_ids[i] = atoi(json_object_get_string(sensor_event_json, "id"));
        readings[i] = atof(json_object_get_string(sensor_event_json, "reading"));

        // Parse time info
        time_info[i] = malloc(sizeof(struct tm));
        memset(time_info[i], 0, sizeof(struct tm));
        json_object *time_json = json_object_object_get(sensor_event_json, "time");
        if (time_json != NULL) {
            tm tmp;
            strptime(json_object_get_string(time_json), "%Y-%m-%d %H:%M:%S", &tmp);
            *time_info[i] = tmp;
        }

        i++;
    }

    // Log each event
    for (int j = 0; j < i; j++) {
        printf("Event ID: %d, Reading: %.2f, Time: %s\n", sensor_ids[j], readings[j], asctime(time_info[j]));
    }

    // Free allocated memory
    for (int k = 0; k < i; k++) {
        free(time_info[k]);
    }
    free(time_info);
    free(readings);
    free(sensor_ids);

    // Close JSON file
    json_object_free(json_file);
}
