// Define structure for event
typedef struct {
    time_t timestamp;
    struct Node* node;
} Event;

// Define structure for linked list node
typedef struct {
    int value;
    char** string_handle;
} Node;

// Function to initialize the data structures
void init_data_structures(Node** head, char*** string_handles, Event** events, int num_nodes, int num_events) {
    // Initialize linked list and array of event structures
    *head = NULL;
    for (int i = 0; i < num_nodes; i++) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed\n");
            exit(1);
        }
        node->value = rand() % 100; // Randomly populate integer values
        *head = insert_node(head, node);
    }

    for (int i = 0; i < num_events; i++) {
        Event* event = malloc(sizeof(Event));
        if (!event) {
            printf("Memory allocation failed\n");
            exit(1);
        }
        event->timestamp = time(NULL); // Randomly populate timestamps
        event->node = NULL;
    }

    for (int i = 0; i < num_events; i++) {
        Event* event = events[i];
        if (!event) continue;

        // Initialize string handles for nodes
        char** string_handles = malloc(sizeof(char*) * num_nodes);
        if (!string_handles) {
            printf("Memory allocation failed\n");
            exit(1);
        }

        for (int j = 0; j < num_nodes; j++) {
            string_handles[j] = malloc(10); // Initialize and populate string handles
            sprintf(string_handles[j], "Node %d", j);
        }

        event->node = head;
    }
}

// Function to insert a node into the linked list
Node* insert_node(Node** head, Node* node) {
    if (!head || !node) return *head;

    Node* current = *head;
    Node* previous = NULL;

    while (current && current->value < node->value) {
        previous = current;
        current = current->next;
    }

    if (!previous) {
        node->next = current;
        *head = node;
    } else {
        node->next = current;
        previous->next = node;
    }

    return *head;
}

// Function to validate the data structures
void validate_data_structures(Node* head, Event* events, int num_events) {
    if (!head || !events) return;

    Node* current = head;
    while (current) {
        if (!current->string_handle) {
            printf("Error: Node %d does not have a valid string handle\n", current->value);
            exit(1);
        }

        for (int i = 0; i < num_events; i++) {
            Event* event = events[i];
            if (event->node == current) {
                if (!event->timestamp || !event->node) {
                    printf("Error: Event %d does not have a valid timestamp or node reference\n", i);
                    exit(1);
                }
                break;
            }
        }

        current = current->next;
    }
}

// Function to handle memory allocation failure
void handle_memory_allocation_failure() {
    printf("Memory allocation failed. Program terminating.\n");
    exit(1);
}
