#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

// Define the structure for a resource pool
typedef struct {
    int capacity;
    int available;
    int total_requests;
    pthread_mutex_t lock;
    sem_t acquire_sem;
    sem_t release_sem;
} ResourcePool;

// Function to initialize the resource pool
ResourcePool* resource_pool_init(int initial_capacity) {
    ResourcePool* pool = (ResourcePool*)malloc(sizeof(ResourcePool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->available = initial_capacity;
    pool->total_requests = 0;

    pthread_mutex_init(&pool->lock, NULL);
    sem_init(&pool->acquire_sem, 0, pool->available);
    sem_init(&pool->release_sem, 0, 0);

    return pool;
}

// Function to acquire a resource from the pool
int resource_acquire(ResourcePool* pool) {
    int ret = 0;

    pthread_mutex_lock(&pool->lock);

    while (sem_wait(&pool->acquire_sem) == -1) {
        // If we reach this point, it means another thread has acquired the resource and released it already
        sem_post(&pool->release_sem);
        pthread_mutex_unlock(&pool->lock);
        return 0;
    }

    pool->available--;
    pool->total_requests++;

    pthread_mutex_unlock(&pool->lock);

    ret = 1;

    return ret;
}

// Function to release a resource back into the pool
void resource_release(ResourcePool* pool) {
    pthread_mutex_lock(&pool->lock);

    while (sem_getvalue(&pool->release_sem, NULL) == pool->available) {
        // Wait for another thread to acquire and release a resource
        sem_wait(&pool->acquire_sem);
    }

    pool->available++;
    sem_post(&pool->release_sem);

    pthread_mutex_unlock(&pool->lock);
}

// Function to get the current number of available resources in the pool
int get_available_resources(ResourcePool* pool) {
    return pool->available;
}

// Function to get the total number of requests processed by the pool
int get_total_requests(ResourcePool* pool) {
    return pool->total_requests;
}

// Example function to demonstrate the usage of the resource pool
void* thread_func(void* arg) {
    ResourcePool* pool = (ResourcePool*)arg;

    // Acquire a resource, do some work, and release it back into the pool
    while (resource_acquire(pool)) {
        printf("Thread acquired a resource.\n");
        // Do some work here...
        resource_release(pool);
        printf("Thread released a resource.\n");
    }

    return NULL;
}

int main() {
    ResourcePool* pool = resource_pool_init(5);

    pthread_t threads[500];

    for (int i = 0; i < 500; i++) {
        pthread_create(&threads[i], NULL, thread_func, pool);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 500; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
