#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the node structure
typedef struct Node {
    int *data;
    struct Node *next;
} Node;

// Define the dynamic list structure
typedef struct DynamicList {
    Node *head;
    Node *tail;
    pthread_mutex_t lock;
    size_t size;
    void (*allocator)(void **);
    FILE *(*serializer)(struct DynamicList *, const char *);
    int *(*deserializer)(FILE *, struct DynamicList *);
} DynamicList;

// Custom allocator function
void custom_allocator(void **ptr) {
    *ptr = malloc(sizeof(int));
}

// Custom serializer function
FILE *custom_serializer(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    Node *current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(int), 1, file);
        current = current->next;
    }
    fclose(file);
    return file;
}

// Custom deserializer function
int *custom_deserializer(FILE *file, DynamicList *list) {
    Node *new_node = malloc(sizeof(Node));
    new_node->data = (int *)malloc(sizeof(int));
    fread(new_node->data, sizeof(int), 1, file);
    list->head = new_node;
    list->tail = new_node;
    return new_node->data;
}

// Function to insert a node at the end of the dynamic list
void insert(DynamicList *list, int *data) {
    Node *new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove a node from the dynamic list
void remove(DynamicList *list, int *data) {
    Node **current = &list->head;
    while (*current != NULL && (*current)->data != data) {
        current = &(*current)->next;
    }
    if (*current == NULL) return;

    pthread_mutex_lock(&list->lock);
    if (*current == list->tail) {
        list->tail = (*current)->next;
    }
    *current = (*current)->next;
    free((*current)->data);
    free(*current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

// Function to search for a node in the dynamic list
void *search(DynamicList *list, int target) {
    Node *current = list->head;
    while (current != NULL && current->data != &target) {
        current = current->next;
    }
    return current != NULL ? current->data : NULL;
}

// Function to serialize the dynamic list
FILE *serialize(DynamicList *list, const char *filename) {
    return custom_serializer(list, filename);
}

// Function to deserialize the dynamic list
int *deserialize(FILE *file, DynamicList *list) {
    return custom_deserializer(file, list);
}
