typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    int capacity;
    pthread_mutex_t mutex; // Mutex for thread safety
} MemoryPool;

MemoryPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

NFAPI_CRC_INDICATION_PDU_T** createArray(int N) {
    if (N <= 0 || N > MAX_ALLOCATED_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Handle invalid input
        return NULL;
    }

    MemoryPool* currentPool = &pool;
    pthread_mutex_lock(&currentPool->mutex);

    int allocatedSize = N + POOL_SIZE;
    void* ptr = malloc(allocatedSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ptr) {
        // Handle allocation failure
        for (int i = 0; i < RETRIES; i++) {
            free(ptr);
            ptr = NULL;
            allocatedSize -= POOL_SIZE;
            if ((ptr = malloc(allocatedSize * sizeof(NFAPI_CRC_INDICATION_PDU_T))) != NULL) {
                break;
            }
            // Retry allocation up to three times
        }
        pthread_mutex_unlock(&currentPool->mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(allocatedSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < allocatedSize; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            // Handle allocation failure
            free(ptr);
            pthread_mutex_unlock(&currentPool->mutex);
            return NULL;
        }
    }

    currentPool->array = array;
    currentPool->capacity = allocatedSize;

    pthread_mutex_unlock(&currentPool->mutex);

    return array;
}
