    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

int main() {
    srand(time(NULL));

    // Initialize arrays with dynamic memory allocation
    node *nodes = alloc(sizeof(node) * 1000);
    event *events = alloc(sizeof(event) * 1000);
    char **strings = (char **)alloc(sizeof(char *) * 1000);

    // Initialize cache for frequently accessed strings
    char **cache = (char **)alloc(sizeof(char *) * CACHE_SIZE);
    int cacheHitCount = 0;

    // Populate nodes and events with random values within specified ranges
    for (int i = 0; i < MAX_NODES; i++) {
        node new_node;
        new_node.value = rand() % 100;
        new_node.str = strings[rand() % 1000];
        nodes[i] = new_node;
    }
    for (int i = 0; i < MAX_EVENTS; i++) {
        event new_event;
        new_event.timestamp = time(NULL) + rand() % 3600;
        new_event.node = &nodes[rand() % MAX_NODES];
        events[i] = new_event;
    }

    // Implement heuristic-based array resizing to balance performance with resource usage
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (i >= (int)sizeof(events) / sizeof(events[0])) {
            void* temp = alloc(sizeof(event) * i * 2);
            memcpy(temp, events, sizeof(event) * i);
            free(events);
            events = temp;
        }
    }

    // Implement logging to monitor memory allocation and deallocation events
    printf("Memory allocated for arrays: %lu bytes\n", (size_t)nodes + (size_t)events + (size_t)strings);

    return 0;
}
