void update_records(record* records, int offset_size, int key_size) {
    for (int i = 0; i < offset_size; i++) {
        int key_val = rand() % (15000 - (-15000)) + (-15000);
        records[i].value += key_val * 2;
    }
}

void update_key(int* key, int size) {
    for (int i = 0; i < size; i++) {
        key[i] *= 3;
    }
}

