        offset_size = max_record_size - key_size;
    }

    record* records = init_records(offset_size);
    int* key = (int*)malloc(key_size * sizeof(int));
    long* offset = (long*)malloc(offset_size * sizeof(long));

    for (int i = 0; i < key_size; i++) {
        key[i] = 0;
    }

    for (int i = 0; i < offset_size; i++) {
        offset[i] = 0;
    }

    update_records(records, offset_size, key_size);

    // Apply transformation function
    int constant_factor = 2;

    for (int i = 0; i < offset_size; i++) {
        records[i].value += key[i] * constant_factor;
    }

    free_records(records);
    free(key);
    free(offset);

    return 0;
}

