```c
#include <stdlib.h>
#include <time.h>
#include <stdio.h>

// Define structure Offset
typedef struct {
    int value;
} Offset;

// Define structure Key
typedef struct {
    int key;
} Key;

// Define structure Record
typedef struct Record {
    Key key;
    int data;
    struct Record* next;
    struct Record* prev;
} Record;

// Function to dynamically manage memory for three interconnected data structures
Record* create_data_structures(size_t size) {
    // Initialize random number generator with current time
    srand(time(NULL));

    // Allocate memory for array of Offset
    Offset* offsets = (Offset*)malloc(sizeof(Offset) * size);
    if (!offsets) return NULL;

    // Initialize Offset array to zero
    for (size_t i = 0; i < size; i++) {
        offsets[i].value = 0;
    }

    // Allocate memory for array of Key
    Key* keys = (Key*)malloc(sizeof(Key) * size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize Key array to sequential values starting from 1
    for (size_t i = 0; i < size; i++) {
        keys[i].key = i + 1;
    }

    // Allocate memory for doubly linked list of Record
    Record* head = NULL;
    Record* tail = NULL;
    for (size_t i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            free(offsets);
            free(keys);
            return NULL;
        }

        // Allocate memory for random integer within a predefined range
        int data = rand() % 100 + 1;

        record->key = keys[i];
        record->data = data;
        record->next = NULL;
        record->prev = tail;

        if (tail) {
            tail->next = record;
        } else {
            head = record;
        }
        tail = record;
    }

    // Return pointer to the head of the linked list
    return head;
}

// Function to periodically garbage collect unused Offset entries
void garbage_collect(Record* head, size_t threshold) {
    Record* current = head;
    while (current != NULL && current->prev == NULL) {
        if (current->data < threshold) {
            // Deallocate memory for Offset and Key at the same index
            free((void*)&offsets[current->key.key]);
            free((void*)&keys[current->key.key]);

            // Remove Record from linked list
            Record* next = current->next;
            if (next != NULL) {
                head = next;
            } else {
                tail = NULL;
            }
            current = next;
        } else {
            break;
        }
    }
}

// Function to track memory usage and performance metrics using a logging framework
void log_memory_usage(size_t allocated, size_t deallocated, size_t threshold) {
    // Implement your logging mechanism here
}
