void* allocate_structures(int num_structs, size_t struct_size) {
    void* ptr = NULL;

    if ((size_t)num_structs * struct_size <= 1024 * 1024) { // Allocation of less than 1MB
        ptr = malloc(num_structs * struct_size);
        if (ptr == NULL) {
            printf("Memory allocation failed.\n");
        }
    } else {
        size_t total_bytes = num_structs * struct_size;

        // Try to allocate the required amount of memory
        ptr = valloc(total_bytes);
        if (ptr == MAP_FAILED) {
            printf("valloc() failed. Trying to allocate %zu bytes.\n", total_bytes);

            // If allocation fails, try allocating a smaller chunk
            size_t half_bytes = total_bytes / 2;
            ptr = valloc(half_bytes);
            if (ptr == MAP_FAILED) {
                printf("Memory allocation failed for %zu bytes. Falling back to normal malloc.\n", half_bytes);

                // If still failing, allocate in small chunks and concatenate
                size_t chunk_size = 1024 * 1024; // 1MB chunk size
                ptr = NULL;
                for (int i = 0; i < total_bytes; i += chunk_size) {
                    void* temp_ptr = malloc(chunk_size);
                    if (temp_ptr == NULL) {
                        printf("Memory allocation failed. %zu bytes remaining.\n", total_bytes - i);
                        break;
                    }

                    // Concatenate the memory chunks
                    if (i > 0) {
                        size_t left_over = total_bytes - i;
                        char* p = (char*)temp_ptr + chunk_size - left_over;
                        for (int j = 0; j < left_over; j++) {
                            p--;
                            *p = *(char*)((char*)ptr + i + j);
                        }
                    }

                    if (i > 0) {
                        free(ptr);
                        ptr = temp_ptr;
                    } else {
                        ptr = temp_ptr;
                    }
                }
            }
        }
    }

    return ptr;
}

void deallocate_structures(void* ptr, int num_structs, size_t struct_size) {
    if (ptr != NULL) {
        free(ptr);
    }
}
