typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NFAPI_CRC_INDICATION_MANAGER_T;

NFAPI_CRC_INDICATION_MANAGER_T nfa_pi_crc_indication_manager = {
    .elements = NULL,
    .size = 0,
    .mutex = PTHREAD_MUTEX_INITIALIZER,
    .cond = PTHREAD_COND_INITIALIZER
};

void nfa_pi_crc_indication_manager_init() {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE_NGPLOCK);
    pthread_mutex_init(&nfa_pi_crc_indication_manager.mutex, &attr);
    pthread_mutexattr_destroy(&attr);
}

void nfa_pi_crc_indication_manager_add(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&nfa_pi_crc_indication_manager.mutex);
    size_t i;
    for (i = 0; i < nfa_pi_crc_indication_manager.size; i++) {
        if (nfa_pi_crc_indication_manager.elements[i].RNTI == pdu->RNTI) {
            pthread_mutex_unlock(&nfa_pi_crc_indication_manager.mutex);
            return;
        }
    }
    nfa_pi_crc_indication_manager.elements = realloc(nfa_pi_crc_indication_manager.elements, (nfa_pi_crc_indication_manager.size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfa_pi_crc_indication_manager.elements[nfa_pi_crc_indication_manager.size++] = *pdu;
    pthread_mutex_unlock(&nfa_pi_crc_indication_manager.mutex);
}

void nfa_pi_crc_indication_manager_remove(int RNTI) {
    pthread_mutex_lock(&nfa_pi_crc_indication_manager.mutex);
    size_t i, j;
    for (i = 0; i < nfa_pi_crc_indication_manager.size; i++) {
        if (nfa_pi_crc_indication_manager.elements[i].RNTI == RNTI) {
            for (j = i + 1; j < nfa_pi_crc_indication_manager.size; j++) {
                nfa_pi_crc_indication_manager.elements[j - 1] = nfa_pi_crc_indication_manager.elements[j];
            }
            free(nfa_pi_crc_indication_manager.elements[--nfa_pi_crc_indication_manager.size]);
        }
    }
    pthread_mutex_unlock(&nfa_pi_crc_indication_manager.mutex);
}

bool nfa_pi_crc_indication_manager_get_CRCFLAG(int RNTI) {
    pthread_mutex_lock(&nfa_pi_crc_indication_manager.mutex);
    size_t i;
    for (i = 0; i < nfa_pi_crc_indication_manager.size; i++) {
        if (nfa_pi_crc_indication_manager.elements[i].RNTI == RNTI) {
            bool crcflag = nfa_pi_crc_indication_manager.elements[i].CRCFLAG;
            pthread_mutex_unlock(&nfa_pi_crc_indication_manager.mutex);
            return crcflag;
        }
    }
    pthread_mutex_unlock(&nfa_pi_crc_indication_manager.mutex);
    return false; // RNTI not found
}

int main() {
    nfa_pi_crc_indication_manager_init();
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 10, true};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 20, true};
    // Add PDU to manager
    nfa_pi_crc_indication_manager_add(&pdu1);
    nfa_pi_crc_indication_manager_add(&pdu2);

    // Remove a PDU based on RNTI
    nfa_pi_crc_indication_manager_remove(10);

    bool crcflag = nfa_pi_crc_indication_manager_get_CRCFLAG(20);
    if (crcflag) {
        printf("CRC flag is valid for RNTI 20\n");
    } else {
        printf("RNTI 20 not found in the manager\n");
    }
    return 0;
}
