int process_integer_array() {
    int range_start = -1000, range_end = 1000;
    int max_int = INT_MIN, num_valids = 0;

    FILE *fp = fopen("stdin", "r");
    if (!fp) return -1; // Handle error opening standard input

    int* valid_integers = NULL;
    int max_len = 1000;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        int num;
        if (sscanf(buffer, "%d", &num) == 1) {
            if (num >= range_start && num <= range_end) {
                // Check for duplicates
                int found = 0;
                for (int i = 0; i < num_valids; i++) {
                    if (valid_integers[i] == num) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    if (num > max_int) max_int = num;

                    // Reallocate array if necessary
                    if (num_valids >= max_len) {
                        max_len *= 2;
                        int* new_array = realloc(valid_integers, sizeof(int) * max_len);
                        valid_integers = new_array;
                    }
                    valid_integers[num_valids++] = num;

                    // Monitor and log performance
                    printf("Valid integer: %d\n", num);
                } else {
                    printf("Duplicate integer: %d\n", num);
                }
            } else {
                printf("Invalid integer: %d\n", num);
            }
        }
    }

    fclose(fp);

    // Limit maximum valid integers to 1000
    if (num_valids >= 1000) {
        printf("Maximum valid integers reached: %d\n", max_int);
        return -2; // Return error code indicating input terminated early
    } else {
        printf("Total valid integers: %d, Largest integer: %d\n", num_valids, max_int);
    }

    free(valid_integers);
    return 0;
}

int main() {
    process_integer_array();
    return 0;
}
