    struct Record* head = NULL;
    struct Record* current = NULL;

    for (int i = 0; i < numRecords; i++) {
        struct Record* record = (struct Record*)malloc(sizeof(struct Record));
        if (!head) {
            head = record;
            current = head;
        } else {
            current->next = record;
            record->prev = current;
            current = record;
        }
        record->value = rand() % 100; // Random value within a range
    }

    return head;
}
