#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    char* buffer;
    void (*func)(char*);
} DataEntry;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    DataEntry** entries;
} DataStructure;

void default_func(char*) {
    printf("Default function called\n");
}

DataStructure* create_data_structure(size_t capacity) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    ds->capacity = capacity;
    ds->size = 0;
    ds->entries = calloc(capacity, sizeof(DataEntry*));
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void free_data_structure(DataStructure* ds) {
    for (size_t i = 0; i < ds->size; i++) {
        if (ds->entries[i]->buffer) {
            free(ds->entries[i]->buffer);
        }
        free(ds->entries[i]);
    }
    free(ds->entries);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

DataEntry* create_data_entry(char* buffer, void (*func)(char*)) {
    DataEntry* entry = malloc(sizeof(DataEntry));
    entry->buffer = strdup(buffer);
    entry->func = func;
    return entry;
}

int add_entry(DataStructure* ds, char* key, char* buffer) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; i++) {
        if (strcmp(ds->entries[i]->buffer, key) == 0) {
            free(entry->buffer);
            entry->buffer = strdup(buffer);
            pthread_mutex_unlock(&ds->lock);
            return 1;
        }
    }
    DataEntry* entry = create_data_entry(buffer, default_func);
    ds->entries[ds->size++] = entry;
    pthread_mutex_unlock(&ds->lock);
    return 0;
}

DataEntry* get_entry(DataStructure* ds, char* key) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; i++) {
        if (strcmp(ds->entries[i]->buffer, key) == 0) {
            pthread_mutex_unlock(&ds->lock);
            return ds->entries[i];
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return NULL;
}

void call_func(DataEntry* entry, char* buffer) {
    if (entry->func) {
        entry->func(buffer);
    } else {
        default_func(buffer);
    }
}
