typedef enum {
    MSG_TYPE_TCP,
    MSG_TYPE_UDP,
    MSG_TYPE_WS
} MessageType;

struct MessageContext {
    int socket_fd;
    char network_interface[16];
    MessageType message_type;
    pthread_mutex_t lock;
