struct MessageContext* initializeMessageProcessingFramework() {
    struct MessageContext* ctx = (struct MessageContext*)malloc(sizeof(struct MessageContext));

    // Initialize TCP
    if ((ctx->socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("TCP socket creation failed");
        return NULL;
    }

    // Initialize UDP
    int udp_socket_fd;
    if ((udp_socket_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("UDP socket creation failed");
        close(ctx->socket_fd);
        free(ctx);
        return NULL;
    }

    // Initialize WebSocket
    int ws_socket_fd;
    if ((ws_socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("WebSocket socket creation failed");
        close(udp_socket_fd);
        close(ctx->socket_fd);
        free(ctx);
        return NULL;
    }

    // Initialize message type
    ctx->message_type = MSG_TYPE_TCP; // Default to TCP

    // Initialize lock
    if (pthread_mutex_init(&ctx->lock, NULL) < 0) {
        perror("Lock initialization failed");
        close(ws_socket_fd);
        close(udp_socket_fd);
        close(ctx->socket_fd);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void* processMessage(void* arg) {
    struct MessageContext* ctx = (struct MessageContext*)arg;

    // Process message using the configured protocol
    if (ctx->message_type == MSG_TYPE_TCP) {
        // TCP processing logic here
    } else if (ctx->message_type == MSG_TYPE_UDP) {
        // UDP processing logic here
    } else if (ctx->message_type == MSG_TYPE_WS) {
        // WebSocket processing logic here
    }

    return NULL;
}

void messageProcessingFramework(int retries, int backoff_ms) {
    struct MessageContext* ctx = initializeMessageProcessingFramework();

    while (retries--) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, processMessage, ctx)) {
            perror("Thread creation failed");
            break;
        }

        // Simulate message processing delay
        usleep(1000);

        int status = pthread_join(thread, NULL);
        if (status) {
            perror("Thread join failed");
            break;
        }
    }

    close(ctx->socket_fd);
    close(ctx->ws_socket_fd);
    close(ctx->udp_socket_fd);
    free(ctx);
}

int main() {
    messageProcessingFramework(MAX_RETRIES, RETRY_BACKOFF);
    return 0;
}
