Record* init_data_structures(int size) {
    // Initialize the key array with sequential values from 1
    Key* keys = (Key*)malloc(sizeof(Key) * size);
    for (int i = 0; i < size; i++) {
        keys[i].value = i + 1;
    }

    // Initialize the offset array to zero
    Offset* offsets = (Offset*)malloc(sizeof(Offset) * size);
    for (int i = 0; i < size; i++) {
        offsets[i].value = 0;
    }

    // Initialize and populate the record linked list
    Record* head = NULL;
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        Record* new_record = (Record*)malloc(sizeof(Record));
        new_record->value = rand() % 100 + 1; // Random integer value between 1 and 100
        if (head == NULL) {
            head = new_record;
        } else {
            new_record->prev = head;
            head->next = new_record;
            head = new_record;
        }
    }

    // Implement custom memory pool for managing record nodes
    Record** memory_pool = (Record**)malloc(sizeof(Record*) * size);
    for (int i = 0; i < size; i++) {
        memory_pool[i] = NULL;
    }

    // Initialize the current record pointer to the head of the list
    Record* current = head;

    return head;
}

// Function to iterate over the linked list in both forward and reverse directions
void iterate_list(Record* head) {
    Record* current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");

    current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->prev;
    }
    printf("\n");
}

