#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Offset {
    long offset;
} Offset;

typedef struct Key {
    int key;
} Key;

typedef struct Record {
    int value;
    struct Record* next;
    struct Record* prev;
} Record;

Record* create_record(int max_value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if(record == NULL) return NULL;
    srand(time(NULL));
    record->value = rand() % max_value;
    record->next = record->prev = NULL;
    return record;
}

void add_to_list(Record** head, int value) {
    Record* new_record = create_record(value);
    if(*head == NULL || (*head)->value > new_record->value) {
        new_record->next = *head;
        *head = new_record;
    } else {
        Record* current = *head;
        while(current->next && current->next->value <= new_record->value) {
            current = current->next;
        }
        new_record->prev = current;
        new_record->next = current->next;
        if(new_record->next) new_record->next->prev = new_record;
        else *head = new_record;
        current->next = new_record;
    }
}

void update_offsets(Offset** offsets, int count) {
    for(int i = 0; i < count; i++) {
        Offset* offset = (Offset*)malloc(sizeof(Offset));
        if(offset == NULL) return;
        offset->offset = 0;
        (*offsets)[i] = *offset;
    }
}

void update_keys(Key** keys, int count) {
    for(int i = 0; i < count; i++) {
        Key* key = (Key*)malloc(sizeof(Key));
        if(key == NULL) return;
        key->key = i + 1;
        (*keys)[i] = *key;
    }
}

Record* init_data_structure(int max_value, int offset_count, int key_count) {
    srand(time(NULL));
    Record* head = NULL;
    Offset* offsets = (Offset*)malloc(sizeof(Offset)*offset_count);
    if(offsets == NULL || (head = create_record(max_value)) == NULL) return NULL;

    for(int i = 0; i < offset_count; i++) {
        add_to_list(&head, max_value);
    }

    update_offsets(&offsets, offset_count);

    Key* keys = (Key*)malloc(sizeof(Key)*key_count);
    if(keys == NULL || update_keys(&keys, key_count)) return NULL;

    return head;
}

int main() {
    // Example usage:
    int max_value = 100;
    int offset_count = 10;
    int key_count = 20;
    Record* head = init_data_structure(max_value, offset_count, key_count);
    if(head == NULL) printf("Memory allocation failed.\n");
    else printf("Linked list initialized successfully.\n");

    return 0;
}
