// Function to dynamically allocate memory for an array of structures within a specified memory budget
NFAPI_CRC_INDICATION_PDU_T** allocate_structures(int num_structures, size_t max_memory_budget) {
    // Initialize variables to track memory allocation and deallocation
    size_t allocated_memory = 0;
    int structure_count = 0;

    while (allocated_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T*) <= max_memory_budget && structure_count < num_structures) {
        NFAPI_CRC_INDICATION_PDU_T** p_structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!p_structures) {
            // Handle memory allocation failure
            printf("Memory allocation failed: %s\n", strerror(errno));
            return NULL;
        }

        allocated_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_structures;
        for (int i = 0; i < num_structures; i++) {
            p_structures[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!p_structures[i]) {
                // Handle memory allocation failure
                printf("Memory allocation failed: %s\n", strerror(errno));
                for (int j = 0; j < i; j++) {
                    free(p_structures[j]);
                }
                free(p_structures);
                return NULL;
            }
        }

        structure_count += num_structures;
    }

    // Deallocate memory upon successful completion
    if (structure_count > 0) {
        for (int i = 0; i < structure_count; i++) {
            free(*(p_structures + i));
        }
        free(p_structures);
    }

    return p_structures;
}

// Function to deallocate all allocated memory
void deallocate_memory(NFAPI_CRC_INDICATION_PDU_T** p_structures, int num_structures) {
    for (int i = 0; i < num_structures; i++) {
        free(*(p_structures + i));
    }
    free(p_structures);
}
