import java.util.*;

public class Pokemon {
    private String name;
    private String type;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    public static String getWeaknesses(Pokemon pokemon) {
        Map<String, List<String>> weaknessesMap = new HashMap<>();
        weaknessesMap.put("Fire", Arrays.asList("Water", "Rock"));
        weaknessesMap.put("Water", Arrays.asList("Electric", "Grass"));
        weaknessesMap.put("Grass", Arrays.asList("Fire", "Poison"));
        // Add more types and their corresponding weaknesses as needed
        return pokemon.getName() + "'s weakness is: " + getWeaknesses(weaknessesMap, pokemon.getType());
    }

    private static String getWeaknesses(Map<String, List<String>> weaknessesMap, String type) {
        if (!weaknessesMap.containsKey(type)) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (String weakness : weaknessesMap.get(type)) {
            sb.append(weakness).append(", ");
        }
        return sb.toString().trim().substring(0, sb.length() - 2);
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }
}
