#include <forward_list>
#include <string>

std::string processStrings(const std::forward_list<std::string>& list, const std::string& search, const std::string& insertion, size_t limit) {
    auto it = list.begin();
    while (it != list.end()) {
        if (it->find(search) != std::string::npos) {
            *it += insertion;
            break;
        }
        ++it;
    }
    if (it == list.end()) {
        *list.insert_after(list.end(), insertion);
    }
    size_t length = 0;
    std::string result;
    for (const auto& str : list) {
        result += str;
        length += str.length();
        if (length > limit) return "";
    }
    if (result.length() <= limit)
        return result + " ...";
    else
        return "";
}
