    static const int MAX_REQUESTS = 100;
    static const int MAX_CONNECTIONS = 10;
    static const int RETRY_INTERVAL_MS = 5000; // 5 seconds
    static const int TIMEOUT_MS = 30000; // 30 seconds

    HttpClient(int numConnections) : connections(numConnections), connectionPool(MAX_CONNECTIONS), requestQueue() {}

    void sendRequest(const std::string& method, const std::string& url, const std::string& body) {
        if (requestQueue.size() >= MAX_REQUESTS) {
            // Handle queue overflow
            return;
        }

        Request req(method, url, body);
        requestQueue.push(req);

        if (connections.empty()) {
            connectionPool.wait();
        }
    }

