class RandomGenerator {
public:
    RandomGenerator() : mt_(std::chrono::high_resolution_clock::now().time_since_epoch().count()) {}

    int generate(int min, int max) {
        std::uniform_int_distribution<> dist(min, max);
        return dist(mt_);
    }

    void reset() {
        mt_ = std::chrono::high_resolution_clock::now().time_since_epoch().count();
    }

private:
    mutable std::mt19937 mt_;
};

class SimulationManager {
public:
    SimulationManager(size_t initialCapacity) : generators_(initialCapacity), lock_(), generatorPoolMutex_() {}

    void addGenerator(RandomGenerator& generator) {
        std::unique_lock<std::mutex> lock(generatorPoolMutex_);
        if (generators_.size() < GENERATOR_POOL_SIZE) {
            generators_.push_back(&generator);
        }
    }

    RandomGenerator* getAvailableGenerator() {
        std::lock_guard<std::mutex> lock(lock_);
        for (auto& generator : generators_) {
            if (!generator->inUse()) {
                return generator;
            }
        }
        return nullptr;
    }

    void releaseGenerator(RandomGenerator* generator) {
        std::unique_lock<std::mutex> lock(generatorPoolMutex_);
        for (auto it = generators_.begin(); it != generators_.end(); ++it) {
            if (*it == generator) {
                *it = nullptr;  // Mark as available
                return;
            }
        }
    }

private:
    std::vector<RandomGenerator*> generators_;
    std::mutex lock_;
    mutable std::recursive_mutex generatorPoolMutex_;
};

const size_t GENERATOR_POOL_SIZE = 10;

int main() {
    SimulationManager manager(GENERATOR_POOL_SIZE);

    // Create and start simulations
    for (size_t i = 0; i < 5; ++i) {
        RandomGenerator* generator = manager.getAvailableGenerator();
        if (generator != nullptr) {
            std::thread simulation([=]() {
                for (int j = 0; j < 100000; ++j) {
                    int randomNum = generator->generate(1, 6);
                    // Process the generated number
                }
            });
            simulation.detach();
            manager.addGenerator(*generator);
        } else {
            std::cout << "No available generators.\n";
            break;
        }
    }

    return 0;
}
