#include <forward_list>
#include <random>

struct DataRecord {
    int random_value;
};

void insertRandomValueAfter(std::forward_list<int>& list, int target, int replacement, int min_random, int max_random) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(min_random, max_random);
            DataRecord data_record;
            data_record.random_value = dis(gen);
            std::forward_list<int> new_list;
            for (int i = 0; it != list.end(); ++i) {
                if (i == 1) {
                    new_list.push_front(data_record.random_value);
                    break;
                }
                new_list.push_front(*it);
                ++it;
            }
            while (it != list.end()) {
                new_list.push_front(*it);
                ++it;
            }
            list = new_list;
            return;
        }
        ++it;
    }
    std::forward_list<int> new_list(list);
    new_list.push_back(replacement);
    list = new_list;
}
