// Structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[64];
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct _Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _Node* next;
} Node;

// Function to create a new linked list node
Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
int manageList(NFAPI_CRC_INDICATION_PDU_T** list, int* size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the linked list
    Node* head = (Node*) malloc(sizeof(Node));
    if (!head) {
        return -1;  // Out-of-memory condition
    }
    head->next = NULL;
    *list = &head->data;
    *size = 0;

    // Function to add an element to the list
    int addElement(NFAPI_CRC_INDICATION_PDU_T data) {
        Node* newNode = createNode(data);
        if (!newNode) {
            return -1;  // Out-of-memory condition
        }
        pthread_mutex_lock(&mutex);

        // Add new node to the end of the list
        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;

        pthread_mutex_unlock(&mutex);
        return 0;  // Success
    }

    // Function to remove an element from the list
    int removeElement(int RNTI) {
        Node* current = head;
        Node* previous = NULL;
        while (current && current->data.RNTI != RNTI) {
            previous = current;
            current = current->next;
        }
        if (!current) {
            return -1;  // Element not found
        }

        pthread_mutex_lock(&mutex);

        // Remove node from the list
        if (previous) {
            previous->next = current->next;
        } else {
            head = current->next;
        }

        free(current);
        pthread_mutex_unlock(&mutex);
        return 0;  // Success
    }

    // Function to periodic garbage collection
    int collectGarbage() {
        Node* current = head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        *size = 0;
        return 0;  // Success
    }

    return 0;  // Success
}
