#include <forward_list>
#include <random>
#include <mutex>
#include <record>

void insertRandomValueAfter(std::forward_list<int>& list, int target, int replacement, int minRange, int maxRange) {
    std::forward_list<int>::iterator it = list.begin();
    bool found = false;

    for (; it != list.end(); ++it) {
        if (*it == target) {
            found = true;
            break;
        }
    }

    if (!found) {
        list.push_back(replacement);
        return;
    }

    record rec;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minRange, maxRange);

    int randomValue = dis(gen);
    rec.data = randomValue;

    try {
        list.insert_after(it++, replacement);
        list.push_back(rec);
    } catch (...) {
        // Handle memory allocation failure
        it = list.begin();
        for (; it != list.end(); ++it) {
            if (*it == target) {
                break;
            }
        }

        if (found)
            list.erase_after(it);

        std::cout << "Memory allocation failed. Original state restored." << std::endl;
    }

    // Log insertion action and random value
    std::cout << "Inserted replacement integer after the target integer (" << target << "). Random value generated: " << randomValue << "." << std::endl;
}
