import { TestResult, PerformanceMetrics } from './test.result';

@Injectable()
export class ComponentPerformanceTester {
  private mockServer: any;
  private cache: Map<string, TestResult>;
  private performanceMetrics: PerformanceMetrics;

  async run(
    label: string,
    testFunction: () => Promise<TestResult>,
    setup: () => void,
    externalConfig: object
  ): Promise<PerformanceMetrics> {
    try {
      const component = await this.initializeComponent(externalConfig);
      setup();
      const result = await this.executeTests(label, testFunction, component);
      return this.logAndSummarize(result);
    } catch (error) {
      console.error(`Error running tests: ${error}`);
      throw error;
    }
  }

  private async initializeComponent(config: object): Promise<any> {
    try {
      const component = await require('./component').default();
      if (!component) {
        throw new Error('Failed to load component');
      }
      return component;
    } catch (error) {
      console.error(`Error initializing component: ${error}`);
      throw error;
    }
  }

  private async executeTests(
    label: string,
    testFunction: () => Promise<TestResult>,
    component: any
  ): Promise<TestResult[]> {
    const results: TestResult[] = [];
    this.mockServer = await this.startMockServer();
    for (let i = 0; i < 10; i++) { // assume 10 tests in total
      const result = await testFunction();
      results.push(result);
    }
    await this.stopMockServer();
    return results;
  }

  private async startMockServer(): Promise<any> {
    try {
      const server = await require('./mock-server').default();
      if (!server) {
        throw new Error('Failed to load mock server');
      }
      return server;
    } catch (error) {
      console.error(`Error starting mock server: ${error}`);
      throw error;
    }
  }

  private async stopMockServer(): Promise<void> {
    try {
      await this.mockServer.stop();
    } catch (error) {
      console.error(`Error stopping mock server: ${error}`);
    }
  }

  private logAndSummarize(results: TestResult[]): PerformanceMetrics {
    const metrics = new PerformanceMetrics();
    results.forEach((result) => {
      metrics.push(result);
    });
    return metrics;
  }
}
