} record_t;

record_t* create_and_persist_records(int num_records, int min_value, int max_value, int unique) {
    // Initialize arrays
    long* offsets = (long*)calloc(num_records + 1, sizeof(long));
    int* keys = (int*)calloc(num_records, sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Generate and persist records
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    int value_range = max_value - min_value + 1;

    for (int i = 0; i < num_records; ++i) {
        record_t* record = &records[i];
        if (unique && i > 0) {
            while ((value_range == 1 || rand() % value_range == 0)) {
                // Generate unique random values
                record->key = min_value + rand() % value_range;
            }
        } else {
            record->key = min_value + rand() % value_range;
        }
    }

    // Free temporary arrays
    free(offsets);
    free(keys);

    return records;
}
