#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* key;
    double value;
} entry;

entry** hashTable = NULL;
int capacity = 16;
int size = 0;

void initHashTable() {
    if (hashTable != NULL) {
        for (int i = 0; i < capacity; i++) {
            free(hashTable[i]);
        }
        free(hashTable);
    }

    hashTable = (entry**)malloc(capacity * sizeof(entry*));
    for (int i = 0; i < capacity; i++) {
        hashTable[i] = NULL;
    }
}

void insertEntry(char* key, double value) {
    int index = keyHash(key);
    if (hashTable[index] == NULL) {
        hashTable[index] = (entry*)malloc(sizeof(entry));
        size++;
    }

    hashTable[index]->key = key;
    hashTable[index]->value = value;
}

int lookupEntry(char* key, double* value) {
    int index = keyHash(key);
    if (hashTable[index] != NULL && strcmp(hashTable[index]->key, key) == 0) {
        *value = hashTable[index]->value;
        return 1;
    }

    return 0;
}

int removeEntry(char* key) {
    int index = keyHash(key);
    if (hashTable[index] != NULL && strcmp(hashTable[index]->key, key) == 0) {
        free(hashTable[index]);
        hashTable[index] = NULL;
        size--;
        return 1;
    }

    return 0;
}

int keyHash(char* key) {
    int sum = 0;
    for (int i = 0; i < strlen(key); i++) {
        sum += key[i];
    }
    return sum % capacity;
}

void resizeHashTable() {
    if (size > capacity * 0.85) {
        capacity *= 2;
        initHashTable();
    }
}

entry* getEntry(char* key, double* value) {
    int index = keyHash(key);
    if (hashTable[index] != NULL && strcmp(hashTable[index]->key, key) == 0) {
        *value = hashTable[index]->value;
        return hashTable[index];
    }

    return NULL;
}

void freeHashTable() {
    for (int i = 0; i < capacity; i++) {
        if (hashTable[i] != NULL) {
            free(hashTable[i]);
        }
    }
    free(hashTable);
    hashTable = NULL;
}
