    records = (record_t *)malloc(num_records * sizeof(record_t));
    offsets = (long *)malloc((num_records + 1) * sizeof(long));
    keys = (int *)malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        record_t rec;
        rec.value = rand() % 100; // random value between 0 and 99
        records[i] = rec;

        if (i > 0 && records[i].value == records[i - 1].value) {
            // adjust to make sure no consecutive records have the same value
            rec.value = (rec.value + 1) % 100;
            records[i] = rec;
        }

        keys[i] = i; // assign each record a unique key
    }
