const { Buffer } = require('buffer');

function copyBufferedData(bufferChunks, start, end) {
  if (!Array.isArray(bufferChunks)) {
    throw new Error('Invalid buffer chunks');
  }
  const bufferSize = (end - start) + 1;
  try {
    const copiedBuffer = Buffer.allocUnsafe(bufferSize);
    let writeIndex = 0;
    for (const bufferChunk of bufferChunks) {
      const chunkWriteIndex = 0;
      while (chunkWriteIndex < bufferChunk.length) {
        const bytesRead = bufferChunk.copy(copiedBuffer, writeIndex, start + chunkWriteIndex, Math.min(start + end, start + chunkWriteIndex));
        writeIndex += bytesRead;
        chunkWriteIndex += bytesRead;
      }
    }
    return copiedBuffer;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

