    Record* records = (Record*)malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100 + 1; // Set record value to a random integer between 1 and 100
    }
    return records;
}

void init_pipeline(int* keys, int num_keys, Record** records, int num_records) {
    // Initialize the key-record map
    int** key_map = (int**)malloc(num_keys * sizeof(int*));
    for (int i = 0; i < num_keys; i++) {
        key_map[i] = (int*)malloc(sizeof(int));
        *(key_map[i]) = -1; // Initialize with -1, to be updated later
    }

    // Create arrays for 'long' offset values and 'int' keys
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* record_offsets = (int*)malloc((num_keys + 1) * sizeof(int));

    // Initialize the offsets array with unique values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
    }

    // Record offset map to efficiently locate records
    int record_offset_index = 0;
    for (int i = 0; i <= num_keys; i++) {
        record_offsets[i] = record_offset_index++;
    }

    // Clean up
    free(key_map);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int num_records = 10000;
    int num_keys = 5000;

    Record* records = create_records(num_records);

    int* keys = (int*)malloc(num_keys * sizeof(int));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand(); // Initialize key values randomly
    }

    init_pipeline(keys, num_keys, &records, num_records);

    // Use the allocated data structures as needed in your pipeline...

    // Clean up when done with the pipeline
    free(records);
    for (int i = 0; i < num_keys; i++) {
        free((int*)malloc(sizeof(int)));
    }
    free(offsets);
    free(record_offsets);

    return 0;
}
