async function processFiles(directoryPath, maxConcurrentOperations = 5, timeoutMs = 30000) {
  const files = await fs.promises.readdir(directoryPath);
  const processedFilesCount = 0;
  const errors = [];
  let aggregatedResult = {};

  for (const file of files) {
    if (!file.endsWith('.json')) continue;

    try {
      const fileContent = await Promise.race([
        fs.promises.readFile(`${directoryPath}/${file}`, 'utf8'),
        new Promise((resolve, reject) => setTimeout(() => reject(new Error('Timeout')), timeoutMs)),
      ]);

      try {
        const jsonData = JSON.parse(fileContent);
        // Validate JSON structure
        if (!isValidJsonStructure(jsonData)) {
          throw new Error(`Invalid JSON structure in file ${file}`);
        }

        // Integrate with external data service to fetch additional metadata
        const metadata = await getMetadataFromService(file);
        // Process the file content with the fetched metadata
        const processedContent = processFileContent(file, jsonData, metadata);

        aggregatedResult[file] = processedContent;
        processedFilesCount++;
      } catch (error) {
        errors.push({ file, error });
      }
    } catch (error) {
      if (error instanceof Error && error.message.includes('Timeout')) continue;
      console.error(`Error processing file ${file}:`, error);
      errors.push({ file, error });
    }

    // Limit concurrent operations
    if (files.length > maxConcurrentOperations) await new Promise(resolve => setTimeout(() => resolve(), 100));
  }

  return { processedFilesCount, errors, aggregatedResult };
}

