#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define LOG_ERROR(fmt, ...) printf("Error: " fmt "\n")

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int entries = 0;

NFAPI_CRC_INDICATION_PDU_T* list = NULL;

void init_list(int max_entries) {
    if (max_entries > MAX_ENTRIES) {
        LOG_ERROR("Invalid maximum entries: %d", max_entries);
        return;
    }

    pthread_mutex_init(&lock, NULL);
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void add_entry(int rnti) {
    if (entries >= MAX_ENTRIES) {
        LOG_ERROR("Maximum entries exceeded");
        return;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* entry = &list[entries];
    sprintf(entry->RX_UE_INFORMATION_TAG, "TAG-%d", rnti);
    entry->RNTI = rnti;
    strcpy(entry->CRC_INDICATION_REL8_TAG, "REL8-TAG");
    srand(time(NULL));
    entry->CRCFLAG = (uint8_t)rand() % 256;

    entries++;

    pthread_mutex_unlock(&lock);
}

void print_list() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < entries; i++) {
        printf("RNTI: %d, RX_UE_INFORMATION_TAG: %s, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: 0x%x\n", 
               list[i].RNTI, list[i].RX_UE_INFORMATION_TAG, list[i].CRC_INDICATION_REL8_TAG, list[i].CRCFLAG);
    }

    pthread_mutex_unlock(&lock);
}

void clean_up() {
    pthread_mutex_lock(&lock);

    if (list != NULL) {
        free(list);
        list = NULL;
    }

    pthread_mutex_unlock(&lock);
}
