#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent WiFi scan results
typedef struct {
    char ssid[32];
    int rssi;
    int channel;
} WIFI_SCAN_RESULT;

// Define a linked list node structure
typedef struct Node {
    WIFI_SCAN_RESULT result;
    struct Node* next;
} NODE;

// Function to manage the linked list of WiFi scan results
void wifi_scan_results_manager(NODE** head, pthread_mutex_t* mutex, int age_threshold) {
    // Initialize the head pointer and the lock
    *head = NULL;
    *mutex = PTHREAD_MUTEX_INITIALIZER;

    // Thread function to add a new scan result
    void* add_result(void* arg) {
        NODE** list_head = (NODE**)arg;
        pthread_mutex_lock(*list_head);
        // Add new scan result, checking if the head is updated while adding
        if (*list_head != NULL && (*list_head)->result.timestamp > age_threshold) {
            NODE* temp = *list_head;
            *list_head = (*list_head)->next;
            free(temp);
        } else {
            // Create a new node and add to the list
            NODE* new_node = (NODE*)malloc(sizeof(NODE));
            strcpy(new_node->result.ssid, "New WiFi Network");
            new_node->result.rssi = 1234; // Example value
            new_node->result.channel = 11;
            new_node->next = *list_head;
            *list_head = new_node;
        }
        pthread_mutex_unlock(*list_head);
    }

    // Thread function to prune old scan results
    void* prune_results(void* arg) {
        NODE** list_head = (NODE**)arg;
        pthread_mutex_lock(*list_head);
        // Traverse the linked list and remove entries older than age_threshold
        NODE* current = *list_head;
        while (current != NULL && current->result.timestamp <= age_threshold) {
            NODE* temp = current;
            current = current->next;
            free(temp);
        }
        *list_head = current;
        pthread_mutex_unlock(*list_head);
    }

    // Start threads to add and prune scan results
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, (void*)add_result, head);
    pthread_create(&thread2, NULL, (void*)prune_results, head);

    // Wait for the threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);
}

// Example usage:
int main() {
    NODE* list_head = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int age_threshold = 3600; // One hour in seconds

    wifi_scan_results_manager(&list_head, &mutex, age_threshold);

    return 0;
}
