#define MAX_MESSAGES 1000
#define MAX_MESSAGE_SIZE 1024

typedef struct {
    int phich_configuration;
    uint32_t ue_id;
    char* dl_mch_data_tag;
} lte_phy_message;

lte_phy_message** messages = NULL;
int message_count = 0;
int max_messages = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("messages.log", "w");

void create_message(int phich_configuration, uint32_t ue_id) {
    lte_phy_message* message = (lte_phy_message*)malloc(sizeof(lte_phy_message));
    if (message == NULL) {
        fprintf(log_file, "Error: Could not allocate memory for message.\n");
        return;
    }

    message->phich_configuration = phich_configuration;
    message->ue_id = ue_id;
    message->dl_mch_data_tag = NULL;

    pthread_mutex_lock(&lock);
    if (message_count >= max_messages) {
        // Periodic garbage collection
        int i, j = 0;
        for (i = 0; i < message_count; i++) {
            if ((messages[i]->phich_configuration == 0) || (messages[i]->ue_id == 0)) {
                free(messages[i]->dl_mch_data_tag);
                free(messages[i]);
                messages[i] = NULL;
            } else {
                messages[j++] = messages[i];
            }
        }

        max_messages = j;
        message_count = j;

        // Monitor and report current state
        printf("Current state: %d messages, %d bytes used.\n", message_count, (message_count * MAX_MESSAGE_SIZE));
    }

    if (messages == NULL) {
        messages = (lte_phy_message**)malloc(MAX_MESSAGES * sizeof(lte_phy_message*));
        max_messages = MAX_MESSAGES;
    }

    if (message_count >= max_messages) {
        // Dynamic array reallocation
        max_messages *= 2;
        messages = (lte_phy_message**)realloc(messages, max_messages * sizeof(lte_phy_message*));
    }

    messages[message_count] = message;
    message_count++;

    pthread_mutex_unlock(&lock);
}

void destroy_message(int ue_id) {
    pthread_mutex_lock(&lock);
    int i;
    for (i = 0; i < message_count; i++) {
        if (messages[i]->ue_id == ue_id) {
            free(messages[i]->dl_mch_data_tag);
            free(messages[i]);
            messages[i] = NULL;
        }
    }

    pthread_mutex_unlock(&lock);
}

void reallocate_messages() {
    pthread_mutex_lock(&lock);

    // Monitor and report current state
    printf("Current state: %d messages, %d bytes used.\n", message_count, (message_count * MAX_MESSAGE_SIZE));

    max_messages *= 2;
    messages = (lte_phy_message**)realloc(messages, max_messages * sizeof(lte_phy_message*));
    pthread_mutex_unlock(&lock);
}

void validate_input(int phich_configuration, uint32_t ue_id) {
    // Validate PHICH_CONFIGURATION and UE_ID inputs
    if (phich_configuration < 0 || phich_configuration > 255) {
        fprintf(log_file, "Error: Invalid PHICH_CONFIGURATION.\n");
    }
    if (ue_id <= 0) {
        fprintf(log_file, "Error: Invalid UE_ID.\n");
    }
}

void print_messages() {
    pthread_mutex_lock(&lock);
    int i;
    for (i = 0; i < message_count; i++) {
        printf("PHICH_CONFIGURATION: %d, UE_ID: %u, DL_MCH_DATA_TAG: %s\n", messages[i]->phich_configuration, messages[i]->ue_id, messages[i]->dl_mch_data_tag);
    }
    pthread_mutex_unlock(&lock);
}

void periodic_garbage_collection() {
    // Periodic garbage collection to reclaim unused memory
    int i, j = 0;
    for (i = 0; i < message_count; i++) {
        if ((messages[i]->phich_configuration == 0) || (messages[i]->ue_id == 0)) {
            free(messages[i]->dl_mch_data_tag);
            free(messages[i]);
            messages[i] = NULL;
        } else {
            messages[j++] = messages[i];
        }
    }

    message_count = j;

    // Monitor and report current state
    printf("Current state: %d messages, %d bytes used.\n", message_count, (message_count * MAX_MESSAGE_SIZE));
}

void* external_data_source(void*) {
    while (1) {
        // Real-time PHICH_CONFIGURATION updates from external data source
        int phich_configuration = ...;
        uint32_t ue_id = ...;

        create_message(phich_configuration, ue_id);

        // Monitor and report current state
        printf("Current state: %d messages, %d bytes used.\n", message_count, (message_count * MAX_MESSAGE_SIZE));
    }
}

int main() {
    pthread_create(&thread, NULL, external_data_source, NULL);
    return 0;
}
