// Define the structure for LTE PHY Layer Control Messages
typedef struct {
    int phich_configuration;
    unsigned long ue_id;
    char* dl_mch_data_tag;
} LteMessage;

// Define the graph database vertex and edge structures
typedef struct {
    int id;
    char* properties;
} Vertex;

typedef struct {
    int from;
    int to;
    int weight;
} Edge;

// Function prototypes
LteMessage* create_lte_message(int phich_configuration, unsigned long ue_id);
void add_to_graph_database(LteMessage*, Vertex**, Edge**);
int create_edges(Vertex**, Edge**, int);

// Create an LTE PHY Layer Control Message with the given configuration and UE ID
LteMessage* create_lte_message(int phich_configuration, unsigned long ue_id) {
    LteMessage* message = (LteMessage*)malloc(sizeof(LteMessage));
    if (!message) return NULL;

    message->phich_configuration = phich_configuration;
    message->ue_id = ue_id;
    message->dl_mch_data_tag = (char*)malloc(20); // dynamically allocate a buffer for the tag
    strcpy(message->dl_mch_data_tag, "DL_MCH_DATA_TAG_"); // initialize with default value

    return message;
}

// Add the created LTE PHY Layer Control Message to the graph database as a vertex and create random edges between them
void add_to_graph_database(LteMessage* message, Vertex** vertices, Edge** edges) {
    int num_edges = rand() % 10 + 1; // create a random number of edges

    Vertex* vertex = (Vertex*)malloc(sizeof(Vertex));
    if (!vertex) return;
    vertex->id = message->ue_id;
    vertex->properties = (char*)malloc(50); // dynamically allocate memory for properties
    sprintf(vertex->properties, "UE_ID_%lu", message->ue_id);

    vertices[message->ue_id] = vertex; // add the vertex to the graph

    int from = message->ue_id;
    for (int i = 0; i < num_edges; i++) {
        Edge* edge = (Edge*)malloc(sizeof(Edge));
        if (!edge) return;
        edge->from = from;
        edge->to = rand() % message->ue_id + 1; // create random edges
        edge->weight = rand() % 10; // assign random weights

        edges[message->ue_id][i] = edge; // add the edge to the graph
    }
}

// Create a batch of LTE PHY Layer Control Messages and add them to the graph database
int create_edges(Vertex** vertices, Edge** edges, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
        LteMessage* message = create_lte_message(rand() % 10, (unsigned long)i);
        if (!message) return -1;

        add_to_graph_database(message, vertices, edges);

        // release memory
        free(message->dl_mch_data_tag);
        free(message);
    }

    return 0;
}

int main() {
    // initialize the graph database with a specified number of messages
    int num_messages = 10;
    Vertex* vertices[num_messages];
    Edge** edges = (Edge**)malloc(num_messages * sizeof(Edge*));
