#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
    union {
        NFAPI_CRC_INDICATION_PDU_T next;
        unsigned long dummy;
    } u;
} NFAPI_CRC_INDICATION_PDU_S;

// Function to manage the linked list
void nfast_crc_indication_pdu_list_manager(int num_elements) {
    // Initialize the head of the linked list
    NFAPI_CRC_INDICATION_PDU_S* head = NULL;

    // Initialize a hash table for fast lookups by RNTI and RX_UE_INFORMATION_TAG
    unsigned long* rnti_hash_table = (unsigned long*)malloc((num_elements * 2) * sizeof(unsigned long));
    memset(rnti_hash_table, 0xFF, (num_elements * 2) * sizeof(unsigned long));

    // Iterate over the specified number of elements
    for(int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_S* new_pdu = (NFAPI_CRC_INDICATION_PDU_S*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_S));

        // Initialize the RNTI and RX_UE_INFORMATION_TAG values
        new_pdu->RNTI = rand() % 0x10000;
        new_pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;

        // Randomly set the CRCFLAG value
        new_pdu->CRCFLAG = (unsigned char)rand();

        // Link the new pdu to the existing linked list
        if (!head) {
            head = &new_pdu->u.next;
        } else {
            NFAPI_CRC_INDICATION_PDU_S* current = head;
            while (&current->u.next != NULL) {
                current = &current->u.next;
            }
            current->u.next = new_pdu;
        }

        // Insert the RNTI and RX_UE_INFORMATION_TAG into the hash table
        rnti_hash_table[new_pdu->RNTI] = (unsigned long)new_pdu;
        rnti_hash_table[(new_pdu->RX_UE_INFORMATION_TAG * 0x10000) + new_pdu->RNTI] = (unsigned long)new_pdu;

        // Update pointers for the newly added pdu
        if (&head->u.next == &new_pdu->u.next) {
            head = &new_pdu->u.next;
        }
    }

    // Free the linked list and hash table when done
    NFAPI_CRC_INDICATION_PDU_S* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_S* next = current->u.next;
        free(current);
        current = next;
    }
    free(rnti_hash_table);
}
