typedef struct {
    int key;
    int value;
} record_t;

record_t* record_new(int key, int value) {
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->key = key;
    new_record->value = value;
    return new_record;
}

int record_free(record_t** records, size_t num_records) {
    for(size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
    return 0;
}

record_t* dataset_new(size_t initial_capacity) {
    record_t** records = (record_t**)malloc(initial_capacity * sizeof(record_t*));
    for(size_t i = 0; i < initial_capacity; ++i) {
        records[i] = NULL;
    }
    return records;
}

void dataset_free(record_t** records, size_t num_records) {
    record_free(records, num_records);
    free(records);
}

record_t* dataset_insert(record_t** records, int key, int value, size_t* capacity) {
    if(key >= *capacity) {
        *capacity *= 2;
        record_t** new_records = (record_t**)realloc(*records, (*capacity) * sizeof(record_t*));
        for(size_t i = *capacity/2; i < *capacity; ++i) {
            new_records[i] = NULL;
        }
        *records = new_records;
    }

    int unique_key = key;
    for(size_t i = 0; i < *capacity; ++i) {
        if(records[i]) {
            if(records[i]->key == key) {
                unique_key++;
                break;
            }
        }
    }

    record_t* new_record = record_new(unique_key, value);
    records[unique_key] = new_record;
    return new_record;
}

int dataset_log(int num_allocations, int num_duplicates) {
    printf("Allocations: %d, Duplicates: %d\n", num_allocations, num_duplicates);
    return 0;
}

record_t* dataset_random(size_t capacity, record_t** records, size_t num_records) {
    srand(time(NULL));
    for(int i = 0; i < num_records; ++i) {
        int key = rand() % capacity;
        int value = rand();
        dataset_insert(records, key, value, &capacity);
    }
    return NULL;
}
