typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    uint16_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
node* head = NULL;

void insert_node(NFAPI_CRC_INDICATION_PDU_T* new_data) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->data = *new_data;
    new_node->next = head;
    pthread_mutex_lock(&mutex);
    if (head != NULL) {
        node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = &new_node->data;
    } else {
        head = &new_node->data;
    }
    pthread_mutex_unlock(&mutex);
}

void remove_node(RNTI rnti) {
    node* prev = NULL;
    node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (prev != NULL) {
                prev->next = current->next;
            } else {
                head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&mutex);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void* iterate_list(void* arg) {
    node* current = head;
    while (current != NULL) {
        // process the data
        printf("%x %d %x\n", current->data.rnti, current->data.crcflag, current->data.crc_indication_rel8);
        current = current->next;
    }
    return NULL;
}

int main() {
    pthread_t thread;

    pthread_create(&thread, NULL, iterate_list, NULL);

    // example usage
    NFAPI_CRC_INDICATION_PDU_T new_data1 = { .rx_ue_info = "something", .rnti = 0x1234, .crc_indication_rel8 = "more data" };
    insert_node(&new_data1);

    NFAPI_CRC_INDICATION_PDU_T new_data2 = { .rx_ue_info = "another thing", .rnti = 0x5678, .crc_indication_rel8 = "even more data" };
    insert_node(&new_data2);

    // remove the first node
    remove_node(0x1234);

    pthread_join(thread, NULL);
}
