} LtePhyMessage;

// Define the dynamic array of LtePhyMessages
LtePhyMessage** lte_phy_messages = NULL;
int num_lte_phy_messages = 0;

// Function to manage dynamic array of LTE PHY Layer Control Messages
void manage_lte_phy_messages(int op, int phich_config, uint32_t ue_id, char* dl_mch_data_tag) {
    // Determine operation type (CREATE, UPDATE, DELETE)
    switch(op) {
        case 1: // CREATE
            // Allocate memory for new message
            LtePhyMessage* new_message = (LtePhyMessage*)malloc(sizeof(LtePhyMessage));
            if(new_message == NULL) {
                printf("Error allocating memory.\n");
                return;
            }
            new_message->phich_config = phich_config;
            new_message->ue_id = ue_id;
            new_message->dl_mch_data_tag = dl_mch_data_tag;
            // Append new message to the array
            lte_phy_messages = (LtePhyMessage**)realloc(lte_phy_messages, (num_lte_phy_messages + 1) * sizeof(LtePhyMessage*));
            if(lte_phy_messages == NULL) {
                printf("Error reallocating memory.\n");
                return;
            }
            lte_phy_messages[num_lte_phy_messages] = new_message;
            num_lte_phy_messages++;
            break;
        case 2: // UPDATE
            // Find the message to update and update its fields
            for(int i = 0; i < num_lte_phy_messages; i++) {
                if(lte_phy_messages[i]->ue_id == ue_id) {
                    lte_phy_messages[i]->phich_config = phich_config;
                    lte_phy_messages[i]->dl_mch_data_tag = dl_mch_data_tag;
                    break;
                }
            }
            break;
        case 3: // DELETE
            // Find the message to delete and remove it from the array
            for(int i = 0; i < num_lte_phy_messages; i++) {
                if(lte_phy_messages[i]->ue_id == ue_id) {
                    free(lte_phy_messages[i]);
                    memmove(&lte_phy_messages[i], &lte_phy_messages[i + 1], (num_lte_phy_messages - i - 1) * sizeof(LtePhyMessage*));
                    num_lte_phy_messages--;
                    break;
                }
            }
            break;
        default:
            printf("Invalid operation.\n");
    }
}

