// Define a record structure with an integer field
typedef struct {
    int key;
    int value;
} Record;

// Define the maximum size for arrays
#define MAX_SIZE 1000

// Custom hash function to determine unique keys
int customHash(int key) {
    return key % MAX_SIZE;
}

// Function to initialize and manipulate arrays and records
void processArrays(int* offsetValues, int* keys, Record* records) {
    // Initialize frequency tracking for generated values
    int valueFrequency[MAX_SIZE] = {0};

    // Set the value of each record's int field to a random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < MAX_SIZE; i++) {
        Record currentRecord;
        do {
            currentRecord.value = rand() % 100;
        } while (valueFrequency[currentRecord.value] > 5);

        // Update frequency tracking and record values
        valueFrequency[currentRecord.value]++;
        records[i].key = customHash(keys[i]);
        records[i].value = currentRecord.value;
    }
}

// Main function to perform array initialization, record allocation, and memory deallocation
void performTask(int size) {
    // Validate input size
    if (size > MAX_SIZE) {
        printf("Error: Input size exceeds maximum allowed size.\n");
        return;
    }

    // Dynamically allocate memory for arrays
    int* offsetValues = (int*)malloc(size * sizeof(int));
    int* keys = (int*)malloc(size * sizeof(int));

    // Initialize arrays with user input values
    for (int i = 0; i < size; i++) {
        offsetValues[i] = i;
        keys[i] = i;
    }

    // Allocate memory for and initialize an array of record structures
    Record* records = (Record*)malloc(size * sizeof(Record));
    for (int i = 0; i < size; i++) {
        records[i].key = customHash(keys[i]);
        records[i].value = offsetValues[i];
    }

    // Perform array manipulation using the processArrays function
    processArrays(offsetValues, keys, records);

    // Deallocate memory for arrays and record structures
    free(offsetValues);
    free(keys);
    free(records);
}

int main() {
    int size;
    printf("Enter the desired size (1-%d): ", MAX_SIZE);
    scanf("%d", &size);

    performTask(size);

    return 0;
}
