#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <zlib.h>

#define NETWORK_EVENT_LOG_ENTRY_MAX_SIZE 1024
#define NETWORK_EVENT_LOG_FILE_FORMAT "json"

typedef struct {
    time_t timestamp;
    int event_id;
    struct CellIDNode* cell_ids;
} NetworkEventLogEntry;

typedef struct CellIDNode {
    int cell_id;
    struct CellIDNode* next;
    struct CellIDNode* prev;
} CellIDNode;

// Dynamic array of NetworkEventLogEntry structures
NetworkEventLogEntry** network_event_log_entries = NULL;
int network_event_log_entry_count = 0;
int network_event_log_entry_max_size = NETWORK_EVENT_LOG_ENTRY_MAX_SIZE;

void init_network_event_log() {
    // Initialize dynamic array with initial size
    network_event_log_entries = (NetworkEventLogEntry**)malloc(network_event_log_entry_max_size * sizeof(NetworkEventLogEntry*));
}

void add_network_event_log_entry(int event_id, int cell_ids_count) {
    NetworkEventLogEntry* entry = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry));
    entry->event_id = event_id;
    entry->timestamp = time(NULL);

    // Allocate memory for cell IDs
    entry->cell_ids = (CellIDNode*)malloc(cell_ids_count * sizeof(CellIDNode));
    for (int i = 0; i < cell_ids_count; i++) {
        entry->cell_ids[i].cell_id = i;
        entry->cell_ids[i].next = &entry->cell_ids[i + 1];
        if (i == cell_ids_count - 1) {
            entry->cell_ids[i].prev = &entry->cell_ids[i - 1];
            entry->cell_ids[i].next = NULL;
        }
    }

    // Compress timestamp using zlib
    unsigned char* compressed_timestamp = (unsigned char*)malloc((int)(sizeof(entry->timestamp)) * 2);
    deflate(compressed_timestamp, entry->timestamp, Z_DEFAULT_COMPRESSION);

    // Add new event to dynamic array
    if (network_event_log_entry_count == network_event_log_entry_max_size) {
        // Resize dynamic array if necessary
        network_event_log_entries = (NetworkEventLogEntry**)realloc(network_event_log_entries,
            (network_event_log_entry_max_size * 2 + 1) * sizeof(NetworkEventLogEntry*));
        network_event_log_entry_max_size *= 2;
    }
    network_event_log_entries[network_event_log_entry_count++] = entry;
}

void log_network_events_to_file(const char* file_path) {
    FILE* file = fopen(file_path, "w");
    for (int i = 0; i < network_event_log_entry_count; i++) {
        NetworkEventLogEntry* entry = network_event_log_entries[i];
        // Write event to file in specified log format
        fwrite(&entry->event_id, sizeof(int), 1, file);
        fwrite(&entry->timestamp, sizeof(time_t), 1, file);
        int cell_ids_count = (int)strlen((char*)malloc(entry->cell_ids_count * sizeof(char)));
        for (int j = 0; j < cell_ids_count; j++) {
            fwrite(&entry->cell_ids[j].cell_id, sizeof(int), 1, file);
        }
    }
    fclose(file);
}

void free_network_event_log() {
    for (int i = 0; i < network_event_log_entry_count; i++) {
        NetworkEventLogEntry* entry = network_event_log_entries[i];
        free(entry->cell_ids);
        free(entry);
    }
    free(network_event_log_entries);
}
