#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    int bearer_ID;
    int QoS_CLASS_ID;
    int traffic_priority;
} UESessionData;

typedef struct {
    UESessionData* data;
    int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* createDynamicList(int capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (UESessionData*)calloc(capacity, sizeof(UESessionData));
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyDynamicList(DynamicList* list) {
    if (!list) return;
    free(list->data);
    free(list);
    pthread_mutex_destroy(&list->lock);
}

int getSessionDataCapacity(DynamicList* list) {
    return list->size * 2; // Dynamically resize the array by a factor of two
}

void pushSessionData(DynamicList* list, UESessionData data) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= getSessionDataCapacity(list)) {
        DynamicList* new_list = createDynamicList(getSessionDataCapacity(list));
        for (int i = 0; i < list->size; i++) {
            new_list->data[i] = list->data[i];
        }
        destroyDynamicList(list);
        list = new_list;
    }

    list->data[list->size++] = data;

    pthread_mutex_unlock(&list->lock);
}

UESessionData popSessionData(DynamicList* list) {
    UESessionData ret;
    pthread_mutex_lock(&list->lock);

    if (list->size > 0) {
        ret = list->data[--list->size];
        free(list->data + list->size);
    }

    pthread_mutex_unlock(&list->lock);
    return ret;
}

int main() {
    DynamicList* list = createDynamicList(10); // Initialize with a small capacity

    for (int i = 0; i < 1000000; i++) {
        UESessionData data = {i, i, i, i}; // Create test session data
        pushSessionData(list, data);
    }

    for (int i = 999999; i >= 0; i--) {
        UESessionData data = popSessionData(list);
        if (data.UE_ID != i) {
            printf("Mismatch at index %d: expected UE_ID %d, got %d.\n", i, i, data.UE_ID);
        }
    }

    destroyDynamicList(list);

    return 0;
}
