typedef struct {
    int value;
    char active;
    long *offset;
    time_t timestamp;
} record;

record* manage_memory(size_t threshold, size_t num_records) {
    // Calculate total memory required for arrays and records
    size_t total_memory = (sizeof(int) + sizeof(long)) * 4 + sizeof(record) * num_records;

    if (total_memory > threshold) {
        printf("Memory allocation failed. Exceeds threshold.\n");
        return NULL;
    }

    int* keys = (int*)malloc(sizeof(int) * num_records);
    long* offsets = (long*)malloc(sizeof(long) * num_records);
    record* records = (record*)malloc(sizeof(record) * num_records);
    time_t* timestamps = (time_t*)malloc(sizeof(time_t) * num_records);

    for (size_t i = 0; i < num_records; i++) {
        keys[i] = i + 1;
        offsets[i] = (long)i;
        records[i].value = rand() % 100 + 1;
        while (records[i].value > 50) {
            // Ensure no duplicates and unique within sliding window
            records[i].value = (records[i-1].value - 50) % 51 + 1;
        }
        records[i].active = true;
        timestamps[i] = time(NULL);
    }

    for (size_t i = 0; i < num_records; i++) {
        // Track last accessed time and identify inactive records
        if (!records[i].active) {
            // Clear inactive records periodically to maintain memory efficiency
            free(records[i].offset);
            free(&records[i]);
        }
    }

    free(keys);
    free(offsets);
    free(timestamps);

    return records;
}
