```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

// Define the structure
typedef struct {
    int rnti;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

void parse_xml_config(const char* filename, int* num_structures, NFAPI_CRC_INDICATION_PDU_T** structures) {
    xmlDoc *doc = NULL;
    xmlNode *root = NULL;
    xmlAttr *attr = NULL;
    xmlChar *content = NULL;
    NFAPI_CRC_INDICATION_PDU_T* structure = NULL;
    int i;

    // Initialize the array
    *num_structures = 0;
    *structures = NULL;

    // Load the XML file
    doc = xmlReadFile(filename, NULL, XML_PARSE_NOERROR);
    if (doc == NULL) {
        // Handle error
    }

    // Parse the root node
    root = xmlDocGetRootElement(doc);
    if (root == NULL) {
        // Handle error
    }

    // Get the number of structures from the config file
    attr = xmlGetAttr(root, "num-structures");
    if (attr != NULL && attr->children != NULL) {
        *num_structures = atoi((char*)attr->children->content);
    } else {
        // Handle error
    }

    // Allocate memory for structures
    *structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (*structures == NULL) {
        // Handle error
    }
    for (i = 0; i < *num_structures; i++) {
        structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structure == NULL) {
            // Handle error
        }
        (*structures)[i] = structure;
    }

    // Parse the XML file and populate structures
    for (root = xmlDocGetRootElement(doc); root != NULL; root = root->next) {
        if (xmlStrEqual(root->name, "structure")) {
            attr = root->children->attributes;
            if (attr != NULL && attr->children != NULL) {
                content = xmlNodeGetContent(attr->children);
                structure->rnti = atoi((char*)content);
                // Parse other fields and populate the structure
            }
        }
    }

    // Free memory and close the XML file
    for (i = 0; i < *num_structures; i++) {
        free((*structures)[i]);
    }
    free(*structures);
    xmlFreeDoc(doc);

    return;
}

int main() {
    int num_structures;
    NFAPI_CRC_INDICATION_PDU_T* structures;

    parse_xml_config("config.xml", &num_structures, &structures);

    // Use the structures as needed
    for (int i = 0; i < num_structures; i++) {
        printf("%d\n", structures[i]->rnti);
    }

    return 0;
}
