void* dynamic_allocation(int size, int num_allocations) {
    // Check if the requested memory can be allocated
    for (int i = 0; i < num_allocations; i++) {
        void* ptr = malloc(size);
        if (ptr == NULL) {
            // If memory allocation fails, reduce the list size and continue with the remaining allocations
            return ptr;
        }
    }

    return NULL;
}

void log_allocation_success(int allocations) {
    // Log successful memory allocations to track performance metrics
    printf("Memory allocation succeeded for %d structures.\n", allocations);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    int num_allocations = 10000;  // Number of structures to allocate

    NFAPI_CRC_INDICATION_PDU_T* struct_list;
    int size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Dynamic memory allocation for the list
    void* ptr = dynamic_allocation(size, num_allocations);
    if (ptr == NULL) {
        printf("Memory allocation failed. Reducing list size...\n");
        num_allocations /= 2;  // Reduce the list size by half
        ptr = dynamic_allocation(size, num_allocations);
    }

    struct_list = (NFAPI_CRC_INDICATION_PDU_T*)ptr;

