    int num_structures;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool memory_pool;

void initialize_memory_pool() {
    memory_pool.num_structures = 0;
    pthread_mutex_init(&memory_pool.mutex, NULL);
}

int create_structure(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_structure;

    pthread_mutex_lock(&memory_pool.mutex);
    if (memory_pool.num_structures >= MAX_STRUCTURES) {
        return -1; // Memory pool is full
    }

    new_structure = memory_pool.structures[memory_pool.num_structures];
    if (!new_structure) {
        new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        strcpy(new_structure->RX_UE_INFORMATION_TAG, "tag");
        strcpy(new_structure->RNTI, "rnti");
        strcpy(new_structure->CRC_INDICATION_REL8_TAG, "tag");
        srand(time(NULL)); // Initialize random seed
        new_structure->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else {
        memset(new_structure, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    memory_pool.structures[memory_pool.num_structures] = new_structure;
    memory_pool.num_structures++;

    pthread_mutex_unlock(&memory_pool.mutex);

    return 0; // Structure created successfully
}

void log_structure_creation(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    FILE* log_file;
    char file_name[256];

    sprintf(file_name, "log_%d.txt", time(NULL)); // Generate unique log file name

    if ((log_file = fopen(file_name, "a")) == NULL) {
        perror("Error opening log file");
        return; // Unable to open log file
    }

    fprintf(log_file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);

    fclose(log_file);
}

void release_memory_pool() {
    pthread_mutex_lock(&memory_pool.mutex);

    for (int i = 0; i < memory_pool.num_structures; i++) {
        free(memory_pool.structures[i]);
    }

    memory_pool.num_structures = 0;

    pthread_mutex_unlock(&memory_pool.mutex);
}
