#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define MIN_VALUE 0
#define MAX_VALUE 255

typedef struct {
    int id;
    int minValue;
    int maxValue;
    char data[1024];
} Record;

typedef struct {
    int size;
    Record *records;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *createMemoryPool(int size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->size = size;
    pool->records = malloc(size * sizeof(Record));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroyMemoryPool(MemoryPool *pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int createRecord(MemoryPool *pool, int id, int minValue, int maxValue) {
    Record record;
    record.id = id;
    record.minValue = minValue;
    record.maxValue = maxValue;
    // Simulate random data generation
    for (int i = 0; i < 1024; i++) {
        record.data[i] = rand() % 256;
    }
    pthread_mutex_lock(&pool->lock);
    int idx = pool->size++;
    pool->records[idx] = record;
    pthread_mutex_unlock(&pool->lock);
    return idx;
}

int validateRecord(MemoryPool *pool, int id) {
    Record *record = &pool->records[id];
    // Validate record integrity
    if (id >= pool->size || record->minValue < MIN_VALUE || record->maxValue > MAX_VALUE) {
        printf("Error: Invalid record ID %d or data\n", id);
        return -1;
    }
    return 0;
}

void *processRecords(void *arg) {
    MemoryPool *pool = (MemoryPool *) arg;
    for (int i = 0; i < MAX_RECORDS; i++) {
        int id = createRecord(pool, i, MIN_VALUE, MAX_VALUE);
        if (id == -1) break;
        validateRecord(pool, id);
    }
    return NULL;
}

int main() {
    MemoryPool *pool = createMemoryPool(MAX_RECORDS);
    pthread_t thread;
    pthread_create(&thread, NULL, processRecords, pool);
    pthread_join(thread, NULL);
    destroyMemoryPool(pool);
    return 0;
}
