typedef struct {
    int value;
} Record;

void* alloc_record(int num_records) {
    void* ptr = malloc(num_records * sizeof(Record));
    if (!ptr) return NULL;
    return ptr;
}

int gen_random(int seed, int max_value) {
    // simple linear congruential generator
    seed = (seed * 1103515245 + 12345) % 2^31;
    return (seed % (max_value + 1));
}

void serialize_record(Record* record, uint8_t* buffer) {
    *(uint32_t*)buffer = htonl(record->value);
    buffer += sizeof(uint32_t);
}

int deserialize_record(uint8_t* buffer, Record* record) {
    memcpy(&record->value, buffer, sizeof(uint32_t));
    return 0;
}

void* alloc_offsets(int num_records) {
    void* ptr = malloc(num_records * sizeof(long));
    if (!ptr) return NULL;
    return ptr;
}

void* alloc_keys(int num_records) {
    void* ptr = malloc(num_records * sizeof(int));
    if (!ptr) return NULL;
    return ptr;
}

