    if (!records) {
        printf("Memory allocation failure\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        int seed = thread_id * i + i;
        records[i].value = gen_random(seed, max_value);
    }

    // serialize and write to file
    uint8_t* buffer = malloc(num_records * sizeof(Record));
    if (!buffer) {
        printf("Memory allocation failure\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        Record record = records[i];
        serialize_record(&record, &buffer[i * sizeof(Record)]);
    }

    FILE* file = fopen("output.bin", "wb");
    if (!file) {
        printf("Error opening file\n");
        return -1;
    }
    fwrite(buffer, 1, num_records * sizeof(Record), file);
    fclose(file);

    // free resources
    free(buffer);
    free(records);

    return 0;
}
