function manageScripts(scripts) {
  const addedScripts = new Map();
  scripts.forEach((script) => {
    const id = `script-${script.name}`;
    const key = script.name;
    const url = script.url;

    if (!addedScripts.has(key)) {
      addedScripts.set(key, { id, key, url });

      // Asynchronous loading
      fetchScript(url).then((response) => {
        const scriptTag = document.createElement('script');
        scriptTag.id = id;
        scriptTag.src = response.url;
        scriptTag.key = key;

        // Set priorities and dependencies as needed
        if (script.priority) {
          scriptTag.onload = () => {
            // Load dependent scripts
            for (const dependency of script.dependencies) {
              const depScript = addedScripts.get(dependency);
              if (depScript) {
                const depTag = document.getElementById(depScript.id);
                depTag.onload();
              }
            }
          };
        }

        // Add the script tag to the footer
        const footer = document.querySelector('#footer');
        footer.appendChild(scriptTag);

        // Track added scripts
        addedScripts.set(key, { id, key, url });
      });
    }
  });

  function fetchScript(url) {
    return new Promise((resolve) => {
      const scriptTag = document.createElement('script');
      scriptTag.src = url;
      scriptTag.onload = () => {
        resolve({ url, status: 'success' });
      };
      scriptTag.onerror = () => {
        resolve({ url, status: 'error' });
      };

      // Asynchronous loading
      document.head.appendChild(scriptTag);
      scriptTag.onload();
    });
  }
}
