    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    char UE_STATE; // IDLE, CONNECTED, ACTIVE
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure to hold the linked list node
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node
Node* newNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) {
        // Handle memory allocation failure
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the end of the list
void insertNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = newNode(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* lastNode = *head;
        while (lastNode->next != NULL) {
            lastNode = lastNode->next;
        }
        lastNode->next = newNode;
    }
}

// Function to delete a node from the list
void deleteNode(Node** head, int data.RNTI) {
    if (*head == NULL) {
        return; // Node not found
    }

    Node* prev = *head;
    Node* current = *head->next;

    while (current != NULL && current->data.RNTI != data.RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        return; // Node not found
    }

    if (current == *head) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
}

// Function to print the linked list
void printList(Node* head) {
    while (head != NULL) {
        printf("RNTI: %d, UE_STATE: %c\n", head->data.RNTI, head->data.UE_STATE);
        head = head->next;
    }
}

// Function to update the UE_STATE field asynchronously
void updateUEState(Node** head, int RNTI, char newUEState) {
    Node* current = *head;
    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (current == NULL) {
        return; // Node not found
    }

    current->data.UE_STATE = newUEState;
}

// Function to subscribe to state change notifications and process them in batches
void subscribeToStateChange(Node** head, void (*callback)(Node*)) {
    pthread_t thread;

    if (pthread_create(&thread, NULL, processStateChanges, head) != 0) {
        // Handle error creating the thread
    }

    // Process state changes in batches
}

// Function to process state changes and call the callback function
void* processStateChanges(void* arg) {
    Node** head = (Node**) arg;

    while (1) {
        // Find nodes with updated UE_STATE field
        Node* current = *head;
        while (current != NULL) {
            if (current->data.UE_STATE == 'C') { // CONNECTED
                callback(current);
            }
            current = current->next;
        }

        // Sleep for a short duration to allow other threads to access the list
        usleep(100000);

        // Re-fetch the updated nodes
    }
}

int main() {
    Node* head = NULL;

    // Insert nodes into the linked list
    insertNode(&head, (NFAPI_CRC_INDICATION_PDU_T){1, 11, 111, 0x01, 'I'});
    insertNode(&head, (NFAPI_CRC_INDICATION_PDU_T){2, 22, 222, 0x02, 'C'});
    insertNode(&head, (NFAPI_CRC_INDICATION_PDU_T){3, 33, 333, 0x03, 'I'});

    // Print the linked list
    printList(head);

    // Update the UE_STATE field asynchronously
    updateUEState(&head, 22, 'A');

    return 0;
}
