record** initArrays(int *offsetsSize, int *keysSize, int *recordsSize,
                     int minRange, int maxRange, int condition) {
    // Initialize arrays and their sizes
    long* offsets = (long*)malloc(*offsetsSize * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets array.\n");
        return NULL;
    }

    int* keys = (int*)malloc(*keysSize * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys array.\n");
        free(offsets);
        return NULL;
    }

    record** records = (record**)malloc(*recordsSize * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records array.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays with random values
    srand(time(NULL));

    int i;
    for (i = 0; i < *offsetsSize; i++) {
        offsets[i] = (long)rand() % (maxRange - minRange + 1) + minRange;
    }

    for (i = 0; i < *keysSize; i++) {
        keys[i] = rand() % (maxRange - minRange + 1) + minRange;
    }

    // Initialize records array with random values
    for (i = 0; i < *recordsSize; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for record.\n");
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            for (i = 0; i < *keysSize; i++) {
                free(&keys[i]);
            }
            free(offsets);
            return NULL;
        }
        records[i]->value = rand() % (maxRange - minRange + 1) + minRange;
    }

    // Initialize offsetsIndex array
    long* offsetsIndex = (long*)malloc(*offsetsSize * sizeof(long));
    if (!offsetsIndex) {
        fprintf(stderr, "Failed to allocate memory for offsetsIndex array.\n");
        for (int j = 0; j < i; j++) {
            free(records[j]);
        }
        for (i = 0; i < *keysSize; i++) {
            free(&keys[i]);
        }
        free(offsets);
        return NULL;
    }

    // Conditionally fill records array
    for (i = 0; i < *recordsSize; i++) {
        if (condition) {
