void init_lte_phy_messages(int num_messages, pthread_mutex_t* lock) {
    // Initialize variables for statistics
    int successful_allocations = 0;
    int failed_allocations = 0;

    // Allocate memory for the dynamic array
    lte_phy_message** messages = (lte_phy_message**)malloc(num_messages * sizeof(lte_phy_message*));

    if (messages == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

