        if (messages[i] == NULL) {
            failed_allocations++;
            continue;
        }

        // Initialize PHICH_CONFIGURATION and UE_ID
        messages[i]->phich_configuration = 0; // Set to a valid value
        messages[i]->ue_id = i + 1;

        // Allocate buffer for DL_MCH_DATA_TAG with a configurable size limit per message
        int buffer_size_limit = 1024;
        char* buffer = (char*)malloc(buffer_size_limit * sizeof(char));

        if (buffer == NULL) {
            failed_allocations++;
            free(messages[i]);
            messages[i] = NULL;
            continue;
        }

        // Initialize DL_MCH_DATA_TAG buffer
        strcpy(buffer, "DL_MCH_DATA_TAG"); // Set to a valid value

        // Assign the buffer to the message
        messages[i]->dl_mch_data_tag = buffer;

        successful_allocations++;
    }

    // Print statistics on memory allocation
    printf("Successful allocations: %d\n", successful_allocations);
    printf("Failed allocations: %d\n", failed_allocations);

    // Integrate with existing message processing framework to queue messages for further processing
    pthread_mutex_lock(lock);
    // Queue the messages here using the existing framework's API
    pthread_mutex_unlock(lock);
}
