        free(data[i]);
    }

    for (int i = 0; i < *humidity_size; i++) {
        if (data[i] != NULL) {
            free(data[i]);
        }
    }

    // Deallocate linked list nodes
    Node* current = records;
    while (current->next != NULL) {
        Node* next = current->next;
        current->next = NULL;
        free(current);
        current = next;
    }
}
