// Thread-safe hash table
typedef struct {
    size_t size;
    void** buckets;
    pthread_mutex_t mutex;
} HashTable;

HashTable* hash_table_create(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->buckets = (void**)calloc(initial_size, sizeof(void*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

bool hash_table_insert(HashTable* table, int RNTI) {
    size_t index = RNTI % table->size;
    void** bucket = &table->buckets[index];
    for (void** p = *bucket; *p != NULL; p++) {
        if (((NFAPI_CRC_INDICATION_PDU_T*)*p)->RNTI == RNTI) {
            return false; // duplicate key
        }
    }
    *bucket = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ((NFAPI_CRC_INDICATION_PDU_T*)*bucket)->RNTI = RNTI;
    pthread_mutex_unlock(&table->mutex);
    return true;
}

// Function to populate and manage CRC indications
