        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % (1 << 16);
        crc_indications[i].CRCFLAG = (rand() & 1) ? true : false;
    }

    return crc_indications;
}

// Helper function to find the largest integer in an array
