    char subnet_mask[16];
    char gateway[16];
    void* custom_routing_rules;
    int phich_configuration;
    int ue_id;
    void* dl_mch_data_tag;
} network_interface_config;

typedef struct {
    network_interface_config* configs;
    size_t config_count;
} configuration_collection;

configuration_collection initialize_collection() {
    configuration_collection collection = {NULL, 0};
    return collection;
}

int add_config(configuration_collection* collection, char* ip_address, char* subnet_mask, char* gateway, int phich_configuration, int ue_id, void* custom_routing_rules, void* dl_mch_data_tag) {
    network_interface_config* new_config = (network_interface_config*)malloc(sizeof(network_interface_config));
    strcpy(new_config->ip_address, ip_address);
    strcpy(new_config->subnet_mask, subnet_mask);
    strcpy(new_config->gateway, gateway);
    new_config->custom_routing_rules = custom_routing_rules;
    new_config->phich_configuration = phich_configuration;
    new_config->ue_id = ue_id;
    new_config->dl_mch_data_tag = dl_mch_data_tag;

    if (collection->configs == NULL) {
        collection->configs = new_config;
        collection->config_count = 1;
    } else {
        network_interface_config** temp_configs = (network_interface_config**)malloc((collection->config_count + 2) * sizeof(network_interface_config*));
        memcpy(temp_configs, collection->configs, collection->config_count * sizeof(network_interface_config*));
        free(collection->configs);
        temp_configs[collection->config_count] = new_config;
        collection->configs = temp_configs;
        collection->config_count++;
    }

    return 0;
}

int validate_config(network_interface_config* config) {
    // Validate IP address, subnet mask, gateway, and custom routing rules
    if (strlen(config->ip_address) > 15 || strlen(config->subnet_mask) > 15 || strlen(config->gateway) > 15) {
        return -1;
    }
    // Validate PHICH configuration and UE ID
    if (config->phich_configuration < 0 || config->ue_id < 0) {
        return -2;
    }

    return 0;
}

int process_config(configuration_collection* collection, network_interface_config* new_config) {
    int err = validate_config(new_config);
    if (err != 0) {
        // Handle invalid configuration
        free(new_config->custom_routing_rules);
        free(new_config->dl_mch_data_tag);
        free(new_config);
        return -1;
    }

    add_config(collection, new_config->ip_address, new_config->subnet_mask, new_config->gateway, new_config->phich_configuration, new_config->ue_id, new_config->custom_routing_rules, new_config->dl_mch_data_tag);

    return 0;
}

void free_collection(configuration_collection* collection) {
    for (size_t i = 0; i < collection->config_count; i++) {
        free(collection->configs[i]->custom_routing_rules);
        free(collection->configs[i]->dl_mch_data_tag);
        free(collection->configs[i]);
    }
    free(collection->configs);
}

int main() {
    configuration_collection collection = initialize_collection();
    // Add configurations and messages to the collection
    process_config(&collection, /* ... */);

    // Free the collection when done
    free_collection(&collection);

    return 0;
}
