    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with given data
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a new node at the end of the list
void insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to find a node with given RNTI
Node* find_node(Node* head, RNTI rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to remove a node with given RNTI
void remove_node(Node** head, RNTI rnti) {
    Node* current = *head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to periodically remove outdated entries
void garbage_collection(Node** head, int age_threshold) {
    Node* current = *head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.crc_indication_rel8.age > age_threshold) {
            previous = current;
            current = current->next;
            free(previous);
        } else {
            previous = current;
            current = current->next;
        }
    }
    *head = current;
}

// Example usage
int main() {
    Node* head = NULL;

    // Insert nodes with unique RNTI values
    insert_node(&head, create_node({/* data */}, 1));
    insert_node(&head, create_node({/* data */}, 2));
    insert_node(&head, create_node({/* data */}, 3));

    // Find a node by its RNTI value
    Node* found_node = find_node(head, 2);
    if (found_node != NULL) {
        printf("Found node with RNTI %d\n", found_node->data.rnti);
    } else {
        printf("Node not found\n");
    }

    // Remove a node by its RNTI value
    remove_node(&head, 3);

    // Periodically remove outdated entries
    garbage_collection(&head, 10);

    return 0;
}
