typedef struct {
    time_t timestamp;
    int value;
    void* key_ptr;
} record;

record** initialize_cache(int num_records, int max_value) {
    // Initialize memory pool for records and keys
    int offset_size = sizeof(record*) * (num_records + 1);
    int* offsets = malloc(offset_size);
    if (!offsets) return NULL; // Handle allocation failure

    void* key_pool = malloc(sizeof(void*) * num_records);
    if (!key_pool) {
        free(offsets);
        return NULL;
    }

    record** records = malloc(sizeof(record*) * (num_records + 1));
    if (!records) {
        free(offsets);
        free(key_pool);
        return NULL;
    }

    // Initialize and populate records array
    for (int i = 0; i < num_records; i++) {
        record* r = malloc(sizeof(record));
        r->timestamp = time(NULL);
        r->value = rand() % max_value;
        r->key_ptr = key_pool + i;

        records[i] = r;
        offsets[i] = (int*)r;
    }
    records[num_records] = NULL; // Terminate list

    return records;
}
