['```
function traverseDOM(selector, options = {}) {
  const { cacheEnabled = true, cacheTTL = 1000 } = options;
  let cache = {};
  let timerId;

  function reevaluateMatches(element) {
    clearTimeout(timerId);
    timerId = setTimeout(() => {
      const matches = getMatches(element, selector);
      if (matches.length > 0) {
        callback(matches);
      }
    }, 16); // wait for the next animation frame
  }

  function getMatches(root, selector) {
    if (!root) return [];
    if (cache[selector]) {
      const cachedMatches = cache[selector];
      if (cachedMatches.expirationTime > Date.now()) {
        return cachedMatches.matches;
      }
    }

    let matches = [];
    if (root.querySelectorAll) {
      matches = root.querySelectorAll(selector);
    } else {
      let matchCount = 0;
      (function traverse(node) {
        if (!node) return;
        if (node.classList) {
          for (let i = 0; i < node.classList.length; i++) {
            const className = node.classList[i];
            if (className === selector) {
              matches.push(node);
              matchCount++;
            }
          }
        }
        traverse(node.querySelector(selector));
      })(root);
    }

    if (cacheEnabled && matches.length > 0) {
      cache[selector] = { matches, expirationTime: Date.now() + cacheTTL };
    }

    return matches;
  }

  function callback(matches) {
    // handle matches here
  }

  if (cacheEnabled) {
    timerId = setTimeout(() => {
      const selectorMatches = getMatches(document.body, selector);
      if (selectorMatches.length > 0) {
        callback(selectorMatches);
      }
    }, cacheTTL);
  } else {
    const matches = getMatches(document.body, selector);
    if (matches.length > 0) {
      callback(matches);
    }
  }

  // listen for DOM mutations and reevaluate matches
  document.addEventListener("DOMSubtreeModified", () => {
    reevaluateMatches(document.body);
  });
}
