// Define the structure for a named semaphore
typedef struct {
    char name[20];
    int value;
    struct {
        pthread_mutex_t mutex;
        pthread_cond_t cond;
    } lock;
} NamedSemaphore;

// Function to create a named semaphore with an initial value
NamedSemaphore* create_semaphore(const char* name, int init_value) {
    // Create the semaphore structure and initialize its components
    NamedSemaphore* sem = (NamedSemaphore*)malloc(sizeof(NamedSemaphore));
    strcpy(sem->name, name);
    sem->value = init_value;

    // Initialize the mutex and condition variable for synchronization
    pthread_mutex_init(&sem->lock.mutex, NULL);
    pthread_cond_init(&sem->lock.cond, NULL);

    return sem;
}

// Function to delete a named semaphore by name
void delete_semaphore(NamedSemaphore* sem) {
    // Deferring deletion until all active operations have completed
    pthread_mutex_lock(&sem->lock.mutex);
    pthread_cond_signal(&sem->lock.cond);
    pthread_mutex_unlock(&sem->lock.mutex);

    // Free the allocated memory for the semaphore structure
    free(sem);
}

// Function to initialize a dynamic array of LTE_DL_FRAME_STRUCT structures
LTE_DL_FRAME_STRUCT** init_frame_array(int num_frames) {
    // Allocate memory for the frame array and its elements
    LTE_DL_FRAME_STRUCT** frames = (LTE_DL_FRAME_STRUCT**)malloc(num_frames * sizeof(LTE_DL_FRAME_STRUCT*));

    // Initialize each frame structure with valid header, symbol, data, and CQI information
    for (int i = 0; i < num_frames; i++) {
        frames[i] = (LTE_DL_FRAME_STRUCT*)malloc(sizeof(LTE_DL_FRAME_STRUCT));
        frames[i]->dl_frame_header = rand() % 100;
        frames[i]->pdsch_symbol = rand() % 10;
        frames[i]->pdsch_data = rand();
        frames[i]->cqi = rand() % 5;
    }

    return frames;
}

// Function to validate the integrity of generated frame data
int validate_frames(LTE_DL_FRAME_STRUCT** frames, int num_frames) {
    // Add your validation logic here
    for (int i = 0; i < num_frames; i++) {
        // Check if each frame contains valid values
        if (frames[i]->dl_frame_header < 0 || frames[i]->pdsch_symbol < 0 || frames[i]->pdsch_data < 0 || frames[i]->cqi < 0) {
            return -1;
        }
    }

    return 0;
}

int main() {
    // Create a named semaphore with an initial value of 500
