#include <iostream>
#include <map>
#include <mutex>
#include <thread>

struct UEContext {
    int ueId;
    int sTmsi;
    int ambr;
    int priorityLevel;
    double qosParameter;
    long processingDelay = 0; // in milliseconds
};

std::map<int, UEContext> ueContextPool;

void updateQoS(int ueId, double congestionLevel) {
    UEContext& context = ueContextPool[ueId];
    if (congestionLevel > 50) { // adjust QoS based on congestion level
        context.qosParameter *= 0.8; // decrease QoS parameter for high congestion
    } else {
        context.qosParameter *= 1.2; // increase QoS parameter for low congestion
    }
}

void processUE(int ueId, double congestionLevel) {
    updateQoS(ueId, congestionLevel);
    UEContext& context = ueContextPool[ueId];
    std::this_thread::sleep_for(std::chrono::milliseconds(context.processingDelay)); // simulate processing delay
    std::cout << "Processed UE " << ueId << " with QoS parameter " << context.qosParameter << std::endl;
}

void initializeUE(int ueId, int sTmsi, int ambr, int priorityLevel) {
    UEContext newContext{ueId, sTmsi, ambr, priorityLevel};
    ueContextPool[ueId] = newContext;
}

int main() {
    // Initialize UEs
    initializeUE(1, 12345, 1000, 2);
    initializeUE(2, 67890, 1500, 3);

    // Simulate congestion monitoring service updates
    std::thread updateThread([&](){
        while (true) {
            for (auto& context : ueContextPool) {
                double congestionLevel = 50 + rand() % 100; // simulate random congestion level
                processUE(context.first, congestionLevel);
            }
            std::this_thread::sleep_for(std::chrono::seconds(1)); // update every second
        }
    });

    // Process UEs concurrently
    std::vector<std::thread> ueThreads;
    for (auto& context : ueContextPool) {
        ueThreads.emplace_back([&context]() { processUE(context.first, 50); });
    }

    for (int i = 0; i < ueThreads.size(); ++i) {
        ueThreads[i].join();
    }

    return 0;
}
