#include <stdlib.h>
#include <stdio.h>
#include <math.h>

typedef struct {
    int x;
    int y;
} point;

typedef struct {
    int num_points;
    point* points;
} polygon;

double area_of_polygon(polygon* p) {
    double sum = 0.0;
    for (int i = 0; i < p->num_points; i++) {
        int j = (i + 1) % p->num_points;
        sum += (p->points[i].x * p->points[j].y - p->points[j].x * p->points[i].y);
    }
    return fabs(sum / 2.0);
}

polygon* read_polygon_data(char* filename, int* num_polygons) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;
    }

    int num_points;
    fscanf(file, "%d", &num_points);

    *num_polygons = 1;

    polygon* poly = malloc(sizeof(polygon));
    poly->num_points = num_points;
    poly->points = malloc(num_points * sizeof(point));

    for (int i = 0; i < num_points; i++) {
        point p;
        fscanf(file, "%d %d", &p.x, &p.y);
        poly->points[i] = p;
    }

    fclose(file);

    return poly;
}

double* calculate_areas(polygon** polygons, int num_polygons) {
    double* areas = malloc(num_polygons * sizeof(double));
    for (int i = 0; i < num_polygons; i++) {
        areas[i] = area_of_polygon(polygons[i]);
    }
    return areas;
}
