        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = ueInfo[i].RX_UE_INFORMATION_TAG;
        pdu.RNTI = ueInfo[i].RNTI;
        pdu.CRCFLAG = getRandomCRCFlag();

        pduArray[i] = pdu;
    }

    return pduArray;
}

int validatePDU(NFAPI_CRC_INDICATION_PDU_T* pdu, int batchSize) {
    UE_INFO cache[batchSize];
    for (int i = 0; i < batchSize; i++) {
        if (i > 0 && ueInfo[i-1].RX_UE_INFORMATION_TAG == pdu[i].RX_UE_INFORMATION_TAG
            && ueInfo[i-1].RNTI == pdu[i].RNTI) {
            // Cache the combination to avoid redundant validation
            cache[i] = ueInfo[i];
        } else {
            // Check CRCFLAG consistency with expected behavior for each RX_UE_INFORMATION_TAG and RNTI pair
            // (Note: this is a placeholder for actual validation logic)
            if (!validateCRCFlag(pdu[i].RX_UE_INFORMATION_TAG, pdu[i].RNTI, pdu[i].CRCFLAG)) {
                return 0;
            }
        }
    }

    return 1;
}

int main() {
    int batchSize = 100; // Adjust batch size as needed
    NFAPI_CRC_INDICATION_PDU_T* pduArray = createCRCIndicationPDU(batchSize);
    validatePDU(pduArray, batchSize);

    // Free memory
    free(ueInfo);
    free(pduArray);

    return 0;
}
