    if (max_size <= 0 || num_allocations <= 0)
        return NULL;

    // Calculate total memory required
    size_t total_memory = sizeof(RX_UE_INFO*) * max_size;

    RX_UE_INFO** array = (RX_UE_INFO**)malloc(total_memory);
    if (!array) {
        fprintf(stderr, "Error allocating memory.\n");
        return NULL;
    }

    // Initialize each structure
    for (int i = 0; i < max_size; ++i) {
        array[i] = (RX_UE_INFO*)malloc(sizeof(RX_UE_INFO));
        if (!array[i]) {
            fprintf(stderr, "Error allocating memory.\n");
            return NULL;
        }

        // Initialize fields
        array[i]->rx_ue_info_tag = malloc(1024); // assuming max 1024 bytes for tag
        if (!array[i]->rx_ue_info_tag) {
            fprintf(stderr, "Error allocating memory.\n");
            free(array[i]);
            return NULL;
        }

        array[i]->value = 0; // initialize value to 0 by default
        array[i]->attribute = 0.0f; // initialize attribute to 0.0 by default

        if (i >= num_allocations) {
            free(array[i]->rx_ue_info_tag);
            free(array[i]);
        }
    }

    return array;
}

void deallocate_RX_UE_INFOS(RX_UE_INFO** array, int max_size) {
    for (int i = 0; i < max_size; ++i) {
        if (array && i < max_size) {
            if (array[i]->rx_ue_info_tag)
                free(array[i]->rx_ue_info_tag);
            free(array[i]);
        }
