#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define TX_PACKET_INFO_T structure
typedef struct {
    uint32_t id;
    MAC_ADDRESS macAddress;
    uint32_t packetSize;
    uint64_t transmissionTimestamp;
    TRANSMISSION_STATUS status;
} TX_PACKET_INFO_T;

// Define a node in the linked list
typedef struct Node {
    TX_PACKET_INFO_T* packetInfo;
    struct Node* next;
} Node;

// Define the dynamic linked list
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new packet info to the list
void addPacketInfo(TX_PACKET_INFO_T* packetInfo) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->packetInfo = packetInfo;
    newNode->next = head;
    pthread_mutex_lock(&lock);
    head = newNode;
    pthread_mutex_unlock(&lock);
}

// Function to remove a packet info from the list
void removePacketInfo(uint32_t id) {
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL && current->packetInfo->id != id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return;

    pthread_mutex_lock(&lock);
    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&lock);
}

// Function to update packet info
void updatePacketInfo(uint32_t id, TRANSMISSION_STATUS status) {
    Node* current = head;
    while (current != NULL && current->packetInfo->id != id) {
        current = current->next;
    }
    if (current == NULL) return;

    pthread_mutex_lock(&lock);
    current->packetInfo->status = status;
    pthread_mutex_unlock(&lock);
}

// Function to get packet info
TX_PACKET_INFO_T* getPacketInfo(uint32_t id) {
    Node* current = head;
    while (current != NULL && current->packetInfo->id != id) {
        current = current->next;
    }
    if (current == NULL) return NULL;

    pthread_mutex_lock(&lock);
    TX_PACKET_INFO_T* packetInfo = current->packetInfo;
    pthread_mutex_unlock(&lock);
    return packetInfo;
}

// Function to log statistical information
void logStatistics() {
