        free(*records);
    }
}

void printLongestString(char** strings, int size) {
    char* longest = NULL;
    int maxLength = 0;

    for (int i = 0; i < size; i++) {
        if (strlen((*strings)[i]) > maxLength) {
            maxLength = strlen((*strings)[i]);
            longest = (*strings)[i];
        }
    }

    printf("Longest string: %s\n", longest);
}

record** processTasks(int* numRecords, int*** offsets, int*** keys, char*** strings) {
    record** records;
    int* offsetVals;
    int* keysVal;
    char** strArr;

    *numRecords = 0;
    *offsets = NULL;
    *keys = NULL;
    *strings = NULL;

    while (1) {
        printf("Enter the number of tasks: ");
        scanf("%d", numRecords);

        records = (record**) malloc(*numRecords * sizeof(record*));
        offsetVals = (int*) malloc(*numRecords * sizeof(int));
        keysVal = (int*) malloc(*numRecords * sizeof(int));

        for (int i = 0; i < *numRecords; i++) {
            printf("Enter record %d offset value: ", i + 1);
            scanf("%ld", &offsetVals[i]);
            printf("Enter record %d key value: ", i + 1);
            scanf("%d", &keysVal[i]);

            char* str = (char*) malloc(100 * sizeof(char));
            printf("Enter string for record %d: ", i + 1);
            fgets(str, 100, stdin);

            records[i] = createRecord(keysVal[i], str);
        }

        int maxStrLen = 0;
        for (int i = 0; i < *numRecords; i++) {
            if (strlen(records[i]->str) > maxStrLen) {
                maxStrLen = strlen(records[i]->str);
            }
        }

        strArr = (char**) malloc((*numRecords) * sizeof(char*));
        for (int i = 0; i < *numRecords; i++) {
            strArr[i] = records[i]->str;
        }

        printf("Enter termination character: ");
        char c;
        scanf(" %c", &c);
        if (c == '\n') break;

        int size = 0;
        while (1) {
            printf("Enter string (%c to terminate): ", c);
            fgets(strArr[size], 100, stdin);
            if (fgetc(stdin) == c) break;
            size++;
        }

        *offsets = offsetVals;
        *keys = keysVal;
        *strings = strArr;

        freeRecords(&records, *numRecords);
    }

    return *offsets, *keys, *strings;
}
