#include <memory>
#include <queue>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

struct PacketProcessingTask {
    std::string sourceIP;
    std::string destinationIP;
    int protocolType;
    int payloadLength;
};

class PacketProcessor {
public:
    void start();
    void stop();

private:
    class TaskQueue {
    public:
        using task_ptr = std::unique_ptr<PacketProcessingTask>;

        bool empty() const;
        void enqueue(task_ptr task);
        task_ptr dequeue();

    private:
        std::queue<task_ptr> tasks;
        mutable std::mutex mutex;
        std::condition_variable condition;
    };

    class PriorityQueue {
    public:
        using priority = int;

        bool empty() const;
        void enqueue(priority priority, PacketProcessingTask& task);
        PacketProcessingTask dequeue();

    private:
        std::priority_queue<PacketProcessingTask, std::vector<PacketProcessingTask>, std::greater<PacketProcessingTask>> queue;
    };

    TaskQueue taskQueue;
    PriorityQueue priorityQueue;
    bool running = true;

    void processTasks();
};

void PacketProcessor::start() {
    std::thread thread([this]() {
        while (running) {
            processTasks();
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }).detach();
}

void PacketProcessor::stop() {
    running = false;
}

bool PacketProcessor::TaskQueue::empty() const {
    std::unique_lock<std::mutex> lock(mutex);
    return tasks.empty();
}

void PacketProcessor::TaskQueue::enqueue(std::unique_ptr<PacketProcessingTask> task) {
    std::unique_lock<std::mutex> lock(mutex);
    tasks.push(std::move(task));
    condition.notify_one();
}

PacketProcessingTask& PacketProcessor::TaskQueue::dequeue() {
    std::unique_lock<std::mutex> lock(mutex);
    while (tasks.empty()) {
        condition.wait(lock);
    }
    auto task = std::move(tasks.front());
    tasks.pop();
    return *task;
}

bool PacketProcessor::PriorityQueue::empty() const {
    return queue.empty();
}

void PacketProcessor::PriorityQueue::enqueue(int priority, PacketProcessingTask& task) {
    task.priority = priority;
    queue.push(task);
}

PacketProcessingTask PacketProcessor::PriorityQueue::dequeue() {
    auto task = queue.top();
    queue.pop();
    return task;
}

void PacketProcessor::processTasks() {
    if (!taskQueue.empty()) {
        while (!taskQueue.empty()) {
            auto task = taskQueue.dequeue();
            // Process the packet
            std::cout << "Processing packet: " << task.sourceIP << " -> " << task.destinationIP << "\n";
        }
    }
}

int main() {
    PacketProcessor processor;
    processor.start();

    // Add tasks to the queue
    for (int i = 0; i < 10; i++) {
        PacketProcessingTask task;
        // Initialize task metadata
        processor.taskQueue.enqueue(std::make_unique<PacketProcessingTask>(task));
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));

    processor.stop();

    return 0;
}
