void* lte_phy_control_msg_init(int num_messages, int size_offsets_array, int range_offsets_values, int condition_offsets_selection) {
    // Initialize arrays
    int** offsets = (int**)malloc(size_offsets_array * sizeof(int*));
    for (int i = 0; i < size_offsets_array; i++) {
        offsets[i] = (int*)malloc(sizeof(int));
        *(offsets[i]) = rand() % range_offsets_values;
    }

    // Initialize record array
    lte_phy_message** records = (lte_phy_message**)malloc(num_messages * sizeof(lte_phy_message*));
    for (int i = 0; i < num_messages; i++) {
        records[i] = (lte_phy_message*)malloc(sizeof(lte_phy_message));
        records[i]->phich_config = rand() % range_offsets_values;
        records[i]->ue_id = i;
        // Dynamically allocate buffer for DL_MCH_DATA_TAG
        records[i]->dl_mch_data_tag = malloc(100);  // assume fixed size of 100 bytes
    }

    // Initialize offsetIndex array
    int** offsetIndex = (int**)malloc(size_offsets_array * sizeof(int*));
    for (int i = 0; i < size_offsets_array; i++) {
        offsetIndex[i] = (int*)malloc(sizeof(int));
        *(offsetIndex[i]) = i;
    }

    return records;
}

void lte_phy_control_msg_free(void* records) {
    // Free memory allocated for records
    if (records != NULL) {
        lte_phy_message** record_array = (lte_phy_message**)records;
        for (int i = 0; i < strlen(record_array); i++) {
            free(record_array[i]->dl_mch_data_tag);
            free(record_array[i]);
        }
        free(record_array);

        // Free memory allocated for offsets and offsetIndex
        int** offsets = ((lte_phy_message**)records)[0]->offsets;
        for (int i = 0; i < strlen(offsets); i++) {
            free(offsets[i]);
        }
        free(offsets);
    }
