#define MEMORY_POOL_SIZE 1000
#define MAX_NAME_LENGTH 50
#define SUFFIX_LENGTH 10

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    double salary;
} Employee;

int employee_count = 0;
Employee* memory_pool[MEMORY_POOL_SIZE];
FILE* log_file = NULL;

void init_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        memory_pool[i] = (Employee*)malloc(sizeof(Employee));
        if (!memory_pool[i]) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
    }
}

void free_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        free(memory_pool[i]);
    }
}

Employee* add_employee(const char* name, int age) {
    Employee* new_employee;
    int found_duplicate = 0;

    if (employee_count >= MEMORY_POOL_SIZE) {
        printf("Memory pool is full! Cannot allocate more employees.\n");
        return NULL; // or handle this better in a real-world scenario
    }

    for (int i = 0; i < employee_count; i++) {
        if (strcmp(memory_pool[i]->name, name) == 0) {
            found_duplicate = 1;
            break;
        }
    }

    if (!found_duplicate) {
        new_employee = memory_pool[employee_count++];
        strcpy(new_employee->name, name);
        new_employee->age = age;
        return new_employee;
    } else {
        char suffix[SUFFIX_LENGTH];
        sprintf(suffix, "_%d", employee_count); // or use a more robust random generator
        strcat(strcat(strcpy(new_employee->name, name), "_"), suffix);

        printf("Duplicate name detected! Using '%s' instead.\n", new_employee->name);
        log_file = fopen("log.txt", "a");
        fprintf(log_file, "Failed to add employee with duplicate name: %s\n", name);
        fclose(log_file);
        return NULL;
    }
}

void update_salary(Employee* employee, double salary) {
    if (!employee) {
        printf("Invalid employee reference!\n");
        return; // or handle this better in a real-world scenario
    }

    employee->salary = salary;
}

void prune_inactive_employees() {
    for (int i = 0; i < employee_count; i++) {
        if (memory_pool[i]->age > 65) { // adjust the age threshold as needed
            memory_pool[i] = NULL;
            employee_count--;
        }
    }
}

void print_employee_list() {
    for (int i = 0; i < employee_count; i++) {
        printf("Name: %s, Age: %d, Salary: %.2f\n", memory_pool[i]->name, memory_pool[i]->age, memory_pool[i]->salary);
    }
}
