typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* xmlToStructs(const char *filename, int *numStructs) {
    xmlDocPtr doc = NULL;
    xmlNodePtr root = NULL;
    xmlAttrPtr attr = NULL;
    NFAPI_CRC_INDICATION_PDU_T* structs = NULL;
    int i = 0;

    // Load XML file
    doc = xmlReadFile(filename, NULL, XML_PARSE_NOERROR);

    if (doc == NULL) {
        return NULL;
    }

    root = xmlDocGetRootElement(doc);
    attr = xmlNewProp(root, "numStructs", "");
    if (attr != NULL) {
        *numStructs = atoi((const char*)xmlNodeGetContent(attr));
        xmlFreeAttr(attr);
    } else {
        *numStructs = 0;
    }

    structs = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*numStructs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (i = 0; i < *numStructs; i++) {
        xmlNodePtr node = root->children;
        while (node != NULL) {
            if (xmlStrEqual(node->name, "RX_UE_INFORMATION_TAG")) {
                structs[i].RX_UE_INFORMATION_TAG = atoi((const char*)xmlNodeGetContent(node));
            } else if (xmlStrEqual(node->name, "RNTI")) {
                structs[i].RNTI = atoi((const char*)xmlNodeGetContent(node));
            } else if (xmlStrEqual(node->name, "CRCFLAG")) {
                structs[i].CRCFLAG = rand() % 1000;
            }
            node = node->next;
        }
    }

