#define MAX_MESSAGES 10000
#define BUFFER_SIZE 1024

typedef struct {
    int phich_configuration;
    uint32_t ue_id;
    char *buffer;
} LTE_PHY_Control_Message;

LTE_PHY_Control_Message *messages[MAX_MESSAGES];
int message_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* allocate_buffer(int size) {
    void *buf = malloc(size);
    if (buf == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return buf;
}

int free_message(LTE_PHY_Control_Message *message) {
    if (message->buffer != NULL) {
        free(message->buffer);
        message->buffer = NULL;
    }
    return 0;
}

void add_message(int phich_config, uint32_t ue_id, char *data) {
    LTE_PHY_Control_Message *new_message = messages[message_count];
    new_message->phich_configuration = phich_config;
    new_message->ue_id = ue_id;
    new_message->buffer = allocate_buffer(BUFFER_SIZE);
    if (memcpy(new_message->buffer, data, BUFFER_SIZE) == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    message_count++;
}

void remove_message(int index) {
    if (index >= 0 && index < message_count) {
        free_message(messages[index]);
        messages[index] = NULL;
        message_count--;
    }
}

int modify_message(int index, int phich_config, uint32_t ue_id, char *data) {
    if (index >= 0 && index < message_count) {
        LTE_PHY_Control_Message *message = messages[index];
        free_message(message);
        add_message(phich_config, ue_id, data);
        return 0;
    }
    return -1;
}

void print_memory_usage() {
    int total_memory = 0;
    for (int i = 0; i < message_count; i++) {
        LTE_PHY_Control_Message *message = messages[i];
        if (message->buffer != NULL) {
            total_memory += sizeof(message->buffer);
        }
    }
    printf("Peak memory consumption: %d\n", total_memory);
}

void* print_messages(void* arg) {
    for (int i = 0; i < message_count; i++) {
        LTE_PHY_Control_Message *message = messages[i];
        if (message != NULL && message->buffer != NULL) {
            printf("PHICH Configuration: %d\nUE ID: %u\nBuffer: %s\n", 
                   message->phich_configuration, message->ue_id, message->buffer);
        }
    }
}

int main() {
    // Initialize the messages array
    for (int i = 0; i < MAX_MESSAGES; i++) {
        messages[i] = NULL;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, print_messages, NULL);

    add_message(1, 2, "Hello");
    add_message(3, 4, "World");

    remove_message(0);

    modify_message(1, 5, 6, "New message");

    print_memory_usage();

    pthread_join(thread, NULL);

    return 0;
}

