import time
from collections import defaultdict

class SessionTracker:
    def __init__(self):
        self.sessions = {}
        self.session_limits = 10000
        self.max_session_age = 5 * 60  # 5 minutes in seconds

    def process_user_activity_stream(self, event_bus):
        while True:
            try:
                event = event_bus.pop()
                if not event:
                    time.sleep(0.1)
                    continue

                session_id, timestamp, activity_type = event
                now = int(time.time())

                if (now - timestamp) > self.max_session_age:
                    # Session timed out, remove it from the tracker
                    del self.sessions[session_id]
                elif len(self.sessions) >= self.session_limits:
                    # Prioritize recent sessions and discard older ones
                    recent_sessions = {k: v for k, v in self.sessions.items() if now - v['last_activity'] < 60}
                    self.sessions = recent_sessions

                if session_id not in self.sessions:
                    self.sessions[session_id] = {'page_views': 0, 'clicks': 0, 'dwell_time': 0, 'last_activity': timestamp}

                if activity_type == 'navigation':
                    self.sessions[session_id]['page_views'] += 1
                elif activity_type == 'click':
                    self.sessions[session_id]['clicks'] += 1
                else:
                    self.sessions[session_id]['dwell_time'] = max(self.sessions[session_id]['dwell_time'], timestamp - self.sessions[session_id]['last_activity'])

                if (self.sessions[session_id]['page_views'] > 10 and self.sessions[session_id]['clicks'] > 5):
                    # Unusual pattern detected, report it
                    print(f"Unusual user activity detected: {session_id}")

            except Exception as e:
                print(f"Error processing event: {e}")
