    free(ptr);
}

int init_data_structures(int offset_count, int key_count, int data_count, float** data_values) {
    srand(time(NULL)); // Seed random number generator for optimal performance

    long* offsets = (long*)allocate_memory(offset_count * sizeof(long));
    int* keys = (int*)allocate_memory(key_count * sizeof(int));
    Data* data = (Data*)allocate_memory(data_count * sizeof(Data));

    // Initialize offset array with random values
    for (int i = 0; i < offset_count; i++) {
        offsets[i] = rand() % 100;
    }

    // Initialize key array with random values
    for (int i = 0; i < key_count; i++) {
        keys[i] = rand() % 100;
    }

    // Initialize data structures with random float values within a specified range
    for (int i = 0; i < data_count; i++) {
        data[i].value = (float)(rand() % 100) / 100.0f;
    }

    *data_values = data;

    return 1;
}

void free_data_structures(Data* data, long* offsets, int* keys) {
    deallocate_memory(data, sizeof(Data) * sizeof(*data));
    deallocate_memory(offsets, sizeof(long) * offset_count);
    deallocate_memory(keys, sizeof(int) * key_count);
}
