                free(array); // attempt failed, clean up memory
                return NULL;
            }
        }

        int is_valid = validate_array(array, N);

        if (!is_valid) {
            free(array);
            return NULL; // array not valid
        }

        break;

    } while (tries++ < 3 && !array); // retry up to 3 times

