#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[1];
} NFAPI_CRC_INDICATION_PDU_T;

void process_and_evaluate_packets(int N, int* p_input_count) {
    // Define the maximum input count
    const int MAX_INPUT_COUNT = 1000;

    // Check for invalid input counts
    if (*p_input_count < 0 || *p_input_count > MAX_INPUT_COUNT) {
        fprintf(stderr, "Invalid input count. Terminating.\n");
        return;
    }

    // Allocate memory for the packet list
    NFAPI_CRC_INDICATION_PDU_T* packets = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!packets) {
        fprintf(stderr, "Memory allocation failed. Terminating.\n");
        return;
    }

    // Initialize the packet list
    for (int i = 0; i < N; i++) {
        packets[i].RX_UE_INFORMATION_TAG = i;
        packets[i].RNTI = i;
        packets[i].CRC_INDICATION_REL8_TAG[0] = rand() & 1;
    }

    // Read integers from standard input until the count reaches 0
    int input_count = *p_input_count;
    int max_integer = find_largest_integer(&input_count);

    // Sort the packet list by RNTI in ascending order, and then by CRCFLAG in descending order
    qsort(packets, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_packets);

    // Calculate and print the average CRCFLAG value across all packets
    float avg_crcflag = 0;
    for (int i = 0; i < N; i++) {
        avg_crcflag += packets[i].CRC_INDICATION_REL8_TAG[0];
    }
    printf("Average CRCFLAG: %f\n", avg_crcflag / N);

    // Free the packet list
    free(packets);
}

int compare_packets(const void* a, const void* b) {
    const NFAPI_CRC_INDICATION_PDU_T* pa = (const NFAPI_CRC_INDICATION_PDU_T*)a;
    const NFAPI_CRC_INDICATION_PDU_T* pb = (const NFAPI_CRC_INDICATION_PDU_T*)b;

    if (pa->RNTI < pb->RNTI) {
        return -1;
    } else if (pa->RNTI > pb->RNTI) {
        return 1;
    } else {
        if (pa->CRC_INDICATION_REL8_TAG[0] < pb->CRC_INDICATION_REL8_TAG[0]) {
            return -1;
        } else {
            return 1;
        }
    }
}

int find_largest_integer(int* p_input_count) {
    int max_integer = 0;

    // Read integers from standard input until the count reaches 0
    while (*p_input_count > 0) {
        int integer;
        if (fscanf(stdin, "%d", &integer) != 1) {
            fprintf(stderr, "Error reading from standard input. Terminating.\n");
            return -1;
        }
        max_integer = fmax(max_integer, integer);
        (*p_input_count)--;
    }

    return max_integer;
}
