#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char source_ip[16];
    char dest_ip[16];
    int event_count;
    struct {
        time_t timestamp;
        int type;
    } events[];
} Transaction;

Transaction* allocateAndPopulateNetworkTransactions(int num_transactions, int max_event_count) {
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    if (!transactions) return NULL;  // Error: unable to allocate memory

    for (int i = 0; i < num_transactions; i++) {
        transactions[i].id = i;
        transactions[i].timestamp = time(NULL);  // Current timestamp
        sprintf(transactions[i].source_ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        sprintf(transactions[i].dest_ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);

        transactions[i].event_count = (rand() % max_event_count) + 1;
        transactions[i].events = (struct {
            time_t timestamp;
            int type;
        } *)malloc(transactions[i].event_count * sizeof(struct {
            time_t timestamp;
            int type;
        }));

        for (int j = 0; j < transactions[i].event_count; j++) {
            transactions[i].events[j].timestamp = time(NULL);
            transactions[i].events[j].type = rand() % 2;  // Random event type
        }
    }

    // Calculate and store checksum
    unsigned int checksum = 0;
    for (int i = 0; i < num_transactions; i++) {
        checksum += transactions[i].id;
        checksum += transactions[i].timestamp;
        for (int j = 0; j < transactions[i].event_count; j++) {
            checksum += transactions[i].events[j].timestamp;
            checksum += transactions[i].events[j].type;
        }
    }

    return transactions;
}

