    unsigned int ue_id;
    char* dl_mch_data_tag;
} lte_phy_layer_control_message;

int last_used_index = -1;
lte_phy_layer_control_message** phy_messages;

void init_phy_messages(int initial_capacity) {
    phy_messages = (lte_phy_layer_control_message**)malloc(initial_capacity * sizeof(lte_phy_layer_control_message*));
}

void add_phy_message(int phich_configuration, unsigned int ue_id, char* dl_mch_data_tag) {
    if (last_used_index >= (int)(sizeof(phy_messages) / sizeof(phy_messages[0])))
        return; // no more memory available

    phy_messages[last_used_index + 1] = malloc(sizeof(lte_phy_layer_control_message));
    phy_messages[last_used_index + 1]->phich_configuration = phich_configuration;
    phy_messages[last_used_index + 1]->ue_id = ue_id;
    phy_messages[last_used_index + 1]->dl_mch_data_tag = dl_mch_data_tag;

    last_used_index++;
}

void remove_phy_message(int index) {
    if (index < 0 || index > last_used_index)
        return; // invalid index

    free(phy_messages[index]);
    for (int i = index; i < last_used_index; i++)
        phy_messages[i] = phy_messages[i + 1];
    last_used_index--;
}

void print_phy_messages() {
    for (int i = 0; i <= last_used_index; i++) {
        printf("PHICH Configuration: %d, UE ID: %u, DL MCH Data Tag: %s\n", 
               phy_messages[i]->phich_configuration, phy_messages[i]->ue_id, phy_messages[i]->dl_mch_data_tag);
    }
}

int main() {
    init_phy_messages(5);

    add_phy_message(1, 12345, "TAG1");
    add_phy_message(2, 67890, "TAG2");
    add_phy_message(3, 11111, "TAG3");

    print_phy_messages();

    remove_phy_message(1);

    print_phy_messages();

    return 0;
}
