#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int num, float probability, int *num_created, int *errors, pthread_mutex_t *log_lock) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    uint8_t rx_tag_value = 0x01; // default RX_UE_INFORMATION_TAG value
    int i;

    pthread_mutex_lock(log_lock);
    *num_created = 0;
    *errors = 0;
    pthread_mutex_unlock(log_lock);

    for (i = 0; i < num; i++) {
        current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current) {
            pthread_mutex_lock(log_lock);
            *errors++;
            pthread_mutex_unlock(log_lock);
            continue;
        }

        current->RX_UE_INFORMATION_TAG = rx_tag_value;
        current->RNTI = i;
        current->CRC_INDICATION_REL8_TAG = 0x02; // default CRC_INDICATION_REL8_TAG value
        current->CRCFLAG = (rand() / (float)RAND_MAX > probability);
        pthread_mutex_lock(log_lock);
        (*num_created)++;
        pthread_mutex_unlock(log_lock);

        if (!pdu_list) {
            pdu_list = current;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = pdu_list;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = current;
        }
    }

    return pdu_list;
}
