    // Initialize event log array
    NetworkEventLogEntry* event_log = (NetworkEventLogEntry*)calloc(num_entries, sizeof(NetworkEventLogEntry));

    // Initialize compression algorithm
    z_stream stream;
    deflateInit2(&stream, Z_DEFAULT_COMPRESSION, 31, 8, 0, Z_DEFAULT_MEM);

    // Iterate over events and compress timestamps
    for (int i = 0; i < num_entries; i++) {
        event_log[i].timestamp = time(NULL);
        event_log[i].event_id = i;
        event_log[i].cell_ids = NULL;

        // Compress timestamp using deflate algorithm
        unsigned char compressed[1024];
        int compressed_len = compress(compressed, 1024, &stream, (const Bytef*)&event_log[i].timestamp, sizeof(time_t));
        stream.total_in += sizeof(time_t);
        stream.next_out = compressed;
        stream.avail_out = compressed_len;

        // Decompress timestamp
        unsigned char decompressed[1024];
        int decompressed_len = uncompress(decompressed, 1024, compressed, compressed_len);
        event_log[i].timestamp = *(time_t*)decompressed;

        // Log events to file
        fprintf(*log_file, "Timestamp: %ld, Event ID: %d\n", event_log[i].timestamp, event_log[i].event_id);

        // Add metadata to log file
        fprintf(*log_file, "Total entries: %d\n", num_entries);
        fprintf(*log_file, "Average event duration: %f seconds\n", (double)sizeof(time_t));
