function updateClinicStatus($clinicId, $newStatus) {
    // Initialize transaction variables
    $originalStatus = null;
    $originalIp = null;

    // Start transaction
    $dbTransaction = db_transaction_start();

    try {
        // Fetch original status and IP address for auditing purposes
        $query = "SELECT status, ip FROM clinics WHERE id = ?";
        $stmt = db_prepare($query, [$clinicId]);
        $result = db_execute($stmt);
        list($originalStatus, $originalIp) = $result->fetch();

        // Update clinic status, last modified IP address, and last modified date
        $query = "UPDATE clinics SET status = ?, ip = inet_aton(?), updated_at = NOW() WHERE id = ?";
        $stmt = db_prepare($query, [$newStatus, $_SERVER['REMOTE_ADDR'], $clinicId]);
        $result = db_execute($stmt);

        // Fetch current user information from external API (introduces latency and failure modes)
        $currentUserInfo = api_fetch_user_info();

        // Log changes for auditing purposes
        $logQuery = "INSERT INTO clinic_logs (clinic_id, original_status, original_ip, new_status, updated_at) VALUES (?, ?, ?, ?, NOW())";
        $logStmt = db_prepare($logQuery, [$clinicId, $originalStatus, $originalIp, $newStatus]);
        db_execute($logStmt);

        // Commit transaction
        db_transaction_commit($dbTransaction);
    } catch (Exception $e) {
        // Rollback transaction on failure and return error message
