#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define HASH_TABLE_SIZE 1000007

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* list;
} HashTable;

HashTable hash_table;

void* process_packet(void* packet) {
    // Parse incoming packets and populate the list
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)packet;
    pthread_mutex_lock(&hash_table.lock);
    int index = hash(pdu->RNTI, HASH_TABLE_SIZE);
    if (hash_table.list[index].RX_UE_INFORMATION_TAG != 0) {
        // Log invalid operation and error
        log_error("Duplicate RNTI found");
        pthread_mutex_unlock(&hash_table.lock);
        return NULL;
    }
    hash_table.list[index] = *pdu;
    hash_table.size++;
    if (hash_table.size > MAX_SIZE) {
        // Handle overflow
        log_error("List size exceeded maximum limit");
        pthread_mutex_unlock(&hash_table.lock);
        return NULL;
    }
    pthread_mutex_unlock(&hash_table.lock);
    return NULL;
}

int main() {
    // Initialize the hash table
    hash_table.size = 0;
    hash_table.list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(HASH_TABLE_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&hash_table.lock, NULL);

    // Start processing packets in parallel
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, process_packet, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

// Hash function for RNTI values
unsigned int hash(uint32_t RNTI, unsigned int size) {
    return (RNTI % size);
}
