    }

    int n, temp;
    printf("Enter the sequence of integers: ");
    scanf("%d", &n);

    int *arr = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // filter out duplicates
    int j = 0;
    for (int i = 0; i < n; i++) {
        if (!binary_search(arr, j, arr[i])) {
            arr[++j] = arr[i];
        }
    }

    n = j;

    // calculate median
    int *median_arr = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 0; i < n; i++) {
        median_arr[i] = arr[i];
    }

    qsort(median_arr, n, sizeof(int), compare);

    if (n % 2 == 0)
        printf("Median: %d\n", (median_arr[n / 2 - 1] + median_arr[n / 2]) / 2);
    else
        printf("Median: %d\n", median_arr[n / 2]);

    // find the largest integer in the filtered array
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("Largest integer: %d\n", max);

    free(ue_info_list);
    free(arr);
    free(median_arr);
}

int binary_search(int *arr, int n, int target) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == target)
            return 1;
    }
    return 0;
}

int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
