typedef struct {
    float value;
    char name[NAME_LENGTH];
} Record;

Record* initRecords(int numRecords) {
    int i, j;
    float values[RECORDS_MAX];
    char names[RECORDS_MAX][NAME_LENGTH];
    Record* records = (Record*)malloc(numRecords * sizeof(Record));

    // initialize record values
    for (i = 0; i < numRecords; i++) {
        if (i == 0 || i == numRecords - 1) {
            // set initial and final values differently
            values[i] = (float)i;
        } else {
            values[i] = (float)(i % 10000); // non-consecutive within records
        }
    }

    // initialize record names
    for (i = 0; i < numRecords; i++) {
        sprintf(names[i], "Record_%d", i);
    }

    // set record values and names
    for (i = 0; i < numRecords; i++) {
        records[i].value = values[i];
        strcpy(records[i].name, names[i]);
    }

    return records;
}

void* readNames(void* ptr) {
    int i;
    char** names = (char**)ptr;

    for (i = 0; i < RECORDS_MAX; i++) {
        printf("Enter name %d: ", i);
        fgets(names[i], NAME_LENGTH, stdin);
        names[i][strlen(names[i]) - 1] = '\0'; // remove newline
    }

    return NULL;
}

void findLongestName(Record* records, char** names) {
    int maxLen = 0, i;
    for (i = 0; i < RECORDS_MAX; i++) {
        if (strlen(names[i]) > maxLen)
            maxLen = strlen(names[i]);
    }
    printf("Longest name: %s (%d characters)\n", names[maxLen], maxLen);
}

int main() {
    int numRecords;
    char** names;

    // read number of records
    printf("Enter number of records: ");
    scanf("%d", &numRecords);

    Record* records = initRecords(numRecords);

    // read names from standard input
    pthread_t thread;
    pthread_create(&thread, NULL, readNames, (void*)&names);
    pthread_join(thread, NULL);

    findLongestName(records, names);

    return 0;
}

