        record->key = rand() % 100;
        record->value = (double)rand() / RAND_MAX;
        record->offset = malloc(sizeof(long));
        if (!record->offset) {
            for (int j = 0; j < i; j++) free(&pdu->data_records[j].offset);
            free(pdu->data_records);
            free(pdu);
            return NULL;
        }
        *record->offset = rand();
