#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* dynamic_array[MAX_ELEMENTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int global_error_flag = 0;

void validate_uniqueness(int rnti, NFAPI_CRC_INDICATION_PDU_T** array) {
    int i;
    for (i = 0; i < *array->size; i++) {
        if (((*array)[i]->RNTI == rnti)) {
            printf("Error: RNTI already exists in the array.\n");
            global_error_flag = 1;
            return;
        }
    }
}

int add_element(int rnti, int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        printf("Error: Memory allocation failed.\n");
        global_error_flag = 1;
        return -1;
    }
    new_element->RX_UE_INFORMATION_TAG = rand();
    new_element->RNTI = rnti;
    new_element->CRC_INDICATION_REL8_TAG = rand();
    new_element->CRCFLAG = crcflag;

    pthread_mutex_lock(&mutex);
    int i;
    for (i = 0; i < MAX_ELEMENTS; i++) {
        if (!dynamic_array[i]) {
            dynamic_array[i] = new_element;
            break;
        }
    }

    if (i == MAX_ELEMENTS) {
        printf("Error: Array is full.\n");
        global_error_flag = 1;
    } else {
        int j;
        for (j = i; j > 0; j--) {
            dynamic_array[j] = dynamic_array[j - 1];
        }
        dynamic_array[0] = new_element;
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int get_size() {
    int size = 0;
    pthread_mutex_lock(&mutex);
    int i;
    for (i = 0; i < MAX_ELEMENTS; i++) {
        if (dynamic_array[i]) {
            size++;
        }
    }
    pthread_mutex_unlock(&mutex);
    return size;
}

int main() {
    // Initialize the dynamic array
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        dynamic_array[i] = NULL;
    }

    int rnti1, rnti2;

    while (!global_error_flag) {
        printf("Enter RNTI: ");
        scanf("%d", &rnti1);
        add_element(rnti1, rand());

        if (get_size() > MAX_ELEMENTS / 2) {
            printf("Array is half full. Limit reached.\n");
            break;
        }
    }

    // Print the array
    int i;
    for (i = 0; i < get_size(); i++) {
        printf("RNTI: %d, CRCFLAG: %d\n", dynamic_array[i]->RNTI, dynamic_array[i]->CRCFLAG);
    }

    return 0;
}
