```javascript
function asyncReduce(arr, callback) {
  if (!arr.length) return callback(null, 0); // handle empty array

  let result = arr[0];
  (async () => {
    for (let i = 1; i < arr.length; i++) {
      try {
        result = await callback(result, arr[i]);
      } catch (error) {
        callback(error, null);
      }
    }
    return callback(null, result);
  })();
}
```
