    struct Offset* offsets = (struct Offset*)malloc(size * sizeof(struct Offset));
    for (int i = 0; i < size; i++) {
        offsets[i].value = 0;
    }

    struct Key* keys = (struct Key*)malloc(size * sizeof(struct Key));
    for (int i = 0; i < size; i++) {
        keys[i].key = i + 1;
