    if (bytesRead != *input_size || fseek(inputFile, 0, SEEK_END) > 0) {
        printf("Invalid or corrupted input file\n");
        fclose(inputFile);
        free(crcIndicationPDU);
        return;
    }

    fclose(inputFile);

    int maxInteger = find_max_integer(*input_size, inputSize);
    printf("Largest integer: %d\n", maxInteger);

    // Free resources
    free(crcIndicationPDU);
}

int find_max_integer(int size, int* array) {
    if (size == 0) {
        return -1;
    }

    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}
