    srand(time(NULL)); // seed the random number generator

    // initialize arrays
    long_offset_values = (int*)malloc(n * sizeof(int));
    if (!long_offset_values) {
        free(long_offset_values);
        return;
    }

    int_keys = (int*)malloc(n * sizeof(int));
    if (!int_keys) {
        free(long_offset_values);
        free(int_keys);
        return;
    }

    record_structures = (double**)malloc(n * sizeof(double*));
    if (!record_structures) {
        free(long_offset_values);
        free(int_keys);
        for (size_t i = 0; i < n; ++i) {
            if (record_structures[i]) {
                free(record_structures[i]);
            }
        }
        free(record_structures);
        return;
    }

    // create linked list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < n; ++i) {
