        if (!head) {
            head = new_pdu;
        } else {
            while (current->next) {
                current = current->next;
            }
            current->next = new_pdu;
        }

        // allocate memory for arrays
        long_offset_values[i] = i * 10;
        int_keys[i] = i + 1;

        record_structures[i] = (double*)malloc(size * sizeof(double));
        if (!record_structures[i]) {
            free(long_offset_values);
            free(int_keys);
            for (size_t j = 0; j < i; ++j) {
                if (record_structures[j]) {
                    free(record_structures[j]);
                }
            }
            for (size_t j = 0; j < n; ++j) {
                if (record_structures[j]) {
