    long timestamp;
    int status_flag;
} Packet;

typedef struct Node {
    Packet packet;
    struct Node* next;
} Node;

void init_packet(Packet* p, const char* pdu, long ts, int sf) {
    strcpy(p->mac_pdu, pdu);
    p->timestamp = ts;
    p->status_flag = sf;
}

int validate_pdu(const Packet* p) {
    // Implement checksum validation mechanism
    // For demonstration purposes, assume a simple length check
    return strlen(p->mac_pdu) == 16 ? 0 : -1; // Returns -1 if PDU is invalid
}

void add_packet(Node** head, Packet* p) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }

    init_packet(&new_node->packet, p->mac_pdu, p->timestamp, p->status_flag);

    // Validate packet MAC_PDU
    int error = validate_pdu(&p->packet);
    if (error) {
        free(new_node);
        printf("Invalid PDU: %s\n", p->mac_pdu);
        return;
    }

    Node* current = *head;
    if (current != NULL) {
        // Check for duplicate MAC_PDUs
        while (current->next != NULL && strcmp(p->packet.mac_pdu, current->next->packet.mac_pdu) != 0) {
            current = current->next;
        }

        if (strcmp(p->packet.mac_pdu, current->packet.mac_pdu) == 0) {
            printf("Duplicate PDU: %s\n", p->mac_pdu);
            free(new_node);
            return;
        }
    }

    new_node->next = *head;
    *head = new_node;
}

void print_packets(Node* head) {
