#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

// Define a structure to represent a packet
typedef struct Packet {
    uint8_t* mac_pdu;
    int timestamp;
    int status_flag;
} Packet;

// Define a structure to represent a node in the doubly linked list
typedef struct Node {
    Packet* packet;
    struct Node* prev;
    struct Node* next;
} Node;

// Custom memory pool allocator for Packet structures
void* my_malloc(size_t size) {
    // Initialize the memory pool with 1000 blocks of 128 bytes each
    static void* memory_pool[1000] = {0};
    static int num_blocks = 0;

    if (num_blocks * 128 >= size) {
        return memory_pool[size % 128];
    } else {
        // Allocate a new block from the system heap if necessary
        if (num_blocks < 1000) {
            void* block = malloc(128);
            memcpy(memory_pool + num_blocks, block, 128);
            free(block);
            num_blocks++;
            return memory_pool[size % 128];
        } else {
            // Handle the case where we're out of blocks
            printf("Out of memory!\n");
            exit(-1);
        }
    }
}

// Function to initialize and manage a dynamic, doubly linked list of Packet structures
void init_packet_list(Node** head_ref) {
    *head_ref = NULL;

    pthread_mutex_init(&lock, NULL);

    // Periodic garbage collection function
    void* periodic_gc(void*) {
        while (1) {
            sleep(10); // Wait for 10 seconds

            pthread_mutex_lock(&lock);
            Node* current = *head_ref;
            Node* prev = NULL;

            while (current != NULL) {
                if (current->packet == NULL || current->timestamp + 1000 < time(NULL)) {
                    // Packet is stale, remove it
                    if (prev != NULL) {
                        prev->next = current->next;
                    } else {
                        *head_ref = current->next;
                    }
                    free(current);
                } else {
                    prev = current;
                    current = current->next;
                }
            }
            pthread_mutex_unlock(&lock);

            sleep(10); // Wait for 10 seconds before the next garbage collection cycle
        }

        return NULL;
    }
}

void add_packet(Node** head_ref, Packet* packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->packet = packet;

    pthread_mutex_lock(&lock);
    if (*head_ref == NULL || (*head_ref)->packet->timestamp < packet->timestamp) {
        // Add the packet to the front of the list
        new_node->next = *head_ref;
        new_node->prev = NULL;
        if (*head_ref != NULL) {
            (*head_ref)->prev = &new_node;
        }
        *head_ref = new_node;
    } else {
        Node* current = *head_ref;
        while (current->next != NULL && current->next->packet->timestamp >= packet->timestamp) {
            current = current->next;
        }

        // Add the packet to the middle of the list
        new_node->prev = current;
        new_node->next = current->next;
        if (current->next != NULL) {
            current->next->prev = &new_node;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

void remove_packet(Node** head_ref, Packet* packet) {
    Node* current = *head_ref;

    while (current != NULL && current->packet != packet) {
        current = current->next;
    }

    if (current == NULL || current->packet != packet) {
        printf("Packet not found!\n");
        return;
    }

    if (current->prev == NULL) {
        // Remove the packet from the front of the list
        *head_ref = current->next;
    } else if (current->next == NULL) {
        // Remove the packet from the end of the list
        current->prev->next = NULL;
    } else {
        // Remove the packet from the middle of the list
        current->prev->next = current->next;
        current->next->prev = current->prev;
    }

    free(current);
}

int main() {
    // Initialize the lock for synchronization
    pthread_mutex_t lock;

    Node* head_ref = NULL;

    // Create a new packet and add it to the list
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    packet->mac_pdu = (uint8_t*)my_malloc(128);
    packet->timestamp = time(NULL);
    packet->status_flag = 0;
    add_packet(&head_ref, packet);

    // Create another new packet and add it to the list
    packet = (Packet*)malloc(sizeof(Packet));
    packet->mac_pdu = (uint8_t*)my_malloc(128);
    packet->timestamp = time(NULL) + 1000;
    packet->status_flag = 1;
    add_packet(&head_ref, packet);

    // Remove a packet from the list
    remove_packet(&head_ref, packet);

    return 0;
}
