void* geospatialDataProcessor(int numPolygons, int seed) {
    // Initialize arrays
    polygon** polygons = (polygon**)malloc(numPolygons * sizeof(polygon));
    point*** points = (point***)malloc(numPolygons * sizeof(point*));
    double* areas = (double*)malloc(numPolygons * sizeof(double));
