        polygons[i] = (polygon)malloc(sizeof(polygon));
        points[i] = (point*)malloc(MAX_POINTS * sizeof(point));
        crcIndications[i].RX_UE_INFORMATION_TAG = rand() % MAX_CHAR_SET_SIZE;
        crcIndications[i].RNTI = rand();
        crcIndications[i].CRC_INDICATION_REL8_TAG = rand() % MAX_CHAR_SET_SIZE;
        crcIndications[i].CRCFLAG = rand();

        // Initialize random seed for reproducibility
        srand(seed);

        // Generate random string and hash password
        int hashStringLength = 10;
        char* hashString = (char*)malloc(hashStringLength + 1);
        strcpy(hashString, "random_string_");
        for (int j = 0; j < hashStringLength; j++) {
            hashString[j] += '0' + rand() % 10;
        }
        hashString[hashStringLength] = '\0';

        // Calculate polygon area
        double polygonArea = 0.0;
        for (int k = 0; k < MAX_POINTS - 1; k++) {
            polygonArea += (points[i][k].x * points[i][k + 1].y - points[i][k + 1].x * points[i][k].y);
        }
        areas[i] = polygonArea;

        // Initialize random CRCFLAG
        crcIndications[i].CRCFLAG = rand() % MAX_CHAR_SET_SIZE;
    }

    // Free any dynamically allocated memory
    for (int i = 0; i < numPolygons; i++) {
        free(polygons[i]->points);
        free(polygons[i]);
    }
    free(polygons);
    free(points);
    free(areas);
    free(hashStrings);
    free(crcIndications);

    // Return initialized arrays
    return NULL;
}
