    int size;
    int capacity;
    pthread_mutex_t mutex;
} ArrayManager;

ArrayManager* create_array_manager(int initial_capacity) {
    ArrayManager* arr_mgr = (ArrayManager*)malloc(sizeof(ArrayManager));
    arr_mgr->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr_mgr->size = 0;
    arr_mgr->capacity = initial_capacity;
    pthread_mutex_init(&arr_mgr->mutex, NULL);
    return arr_mgr;
}

void free_array_manager(ArrayManager* arr_mgr) {
    free(arr_mgr->data);
    free(arr_mgr);
}

// Add a new entry
int add_entry(ArrayManager* arr_mgr, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&arr_mgr->mutex);

    for (int i = 0; i < arr_mgr->size; i++) {
        if (new_entry->rnti == arr_mgr->data[i].rnti) {
            // Update existing entry
            arr_mgr->data[i] = *new_entry;
            pthread_mutex_unlock(&arr_mgr->mutex);
            return 1; // Update successful
        }
    }

    // No duplicate found, add new entry
    if (arr_mgr->size == arr_mgr->capacity) {
        int new_capacity = arr_mgr->capacity * 2 + 1;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr_mgr->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        arr_mgr->data = new_data;
        arr_mgr->capacity = new_capacity;
    }
    arr_mgr->data[arr_mgr->size++] = *new_entry;

    pthread_mutex_unlock(&arr_mgr->mutex);
    return 0; // Add successful
}

// Remove an entry by RNTI
void remove_entry_by_rnti(ArrayManager* arr_mgr, RNTI rnti) {
    pthread_mutex_lock(&arr_mgr->mutex);

    for (int i = 0; i < arr_mgr->size; i++) {
        if (arr_mgr->data[i].rnti == rnti) {
            // Remove entry
            memmove(arr_mgr->data + i, arr_mgr->data + i + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (arr_mgr->size - i - 1));
            arr_mgr->size--;
            break;
        }
    }

    pthread_mutex_unlock(&arr_mgr->mutex);
}

// Update CRCFLAG for a specific RNTI
void update_crcflag(ArrayManager* arr_mgr, RNTI rnti, int new_crcflag) {
    pthread_mutex_lock(&arr_mgr->mutex);

    for (int i = 0; i < arr_mgr->size; i++) {
        if (arr_mgr->data[i].rnti == rnti) {
            // Update CRCFLAG
            arr_mgr->data[i].crcflag = new_crcflag;
            pthread_mutex_unlock(&arr_mgr->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&arr_mgr->mutex);
}

// Retrieve unique RNTI count
int get_unique_rnti_count(ArrayManager* arr_mgr) {
    int unique_rntis = 0;

    pthread_mutex_lock(&arr_mgr->mutex);

    for (int i = 0; i < arr_mgr->size; i++) {
        bool found = false;
        for (int j = 0; j < unique_rntis; j++) {
            if (arr_mgr->data[i].rnti == arr_mgr->data[j].rnti) {
                found = true;
                break;
            }
        }
        if (!found) {
            unique_rntis++;
        }
    }

    pthread_mutex_unlock(&arr_mgr->mutex);
    return unique_rntis;
}
