// Dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T **nfaArray;
int nfaArraySize = 0;

// Function to add a new entry to the array, ensuring no two entries have the same RNTI
void addEntry(int RNTI, int CRCFLAG) {
    // Check if RNTI already exists in the array
    for (int i = 0; i < nfaArraySize; i++) {
        if (nfaArray[i]->RNTI == RNTI) {
            // Handle collision by expanding the array
            nfaArraySize++;
            nfaArray = realloc(nfaArray, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * nfaArraySize);
            break;
        }
    }

    // Create a new entry and add it to the array
    NFAPI_CRC_INDICATION_PDU_T *newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(newEntry->RX_UE_INFORMATION_TAG, "New Entry");
    newEntry->RNTI = RNTI;
    newEntry->CRCFLAG = CRCFLAG;
    nfaArray[nfaArraySize++] = newEntry;
}

// Function to remove an entry by RNTI
void removeEntry(int RNTI) {
    for (int i = 0; i < nfaArraySize; i++) {
        if (nfaArray[i]->RNTI == RNTI) {
            // Handle multiple entries with the same RNTI by providing options for exact match removal or batch deletion
            printf("Multiple entries found with RNTI %d. Please specify a removal strategy.\n", RNTI);
            return;
        }
    }
    printf("No entry found with RNTI %d.\n", RNTI);
}

// Function to update the CRCFLAG for a specific RNTI
void updateCRCFLAG(int RNTI, int newCRCFLAG) {
    for (int i = 0; i < nfaArraySize; i++) {
        if (nfaArray[i]->RNTI == RNTI) {
            // Update only one CRCFLAG per operation
            nfaArray[i]->CRCFLAG = newCRCFLAG;
            return;
        }
    }
}

// Function to retrieve the total number of unique RNTIs in the array
int countUniqueRNTIs() {
    int uniqueRNTIs = 0;
    for (int i = 0; i < nfaArraySize; i++) {
        if (!foundInArray(nfaArray[i]->RNTI)) {
            uniqueRNTIs++;
        }
    }
    return uniqueRNTIs;
}

// Function to export the array to a file
void exportArray(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Failed to open file %s for writing.\n", filename);
        return;
    }

    // Write checksum and array data to the file
    int checksum = calculateChecksum();
    fwrite(&checksum, sizeof(int), 1, file);
    for (int i = 0; i < nfaArraySize; i++) {
        fwrite(nfaArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

// Function to import the array from a file
void importArray(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file %s for reading.\n", filename);
        return;
    }

    // Read checksum and array data from the file
    int checksum;
    fread(&checksum, sizeof(int), 1, file);

    // Validate the data before inserting it into the existing array
    if (validateArrayData(checksum)) {
        // Insert the imported entries into the existing array
        for (int i = 0; i < nfaArraySize; i++) {
            fread(nfaArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        }
    }

    fclose(file);
}

