void add_entry(NFAPI_RX_PDU_T* entry) {
    pthread_mutex_lock(&mutex);

    // Check if an entry with the same RF_TX_CHANNEL_ID already exists
    int found = 0;
    for (int i = 0; i < nfa_pi_rx_pdu_hash.count && !found; i++) {
        if (nfa_pi_rx_pdu_hash.entries[i].rf_tx_channel_id == entry->rf_tx_channel_id) {
            found = 1;
