void populateRecordArray(record** arr, int size) {
    for (int i = 0; i < size; i++) {
        (*arr)[i].data = rand() % 100 + 1;
    }
}

UEInformation* allocateUEInfo(int size) {
    UEInformation* ueInfo = (UEInformation*)malloc(size * sizeof(UEInformation));
    for (int i = 0; i < size; i++) {
        strcpy(ueInfo[i].tag, "RX_UE_INFORMATION_TAG");
        ueInfo[i].RNTI = rand() % 100 + 1;
        ueInfo[i].CRCFLAG = rand() % 2;
    }
    return ueInfo;
}

void filterAndCalculate(int* arr, int size) {
    // Filter out duplicates
    int uniqueSize = 0;
    for (int i = 0; i < size; i++) {
        int found = 0;
        for (int j = 0; j < uniqueSize; j++) {
            if (arr[i] == arr[j]) {
                found = 1;
                break;
            }
        }
        if (!found) {
            arr[uniqueSize++] = arr[i];
        }
    }

    // Calculate median
    int mid = uniqueSize / 2;
    if (uniqueSize % 2 == 0) {
        printf("Median: %d, %d\n", arr[mid - 1], arr[mid]);
    } else {
        printf("Median: %d\n", arr[mid]);
    }

    // Find largest integer
    int max = arr[0];
    for (int i = 1; i < uniqueSize; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest: %d\n", max);
}

void freeUEInfo(UEInformation* ueInfo, int size) {
    for (int i = 0; i < size; i++) {
        free((char*)ueInfo[i].tag);
    }
    free(ueInfo);
}

