#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

// Structure representing a network interface configuration
typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    int* routing_rules;
    time_t last_active;
} Config;

// Dynamic collection of configurations
typedef struct {
    pthread_mutex_t lock;  // Mutex for concurrency control
    Config** configs;       // Array to store configuration pointers
    size_t capacity;        // Current array capacity
    size_t count;           // Number of actual configurations
} ConfigCollection;

// Function to create a new configuration
Config* config_create(char* ip_address, char* subnet_mask, char* gateway) {
    Config* config = (Config*)malloc(sizeof(Config));
    strcpy(config->ip_address, ip_address);
    strcpy(config->subnet_mask, subnet_mask);
    strcpy(config->gateway, gateway);
    config->routing_rules = NULL;
    config->last_active = time(NULL);
    return config;
}

// Function to add a configuration to the collection
void config_collection_add(ConfigCollection* collection, Config* config) {
    pthread_mutex_lock(&collection->lock);  // Acquire lock for concurrency control

    if (collection->count >= collection->capacity) {  // Reallocate memory if necessary
        size_t new_capacity = collection->capacity * 2;
        Config** new_configs = (Config**)realloc(collection->configs, new_capacity * sizeof(Config*));
        collection->configs = new_configs;
        collection->capacity = new_capacity;
    }

    collection->configs[collection->count] = config;  // Add configuration to the array
    collection->count++;

    pthread_mutex_unlock(&collection->lock);  // Release lock for concurrency control
}

// Function to remove a configuration from the collection
void config_collection_remove(ConfigCollection* collection, Config* config) {
    pthread_mutex_lock(&collection->lock);  // Acquire lock for concurrency control

    for (int i = 0; i < collection->count; i++) {  // Find and remove the specified configuration
        if (collection->configs[i] == config) {
            memmove(collection->configs + i, collection->configs + i + 1, (collection->count - i - 1) * sizeof(Config*));
            collection->count--;
            free(config);
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);  // Release lock for concurrency control
}

// Function to modify a configuration in the collection
void config_collection_modify(ConfigCollection* collection, Config* config, char* new_ip_address, char* new_subnet_mask, char* new_gateway) {
    pthread_mutex_lock(&collection->lock);  // Acquire lock for concurrency control

    for (int i = 0; i < collection->count; i++) {  // Find and modify the specified configuration
        if (collection->configs[i] == config) {
            strcpy(config->ip_address, new_ip_address);
            strcpy(config->subnet_mask, new_subnet_mask);
            strcpy(config->gateway, new_gateway);
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);  // Release lock for concurrency control
}

// Function to purge unused configurations based on their last active timestamp
void config_collection_purge(ConfigCollection* collection) {
    pthread_mutex_lock(&collection->lock);  // Acquire lock for concurrency control

    for (int i = 0; i < collection->count; i++) {  // Find and remove configurations older than a certain threshold
        if ((time(NULL) - collection->configs[i]->last_active) > 3600) {
            memmove(collection->configs + i, collection->configs + i + 1, (collection->count - i - 1) * sizeof(Config*));
            collection->count--;
            free(collection->configs[i]);
        }
    }

    pthread_mutex_unlock(&collection->lock);  // Release lock for concurrency control
}

// Function to validate a configuration against specific criteria
int config_validate(Config* config, int ip_range_check) {
    if (strlen(config->ip_address) > 15 || strlen(config->subnet_mask) > 15 || strlen(config->gateway) > 15) {
        return -1;  // Configuration exceeds maximum length limit
    }

    if (!isValidIP(config->ip_address)) {
        return -2;  // IP address is invalid
    }

    if (ip_range_check && !isInRange(config->ip_address, config->subnet_mask)) {
        return -3;  // IP address falls outside the valid range
    }

    return 0;  // Configuration is valid
}

// Function to check whether a configuration is currently in use based on its last active timestamp
int config_is_in_use(Config* config) {
    if ((time(NULL) - config->last_active) < 3600) {
        return 1;  // Configuration is still in use within the past hour
    } else {
        return 0;  // Configuration has not been used for over an hour
    }
}

int main() {
    ConfigCollection* collection = (ConfigCollection*)malloc(sizeof(ConfigCollection));
    pthread_mutex_init(&collection->lock, NULL);
    collection->configs = (Config**)malloc(1 * sizeof(Config*));  // Initialize the array with a single slot
    collection->capacity = 1;
    collection->count = 0;

    Config* config = config_create("192.168.1.100", "255.255.255.0", "192.168.1.1");
    config_collection_add(collection, config);

    // ... Add more configurations, modify some, and purge unused ones ...

    return 0;
}
