#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEYS 10000
#define TABLE_SIZE 1024

typedef struct {
    int key;
    long value;
} Record;

Record* db = NULL;
int size = 0;

void insert(int key, long value) {
    if (size >= MAX_KEYS) {
        printf("Error: Maximum number of keys reached.\n");
        return;
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    new_record->key = key;
    new_record->value = value;

    if (size == 0 || hash(key, TABLE_SIZE) % size != size - 1) {
        Record* temp = db;
        db = new_record;
        new_record = temp;
        size++;
    } else {
        // Handle collision
        Record* prev = &db[hash(key, TABLE_SIZE) % (size - 1)];
        while (prev->key < key)
            prev = &prev->value;

        *new_record = *prev;
        free(prev);
    }
}

long retrieve(int key) {
    int index = hash(key, TABLE_SIZE) % size;
    if (index >= 0 && index < size) {
        return db[index].value;
    } else {
        printf("Error: Key not found.\n");
        return -1;
    }
}

void update(int key, long value) {
    int index = hash(key, TABLE_SIZE) % size;
    if (index >= 0 && index < size) {
        db[index].value = value;
    } else {
        printf("Error: Key not found.\n");
    }
}

int hash(int key, int table_size) {
    return key % table_size;
}

void iterateRecords(void (*operation)(Record*)) {
    for (int i = 0; i < size; i++) {
        operation(db[i]);
    }
}

// Initialize database
void init() {
    db = (Record*)malloc(sizeof(Record));
    if (!db) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    size = 1;
}

// Clean up resources
void cleanup() {
    for (int i = 0; i < size; i++) {
        free(&db[i]);
    }
    free(db);
}
