    time_t timestamp;
    int event_id;
    // Implement a linked list structure to manage cell IDs
    struct CellIDNode* cell_ids;
} NetworkEventLogEntry;

// Define a struct to represent the head of the linked list for cell IDs
typedef struct {
    NetworkEventLogEntry* entry;
    struct CellIDNode* next;
} CellIDNode;

// Function to initialize and populate the dynamic array of NetworkEventLogEntries
void initNetworkEventLog(NetworkEventLogEntry** log, int capacity) {
    // Initialize the log with the given capacity
    *log = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry) * capacity);

    for (int i = 0; i < capacity; i++) {
        (*log)[i].timestamp = time(NULL); // Initialize timestamp to current system time
        (*log)[i].event_id = i;
        (*log)[i].cell_ids = NULL; // Initialize cell ID linked list
    }
}

// Function to add a new event log entry with associated cell IDs
void addEventLogEntry(NetworkEventLogEntry** log, int capacity, NetworkEventLogEntry* entry) {
    // Find the next available slot in the log array
    for (int i = 0; i < capacity; i++) {
        if ((*log)[i].timestamp == entry->timestamp && (*log)[i].event_id == entry->event_id) {
            // Reuse an existing entry with matching timestamp and event ID
            break;
        } else if ((*log)[i].cell_ids == NULL) {
            // Found an empty slot, add the new entry here
            (*log)[i] = *entry;
            return;
        }
    }

    // If no empty slots found, resize the log array and add the new entry
    int newSize = capacity * 2; // Resize to twice the current capacity
    NetworkEventLogEntry* newLog = (NetworkEventLogEntry*)realloc(*log, sizeof(NetworkEventLogEntry) * newSize);
    for (int i = capacity; i < newSize; i++) {
        newLog[i].timestamp = time(NULL); // Initialize timestamp to current system time
        newLog[i].event_id = i;
        newLog[i].cell_ids = NULL; // Initialize cell ID linked list
    }

    // Add the new entry to the resized log array
    *log = newLog;
}

// Function to export the log entries in a standardized format (e.g., JSON, CSV)
void exportLog(NetworkEventLogEntry** log, int capacity) {
    // Implement export logic based on chosen format (JSON or CSV)
    for (int i = 0; i < capacity; i++) {
        printf("%ld,%d,", (*log)[i].timestamp, (*log)[i].event_id); // Print timestamp and event ID
        // Iterate through cell IDs linked list and print each ID separated by commas
        CellIDNode* current = (*log)[i].cell_ids;
        while (current != NULL) {
            printf("%d,", current->entry->cell_id);
            current = current->next;
        }
        printf("\n"); // Print a newline for each entry
    }
}
