        printf("Invalid input: Maximum count or allocation threshold is invalid.\n");
        return -1;
    }

    structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!structures) {
        printf("Memory allocation failed.\n");
        return -2;
