            // Filter out structures with CRC flag value below the minimum threshold
            free(structures[i]);
            for (int j = i; j < max_count - 1; j++) {
                structures[j] = structures[j + 1];
            }
            structures[max_count - 1] = NULL;
            max_count--;
            i--;
        } else if (logging_enabled) {
            printf("Structure allocated with CRC flag value: %d\n", structures[i]->CRC_INDICATION_REL8_TAG);
        }

        (*allocated_count)++;
    }

    free(structures);

    return *allocated_count;
}

int main() {
    int max_count = 10; // Example maximum count
    int allocated_count;

    allocated_count = allocate_structures(max_count, &allocated_count);

    printf("Number of structures successfully allocated: %d\n", allocated_count);

    return 0;
}
