    int local_port;
    int remote_port;
    int state; // 0: established, 1: closing, 2: closed
    long timestamp;
} TID_DATA;

int tid_list_size = 0;
TID_DATA** tid_list = NULL;
int max_tid_size = 0;

void tid_manage_init(int new_max) {
    if (new_max <= 0) return;

    if (max_tid_size > 0 && tid_list != NULL) {
        for (int i = 0; i < max_tid_size; i++) {
            free(tid_list[i]);
        }
        free(tid_list);
    }

    max_tid_size = new_max;
    tid_list = (TID_DATA**)malloc(max_tid_size * sizeof(TID_DATA*));
    tid_list_size = 0;
}

void tid_manage_alloc(TID_DATA** new_data) {
    if (tid_list_size >= max_tid_size) {
        // Handle memory allocation failure
        printf("Error: Out of memory\n");
        return;
    }

    tid_list[tid_list_size] = *new_data;
    tid_list_size++;
}

int tid_manage_free(int index) {
    if (index < 0 || index >= tid_list_size) return -1;

    free(tid_list[index]);
    for (int i = index; i < tid_list_size - 1; i++) {
