```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int key;
    int value;
} record;

record *db = NULL;
int *keys = NULL;
int numRecords = 0;
int usedKeys[10000] = {0}; // assuming a maximum of 10,000 records

void insertRecord(int key, int value) {
    if (numRecords >= 10000) {
        printf("Database full. Cannot insert new record.\n");
        return;
    }

    if (!usedKeys[key]) {
        usedKeys[key] = 1;
        db[numRecords].key = key;
        db[numRecords].value = value;
        numRecords++;
    } else {
        printf("Key already in use. Cannot insert new record.\n");
    }
}

void updateRecord(int key, int value) {
    for (int i = 0; i < numRecords; i++) {
        if (db[i].key == key) {
            db[i].value = value;
            return;
        }
    }
    printf("Key not found. Cannot update record.\n");
}

void retrieveRecord(int key, int *returnValue) {
    for (int i = 0; i < numRecords; i++) {
        if (db[i].key == key) {
            *returnValue = db[i].value;
            return;
        }
    }
    printf("Key not found. Cannot retrieve record.\n");
}

void freeDatabase() {
    if (db != NULL) {
        for (int i = 0; i < numRecords; i++) {
            free(&db[i]);
        }
        free(db);
        db = NULL;
    }
}
