typedef struct {
    int key;
    long offset;
} record_t;

record_t* init_records(int num_records) {
    srand(time(NULL));

    // Initialize arrays for 'long' offsets and 'int' keys
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize record array
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));

    for (int i = 0; i < num_records; i++) {
        long offset;
        do {
            offset = rand() % INT_MAX + 1;
        } while (i > 0 && offset <= offsets[i - 1]);
        offsets[i] = offset;

        int key = rand() % INT_MAX + 1;
        keys[i] = key;

        records[i].key = key;
        records[i].offset = offset;
    }

    // Store each 'record' in a file-based database
    FILE* db_file = fopen("records.db", "wb");
    fwrite(&num_records, sizeof(int), 1, db_file);
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(record_t), 1, db_file);
    }
    fclose(db_file);

    // Free memory
    free(offsets);
    free(keys);
    return records;
}

int main() {
    int num_records = 1000000;
    record_t* records = init_records(num_records);
    // Use the 'records' array...
