struct NFAPI_CRC_INDICATION_PDU_T* records[MAX_NFAPI_CRC_INDICATION_PDU_T];

void* generate_random_value(void* arg) {
    // Random value generation strategy
    int min_val = 1;
    int max_val = 1000;
    int val = (int)(rand() / (RAND_MAX / (max_val - min_val + 1)) + min_val);
    return &val;
}

void generate_records(int num_records) {
    record_size = num_records;
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        int rnti = rand() % (max_val - min_val + 1) + min_val;
        int crcflag = rand() & 0x1; // Randomly set CRCFLAG
        records[i]->RX_UE_INFORMATION_TAG = i;
        records[i]->RNTI = rnti;
        records[i]->CRC_INDICATION_REL8_TAG = (int)(rand() / (RAND_MAX / (max_val - min_val + 1)) + min_val);
        records[i]->CRCFLAG = crcflag;
    }
}

void write_records_to_file(int num_records) {
    int fd = open("records.json", O_RDWR | O_CREAT, 0644);
    if (fd < 0) {
        fprintf(stderr, "File operation failed\n");
        exit(1);
    }
    for (int i = 0; i < num_records; i++) {
        json_object* record_json = json_object_new_object();
        json_object_object_add(record_json, "RX_UE_INFORMATION_TAG", json_object_new_int(records[i]->RX_UE_INFORMATION_TAG));
        json_object_object_add(record_json, "RNTI", json_object_new_int(records[i]->RNTI));
        json_object_object_add(record_json, "CRC_INDICATION_REL8_TAG", json_object_new_int(records[i]->CRC_INDICATION_REL8_TAG));
        json_object_object_add(record_json, "CRCFLAG", json_object_new_int(records[i]->CRCFLAG));
        int bytes_written = write(fd, record_json->buffer, record_json->length);
        if (bytes_written < 0) {
            fprintf(stderr, "File operation failed\n");
            exit(1);
        }
    }
    close(fd);
}

void* thread_handler(void* arg) {
    int num_records = *(int*)arg;
    generate_records(num_records);
    write_records_to_file(num_records);
    free(arg);
    return NULL;
}

int main(int argc, char** argv) {
    pthread_t threads[MAX_NFAPI_CRC_INDICATION_PDU_T];
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
        int num_records = rand() % (MAX_RECORDS - 1) + 1;
        pthread_create(&threads[i], NULL, thread_handler, &num_records);
    }
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
        pthread_join(threads[i], NULL);
