// Custom memory pool structure to manage dynamic allocations
typedef struct {
    void** blocks;
    size_t total_size;
    size_t allocated_size;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool* pool, size_t initial_size) {
    pool->blocks = (void**)malloc(initial_size * sizeof(void*));
    pool->total_size = initial_size * 1024; // assume 1KB blocks
    pool->allocated_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

MemoryPool memory_pool;

// Initialize and configure a dynamic array of LTE PHY Layer Control Messages
int init_lte_phy_layer_control_messages(int num_messages) {
    if (num_messages > 10000)
        return -1; // overflow detection mechanism

    LTE_PHY_Layer_Control_Message* messages = (LTE_PHY_Layer_Control_Message*)malloc(num_messages * sizeof(LTE_PHY_Layer_Control_Message));

    for (int i = 0; i < num_messages; i++) {
        messages[i].phich_config[0] = i % PHICH_CONFIG_SIZE;
        strcpy(messages[i].ue_id, "UE_ID");
        messages[i].dl_mch_data_tag = (char*)malloc(DL_MCH_DATA_TAG_SIZE);
    }

    return 0;
}

int release_lte_phy_layer_control_messages(LTE_PHY_Layer_Control_Message* messages, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
        free(messages[i].dl_mch_data_tag);
    }
    free(messages);

    // Clean up memory pool resources
    if (memory_pool.allocated_size > 0) {
        for (size_t i = 0; i < memory_pool.allocated_size; i++) {
            free(memory_pool.blocks[i]);
        }
        free(memory_pool.blocks);
        pthread_mutex_destroy(&memory_pool.lock);
    }

    return 0;
}

