// Function to add a slash to the end of a string if it does not exceed the size limit
char* add_slash(char* str, int size_limit) {
    char* modified_str = (char*)malloc(strlen(str) + 2);
    strcpy(modified_str, str);
    if(strlen(str) < size_limit) {
        strcat(modified_str, "/");
    }
    return modified_str;
