            records[unique_records].value = input_array[i];
            unique_records++;

            // Check for duplicate values
            for (int j = 0; j < unique_records; j++) {
                if (records[j].value == input_array[i]) {
                    printf("Duplicate value detected. Please enter a new value.\n");
