    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->data = pdu;
    new_node->next = head;
    head = new_node;
    list_size++;
}

int compact_list() {
    Node* prev = NULL;
    Node* current = head;
    while (current) {
        if (list_size < MIN_COMPACTED_LIST_SIZE && !prev) {
            free(current);
            list_size--;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

