#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int qos;
    int ue_id;
    char* payload;
} Message;

Message** messages;
int num_messages = 0;
int max_messages = 100;
pthread_mutex_t lock;

void init_message_queue() {
    messages = (Message**)malloc(max_messages * sizeof(Message*));
    pthread_mutex_init(&lock, NULL);
}

Message* create_message(int qos, int ue_id, char* payload) {
    Message* msg = (Message*)malloc(sizeof(Message));
    msg->qos = qos;
    msg->ue_id = ue_id;
    msg->payload = payload;
    return msg;
}

void enqueue_message(Message* msg) {
    pthread_mutex_lock(&lock);
    messages[num_messages] = msg;
    num_messages++;
    pthread_mutex_unlock(&lock);
}

Message* dequeue_message() {
    pthread_mutex_lock(&lock);
    if (num_messages == 0) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    Message* msg = messages[0];
    memmove(messages, &messages[1], (num_messages - 1) * sizeof(Message*));
    num_messages--;
    pthread_mutex_unlock(&lock);
    return msg;
}

void destroy_message_queue() {
    for (int i = 0; i < num_messages; i++) {
        free(messages[i]->payload);
        free(messages[i]);
    }
    free(messages);
    pthread_mutex_destroy(&lock);
}
