typedef struct {
    double min;
    double max;
    double avg;
} Statistics;

void process_file_and_generate_statistics(const char* file_path, Statistics* stats, int buffer_size, const FileConfig* config) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        // Handle file not found or permission issues
        if (ferror(file)) {
            // Log error and retry according to config
            if (config->retry_limit > 0) {
                // Retry reading the file
                // ...
            } else {
                printf("Error: File not found or permission issue.\n");
            }
        } else {
            printf("Error: Unknown error while opening file.\n");
        }
        return;
    }

    char* buffer = NULL;
    size_t buffer_len = 0;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);

    rewind(file);
    if (file_size > buffer_size) {
        // Handle partial reads
        buffer = malloc(buffer_size * sizeof(char));
        buffer_len = buffer_size;
    } else {
        buffer = malloc((file_size + 1) * sizeof(char));
        buffer_len = file_size;
    }

    fread(buffer, sizeof(char), file_size, file);
    fclose(file);

    if (buffer_len > 0) {
        // Parse file content
        char* line = strtok(buffer, "\n");
        while (line != NULL) {
            // Validate and parse each line
            if (!validate_line(line)) {
                free(buffer);
                return;
            }
            process_line(line, stats);
            line = strtok(NULL, "\n");
        }
    } else {
        printf("Error: File is empty.\n");
    }

    free(buffer);

    // Calculate statistics and update the struct
    stats->min = min(stats->values);
    stats->max = max(stats->values);
    stats->avg = avg(stats->values);

    return;
}
