#define MAX_SIZE 1000

typedef struct {
    int i;
    float f;
    char* c;
} item;

void process_data(item** items1, item** items2, item** items3, size_t n) {
    // Sort items based on integer field
    qsort(*items1, n, sizeof(item), (int (*)(const void*, const void*))cmp_item);

    // Integrate with logging library for performance metrics
    printf("Sorting duration: %f seconds\n", difftime(clock(), (double)start_time));
}

int cmp_item(const void* a, const void* b) {
    item* ia = *(item**)a;
    item* ib = *(item**)b;

    if (ia->i < ib->i)
        return -1;
    else if (ia->i > ib->i)
        return 1;
    else
        return strcmp(ia->c, ib->c);
}

int main() {
    srand(time(NULL));

    item* items1 = malloc(MAX_SIZE * sizeof(item));
    item* items2 = malloc(MAX_SIZE * sizeof(item));
    item* items3 = malloc(MAX_SIZE * sizeof(item));

    for (size_t i = 0; i < MAX_SIZE; ++i) {
        // Populate character strings with random ASCII characters
        char c[5];
        sprintf(c, "%c", (char)(rand() % 26 + 'a'));
        item* it = &items1[i];
        it->i = rand();
        it->f = (float)rand() / RAND_MAX;
        it->c = malloc(strlen(c) + 1);
        strcpy(it->c, c);

        // Alternate between items1 and items2
        if (i % 2 == 0)
            memcpy(&items3[i], &items1[i], sizeof(item));
        else
            memcpy(&items3[i], &items2[i], sizeof(item));
    }

    process_data(&items1, &items2, &items3, MAX_SIZE);

    // Free memory and release resources properly
    for (size_t i = 0; i < MAX_SIZE; ++i) {
        free(items1[i].c);
        free(items2[i].c);
        free(items3[i].c);
    }
    free(items1);
    free(items2);
    free(items3);

    return 0;
}

