struct OctreeNode {
    int featureSize;
    int numLeafNodes;
    int maxDepth;
    std::vector<OctreeNode*> children; // dynamically allocated array of child nodes
    bool isLeaf; // flag indicating whether this node is a leaf node
    int dataPoints[8]; // array to store data points (initialize with zeros)
};

class Octree {
private:
    OctreeNode* root;
    std::mutex mtx; // mutex for thread-safe access

public:
    Octree(int featureSize, int numLeafNodes, int maxDepth) : 
        featureSize(featureSize), numLeafNodes(numLeafNodes), maxDepth(maxDepth) {}

    OctreeNode* initOctree() {
        root = new OctreeNode();
        root->featureSize = featureSize;
        root->numLeafNodes = numLeafNodes;
        root->maxDepth = maxDepth;
        return root;
    }

    void insertDataPoint(OctreeNode* node, int x, int y, int z) {
        if (!node || node->isLeaf) {
            // handle leaf nodes or null nodes
            // (e.g., update dataPoints array)
            return;
        }

        int idx = 0;
        if (x < node->featureSize) idx |= 1 << 0;
        if (y < node->featureSize) idx |= 1 << 1;
        if (z < node->featureSize) idx |= 1 << 2;

        OctreeNode* child = node->children[idx];
        if (!child) {
            child = new OctreeNode();
            child->featureSize = featureSize / 2;
            child->numLeafNodes = numLeafNodes / 8;
            child->maxDepth = maxDepth - 1;
            node->children[idx] = child;
        }
        insertDataPoint(child, x, y, z);
    }

    void startInsertionThread() {
        std::thread thread([&]() {
            // concurrent data insertion logic here
            for (int i = 0; i < numLeafNodes; i++) {
                int x, y, z;
                // read data points from external source or system dependencies
                insertDataPoint(root, x, y, z);
            }
        });
        thread.detach();
    }

    ~Octree() {
        if (root) deleteTree(root);
    }

private:
    void deleteTree(OctreeNode* node) {
        if (!node) return;

        for (auto child : node->children) {
            deleteTree(child);
        }
        delete node;
    }
};

