    for (int i = index; i < num_mounts - 1; i++) {
        memmove(&mount_configs[i], &mount_configs[i + 1], sizeof(MountConfig));
    }
    num_mounts--;
}

void compact_memory_pool() {
    int freed_size = 0;
    void* ptr = memory_pool[0];
    while (ptr) {
        if (!current_memory_pool_usage) break;
        size_t size = *(size_t*)ptr - sizeof(size_t);
        free(ptr);
        freed_size += size + sizeof(size_t);
        current_memory_pool_usage -= size + sizeof(size_t);
        ptr = memory_pool[0];
    }
}

