    long *offsets = (long*)malloc(num_records * sizeof(long));
    int *keys = (int*)malloc(num_records * sizeof(int));
    Record *records = (Record*)malloc(num_records * sizeof(Record));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
        keys[i] = i + 1;

        if (i > 0) {
            while (rand() % 2 == 0 && records[i-1].value == keys[i]) {
                records[i-1].value = rand() % 100;
            }
        }

        records[i].key = keys[i];
        records[i].value = rand() % 100;

        fseek(db, ftell(db) + sizeof(Record), SEEK_END);
        fwrite(&records[i], sizeof(Record), 1, db);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
