#include <string.h>
#include <time.h>

typedef struct {
    float measurement;
    bool valid;
    long* timestamp;
} status_t;

status_t** allocateMemory(int size) {
    status_t** array = (status_t**)malloc(size * sizeof(status_t*));
    if (!array) return NULL;

    for (int i = 0; i < size; i++) {
        array[i] = (status_t*)malloc(sizeof(status_t));
        if (!array[i]) {
            free(array);
            return NULL;
        }
    }

    return array;
}

long* generateTimestamp(int size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (!array) return NULL;

    for (int i = 0; i < size; i++) {
        array[i] = rand() % 10000000L + 1;
    }

    return array;
}

char* generateIdentifier(int size, int seed) {
    srand(seed);
    char* array = (char*)malloc((size+1)*sizeof(char));
    if (!array) return NULL;

    for (int i = 0; i < size; i++) {
        array[i] = (char)(rand() % 26 + 'a');
    }
    array[size] = '\0';

    return array;
}

double* generateNumerical(int size, int min, int max) {
    double* array = (double*)malloc(size * sizeof(double));
    if (!array) return NULL;

    for (int i = 0; i < size; i++) {
        do {
            array[i] = ((double)(rand() % (max - min + 1))) + min;
        } while (duplicate(array, i, size, min, max));
    }

    return array;
}

bool duplicate(double* arr, int pos, int size, double min, double max) {
    for (int i = 0; i < pos; i++) {
        if (fabs(arr[i] - ((double)(rand() % (max - min + 1))) + min) < 1e-6) return true;
    }
    return false;
}

status_t** manageMemory(int size, int identifierSize, int numericalSize, int min, int max) {
    status_t** array = allocateMemory(size);
    if (!array) return NULL;

    long* timestamps = generateTimestamp(size);
    char** identifiers = (char**)malloc(size * sizeof(char*));
    double* numerics = generateNumerical(numericalSize, min, max);

    for (int i = 0; i < size; i++) {
        array[i]->measurement = ((double)(rand() % (max - min + 1))) + min;
        array[i]->valid = true;
        array[i]->timestamp = &timestamps[i];
    }

    free(timestamps);
    free(numerics);

    return array;
}

void freeMemory(status_t** array, int size) {
    for (int i = 0; i < size; i++) {
        if (array[i]) {
            free(array[i]->timestamp);
            free(array[i]);
        }
    }
    free(array);
}
