typedef struct {
    int session_id;
    void* payload;
    size_t payload_len;
    int type;
    time_t timestamp;
} Message;

typedef struct {
    Message** messages;
    int capacity;
    int count;
} MessageQueue;

MessageQueue* message_queue_init(int max_capacity) {
    MessageQueue* queue = (MessageQueue*)malloc(sizeof(MessageQueue));
    queue->messages = (Message**)calloc(max_capacity, sizeof(Message*));
    queue->capacity = max_capacity;
    queue->count = 0;
    return queue;
}

void message_queue_free(MessageQueue* queue) {
    for (int i = 0; i < queue->count; i++) {
        free(queue->messages[i]->payload);
        free(queue->messages[i]);
    }
    free(queue->messages);
    free(queue);
}

Message* message_init(int session_id, void* payload, size_t payload_len, int type) {
    Message* message = (Message*)malloc(sizeof(Message));
    message->session_id = session_id;
    message->payload = payload;
    message->payload_len = payload_len;
    message->type = type;
    message->timestamp = time(NULL);
    return message;
}

void message_queue_enqueue(MessageQueue* queue, Message* message) {
    if (queue->count >= queue->capacity - 1) {
        printf("Error: Queue is full.\n");
        return;
    }
    queue->messages[queue->count] = message;
    queue->count++;
}

Message* message_queue_dequeue(MessageQueue* queue) {
    if (queue->count <= 0) {
        printf("Error: Queue is empty.\n");
        return NULL;
    }
    Message* message = queue->messages[0];
    for (int i = 0; i < --queue->count; i++) {
        queue->messages[i] = queue->messages[i + 1];
    }
    return message;
}

void message_queue_process(MessageQueue* queue) {
    while (queue->count > 0) {
        Message* message = message_queue_dequeue(queue);
        // Process the message here
        free(message->payload);
        free(message);
    }
}

int main() {
    MessageQueue* queue = message_queue_init(5000);
    // Create and enqueue messages
    for (int i = 0; i < 100; i++) {
        Message* message = message_init(i, malloc(1024), 1024, 1);
        message_queue_enqueue(queue, message);
    }
    // Process the queue
    message_queue_process(queue);
    message_queue_free(queue);
    return 0;
}
