int list_add(struct NFAPI_CRC_INDICATION_PDU_T** list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    struct NFAPI_CRC_INDICATION_PDU_T* new_element = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc_or_die(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) return -1;

    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    for (int i = 0; i < 4; i++) {
        new_element->CRC_INDICATION_REL8_TAG[i] = (uint8_t)(rand() % 256);
    }

