            memmove(&(*list)[i], &(*list)[i+1], sizeof(struct NFAPI_CRC_INDICATION_PDU_T*) * (|--((*list)->size)));
            break;
        }
    }

    return 0;
}

void list_free(struct NFAPI_CRC_INDICATION_PDU_T** list) {
    for (int i = 0; i < (*list)->size; i++) {
