} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL; // Handle memory allocation failure
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void free_list(Node** head_ref) {
    Node* current = *head_ref;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head_ref = NULL;
}

Node* insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = create_node(data);
    if (*head == NULL || (*head)->data.RX_UE_INFORMATION_TAG != node->data.RX_UE_INFORMATION_TAG || (*head)->data.RNTI != node->data.RNTI) {
        node->next = *head;
        *head = node;
    } else {
        Node* current = *head;
        while (current->next && (current->next->data.RX_UE_INFORMATION_TAG == node->data.RX_UE_INFORMATION_TAG || current->next->data.RNTI == node->data.RNTI)) {
            current = current->next;
        }
        node->next = current->next;
        current->next = node;
    }
    return *head;
}

void serialize_list(Node* head, FILE* file) {
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

Node* deserialize_list(FILE* file) {
    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        head = insert_node(&head, data);
    }
    return head;
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    Node* head = NULL;

    int max_elements = 1000; // Define the maximum allowed elements in the list
    int threshold = 500; // Define the threshold for dynamic resizing

    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand();
        data.RNTI = rand();
        data.CRC_INDICATION_REL8_TAG = rand();
        data.CRCFLAG = rand() % 2;

        head = insert_node(&head, data);

        if (list_size(head) > threshold) {
            // Resize the list dynamically
            Node** new_head = (Node**)malloc(sizeof(Node*));
            *new_head = head;
            head = new_head;
            threshold *= 2; // Increase the threshold for dynamic resizing
        }
    }

    FILE* file = fopen("data.bin", "wb");
    serialize_list(head, file);
    fclose(file);

    file = fopen("data.bin", "rb");
    Node* deserialized_head = deserialize_list(file);
    fclose(file);

    free_list(&deserialized_head);

    return 0;
}
