#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure for record
typedef struct {
    int value;
} Record;

// Custom memory pool structure
typedef struct {
    void** blocks;
    size_t* sizes;
    size_t capacity;
    size_t used;
} MemoryPool;

// Initialize and allocate a custom memory pool
MemoryPool* initialize_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->capacity = capacity;
    pool->used = 0;
    pool->blocks = (void**)calloc(capacity, sizeof(void*));
    pool->sizes = (size_t*)calloc(capacity, sizeof(size_t));
    return pool;
}

// Allocate memory from the custom memory pool
void* allocate_memory_pool(MemoryPool* pool, size_t size) {
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->sizes[i] >= size) {
            void* ptr = pool->blocks[i];
            pool->sizes[i] -= size;
            return ptr;
        }
    }
    return NULL;
}

// Deallocate memory from the custom memory pool
void deallocate_memory_pool(MemoryPool* pool, void* ptr, size_t size) {
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->blocks[i] == ptr) {
            pool->sizes[i] += size;
            return;
        }
    }
}

// Initialize and store records
void initialize_records(MemoryPool* offset_pool, MemoryPool* key_pool, int num_records, Record** records) {
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)allocate_memory_pool(offset_pool, sizeof(Record));
        if (!record) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            return;
        }
        int random_value = rand() % (2 * 1024); // Generate a random value within the specified range
        record->value = random_value; // Initialize the record's int field with the random value
        records[i] = record; // Store the initialized record
    }
}

// Persistent storage mechanism using a file-based database
void store_records(Record** records, int num_records) {
    FILE* file = fopen("records.txt", "wb");
    if (!file) {
        // Handle file operation failure
        printf("File operation failed.\n");
        return;
    }
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        fwrite(&record, sizeof(Record), 1, file);
    }
    fclose(file);
}

// Main function
int main() {
    int num_records = 10000000;
    MemoryPool* offset_pool = initialize_memory_pool(num_records * sizeof(long));
    MemoryPool* key_pool = initialize_memory_pool(num_records * sizeof(int));
    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    initialize_records(offset_pool, key_pool, num_records, records);
    store_records(records, num_records);
    for (int i = 0; i < num_records; i++) {
        deallocate_memory_pool(offset_pool, records[i], sizeof(Record));
        free(records[i]);
    }
    free(records);
    free(key_pool->blocks);
    free(key_pool->sizes);
    free(offset_pool->blocks);
    free(offset_pool->sizes);
    return 0;
}
