typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to represent a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random CRCFLAG
Node* create_node() {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL; // Handle memory allocation failure

    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = rand();
    data.RNTI = rand();
    data.CRCFLAG = rand() % 2;

    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the end of the list
void insert_node(Node** head, Node* new_node) {
    if (!*head) *head = new_node;
    else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
}

// Function to delete a node with the given RX_UE_INFORMATION_TAG and RNTI
void delete_node(Node** head, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!*head) return; // List is empty

    Node* current = *head;
    Node* prev = NULL;

    while (current && (current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG || current->data.RNTI != RNTI)) {
        prev = current;
        current = current->next;
    }

    if (!current) return; // Node not found

    if (!prev) *head = current->next;
    else prev->next = current->next;

    free(current);
}

// Function to serialize the linked list to disk
void serialize_list(Node* head, FILE* file) {
    Node* current = head;
    while (current) {
        fwrite(&current->data.RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&current->data.RNTI, sizeof(int), 1, file);
        fwrite(&current->data.CRCFLAG, sizeof(int), 1, file);
        current = current->next;
    }
}

// Function to deserialize the linked list from disk
Node* deserialize_list(FILE* file) {
    Node* head = NULL;
    int RX_UE_INFORMATION_TAG, RNTI, CRCFLAG;

    while (fscanf(file, "%d %d %d", &RX_UE_INFORMATION_TAG, &RNTI, &CRCFLAG) == 3) {
        Node* node = create_node();
        if (!node) return NULL; // Handle memory allocation failure

        node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        node->data.RNTI = RNTI;
        node->data.CRCFLAG = CRCFLAG;

        if (!head) head = node;
        else {
            Node* current = head;
            while (current->next) current = current->next;
            current->next = node;
        }
    }

    return head;
}

// Function to log events
