typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size, capacity;
} nfa_pi_crc_indication_pdu_manager = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, 10000};

NFAPI_CRC_INDICATION_PDU_T* create_element(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = rand();
    new_element->CRCFLAG = rand();
    return new_element;
}

int get_index(NFAPI_CRC_INDICATION_PDU_T* element) {
    return (element->RX_UE_INFORMATION_TAG << 16) | element->RNTI;
}

void* hash_table_insert(void* key, void* value) {
    // use a simple linear probing strategy
    size_t index = *(size_t*)key;
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)(pthread_getspecific(nfa_pi_crc_indication_pdu_manager.lock));
    while (array[index] != NULL) {
        index++;
    }
    array[index] = value;
}

void* hash_table_lookup(void* key) {
    size_t index = *(size_t*)key;
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)(pthread_getspecific(nfa_pi_crc_indication_pdu_manager.lock));
    while (array[index] != NULL) {
        if (*((NFAPI_CRC_INDICATION_PDU_T**)array[index])->RX_UE_INFORMATION_TAG == *(int*)key) {
            return array[index];
        }
        index++;
    }
    return NULL;
}

void nfa_pi_crc_indication_pdu_manager_init() {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_DEFAULT);
    pthread_mutex_init(&nfa_pi_crc_indication_pdu_manager.lock, &attr);
    pthread_mutexattr_destroy(&attr);
}

int nfa_pi_crc_indication_pdu_manager_insert(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_manager.lock);
    if (nfa_pi_crc_indication_pdu_manager.size == nfa_pi_crc_indication_pdu_manager.capacity) {
        // re-allocate memory
        NFAPI_CRC_INDICATION_PDU_T** new_array = (NFAPI_CRC_INDICATION_PDU_T**)realloc(nfa_pi_crc_indication_pdu_manager.array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * nfa_pi_crc_indication_pdu_manager.capacity * 2);
        if (new_array == NULL) {
            pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_manager.lock);
            return -1;
        }
        nfa_pi_crc_indication_pdu_manager.array = new_array;
        nfa_pi_crc_indication_pdu_manager.capacity *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_element = create_element(RX_UE_INFORMATION_TAG, RNTI);
    size_t index = get_index(new_element);
    hash_table_insert(&index, new_element);
    nfa_pi_crc_indication_pdu_manager.array[nfa_pi_crc_indication_pdu_manager.size] = new_element;
    nfa_pi_crc_indication_pdu_manager.size++;
    pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_manager.lock);
}

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_manager_lookup(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_manager.lock);
    size_t index = get_index(create_element(RX_UE_INFORMATION_TAG, RNTI));
    NFAPI_CRC_INDICATION_PDU_T* result = hash_table_lookup(&index);
    pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_manager.lock);
    return result;
}

void nfa_pi_crc_indication_pdu_manager_deinit() {
    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_manager.lock);
    for (size_t i = 0; i < nfa_pi_crc_indication_pdu_manager.size; i++) {
        free(nfa_pi_crc_indication_pdu_manager.array[i]);
    }
    free(nfa_pi_crc_indication_pdu_manager.array);
    pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_manager.lock);
}
