// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
int create_crc_indication_pdu_list(int n, FILE *log_file) {
    // Define the size of the memory pool (adjust according to performance and memory usage requirements)
    int MEM_POOL_SIZE = 1048576; // 1MB

    // Initialize the linked list head
    NFAPI_CRC_INDICATION_PDU_T **head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *tail = NULL;

    // Allocate the memory pool
    void *mem_pool = malloc(MEM_POOL_SIZE);
    if (!mem_pool) {
        return -1; // Error handling for memory allocation failure
    }

    // Create and populate the linked list
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = mem_pool + sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i % MEM_POOL_SIZE);
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 1000;
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        if (i == 0) {
            head = &pdu;
            tail = pdu;
        } else {
            tail->next = pdu;
            tail = pdu;
        }
    }

    // Process the linked list and log statistics
    int successful_crc_indications = 0;
    for (NFAPI_CRC_INDICATION_PDU_T *current = head; current != NULL; current = current->next) {
        if (current->CRCFLAG == 1) { // Check CRCFLAG for successful reception
            // Process the PDU structure (e.g., update network stack)
            printf("Processed PDU with RX_UE_INFORMATION_TAG %d and RNTI %d\n", current->RX_UE_INFORMATION_TAG, current->RNTI);
            successful_crc_indications++;
        } else {
            // Log failed CRC indication
            fprintf(log_file, "Failed CRC indication: RX_UE_INFORMATION_TAG %d, RNTI %d\n", current->RX_UE_INFORMATION_TAG, current->RNTI);
        }
    }

    // Log processing statistics
    fprintf(log_file, "Total PDUs processed: %d\n", n);
    fprintf(log_file, "Successful CRC indications: %d\n", successful_crc_indications);

    return 0;
}

int main() {
    FILE *log_file = fopen("crc_indication_log.txt", "w");
    if (!log_file) {
        return -1; // Error handling for file opening failure
    }

    int n = 100; // Number of PDUs to process in a batch
    create_crc_indication_pdu_list(n, log_file);

    fclose(log_file);
    return 0;
}

