typedef struct {
    int id;
} Record;

Record* allocateRecords(int count) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    return records;
}

void initRecords(Record* records, int count, int uniqueAcrossAll) {
    for (int i = 0; i < count; i++) {
        if (uniqueAcrossAll) {
            records[i].id = i;
        } else {
            int value;
            do {
                value = rand() % 10000;
            } while (value == records[(i-1) % count].id);
            records[i].id = value;
        }
    }
}

int persistRecords(Record* records, int count) {
    int fd = open("records.txt", O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return -1;
    }

    for (int i = 0; i < count; i++) {
        char buffer[1024];
        sprintf(buffer, "%d\n", records[i].id);
        write(fd, buffer, strlen(buffer));
    }
    close(fd);

    return 0;
}

void logRecordPersistence(int count) {
    time_t now = time(NULL);
    printf("Records persisted at %s\n", ctime(&now));
}

int main() {
    int count = 1000000; // adjust this value for desired record count
    int uniqueAcrossAll = 1; // set to 1 for unique across all, or 0 for non-consecutive

    Record* records = allocateRecords(count);
    initRecords(records, count, uniqueAcrossAll);

    if (persistRecords(records, count) < 0) {
        printf("Error persisting records\n");
    }

    logRecordPersistence(count);

    free(records); // don't forget to deallocate memory!

    return 0;
}
