#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int id;
    int status;
} EventLogEntry;

typedef struct {
    size_t capacity;
    size_t size;
    EventLogEntry** entries;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->capacity = initialCapacity;
    arr->size = 0;
    arr->entries = (EventLogEntry**)malloc(arr->capacity * sizeof(EventLogEntry*));
    return arr;
}

void freeDynamicArray(DynamicArray* arr) {
    for (size_t i = 0; i < arr->size; i++) {
        free(arr->entries[i]);
    }
    free(arr->entries);
    free(arr);
}

EventLogEntry* appendEventLogEntry(DynamicArray* arr, time_t timestamp, int id, int status) {
    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        arr->entries = (EventLogEntry**)realloc(arr->entries, arr->capacity * sizeof(EventLogEntry*));
    }
    EventLogEntry* entry = (EventLogEntry*)malloc(sizeof(EventLogEntry));
    entry->timestamp = timestamp;
    entry->id = id;
    entry->status = status;
    arr->entries[arr->size] = entry;
    arr->size++;
