#include <stdlib.h>
#include <pthread.h>

// Define the NR_RRC_Transaction structure
typedef struct {
    uint32_t MAC_TransportChannelID;
    uint16_t RRC_ConnectionID;
    uint64_t RRC_UE_Identity;
} NR_RRC_Transaction;

// Define the dynamic array of NR_RRC_Transactions
typedef struct {
    NR_RRC_Transaction* transactions;
    size_t capacity;
    pthread_mutex_t mutex; // For concurrency control
    pthread_cond_t cond; // For condition variable
} RRC_Transaction_Array;

// Initialize and manage a dynamic array of NR_RRC_Transactions
RRC_Transaction_Array* rrc_transaction_array_init(size_t initial_capacity) {
    RRC_Transaction_Array* arr = (RRC_Transaction_Array*)malloc(sizeof(RRC_Transaction_Array));
    if (!arr) return NULL; // Handle memory allocation error

    arr->transactions = (NR_RRC_Transaction*)calloc(initial_capacity, sizeof(NR_RRC_Transaction));
    if (!arr->transactions) {
        free(arr);
        return NULL; // Handle memory allocation error
    }

    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->mutex, NULL); // Initialize mutex for concurrency control
    pthread_cond_init(&arr->cond, NULL); // Initialize condition variable

    return arr;
}

// Add a new NR_RRC_Transaction to the array
int rrc_transaction_array_add(RRC_Transaction_Array* arr, NR_RRC_Transaction transaction) {
    size_t i;
    for (i = 0; i < arr->capacity; i++) {
        if (!arr->transactions[i].MAC_TransportChannelID) { // Find empty slot
            break;
        }
    }

    if (i == arr->capacity) { // Array full, need to grow capacity
        size_t new_capacity = arr->capacity * 2 + 1; // Double the current capacity with a minimum of 2 elements
        NR_RRC_Transaction* new_transactions = (NR_RRC_Transaction*)realloc(arr->transactions, new_capacity * sizeof(NR_RRC_Transaction));
        if (!new_transactions) return -ENOMEM; // Handle memory allocation error

        arr->transactions = new_transactions;
        arr->capacity = new_capacity;

        i = 0; // Restart search from the beginning
    }

    arr->transactions[i] = transaction;
    return 0;
}

// Remove an NR_RRC_Transaction by identifier from the array
int rrc_transaction_array_remove_by_id(RRC_Transaction_Array* arr, uint32_t MAC_TransportChannelID) {
    size_t i;
    for (i = 0; i < arr->capacity; i++) {
        if (arr->transactions[i].MAC_TransportChannelID == MAC_TransportChannelID) { // Find the desired transaction
            break;
        }
    }

    if (i == arr->capacity) return -ENOENT; // Not found

    memmove(&arr->transactions[i], &arr->transactions[i + 1], sizeof(NR_RRC_Transaction) * (arr->capacity - i - 1));
    arr->capacity--;

    return 0;
}

// Iterate over all NR_RRC_Transactions in the array and perform an operation
int rrc_transaction_array_for_each(RRC_Transaction_Array* arr, void (*operation)(NR_RRC_Transaction*)) {
    size_t i;
    for (i = 0; i < arr->capacity; i++) {
        pthread_mutex_lock(&arr->mutex);
        operation(arr->transactions[i]);
        pthread_mutex_unlock(&arr->mutex); // Release the mutex before continuing
    }

    return 0;
}

// Clean up and free resources when done with the array
void rrc_transaction_array_free(RRC_Transaction_Array* arr) {
    if (arr) {
        free(arr->transactions);
        pthread_mutex_destroy(&arr->mutex);
        pthread_cond_destroy(&arr->cond);
        free(arr);
    }
}
