#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MEMORY_POOL_SIZE 1024
#define MESSAGE_BUFFER_SIZE 128

typedef struct {
    uint8_t phich_config;
    uint16_t ue_id;
} lte_phy_layer_control_message;

struct memory_pool {
    void **blocks;
    int size;
};

void *malloc_from_memory_pool(struct memory_pool *pool, size_t size) {
    if (size > MEMORY_POOL_SIZE) {
        printf("Error: Memory pool exhausted\n");
        return NULL;
    }
    for (int i = 0; i < pool->size; i++) {
        if ((pool->blocks[i] - (void *)1) == size) {
            void *ptr = pool->blocks[i];
            pool->blocks[i] = NULL;
            return ptr;
        }
    }
    printf("Error: Memory block not found\n");
    return NULL;
}

int free_memory_block(struct memory_pool *pool, void *block) {
    for (int i = 0; i < pool->size; i++) {
        if ((void *)1 + i == block) {
            pool->blocks[i] = NULL;
            return 1;
        }
    }
    printf("Error: Memory block not found\n");
    return 0;
}

struct memory_pool initialize_memory_pool() {
    struct memory_pool pool;
    pool.size = MEMORY_POOL_SIZE / MESSAGE_BUFFER_SIZE;
    pool.blocks = (void **)malloc(pool.size * sizeof(void *));
    for (int i = 0; i < pool.size; i++) {
        pool.blocks[i] = malloc(MESSAGE_BUFFER_SIZE);
    }
    return pool;
}

lte_phy_layer_control_message* create_lte_phy_layer_control_message(struct memory_pool *pool, uint8_t phich_config, uint16_t ue_id) {
    void *block = malloc_from_memory_pool(pool, MESSAGE_BUFFER_SIZE);
    lte_phy_layer_control_message* message = block;
    message->phich_config = phich_config;
    message->ue_id = ue_id;
    return message;
}

void destroy_lte_phy_layer_control_message(struct memory_pool *pool, lte_phy_layer_control_message* message) {
    free_memory_block(pool, message);
    free(message);
}
