#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    char* key;
    void* value;
} config_t;

typedef struct node {
    config_t config;
    struct node* child;
    struct node* sibling;
} node_t;

node_t* init_config(const char* path) {
    // Initialize the root node
    node_t* root = (node_t*)malloc(sizeof(node_t));
    if (!root) return NULL;

    root->child = NULL;
    root->sibling = NULL;

    // Load the configuration file
    FILE* file = fopen(path, "r");
    if (!file) {
        free(root);
        return NULL;
    }

    // Read the configuration hierarchy levels
    node_t* current = root;
    while (fscanf(file, "%[^:]: %s\n", &current->config.key, &current->config.value) == 2) {
        char temp[256];
        if (fgets(temp, sizeof(temp), file)) {
            // Parse the child configuration
            node_t* child = init_config(temp);
            current->child = child;
            current = child;
        } else {
            break;
        }
    }

    fclose(file);

    return root;
}

void print_config(node_t* node) {
    if (!node) return;

    printf("%s: %s\n", node->config.key, node->config.value);
    if (node->child) {
        // Recursively print the child configurations
        print_config(node->child);
    }
}

int main() {
    node_t* root = init_config("path/to/config/file");
    if (!root) {
        printf("Error initializing configuration parser\n");
        return 1;
    }

    print_config(root);

    return 0;
}
