void lte_phy_rx_array_reset(void* arr) {
    LTE_PHY_RX_T** array = (LTE_PHY_RX_T**)arr;
    pthread_mutex_lock(&mutex);

    // Release memory for each element in the array
    for (int i = 0; i < num_elements; i++) {
        if (array[i]->data != NULL) {
            free(array[i]->data);
            free(array[i]);
        }
    }

    // Free the array itself
