// Function to initialize and populate the dynamic array of NetworkEventLogEntry structures
NetworkEventLogEntry* initializeNetworkEventLog(int capacity) {
    NetworkEventLogEntry* log = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry) * capacity);
    for (int i = 0; i < capacity; i++) {
        log[i].timestamp = compressTimestamp(time(NULL));
        log[i].eventID = i;
        log[i].cellIDs = NULL;
    }
    return log;
}

// Function to add a new cell ID to the associated cell IDs of an existing NetworkEventLogEntry
void addCellID(NetworkEventLogEntry* entry, int cellID) {
    CellID* newCellID = (CellID*)malloc(sizeof(CellID));
    newCellID->id = cellID;
    if (!entry->cellIDs) {
        entry->cellIDs = newCellID;
    } else {
        newCellID->prev = entry->cellIDs;
        newCellID->next = NULL;
        if (entry->cellIDs->prev) {
            entry->cellIDs->prev->next = newCellID;
        }
        entry->cellIDs = newCellID;
    }
}

// Function to remove a cell ID from the associated cell IDs of an existing NetworkEventLogEntry
void removeCellID(NetworkEventLogEntry* entry, int cellID) {
    CellID* current = entry->cellIDs;
    while (current && current->id != cellID) {
        current = current->next;
    }
    if (current) {
        if (!current->prev) {
            entry->cellIDs = current->next;
        } else {
            current->prev->next = current->next;
        }
        free(current);
    }
}

