#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void process_data(int N, FILE* file) {
    // Dynamic memory allocation for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    // Generation of the list
    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = (uint8_t)i;
        pdu_list[i].RNTI = (uint16_t)(i << 1);
        pdu_list[i].CRC_INDICATION_REL8_TAG = (uint16_t)(i % 256);
        pdu_list[i].CRCFLAG = (bool)rand() % 2;
    }

    // Pool of pre-allocated resources
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static NFAPI_CRC_INDICATION_PDU_T* pool[1024];
    int available_slots = 0, allocated_slots = 0;

    void* allocate() {
        pthread_mutex_lock(&lock);
        if (available_slots > 0) {
            void* temp = pool[--available_slots];
            pool[allocated_slots++] = NULL;
            pthread_mutex_unlock(&lock);
            return temp;
        }

        void* new_block = malloc(1024 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_block) {
            printf("Error: Memory allocation failed.\n");
            return NULL;
        }

        for (int i = 0; i < 1024; i++) {
            pool[i] = &((NFAPI_CRC_INDICATION_PDU_T*)new_block)[i];
        }

        available_slots = 1023, allocated_slots = 1;
        pthread_mutex_unlock(&lock);
        return new_block;
    }

    void deallocate(void* ptr) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < allocated_slots; i++) {
            if (&((NFAPI_CRC_INDICATION_PDU_T*)ptr)[i] == pool[i]) {
                pool[i] = pool[--allocated_slots];
                break;
            }
        }

        free(ptr);
        pthread_mutex_unlock(&lock);
    }

    // Pool usage
    NFAPI_CRC_INDICATION_PDU_T* temp = allocate();
    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = ((NFAPI_CRC_INDICATION_PDU_T*)temp)[i].RX_UE_INFORMATION_TAG;
        pdu_list[i].RNTI = ((NFAPI_CRC_INDICATION_PDU_T*)temp)[i].RNTI;
        pdu_list[i].CRC_INDICATION_REL8_TAG = ((NFAPI_CRC_INDICATION_PDU_T*)temp)[i].CRC_INDICATION_REL8_TAG;
        pdu_list[i].CRCFLAG = ((NFAPI_CRC_INDICATION_PDU_T*)temp)[i].CRCFLAG;
    }

    deallocate(temp);

    // Reading integers from the file into an array
    int* data = (int*)malloc(sizeof(int));
    if (!data) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    int max_int = 0, current_int = fgetc(file);

    while (current_int != EOF) {
        if (*data == 0 && current_int == '\r' || *data > max_int) {
            max_int = current_int;
        }

        data++;
        *data++ = current_int;
        current_int = fgetc(file);
    }

    // Validation of the generated list and accuracy of the largest integer found
    int total_checksum = 0;
    for (int i = 0; i < N; i++) {
        total_checksum += pdu_list[i].RX_UE_INFORMATION_TAG + pdu_list[i].RNTI + pdu_list[i].CRC_INDICATION_REL8_TAG;
    }

    if (total_checksum != checksum(pdu_list, N)) {
        printf("Error: Integrity of the generated list failed.\n");
        return;
    }

    // Logging
    fprintf(stderr, "Process completed successfully.\n");
}
