NFAPI_CRC_INDICATION_PDU_LIST* nfapi_crc_indication_pdu_list_create(size_t m) {
    NFAPI_CRC_INDICATION_PDU_LIST* list = (NFAPI_CRC_INDICATION_PDU_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    if (!list) return NULL;
    list->capacity = m * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list->count = 0;
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(m, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }
    return list;
}

void nfapi_crc_indication_pdu_list_destroy(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    if (list) {
        free(list->list);
        free(list);
    }
}

int nfapi_crc_indication_pdu_list_add(NFAPI_CRC_INDATION_PDU_T new_pdu, NFAPI_CRC_INDICATION_PDU_LIST* list) {
    if (!list) return -1;
    if (list->count >= list->capacity) {
        // Dynamic resizing
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity);
        if (!new_list) return -1;
        list->capacity = new_capacity;
        list->list = new_list;
    }
    for (size_t i = 0; i < list->count; i++) {
        if (memcmp(&list->list[i].rnti, &new_pdu.rnti, sizeof(RNTI)) == 0) {
            // Duplicate RNTI detected
            return -2;
        }
    }
    memmove(&list->list[list->count], &list->list[list->count-1], 1 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->list[list->count++] = new_pdu;
    return 0;
}

void nfapi_crc_indication_pdu_list_remove(RNTI rnti, NFAPI_CRC_INDICATION_PDU_LIST* list) {
    if (!list || list->count == 0) return;
    for (size_t i = 0; i < list->count; i++) {
        if (memcmp(&list->list[i].rnti, &rnti, sizeof(RNTI)) == 0) {
            memmove(&list->list[i], &list->list[i+1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
            return;
        }
    }
}
