    if (numUsers < 0 || numUsers > max_users) {
        fprintf(stderr, "Invalid number of users: %d\n", numUsers);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(numUsers * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < numUsers; i++) {
        pdu_list[i].sequenceNumber = i + 1;
        strcpy(pdu_list[i].rx_ue_info_tag, "Valid RX UE Info Tag");
        pdu_list[i].rnti = rand() % UINT_MAX;
        pdu_list[i].crc_indication_rel8_tag.crcFlag = (uint8_t)rand() & 0xFF;
    }

    return pdu_list;
}

int serialize_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int numUsers, FILE* file) {
    if (!pdu_list || numUsers < 1) {
        return -1; // invalid input
    }

    for (int i = 0; i < numUsers; i++) {
        fwrite(&pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    return 0;
}

