    int max_users = 100;
    int num_users = 50;

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_crc_indication_pdu(num_users, max_users);

    if (!pdu_list) {
        return -1; // error creating PDU list
    }

    FILE* file = fopen("crc_indication_pdu.bin", "wb");
    if (!file) {
        perror("Failed to open output file");
        free(pdu_list);
        return -1;
    }

    int result = serialize_crc_indication_pdu(pdu_list, num_users, file);

    if (result != 0) {
        fclose(file);
        free(pdu_list);
        return -1; // serialization failed
    }

    fclose(file);
    free(pdu_list);

    return 0;
}
