#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure type NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic hash table implementation using a base array
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* records;
    int capacity;
    int size;
} hash_table_t;

// Initialize the hash table with a specified initial capacity and resize strategy
hash_table_t* initialize_hash_table(int initial_capacity, float load_factor) {
    hash_table_t* hash_table = (hash_table_t*)malloc(sizeof(hash_table_t));
    hash_table->records = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    hash_table->capacity = initial_capacity;
    hash_table->size = 0;

    return hash_table;
}

// Insert a new record into the hash table
void insert_record(hash_table_t* hash_table, int RNTI, NFAPI_CRC_INDICATION_PDU_T* record) {
    // Calculate the index using the RNTI value as the key
    int index = RNTI % hash_table->capacity;

    // Find the first empty slot in the chain starting from the calculated index
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->records[index].RNTI == -1) {
            memcpy(&hash_table->records[index], record, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            hash_table->size++;
            return;
        }
        index = (index + 1) % hash_table->capacity;
    }

    // Resize the hash table if load factor exceeds the specified threshold
    float load_factor = (float)hash_table->size / hash_table->capacity;
    if (load_factor > 0.85) {
        int new_capacity = hash_table->capacity * 2;
        hash_table->records = realloc(hash_table->records, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        hash_table->capacity = new_capacity;
    }
}

// Lookup a record in the hash table by RNTI value
NFAPI_CRC_INDICATION_PDU_T* lookup_record(hash_table_t* hash_table, int RNTI) {
    int index = RNTI % hash_table->capacity;

    // Find the matching record in the chain starting from the calculated index
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->records[index].RNTI == RNTI) {
            return &hash_table->records[index];
        }
        index = (index + 1) % hash_table->capacity;
    }

    // Return NULL if the record is not found
    return NULL;
}

// Delete a record from the hash table by RNTI value
void delete_record(hash_table_t* hash_table, int RNTI) {
    int index = RNTI % hash_table->capacity;

    // Find the matching record in the chain starting from the calculated index
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->records[index].RNTI == RNTI) {
            memset(&hash_table->records[index], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            hash_table->size--;
            return;
        }
        index = (index + 1) % hash_table->capacity;
    }
}

// Free all allocated memory upon function exit
void finalize_hash_table(hash_table_t* hash_table) {
    if (hash_table != NULL) {
        free(hash_table->records);
        free(hash_table);
    }
}
