#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_PACKET_SIZE 1024
#define MAX_PAYLOAD_SIZE 2048

typedef struct {
    int packet_id;
    char payload[MAX_PAYLOAD_SIZE];
    time_t timestamp;
} DataPacket;

void handle_packet(int sock, struct sockaddr_in* addr, char buffer[], size_t len) {
    // Parse the incoming data
    DataPacket packet;
    memcpy(&packet, buffer, sizeof(packet));

    // Process the packet (e.g., extract relevant information)
    printf("Received packet %d with payload '%s' at timestamp %ld\n", packet.packet_id, packet.payload, packet.timestamp);

    // Store the packet in a dynamically growing list
    // For simplicity, use a static array for now
    static DataPacket packets[10];
    static int packet_count = 0;

    if (packet_count < sizeof(packets) / sizeof(*packets)) {
        memcpy(&packets[packet_count], &packet, sizeof(packet));
        packet_count++;
    } else {
        // Handle overflow or fragmentation
        printf("Packet buffer full; cannot store further packets\n");
    }
}

int main() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    int bind_status = bind(sock, (struct sockaddr*) &addr, sizeof(addr));
    if (bind_status < 0) {
        perror("binding failed");
        return -1;
    }

    while (1) {
        char buffer[MAX_PACKET_SIZE];
        size_t len = recvfrom(sock, buffer, MAX_PACKET_SIZE, 0, NULL, 0);

        if (len < 0) {
            perror("recvfrom failed");
            continue;
        }

        handle_packet(sock, &addr, buffer, len);
    }

    close(sock);
    return 0;
}

