void generateCrcIndications(int N, NFAPI_CRC_INDICATION_PDU_T* indications) {
    // Initialize random number generator
    srand(time(NULL));

    // Generate and fill the indication structures
    for (int i = 0; i < N; i++) {
        indications[i].RX_UE_INFORMATION_TAG = rand() % 100;
        int rnti;
        do {
            rnti = rand() % 10000;
