        indications[i].RNTI = rnti;
        sprintf(indications[i].CRC_INDICATION_REL8_TAG, "CRCFLAG_%d", rand() % 2);
    }
}

void findLargestInteger(int* array, int size) {
    int max = array[0];

    for (int i = 1; i < size; i++) {
        if (array[i] > max)
            max = array[i];
    }

    printf("The largest integer is: %d\n", max);
}

