    srand(time(NULL));

    // Initialize the list
    NFAPI_CRC_INDICATION_PDU_T* records = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for(int i = 0; i < num_records; i++) {
        records[i].RX_UE_INFORMATION_TAG = rand() % 100;
        records[i].RNTI = rand() % 256;
        records[i].CRC_INDICATION_REL8_TAG = rand() % 1024;
        records[i].CRCFLAG = rand() & 1;
    }

    // Initialize the offset array
    long* offsets_array = (long*)malloc((num_records + 1) * sizeof(long));
    for(int i = 0; i <= num_records; i++) {
        offsets_array[i] = i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Initialize the key array
    int* keys_array = (int*)malloc(num_records * sizeof(int));
    for(int i = 0; i < num_records; i++) {
        keys_array[i] = i;
    }

    // Store each record in the database
    for(int i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, db_file);
    }

