NFAPI_MESSAGE_T** init_and_populate_nfaapi_messages(int num_elements, uint32_t seed, int logging_level) {
    NFAPI_MESSAGE_T** messages = NULL;
    int i;

    // Calculate the total number of bytes required for the array
    size_t total_bytes = sizeof(NFAPI_MESSAGE_T*) * num_elements + sizeof(RX_UE_INFORMATION_TAG) * num_elements + sizeof(CRC_INDICATION_REL8_TAG*) * num_elements;

    if ((messages = (NFAPI_MESSAGE_T**)malloc(total_bytes)) == NULL) {
        return NULL;
    }

    // Initialize the array with null pointers
    for (i = 0; i < num_elements; i++) {
        messages[i] = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));

        if (messages[i] == NULL) {
            free(messages);
            return NULL;
        }

        // Initialize the RX_UE_INFORMATION_TAG
        messages[i]->rx_ue_info.tag = RX_UE_INFORMATION_TAG;

        // Generate a random RNTI value based on the seed
        messages[i]->rnti = (uint16_t)(seed ^ (seed >> 15));

        // Dynamically allocate and initialize the CRC_INDICATION_REL8_TAG structure
        messages[i]->crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));

        if (messages[i]->crc_indication_rel8_tag == NULL) {
            free(messages[i]);
            free(messages);
            return NULL;
        }

        // Initialize the CRCFLAG value
        messages[i]->crc_indication_rel8_tag->crcflag = 0;

        logging_level > 0 ? LOG_DEBUG("Initialized NFAPI message %d", i) : 0;
    }

    return messages;
}
