typedef struct {
    long timestamp;
    int key;
    int value;
    char id[20];
    bool processed;
} record_t;

void manage_memory(int num_timestamps, int num_keys, int num_records) {
    // Allocate memory for timestamp array
    long* timestamps = (long*)malloc(num_timestamps * sizeof(long));
    if (!timestamps) {
        printf("Error allocating memory for timestamps\n");
        return;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Error allocating memory for keys\n");
        free(timestamps);
        return;
    }

    // Allocate memory for record array
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Error allocating memory for records\n");
        free(timestamps);
        free(keys);
        return;
    }

    srand(time(NULL));  // Initialize random seed

    // Populate timestamp array
    for (int i = 0; i < num_timestamps; i++) {
        timestamps[i] = rand() % 10000000L;  // Random long value within specified range
    }

    // Populate key array
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 100;  // Random int value within specified range
    }

    // Populate record array with random events
    for (int i = 0; i < num_records; i++) {
        records[i].timestamp = timestamps[rand() % num_timestamps];
        records[i].key = keys[rand() % num_keys];
        records[i].value = rand() % 100;  // Random int value within specified range
        sprintf(records[i].id, "Event-%d", i);
        records[i].processed = false;
    }

    printf("Memory usage: %ld bytes (timestamps), %ld bytes (keys), and %ld bytes (records)\n",
           num_timestamps * sizeof(long), num_keys * sizeof(int), num_records * sizeof(record_t));

    // Free allocated memory
    free(timestamps);
    free(keys);
    free(records);
}

int main() {
    int num_timestamps = 10000;
    int num_keys = 1000;
    int num_records = 50000;

    manage_memory(num_timestamps, num_keys, num_records);

    return 0;
}
