#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int val;
    char* buffer;
} record_t;

// Define a record management structure
typedef struct {
    long* offsets; // Array of offsets (long)
    int* keys;      // Array of key values (int)
    record_t** records; // Array of record structures (record_t*)
    int record_count; // Number of allocated records
    size_t total_record_size; // Total buffer size for all records
} record_manager_t;

// Function to initialize the record manager
record_manager_t* init_record_manager(size_t total_record_size) {
    record_manager_t* manager = malloc(sizeof(record_manager_t));

    manager->offsets = malloc(total_record_size * sizeof(long));
    manager->keys = malloc(total_record_size * sizeof(int));
    manager->records = malloc(total_record_size * sizeof(record_t*));
    manager->record_count = 0;
    manager->total_record_size = total_record_size;

    return manager;
}

// Function to allocate a new record
int add_record(record_manager_t* manager, int key) {
    if (manager->record_count >= manager->total_record_size) {
        // Need to compact the records first before adding more
        compact_records(manager);
    }

    // Allocate memory for the new record
    record_t* record = malloc(sizeof(record_t));
    record->val = 0;
    record->buffer = malloc(100); // configurable buffer size

    manager->keys[manager->record_count] = key;
    manager->offsets[manager->record_count] = (long)record - (long)manager->records[0];
    manager->records[manager->record_count++] = record;

    return 1; // success
}

// Function to retrieve a specific record by its index
record_t* get_record(record_manager_t* manager, int idx) {
    if (idx >= manager->record_count)
        return NULL; // out of bounds

    return manager->records[idx];
}

// Function to query the number of active records
int get_record_count(record_manager_t* manager) {
    return manager->record_count;
}

// Compaction mechanism: periodically reclaim unused memory and optimize performance
void compact_records(record_manager_t* manager) {
    int i, j = 0;

    for (i = 0; i < manager->record_count; i++) {
        if (manager->records[i] != NULL && strlen(manager->records[i]->buffer) > 0) {
            // Record is in use, move it to the front
            manager->keys[j] = manager->keys[i];
            manager->offsets[j] = manager->offsets[i];
            manager->records[j++] = manager->records[i];
        }
    }

    // Shrink arrays based on the new count
    manager->offsets = realloc(manager->offsets, j * sizeof(long));
    manager->keys = realloc(manager->keys, j * sizeof(int));
    manager->records = realloc(manager->records, j * sizeof(record_t*));

    manager->record_count = j;
}

// Example usage:
int main() {
    record_manager_t* manager = init_record_manager(10);

    add_record(manager, 1); // allocate a new record with key 1
    add_record(manager, 2); // allocate another record with key 2

    printf("Number of active records: %d\n", get_record_count(manager));

    record_t* record = get_record(manager, 0);
    if (record != NULL) {
        printf("Record buffer: %s\n", record->buffer);
    }

    return 0;
}

