#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PACKETS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int packet_id;
    char payload[BUFFER_SIZE];
    time_t timestamp;
} DataPacket;

DataPacket* packets = NULL;
int num_packets = 0;
sem_t lock; // Mutex for concurrent access

void process_packet(DataPacket* packet) {
    // Process the packet
    printf("Processing packet %d\n", packet->packet_id);
}

void* receive_and_process_data(void* arg) {
    int client_socket = *(int*)arg;
    free(arg);

    while (1) {
        DataPacket packet;
        memset(&packet, 0, sizeof(packet));

        // Read data from network socket
        int bytes_read = read(client_socket, &packet, sizeof(packet));
        if (bytes_read < 0) {
            // Handle read error
            perror("Error reading from socket");
            continue;
        }

        // Ensure packet is fully received
        while (bytes_read < sizeof(packet)) {
            int remaining_bytes = sizeof(packet) - bytes_read;
            int new_bytes = read(client_socket, &(packet.payload[bytes_read]), remaining_bytes);
            if (new_bytes < 0) {
                // Handle read error
                perror("Error reading from socket");
                continue;
            }
            bytes_read += new_bytes;
        }

        // Process the packet
        process_packet(&packet);

        // Update statistics
        printf("Packet received: ID=%d, Timestamp=%lu\n", packet.packet_id, (unsigned long)packet.timestamp);
    }
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);

    bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address));
    listen(server_socket, 3);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int* client_socket_ptr = malloc(sizeof(int));
        *client_socket_ptr = accept(server_socket, NULL, NULL);
        pthread_create(&threads[i], NULL, receive_and_process_data, client_socket_ptr);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    close(server_socket);

    return 0;
}
