#define MAX_PACKET_SIZE 1024
#define MAX_CONCURRENT_CONNECTIONS 10
#define RETRY_COUNT 3
#define LOG_LEVEL 1 // 0: error, 1: warning, 2: info, 3: debug

typedef struct {
    int packet_id;
    void *payload;
    size_t payload_len;
    time_t timestamp;
} DataPacket;

DataPacket **packet_list = NULL;
pthread_mutex_t packet_list_lock = PTHREAD_MUTEX_INITIALIZER;
int packet_list_size = 0;

void add_packet(int packet_id, void *payload, size_t payload_len) {
    pthread_mutex_lock(&packet_list_lock);

    if (packet_list == NULL || packet_list_size >= MAX_CONCURRENT_CONNECTIONS) {
        int new_size = packet_list_size + (packet_list_size / 2 + 1);
        packet_list = realloc(packet_list, sizeof(DataPacket *) * new_size);
        for (int i = packet_list_size; i < new_size; i++) {
            packet_list[i] = NULL;
        }
    }

    DataPacket *new_packet = malloc(sizeof(DataPacket));
    new_packet->packet_id = packet_id;
    new_packet->payload = payload;
    new_packet->payload_len = payload_len;
    time(&new_packet->timestamp);
    packet_list[packet_list_size++] = new_packet;

    pthread_mutex_unlock(&packet_list_lock);
}

void remove_packet(int packet_id) {
    pthread_mutex_lock(&packet_list_lock);

    for (int i = 0; i < packet_list_size; i++) {
        if (packet_list[i]->packet_id == packet_id) {
            free(packet_list[i]);
            memmove(&packet_list[i], &packet_list[i+1], sizeof(DataPacket *) * (packet_list_size - i));
            packet_list_size--;
            break;
        }
    }

    pthread_mutex_unlock(&packet_list_lock);
}

DataPacket *get_packet(int packet_id) {
    pthread_mutex_lock(&packet_list_lock);

    for (int i = 0; i < packet_list_size; i++) {
        if (packet_list[i]->packet_id == packet_id) {
            return packet_list[i];
        }
    }

    pthread_mutex_unlock(&packet_list_lock);
    return NULL;
}

void *handle_packet(int socket, void *payload, size_t payload_len) {
    // Implement network I/O operations and data processing here
}

