        strcpy(records[i].metadata, metadata[rand() % METADATA_ENTRIES]);
    }

    return records;
}

void freeRecords(Record* records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].metadata);
    }
    free(records);
}

void checkInit(int count, Record* records) {
    for (int i = 0; i < count; i++) {
        if (!records[i].metadata) {
            printf("Error: record %d not initialized\n", i);
            return;
        }
    }
    printf("All records initialized successfully\n");
}

