    Record* records = initRecords(MAX_RECORDS, metadata);
    if (!records) {
        printf("Error: out of memory\n");
    } else {
        checkInit(MAX_RECORDS, records);
        freeRecords(records, MAX_RECORDS);
    }
    return 0;
}
