```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <libpq-fe.h>

#define MAX_RECORDS 10000000
#define RANDOM_VALUE_RANGE 1000

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    int crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void initializeDataHandlingEnvironment(int num_records, int random_value_uniqueness) {
    srand(time(NULL));

    // Initialize dynamic dataset from external API
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        fprintf(stderr, "Memory allocation failed for data\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed for offsets and keys\n");
        exit(EXIT_FAILURE);
    }

    // Initialize random values
    for (int i = 0; i < num_records; i++) {
        data[i].rx_ue_info_tag = rand() % RANDOM_VALUE_RANGE;
        if (random_value_uniqueness) {
            while (1) {
                int value = rand() % RANDOM_VALUE_RANGE;
                int found = 0;
                for (int j = 0; j < i; j++) {
                    if (value == data[j].rx_ue_info_tag) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    data[i].rx_ue_info_tag = value;
                    break;
                }
            }
        }
    }

    // Persist each record in a file-based database
    PGconn *conn = PQconnectdb("host=localhost port=5432 dbname=mydatabase user=myuser password=mypassword");
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to PostgreSQL failed\n");
        exit(EXIT_FAILURE);
    }

    // Create a metrics system using Prometheus client library
    PGresult *res = PQexec(conn, "CREATE TABLE IF NOT EXISTS records (id SERIAL PRIMARY KEY, rx_ue_info_tag INT, rnti INT, crc_ind_rel8_tag INT)");
    if (PQresultStatus(res) != PGRES_OK) {
        fprintf(stderr, "Failed to create table in PostgreSQL\n");
        exit(EXIT_FAILURE);
    }
    PQclear(res);

    for (int i = 0; i < num_records; i++) {
        res = PQexec(conn, "INSERT INTO records (rx_ue_info_tag, rnti, crc_ind_rel8_tag) VALUES ($1, $2, $3)", data[i].rx_ue_info_tag, data[i].rnti, data[i].crc_ind_rel8_tag);
        if (PQresultStatus(res) != PGRES_OK) {
            fprintf(stderr, "Failed to insert record into PostgreSQL\n");
            exit(EXIT_FAILURE);
        }
        PQclear(res);

        // Log the initialization and persistence of each record
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        printf("Record initialized and persisted at %s\n", timestamp);
    }

    // Release resources
    PQfinish(conn);

    // Free memory
    free(data);
    free(offsets);
    free(keys);
}
