        if (!head) {
            head = current = new_struct;
        } else {
            current->next = new_struct;
            current = new_struct;
        }
    }

    return head;
}

// Function to identify the largest valid RNTI within the structures and print it along with the corresponding CRC_INDICATION_REL8_TAG
void identify_largest_rnti(NFAPI_CRC_INDICATION_PDU_T* linked_list) {
    NFAPI_CRC_INDICATION_PDU_T* current = linked_list;
    int max_rnti = 0;

    // Traverse the linked list to find the largest valid RNTI
    while (current) {
        if (current->rnti > max_rnti) {
            max_rnti = current->rnti;
        }
        current = current->next;
    }

    printf("Largest valid RNTI: %d, CRC_INDICATION_REL8_TAG: %s\n", max_rnti, current->crc_indication_rel8);
}

int main() {
    int n = 100; // Number of structures in the input array

    // Construct the linked list
    NFAPI_CRC_INDICATION_PDU_T* linked_list = construct_linked_list(n);

    // Identify the largest valid RNTI within the structures and print it along with the corresponding CRC_INDICATION_REL8_TAG
    identify_largest_rnti(linked_list);

    return 0;
}
