#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define LTE_RNTI_RANGE 1
#define FIVE_G_RNTI_RANGE 1008
#define CRCFLAG_PROBABILITY 0.5

typedef struct {
    long offset;
    int key;
    int value;
} record_t;

record_t *memory_pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int total_records = 0;

void* add_record(void* arg) {
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    if (!new_record) {
        return NULL;
    }

    // Randomly set CRCFLAG
    if ((rand() / (RAND_MAX + 1.0)) < CRCFLAG_PROBABILITY) {
        new_record->key |= (1 << 31);
    }

    // Validate RNTI value against LTE or 5G range
    int rnti = rand() % (FIVE_G_RNTI_RANGE - LTE_RNTI_RANGE + 1) + LTE_RNTI_RANGE;
    if (rnti < LTE_RNTI_RANGE || rnti > FIVE_G_RNTI_RANGE) {
        free(new_record);
        return NULL;
    }

    // Randomly initialize value
    new_record->value = rand() % 100;

    // Add record to pool
    pthread_mutex_lock(&pool_lock);
    memory_pool[total_records++] = *new_record;
    pthread_mutex_unlock(&pool_lock);

    free(new_record);
    return NULL;
}

int main(int argc, char* argv[]) {
    int num_threads = atoi(argv[1]);
    int num_records_per_thread = atoi(argv[2]);

    // Initialize random seed
    srand(time(NULL));

    memory_pool = (record_t*)malloc(MAX_RECORDS * sizeof(record_t));
    if (!memory_pool) {
        return 1;
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, add_record, NULL);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log successful structure additions
    printf("Added %d records successfully.\n", total_records);

    free(memory_pool);
    return 0;
}
