NetworkEvent* initialize_and_populate_network_events(int N, int seed, int logging_level) {
    // Initialize the array
    NetworkEvent* events = (NetworkEvent*)malloc(N * sizeof(NetworkEvent));
    if (!events) return NULL;  // Handle allocation failure

    // Set random event type selection seed
    srand(seed);

    int unique_events = 0;
    for (int i = 0; i < N; i++) {
        EventType event_type = (EventType)(rand() % 3);
        events[i].Timestamp = time(NULL);
        events[i].EventType = event_type;

        // Populate event data based on event type
        switch (event_type) {
            case EVENT_TYPE_A:
                events[i].EventData.A.DataA1 = i;
                events[i].EventData.A.DataA2 = rand();
                break;
            case EVENT_TYPE_B:
                sprintf(events[i].EventData.B, "Event B %d", i);
                break;
            case EVENT_TYPE_C:
                for (int j = 0; j < 10; j++) {
                    events[i].EventData.C[j][0] = (float)i;
                    events[i].EventData.C[j][1] = (float)rand() / RAND_MAX;
                }
                break;
        }

        // Check for duplicate event
        int found_duplicate = 0;
        for (int k = 0; k < i; k++) {
            if (events[k].EventType == event_type && events[i].Timestamp == events[k].Timestamp) {
                found_duplicate = 1;
                break;
            }
        }

        if (!found_duplicate) unique_events++;
    }

    // Update logging level
    // ...

    return events;
}
