#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define message structure
typedef struct {
    time_t timestamp;
    char* id;
    int status;
} Message;

// Define message list node structure
typedef struct Node {
    Message msg;
    struct Node* next;
} Node;

// Define message list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} MessageList;

// Initialize a new message list
MessageList* message_list_init() {
    MessageList* ml = (MessageList*)malloc(sizeof(MessageList));
    ml->head = NULL;
    ml->tail = NULL;
    pthread_mutex_init(&ml->mutex, NULL);
    return ml;
}

// Add a new message to the list
void message_list_add(MessageList* ml, Message msg) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->msg = msg;
    node->next = NULL;

    if (ml->head == NULL) {
        ml->head = node;
        ml->tail = node;
    } else {
        ml->tail->next = node;
        ml->tail = node;
    }

    pthread_mutex_unlock(&ml->mutex);
}

// Remove a message from the list by ID
void message_list_remove(MessageList* ml, char* id) {
    Node* current = ml->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->msg.id, id) == 0) {
            if (previous == NULL) {
                ml->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (ml->tail == current) {
                ml->tail = previous;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Retrieve messages within a specified time range
void message_list_query(MessageList* ml, time_t start, time_t end) {
    Node* current = ml->head;

    while (current != NULL) {
        if (start <= current->msg.timestamp && current->msg.timestamp <= end) {
            printf("Timestamp: %ld, ID: %s, Status: %d\n", current->msg.timestamp, current->msg.id, current->msg.status);
        }
        current = current->next;
    }
}

// Clean up the message list
void message_list_free(MessageList* ml) {
    Node* current = ml->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&ml->mutex);
    free(ml);
}

int main() {
    // Initialize the message list
    MessageList* ml = message_list_init();

    // Add some messages to the list
    Message msg1 = {time(NULL), "msg1", 0};
    Message msg2 = {time(NULL) + 10, "msg2", 1};
    Message msg3 = {time(NULL) - 5, "msg3", 0};

    message_list_add(ml, msg1);
    message_list_add(ml, msg2);
    message_list_add(ml, msg3);

    // Remove a message from the list
    message_list_remove(ml, "msg2");

    // Query messages within a time range
    message_list_query(ml, time(NULL) - 10, time(NULL));

    // Clean up the message list
    message_list_free(ml);

    return 0;
}

