            cache_count++;
            return;
        }
    }
}

record_t* cache_evict() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (!cache[i]) continue;

        free(cache[i]);
        cache[i] = NULL;
        cache_count--;
        return cache[i];
    }

