            NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)pool + i;
            if ((void*)p > (void*)((char*)pool + remaining_size)) {
                free(result);
                result = NULL;
                break;
            }
        }
    }

    pthread_mutex_unlock(&pool_lock);

    return result;
}

