typedef struct UEContext {
    uint64_t ue_id;
    uint32_t num_active_sessions;
    char** active_sessions;
    void* session_data;
} UEContext;

// Dynamic array of UEContext structures
UEContext** ue_contexts = NULL;
size_t max_ue_contexts = 0;
size_t current_ue_contexts = 0;

// Lock for concurrent access to UEContext data
pthread_mutex_t ue_context_lock = PTHREAD_MUTEX_INITIALIZER;

void add_session_to_ue(uint64_t ue_id, uint32_t session_id) {
    pthread_mutex_lock(&ue_context_lock);
    // Find the UE context and add a new session
    for (size_t i = 0; i < current_ue_contexts; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            // Allocate memory for the new session
            char** new_active_sessions = (char**) realloc(ue_contexts[i]->active_sessions, sizeof(char*) * (ue_contexts[i]->num_active_sessions + 1));
            new_active_sessions[ue_contexts[i]->num_active_sessions] = malloc(strlen("session") + 1);
            strcpy(new_active_sessions[ue_contexts[i]->num_active_sessions], "session");
            ue_contexts[i]->active_sessions = new_active_sessions;
            ue_contexts[i]->num_active_sessions++;
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

void update_session_data(uint64_t ue_id, uint32_t session_id, void* data) {
    pthread_mutex_lock(&ue_context_lock);
    // Find the UE context and update the session data
    for (size_t i = 0; i < current_ue_contexts; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            for (uint32_t j = 0; j < ue_contexts[i]->num_active_sessions; j++) {
                if (!strcmp(ue_contexts[i]->active_sessions[j], "session")) {
                    // Update the session data
                    memcpy(ue_contexts[i]->session_data, data, sizeof(void*));
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

void get_session_data(uint64_t ue_id, uint32_t session_id, void** data) {
    pthread_mutex_lock(&ue_context_lock);
    // Find the UE context and retrieve the session data
    for (size_t i = 0; i < current_ue_contexts; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            for (uint32_t j = 0; j < ue_contexts[i]->num_active_sessions; j++) {
                if (!strcmp(ue_contexts[i]->active_sessions[j], "session")) {
                    *data = ue_contexts[i]->session_data;
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

int main() {
    // Initialize the UEContext array
    max_ue_contexts = 1000000;  // Max number of UEs (1 million)
    ue_contexts = malloc(max_ue_contexts * sizeof(UEContext*));
    for (size_t i = 0; i < max_ue_contexts; i++) {
        ue_contexts[i] = malloc(sizeof(UEContext));
        ue_contexts[i]->ue_id = 0;
        ue_contexts[i]->num_active_sessions = 0;
        ue_contexts[i]->active_sessions = NULL;
        ue_contexts[i]->session_data = NULL;
    }
    current_ue_contexts = 0;

    // Initialize the lock
    pthread_mutex_init(&ue_context_lock, NULL);

    return 0;
}
