        for (int j = 0; j < rand() % 100 + 1; j++) {
            string[j] = (char)(rand() % 26 + 'a');
        }
        string[rand() % 100 + 1] = '\0'; // Null-terminate the string
        (*records)[i]->string = string;
    }

    // Add cryptographic primitives to OpenSSL library
    EVP_add_cipher(NID_aes_128_cbc);
    EVP_add_digest(NID_md5);
    EVP_add_digest_alias(NID_sha1, NID_sha256);

    // Handle special case where input range for random values is zero
    if (rand() % 1000 == 0) {
        // Return error in such scenarios
        fprintf(stderr, "Error: Input range for random values is zero.\n");
        exit(1);
    }
}

