} record_t;

record_t* pool = NULL;
size_t capacity = 0;
size_t used = 0;
int table[TABLE_SIZE];

int get_unique_key() {
    int seed = time(NULL);
    for (int i = 0; i < TABLE_SIZE; i++) {
        int key = (seed * 1103515245 + 12345) % TABLE_SIZE;
        if (!table[key]) {
            return key;
        }
    }
    return -1;
}

record_t* allocate_record() {
    record_t* new_pool = realloc(pool, capacity + RECORD_SIZE);
    if (new_pool == NULL) {
        printf("Failed to allocate memory.\n");
        exit(1);
    }
    pool = new_pool;
    used += 1;
    return &pool[capacity++ - 1];
}

void insert_record(int key, int offset, int value) {
    record_t* new_record = allocate_record();
    if (table[key]) {
        printf("Duplicate key detected. Aborting insertion.\n");
        return;
    }
    table[key] = used;
    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;
}

void log_stats() {
    printf("Total records allocated: %zu\n", used);
    printf("Failed insertions due to duplicate keys: %d\n", count_duplicates());
}

int main() {
    // Initialize the pool and table
    allocate_record();

    // Perform record insertion operations
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = get_unique_key();
        if (key == -1) {
            printf("Failed to generate a unique key.\n");
            break;
        }
        insert_record(key, 42, i);
    }

    log_stats();

    return 0;
}
```']

