#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int tag, int rnti, int rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rel8_tag;
    srand(time(NULL)); // random seed
    pdu->CRCFLAG = rand() % 2; // 0 or 1
    return pdu;
}

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    return list;
}

void insert_at_tail(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->prev = list->tail;
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
}

void delete_at_tail(DoublyLinkedList* list) {
    Node* temp = list->tail;
    if (temp != NULL) {
        list->tail = temp->prev;
        free(temp);
    }
}

int random_range(int min, int max) {
    return rand() % ((max + 1) - min) + min;
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdu_batch(int num_pdus, DoublyLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < num_pdus; i++) {
        int tag = random_range(1, 100);
        int rnti = random_range(1, 100);
        int rel8_tag = random_range(1, 100);
        pdus[i] = create_pdu(tag, rnti, rel8_tag);
        insert_at_tail(list, pdus[i]);
    }
    free(pdus);
    return NULL;
}
