typedef struct {
    time_t timestamp;
    int id;
    int status;
} Message;

// Define a dynamic array of messages
typedef struct {
    Message* arr;
    int size;
    int capacity;
} DynamicArray;

// Function to initialize the dynamic array
DynamicArray* initDynamicArray(int initialCapacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->arr = (Message*)calloc(initialCapacity, sizeof(Message));
    da->size = 0;
    da->capacity = initialCapacity;
    return da;
}

// Function to add a new message to the dynamic array
void addMessage(DynamicArray* da, time_t timestamp, int id, int status) {
    if (da->size == da->capacity) {
        // Increase capacity and resize the array
        da->capacity *= 2;
        Message* newArr = (Message*)realloc(da->arr, sizeof(Message) * da->capacity);
        da->arr = newArr;
    }
    da->arr[da->size].timestamp = timestamp;
    da->arr[da->size].id = id;
    da->arr[da->size].status = status;
    da->size++;
}

// Function to remove a message by identifier
void removeMessage(DynamicArray* da, int id) {
    for (int i = 0; i < da->size; i++) {
        if (da->arr[i].id == id) {
            // Shift the remaining messages and update the size
            for (int j = i + 1; j < da->size; j++) {
                da->arr[j - 1] = da->arr[j];
            }
            da->size--;
            return;
        }
    }
}

// Function to retrieve messages within a specified time range
Message* retrieveMessages(DynamicArray* da, time_t start, time_t end) {
    Message* result = (Message*)malloc(sizeof(Message) * (da->size - 1));
    int j = 0;
    for (int i = 0; i < da->size; i++) {
        if (start <= da->arr[i].timestamp && da->arr[i].timestamp <= end) {
            result[j] = da->arr[i];
            j++;
        }
    }
    free(da->arr);
    da->arr = result;
    return result;
}

// Function to print the dynamic array
void printDynamicArray(DynamicArray* da) {
    for (int i = 0; i < da->size; i++) {
        printf("Timestamp: %ld, ID: %d, Status: %d\n", da->arr[i].timestamp, da->arr[i].id, da->arr[i].status);
    }
}

// Example usage
int main() {
    DynamicArray* da = initDynamicArray(10);

    addMessage(da, time(NULL), 1, 0);
    addMessage(da, time(NULL) + 1000, 2, 1);
    addMessage(da, time(NULL) + 2000, 3, 0);
    addMessage(da, time(NULL) + 3000, 4, 1);

    printDynamicArray(da);

    Message* result = retrieveMessages(da, time(NULL) - 1000, time(NULL) + 5000);
    printf("Retrieved messages:\n");
    for (int i = 0; i < da->size; i++) {
        printf("Timestamp: %ld, ID: %d, Status: %d\n", result[i].timestamp, result[i].id, result[i].status);
    }

    return 0;
}
