```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define message structure
typedef struct {
    time_t timestamp;
    int id;
    char status[10];
    size_t size;
    int priority;
} Message;

// Define a hash table for storing messages
typedef struct {
    int capacity;
    int size;
    Message **messages;
} MessageHash;

// Initialize the message hash table
MessageHash* init_message_hash(int capacity) {
    MessageHash* hash = (MessageHash*)malloc(sizeof(MessageHash));
    hash->capacity = capacity;
    hash->size = 0;
    hash->messages = (Message**)calloc(capacity, sizeof(Message*));
    return hash;
}

// Add a message to the hash table
void add_message(MessageHash* hash, Message* message) {
    int index = message->id % hash->capacity;
    if (hash->size >= hash->capacity / 2) {
        // Resize the hash table if it's getting full
        hash->messages = (Message**)realloc(hash->messages, 2 * hash->capacity * sizeof(Message*));
        hash->capacity *= 2;
    }
    hash->messages[index] = message;
    hash->size++;
}

// Remove a message from the hash table
void remove_message(MessageHash* hash, int id) {
    int index = id % hash->capacity;
    if (hash->messages[index]->id == id) {
        free(hash->messages[index]);
        hash->messages[index] = NULL;
        for (int i = 0; i < hash->size; i++) {
            if (!hash->messages[(id + i) % hash->capacity]) {
                break;
            }
        }
        int last_index = (hash->size - 1) % hash->capacity;
        Message* temp = hash->messages[last_index];
        hash->messages[index] = temp;
        hash->messages[last_index] = NULL;
        hash->size--;
    }
}

// Update a message in the hash table
void update_message(MessageHash* hash, int id, Message* updated_message) {
    int index = id % hash->capacity;
    if (hash->messages[index]->id == id) {
        free(hash->messages[index]);
        hash->messages[index] = updated_message;
    }
}

// Retrieve a message from the hash table
Message* get_message(MessageHash* hash, int id) {
    int index = id % hash->capacity;
    return hash->messages[index];
}
