```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the LTE_PDCP_SDU structure
typedef struct {
    int PDCP_SN;
    char* PDCP_SDU_DATA;
} LTE_PDCP_SDU;

// Function prototypes
void* lte_pdcpsdu_array_new(size_t);
void lte_pdcpsdu_array_free(void**);
int lte_pdcpsdu_array_insert(LTE_PDCP_SDU**, size_t, int, char*);
LTE_PDCP_SDU* lte_pdcpsdu_array_get(LTE_PDCP_SDU**, size_t);

// Data structure to manage the dynamic array
typedef struct {
    LTE_PDCP_SDU** elements;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock; // Mutex for thread-safe access
} lte_pdcpsdu_array;

// Function to create a new dynamic array with the given initial capacity
void* lte_pdcpsdu_array_new(size_t initial_capacity) {
    lte_pdcpsdu_array* array = (lte_pdcpsdu_array*)malloc(sizeof(lte_pdcpsdu_array));

    array->elements = (LTE_PDCP_SDU**)calloc(initial_capacity, sizeof(LTE_PDCP_SDU*));
    array->capacity = initial_capacity;
    array->length = 0;

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Function to free the dynamic array and its elements
void lte_pdcpsdu_array_free(void** array) {
    lte_pdcpsdu_array* arr = (lte_pdcpsdu_array*)*array;

    for (size_t i = 0; i < arr->length; i++) {
        free(arr->elements[i]->PDCP_SDU_DATA);
        free(arr->elements[i]);
    }

    free(arr->elements);
    free(arr);

    return;
}

// Function to insert a new LTE_PDCP_SDU instance into the array
int lte_pdcpsdu_array_insert(LTE_PDCP_SDU** array, size_t capacity, int pdcp_sn, char* data) {
    lte_pdcpsdu_array* arr = (lte_pdcpsdu_array*)array;

    pthread_mutex_lock(&arr->lock);

    if (arr->length >= capacity) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed; operation aborted.\n");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    LTE_PDCP_SDU* new_sdu = (LTE_PDCP_SDU*)malloc(sizeof(LTE_PDCP_SDU));
    new_sdu->PDCP_SN = pdcp_sn;
    new_sdu->PDCP_SDU_DATA = malloc(strlen(data) + 1);
    strcpy(new_sdu->PDCP_SDU_DATA, data);

    arr->elements[arr->length++] = new_sdu;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function to retrieve an LTE_PDCP_SDU instance from the array
LTE_PDCP_SDU* lte_pdcpsdu_array_get(LTE_PDCP_SDU** array, size_t index) {
    lte_pdcpsdu_array* arr = (lte_pdcpsdu_array*)array;

    pthread_mutex_lock(&arr->lock);

    if (index >= arr->length || index < 0) {
        // Handle out-of-bounds error gracefully
        printf("Invalid index; operation aborted.\n");
        pthread_mutex_unlock(&arr->lock);
        return NULL;
    }

    LTE_PDCP_SDU* sdu = arr->elements[index];

    pthread_mutex_unlock(&arr->lock);

    return sdu;
}

