```cpp
#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class UserSession {
public:
    std::string user_id;
    std::string transaction_log;
    int session_status;

    UserSession(const std::string& id, const std::string& log, int status)
        : user_id(id), transaction_log(log), session_status(status) {}
};

class UserSessionManager {
private:
    std::vector<UserSession*> sessions_;
    std::unordered_map<std::string, size_t> user_session_ids_;
    std::mutex session_mutex_;
    std::condition_variable session_cv_;

public:
    void add_user(const std::string& id) {
        if (user_session_ids_.find(id) != user_session_ids_.end()) {
            return; // User already exists
        }

        size_t idx = sessions_.size();
        sessions_.emplace_back(new UserSession(id, "", 0));
        user_session_ids_[id] = idx;
    }

    void update_transaction(const std::string& id, const std::string& log) {
        std::unique_lock<std::mutex> lock(session_mutex_);
        for (size_t i = 0; i < sessions_.size(); ++i) {
            if (sessions_[i]->user_id == id) {
                sessions_[i]->transaction_log = log;
                break;
            }
        }
    }

    UserSession* get_session(const std::string& id) {
        if (user_session_ids_.find(id) == user_session_ids_.end()) {
            return nullptr; // User not found
        }

        size_t idx = user_session_ids_[id];
        return sessions_[idx];
    }

    void remove_user(const std::string& id) {
        if (user_session_ids_.find(id) == user_session_ids_.end()) {
            return; // User not found
        }

        size_t idx = user_session_ids_[id];
        delete sessions_[idx];
        sessions_.erase(idx);
        user_session_ids_.erase(id);
    }
};
