LTE_PHY_TX_RX_STREAMS *initialize_tx_rx_streams(size_t num_streams) {
    LTE_PHY_TX_RX_STREAMS *streams = (LTE_PHY_TX_RX_STREAMS *)malloc(num_streams * sizeof(LTE_PHY_TX_RX_STREAMS));
    if (!streams) return NULL;  // Handle allocation failure

    pthread_mutex_init(&streams->mutex, NULL);  // Initialize mutex for concurrent access
    for (size_t i = 0; i < num_streams; ++i) {
        streams[i].modulation = QPSK;
        streams[i].bandwidth = 10;  // Default bandwidth setting
        streams[i].buffer_size = 1024 * 1024;  // Initial buffer size
    }
    return streams;
}

void configure_stream(LTE_PHY_TX_RX_STREAMS *stream, enum { QPSK, QAM64, QAM256 } modulation, int bandwidth) {
    pthread_mutex_lock(&stream->mutex);  // Lock for concurrent access
    stream->modulation = modulation;
    stream->bandwidth = bandwidth;
    // Allocate buffer dynamically based on configuration
    if (!stream->buffer || (size_t)bandwidth > stream->buffer_size) {
        free(stream->buffer);
        stream->buffer = malloc(bandwidth * sizeof(char));
        if (!stream->buffer) {
            // Handle buffer allocation failure gracefully
            pthread_mutex_unlock(&stream->mutex);  // Unlock to avoid deadlock
            return;
        }
    }
    pthread_mutex_unlock(&stream->mutex);  // Unlock after configuration
}
