    int free_connections;
    pthread_mutex_t lock;
} connection_pool;

connection_pool connection_pool = {NULL, MAX_CONNECTIONS};

// Initialize the connection pool
void init_connection_pool() {
    pthread_mutex_init(&connection_pool.lock, NULL);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool.connections[i] = NULL;
    }
    connection_pool.free_connections = MAX_CONNECTIONS;
}

// Allocate a new TCP connection structure
tcp_connection* allocate_tcp_connection() {
    pthread_mutex_lock(&connection_pool.lock);
    tcp_connection* conn = connection_pool.connections[connection_pool.free_connections];
    if (conn) {
        connection_pool.free_connections--;
    }
    pthread_mutex_unlock(&connection_pool.lock);
    return conn;
}

// Release a TCP connection structure
void release_tcp_connection(tcp_connection* conn) {
    pthread_mutex_lock(&connection_pool.lock);
    connection_pool.connections[connection_pool.free_connections++] = conn;
    pthread_mutex_unlock(&connection_pool.lock);
}

