typedef struct {
    int id;
    time_t timestamp;
    int length;
} DataPacket;

DataPacket* processPacketsAndStatistics(int N) {
    DataPacket** packets = (DataPacket**)malloc((N+1)*sizeof(DataPacket*));
    for(int i=0; i<=N; i++) {
        packets[i] = (DataPacket*)malloc(sizeof(DataPacket));
        packets[i]->id = i;
        packets[i]->timestamp = time(NULL);
        packets[i]->length = rand() % 100 + 1;
    }

    int* integers = NULL;
    int integerCount = 0;

    for(int i=0; i<N; i++) {
        int num;
        scanf("%d", &num);
        if(integers == NULL) {
            integers = (int*)malloc(sizeof(int));
            integerCount++;
        } else {
            integers = (int*)realloc(integers, sizeof(int)*(integerCount+1));
            integerCount++;
        }
        integers[integerCount-1] = num;
    }

    int total = 0;

    if(integerCount > 0) {
        for(int i=0; i<integerCount; i++) {
            total += integers[i];
        }
        printf("%f\n", (double)total / integerCount);
    } else {
        printf("Array is empty.\n");
    }

    free(integers);

    return *packets;
}
