LTE_DL_FRAME_STRUCT** lte_dl_frame_init(int num_frames, ConfigurationStruct* config) {
    // Seed the random number generator for reproducibility
    srand(time(NULL));

    // Allocate memory for the frame array
    LTE_DL_FRAME_STRUCT** frames = (LTE_DL_FRAME_STRUCT**)malloc(num_frames * sizeof(LTE_DL_FRAME_STRUCT*));
    if (!frames) {
        return NULL;
