    for (int i = 0; i < num_frames; i++) {
        frames[i] = (LTE_DL_FRAME_STRUCT*)malloc(sizeof(LTE_DL_FRAME_STRUCT));
        if (!frames[i]) {
            for (int j = 0; j <= i; j++) {
                free(frames[j]);
            }
            return NULL;
        }

        // Initialize DL_FRAME_HEADER and PDSCH_SYMBOL information
        frames[i]->dl_frame_header1 = rand() % config->data_size_bytes;
        frames[i]->dl_frame_header2 = rand() % config->frames_per_second;

        frames[i]->pdsch_symbol1 = rand() % config->num_cqi_values;
        frames[i]->pdsch_symbol2 = rand() % i;

        // Initialize PDSCH_DATA and CQI values
        for (int j = 0; j < config->num_cqi_values; j++) {
            frames[i]->cqis[j] = (float)rand() / RAND_MAX;
        }
    }

    return frames;
}

// Function to release memory allocated by lte_dl_frame_init
