void process_network_statistics_and_aggregate_metrics(int N, NetworkMetrics* metrics_array, int* output_length) {
    // Generate PDUs
    PDU* pdus = (PDU*)malloc(N * sizeof(PDU));
    for (int i = 0; i < N; i++) {
        pdus[i].node_identifier = generate_node_identifier();
        pdus[i].measurement_type = generate_measurement_type();
        pdus[i].metrics_data = generate_metrics_data(pdus[i].measurement_type);
    }

    // Collect metrics data
    int metric_index = 0;
    char input[1024];
