        char* token = strtok(input, " ");
        if (!token || !isdigit(token[0])) break;
        NodeIdentifier node_id = parse_node_identifier(token);
        double metric_value = parse_metric_value(token + strlen(token));
        metrics_array[metric_index].node_identifier = node_id;
        metrics_array[metric_index++].metric_value = metric_value;
    }
    if (metric_index < *output_length) {
        for (int i = metric_index; i < *output_length; i++) {
            metrics_array[i].node_identifier = -1;
            metrics_array[i].metric_value = -1.0;
        }
    }
    *output_length = metric_index;

    // Aggregate metrics
    int unique_nodes = 0;
    for (int i = 0; i < *output_length; i++) {
        if (metrics_array[i].node_identifier != -1) {
            NodeIdentifier node_id = metrics_array[i].node_identifier;
            double total_value = 0.0;
            int count = 0;
            for (int j = 0; j < *output_length; j++) {
                if (metrics_array[j].node_identifier == node_id) {
                    total_value += metrics_array[j].metric_value;
                    count++;
                }
            }
            if (count > 0) {
                double average_value = total_value / count;
                metrics_array[i].average_metric_value = average_value;
                unique_nodes++;
            } else {
                metrics_array[i].average_metric_value = -1.0;
            }
        }
    }

    // Free dynamically allocated memory
    free(pdus);
}
