#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initRecords(int capacity) {
    record* records = (record*)malloc(sizeof(record) * capacity);
    for(int i = 0; i < capacity; i++) {
        records[i].value = rand() % 100;
    }
    return records;
}

void processInput(int** arr, int* capacity, int range[2]) {
    FILE* file = fopen("input.txt", "r");
    if(file == NULL) {
        printf("Failed to open input file.\n");
        return;
    }

    int num;
    while(fscanf(file, "%d\n", &num) == 1 && num >= range[0] && num <= range[1]) {
        if(*capacity < *arr) {
            *arr = (int*)realloc(*arr, sizeof(int) * (*capacity * 2));
            *capacity *= 2;
        }
        (*arr)[*capacity - 1] = num;
        (*capacity)++;
    }

    fclose(file);
}

void printArray(int* arr, int capacity) {
    for(int i = 0; i < capacity; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int findLargest(int* arr, int capacity) {
    int max = arr[0];
    for(int i = 1; i < capacity; i++) {
        if(arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void sortArray(int* arr, int capacity) {
    int temp;
    for(int i = 0; i < capacity - 1; i++) {
        for(int j = 0; j < capacity - i - 1; j++) {
            if(arr[j] > arr[j + 1]) {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

void saveArrayToFile(int* arr, int capacity) {
    FILE* file = fopen("output.txt", "w");
    if(file == NULL) {
        printf("Failed to open output file.\n");
        return;
    }

    for(int i = 0; i < capacity; i++) {
        fprintf(file, "%d\n", arr[i]);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    int recordsCapacity = 10;
    record* records = initRecords(recordsCapacity);

    int range[2] = {1, 100};
    int* arr = (int*)malloc(sizeof(int) * 4);
    int capacity = 4;

    processInput(&arr, &capacity, range);

    printf("Input array: ");
    printArray(arr, capacity);
    printf("Largest number: %d\n", findLargest(arr, capacity));
    sortArray(arr, capacity);
    printf("Sorted array: ");
    printArray(arr, capacity);
    saveArrayToFile(arr, capacity);

    free(records);
    free(arr);

    return 0;
}
