#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define a struct for MAC configuration
typedef struct {
    char id[17]; // 12 bytes for MAC address, +5 bytes for null terminator
    int power;
    int channel;
    int active;
} mac_config_t;

// Define a structure to represent the dynamic list of MAC configurations
typedef struct {
    int size;
    mac_config_t *configs;
    pthread_mutex_t lock; // Lock for concurrent access
} mac_list_t;

// Function to create and initialize a new MAC configuration list
mac_list_t* mac_list_create() {
    mac_list_t* list = (mac_list_t*)malloc(sizeof(mac_list_t));
    list->size = 0;
    list->configs = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new MAC configuration to the list
void mac_list_add(mac_list_t* list, const char* id, int power, int channel) {
    mac_config_t* config = (mac_config_t*)malloc(sizeof(mac_config_t));
    strcpy(config->id, id);
    config->power = power;
    config->channel = channel;
    config->active = 1; // Default to active

    pthread_mutex_lock(&list->lock);
    list->configs = realloc(list->configs, (list->size + 1) * sizeof(mac_config_t));
    list->configs[list->size++] = *config;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove a MAC configuration from the list
void mac_list_remove(mac_list_t* list, const char* id) {
    int i;
    for (i = 0; i < list->size; i++) {
        if (!strcmp(list->configs[i].id, id)) {
            break;
        }
    }

    pthread_mutex_lock(&list->lock);
    if (i < list->size) {
        memmove(&list->configs[i], &list->configs[i + 1], (list->size - i - 1) * sizeof(mac_config_t));
        free(list->configs[--list->size]);
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to retrieve a MAC configuration from the list
mac_config_t* mac_list_get(mac_list_t* list, const char* id) {
    int i;
    for (i = 0; i < list->size; i++) {
        if (!strcmp(list->configs[i].id, id)) {
            return &list->configs[i];
        }
    }
    return NULL;
}

// Function to free the memory allocated by a MAC configuration list
void mac_list_free(mac_list_t* list) {
    int i;
    pthread_mutex_lock(&list->lock);
    for (i = 0; i < list->size; i++) {
        free(list->configs[i].id); // Free individual strings
        free(&list->configs[i]); // Free each configuration struct
    }
    free(list->configs); // Free the array of configurations
    pthread_mutex_unlock(&list->lock);
    free(list);
}
