void initializeNFAPCIDirectory(int numRecords, int maxMemoryUsage) {
    // Initialize environment variable for directory path
    char* dirPath = getenv("NFAPI_DIRECTORY");
    if (dirPath == NULL) {
        dirPath = malloc(strlen(getenv("TMPDIR")) + 16);
        strcpy(dirPath, getenv("TMPDIR"));
        strcat(strcat(dirPath, "/"), "NFAPCIDirectory");
        setenv("NFAPI_DIRECTORY", dirPath, 1);
    }

    // Initialize arrays
    long* offsets = (long*)malloc(maxMemoryUsage * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));
    char** metadataList = (char**)malloc(MAX_METADATA_SIZE);
    FILE* fileMetadata;
    int i, j;

    // Load additional metadata from file
    fileMetadata = fopen("metadata.txt", "r");
    if (fileMetadata == NULL) {
        printf("Error opening file for metadata.\n");
        return;
    }

    for (i = 0; i < MAX_METADATA_SIZE; i++) {
        char line[MAX_FILE_SIZE];
        fgets(line, sizeof(line), fileMetadata);
        int len = strlen(line) - 1;
        if (line[len] == '\n') {
            line[len] = '\0';
        }
        metadataList[i] = malloc(len + 1);
        strcpy(metadataList[i], line);
    }

    fclose(fileMetadata);

    // Initialize records
    srand(time(NULL));
    for (i = 0; i < numRecords; i++) {
        record_t* currentRecord = &records[i];
        currentRecord->value = rand() % 100;
        int len = rand() % MAX_METADATA_SIZE + 1;
        char* tempMeta = malloc(len);
        strcpy(tempMeta, metadataList[rand() % MAX_METADATA_SIZE]);
        currentRecord->metadata = tempMeta;
    }

    // Print memory usage
    printf("Memory Usage: %d bytes\n", maxMemoryUsage * sizeof(long) + numRecords * (sizeof(int) + sizeof(record_t)) + MAX_METADATA_SIZE * sizeof(char*) + len);
    printf("Number of Records: %d\n", numRecords);

    free(dirPath);
    free(offsets);
    free(keys);
    for (i = 0; i < numRecords; i++) {
        free(records[i].metadata);
        free(&records[i]);
    }
    free(metadataList);
}
