```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODES 10000
#define STRING_LENGTH_MIN 10
#define STRING_LENGTH_MAX 50
#define FILE_BUFFER_SIZE 1024

typedef struct item {
    char* string;
    struct item* next;
    struct item* prev;
} item_t;

typedef struct node {
    int key;
    item_t* head;
} node_t;

void* my_malloc(size_t size) {
    // Custom allocation function
    return malloc(size);
}

void my_free(void* ptr) {
    // Custom deallocation function
    free(ptr);
}

node_t* init_node(int key, char* string) {
    node_t* node = (node_t*)my_malloc(sizeof(node_t));
    node->key = key;
    node->head = NULL;

    item_t* current = (item_t*)my_malloc(sizeof(item_t));
    current->string = strdup(string);
    current->next = NULL;
    current->prev = NULL;
    node->head = current;

    return node;
}

void populate_nodes(node_t** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        char* string = (char*)my_malloc(strlen(nodes[i]->head->string) + STRING_LENGTH_MAX);
        sprintf(string, "%s-%d", nodes[i]->head->string, i);

        item_t* current = nodes[i]->head;
        while (current) {
            current->next = (item_t*)my_malloc(sizeof(item_t));
            current->next->string = string;
            current->next->prev = current;
            current->next->next = NULL;
            current = current->next;
        }
    }
}

void export_nodes(node_t* node, char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    item_t* current = node->head;
    while (current) {
        fprintf(file, "%s\n", current->string);
        current = current->next;
    }

    fclose(file);
}

node_t* import_nodes(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return NULL;
    }

    node_t* node = (node_t*)my_malloc(sizeof(node_t));
    item_t* current = NULL;

    char buffer[FILE_BUFFER_SIZE];
    while (fgets(buffer, FILE_BUFFER_SIZE, file)) {
        item_t* new_item = (item_t*)my_malloc(sizeof(item_t));
        new_item->string = strdup(buffer);
        new_item->next = NULL;
        new_item->prev = current;
        if (current) {
            current->next = new_item;
        } else {
            node->head = new_item;
        }
        current = new_item;
    }

    fclose(file);

    return node;
}

int main(int argc, char* argv[]) {
    // Parse command-line arguments
    int num_nodes = atoi(argv[1]);
    int min_length = atoi(argv[2]);
    int max_length = atoi(argv[3]);
    char* import_file = argv[4];
    char* export_file = argv[5];

    node_t* nodes[MAX_NODES];
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = init_node(i, "Initial String");
    }

    // Populate nodes
    populate_nodes(nodes, num_nodes);

    // Import data from file
    node_t* imported_node = import_nodes(import_file);
    if (imported_node) {
        item_t* current = imported_node->head;
        while (current) {
            item_t* temp = current;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = node->head;
            node->head = current;
            current = NULL;
        }

        // Export data to file
        export_nodes(node, export_file);
    }

    for (int i = 0; i < num_nodes; i++) {
        my_free(nodes[i]->head);
        my_free(nodes[i]);
    }
    return 0;
}
```

