#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure
typedef struct {
    int frame_number;
    LTE_DL_FRAME_MSG_SRB* srbs;
    LTE_DL_FRAME_MSG_DRB* drbs;
} LTE_DL_FRAME_MSG;

// Define the lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define the dynamic array and its size
LTE_DL_FRAME_MSG** frames = NULL;
int frame_count = 0;

// Function to add a new frame
void add_frame(LTE_DL_FRAME_MSG* frame) {
    pthread_mutex_lock(&lock);

    // Check for memory allocation failures
    if ((frames = realloc(frames, (frame_count + 1) * sizeof(LTE_DL_FRAME_MSG*) )) == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    frames[frame_count] = frame;
    frame_count++;

    pthread_mutex_unlock(&lock);
}

// Function to retrieve a specific frame
LTE_DL_FRAME_MSG* get_frame(int frame_number) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < frame_count; i++) {
        if (frames[i]->frame_number == frame_number) {
            pthread_mutex_unlock(&lock);
            return frames[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to clear all frames
void clear_frames() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < frame_count; i++) {
        free(frames[i]->srbs);
        free(frames[i]->drbs);
        free(frames[i]);
    }

    free(frames);
    frames = NULL;
    frame_count = 0;

    pthread_mutex_unlock(&lock);
}

// Example usage:
int main() {
    LTE_DL_FRAME_MSG* new_frame = malloc(sizeof(LTE_DL_FRAME_MSG));
    new_frame->frame_number = 1;
    new_frame->srbs = malloc(10 * sizeof(LTE_DL_FRAME_MSG_SRB));
    new_frame->drbs = malloc(5 * sizeof(LTE_DL_FRAME_MSG_DRB));

    add_frame(new_frame);

    LTE_DL_FRAME_MSG* retrieved_frame = get_frame(1);
    if (retrieved_frame != NULL) {
        // Process the frame
        printf("Frame Number: %d\n", retrieved_frame->frame_number);
    }

    clear_frames();

    return 0;
}
