```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct node with an integer key and a linked list of item nodes
typedef struct {
    int key;
    struct {
        char* str;
        struct item* next, *prev;
    } item;
} node;

// Define a struct item node with a string and a pointer to another item node
typedef struct {
    char* str;
    struct item* next, *prev;
} item;

// Function to dynamically allocate memory for an array of struct node pointers
node** initNodeArray(int size) {
    node** arr = (node**)malloc(size * sizeof(node*));
    for (int i = 0; i < size; i++) {
        arr[i] = NULL;
    }
    return arr;
}

// Function to initialize the first node with a specific key and a given string
void initFirstNode(node** head, int key, char* str) {
    *head = (node*)malloc(sizeof(node));
    (*head)->key = key;
    (*head)->item.str = str;
    (*head)->item.next = NULL;
    (*head)->item.prev = NULL;
}

// Function to insert new nodes at any position in the list
void insertNode(node** head, node* newNode) {
    if (!*head || newNode->key < (*head)->key) {
        newNode->item.next = *head;
        newNode->item.prev = NULL;
        *head = newNode;
    } else {
        node* current = *head;
        while (current && newNode->key >= current->key) {
            if (!current->item.next || newNode->key < current->item.next->key) {
                newNode->item.next = current->item.next;
                newNode->item.prev = current;
                current->item.next = newNode;
                if (newNode->item.next) {
                    newNode->item.next->item.prev = newNode;
                } else {
                    (*head)->item.prev = newNode;
                }
                return;
            }
            current = current->item.next;
        }
    }
}

// Function to delete nodes
void deleteNode(node** head, node* target) {
    if (!target) return;

    if (target == *head) {
        *head = target->item.next;
        if (*head) {
            (*head)->item.prev = NULL;
        } else {
            *head = NULL;
        }
    } else {
        node* current = *head;
        while (current && current != target) {
            current = current->item.next;
        }
        if (!current) return;

        current->item.prev->item.next = current->item.next;
        if (target->item.next) {
            target->item.next->item.prev = target->item.prev;
        } else {
            (*head)->item.prev = target->item.prev;
        }

        free(target);
    }
}

// Function to traverse the linked list and print each string
void printList(node* head) {
    node* current = head;
    while (current) {
        printf("%s\n", current->item.str);
        current = current->item.next;
    }
}

// Function to serialize the linked list to a file
void serializeList(FILE* file, node* head) {
    node* current = head;
    while (current) {
        fprintf(file, "%d:%s\n", current->key, current->item.str);
        current = current->item.next;
    }
}

// Function to deserialize the linked list from a file
node* deserializeList(FILE* file) {
    node* head = NULL;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int key = atoi(strtok(line, ":"));
        char* str = strtok(NULL, ":");
        node* newNode = (node*)malloc(sizeof(node));
        newNode->key = key;
        newNode->item.str = str;
        newNode->item.next = NULL;
        newNode->item.prev = NULL;

        if (!head) {
            head = newNode;
        } else {
            node* current = head;
            while (current->item.next) {
                current = current->item.next;
            }
            current->item.next = newNode;
            newNode->item.prev = current;
        }
    }
    fclose(file);
    return head;
}
