#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *states;
    int num_states;
    int **transitions;
} FSA;

FSA* expand_state(FSA* f, int current_states[], int num_states, int last_state, int include_hidden) {
    // Allocate memory for the new state list
    FSA* new_fsa = (FSA*)malloc(sizeof(FSA));
    if (!new_fsa) return NULL;

    // Calculate the number of states in the new list
    int new_num_states = num_states + (include_hidden ? 1 : 0);

    // Allocate memory for the new state array
    new_fsa->states = (int*)malloc(new_num_states * sizeof(int));
    if (!new_fsa->states) {
        free(new_fsa);
        return NULL;
    }

    // Copy the current states to the new list
    for (int i = 0; i < num_states; i++) {
        new_fsa->states[i] = current_states[i];
    }
    if (include_hidden) {
        new_fsa->states[num_states] = last_state + 1;
    }

    // Update the transition table
    new_fsa->transitions = (int**)malloc(new_num_states * sizeof(int*));
    for (int i = 0; i < new_num_states; i++) {
        new_fsa->transitions[i] = (int*)malloc(f->num_states * sizeof(int));
        if (!new_fsa->transitions[i]) {
            // Free the memory we've allocated so far
            free(new_fsa->states);
            free(new_fsa);
            return NULL;
        }
    }

    // Copy the transitions from the old FSA to the new one
    for (int i = 0; i < num_states; i++) {
        for (int j = 0; j < f->num_states; j++) {
            new_fsa->transitions[i][j] = f->transitions[i][j];
        }
    }

    // Update the next pointer of the last state in the list
    if (include_hidden) {
        new_fsa->transitions[new_num_states - 1][0] = new_fsa;
    }

    // Free the memory we're no longer using
    for (int i = 0; i < num_states; i++) {
        free(f->transitions[i]);
    }
    free(f->transitions);

    return new_fsa;
}
