FrameHeader* initializeFrameHeaders(int numFrames, int maxPayloadSize) {
    if (numFrames <= 0 || maxPayloadSize <= 0) {
        return NULL;
    }

    FrameHeader* frameHeaders = (FrameHeader*)malloc(numFrames * sizeof(FrameHeader));
    if (!frameHeaders) {
        return NULL;
    }

    for (int i = 0; i < numFrames; i++) {
        frameHeaders[i].timestamp = time(NULL);
        sprintf(frameHeaders[i].sourceMAC, "%02x:%02x:%02x:%02x:%02x:%02x",
                rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        sprintf(frameHeaders[i].destinationMAC, "%02x:%02x:%02x:%02x:%02x:%02x",
                rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256);

        size_t payloadLength = (size_t)rand() % (maxPayloadSize - 100) + 100;
        frameHeaders[i].payloadLength = payloadLength;

        // Dynamically allocate memory for the payload
        frameHeaders[i].payload = malloc(payloadLength);
        if (!frameHeaders[i].payload) {
            printf("Failed to allocate memory for payload. Retrying...\n");
            for (int j = 0; j < 3 && !frameHeaders[i].payload; j++) {
                frameHeaders[i].payload = malloc(payloadLength);
                if (!frameHeaders[i].payload) {
                    printf("Memory allocation failed after %d retries.\n", j + 1);
                    return NULL;
                }
            }
        }

        // Implement logging framework integration here
        printf("Frame header initialized with timestamp: %lu, source MAC: %s, destination MAC: %s, and payload length: %zu\n",
               (unsigned long)frameHeaders[i].timestamp, frameHeaders[i].sourceMAC, frameHeaders[i].destinationMAC, frameHeaders[i].payloadLength);
    }

    return frameHeaders;
}

void releaseFrameHeaders(FrameHeader* frameHeaders, int numFrames) {
    for (int i = 0; i < numFrames; i++) {
        if (frameHeaders[i].payload) {
            free(frameHeaders[i].payload);
        }
    }
    free(frameHeaders);
}
