NFAPI_CRC_INDICATION_PDU_T* create_array(int n) {
    return (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T** arr, int n) {
    for (int i = 0; i < n; i++) {
        (*arr)[i].rx_ue_info_tag[0] = '\0';
        (*arr)[i].rnti = rand();
        (*arr)[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }
}

int find_rnti(NFAPI_CRC_INDICATION_PDU_T** arr, int n, int target) {
    for (int i = 0; i < n; i++) {
        if ((*arr)[i].rnti == target) {
            return i;
        }
    }
    return -1;
}

void remove_entry(NFAPI_CRC_INDICATION_PDU_T** arr, int* n, int rnti) {
    for (int i = 0; i < *n; i++) {
        if ((*arr)[i].rnti == rnti) {
            memmove(&(*arr)[i], &(*arr)[i + 1], (*n - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (*n]--;
            break;
        }
    }
}

void update_crcflag(NFAPI_CRC_INDICATION_PDU_T** arr, int n, int rnti, uint8_t crcflag) {
    for (int i = 0; i < n; i++) {
        if ((*arr)[i].rnti == rnti) {
            (*arr)[i].crc_indication_rel8_tag.crcflag = crcflag;
            break;
        }
    }
}

int count_unique_rntis(NFAPI_CRC_INDICATION_PDU_T** arr, int n) {
    int unique_rntis = 0;
    for (int i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < unique_rntis; j++) {
            if ((*arr)[i].rnti == (*arr)[j].rnti) {
                found = 1;
                break;
            }
        }
        if (!found) {
            unique_rntis++;
        }
    }
    return unique_rntis;
}

void export_array(NFAPI_CRC_INDICATION_PDU_T** arr, int n) {
    FILE* file = fopen("output.txt", "w");
    for (int i = 0; i < n; i++) {
        fprintf(file, "%s %d\n", (*arr)[i].rx_ue_info_tag, (*arr)[i].rnti);
    }
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* import_array() {
    FILE* file = fopen("input.txt", "r");
    int n;
    fscanf(file, "%d", &n);
    NFAPI_CRC_INDICATION_PDU_T* arr = create_array(n);
    for (int i = 0; i < n; i++) {
        fgets((arr + i)->rx_ue_info_tag, sizeof((arr + i)->rx_ue_info_tag), file);
        fscanf(file, "%d\n", &(arr + i)->rnti);
    }
    fclose(file);
    return arr;
}

void log_operation(char* operation) {
    time_t now = time(NULL);
    FILE* file = fopen("log.txt", "a");
    fprintf(file, "[%s] %ld %s\n", asctime(localtime(&now)), (long)now, operation);
    fclose(file);
}
