typedef struct {
    char RX_UE_INFORMATION_TAG[17];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[9];
    int CRCFLAG;
    char MD5_hash[33];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU(int N) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for(int i = 0; i < N; i++) {
        char RX_UE_INFORMATION_TAG[17];
        int RNTI;
        strcpy(RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        RNTI = rand() % 10000;

        char CRC_INDICATION_REL8_TAG[9];
        strcpy(CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");

        int CRCFLAG;
        CRCFLAG = (rand() % 2 == 0) ? 1 : 0;

        unsigned char md5[16];
        MD5_CTX md5_ctx;
        MD5_Init(&md5_ctx);
        MD5_Update(&md5_ctx, RX_UE_INFORMATION_TAG, strlen(RX_UE_INFORMATION_TAG));
        MD5_Update(&md5_ctx, &RNTI, sizeof(int));
        MD5_Update(&md5_ctx, CRC_INDICATION_REL8_TAG, strlen(CRC_INDICATION_REL8_TAG));
        MD5_Update(&md5_ctx, &CRCFLAG, sizeof(int));
        MD5_Final(md5, &md5_ctx);

        char* md5_hash = (char*)malloc(33 * sizeof(char));
        for(int j = 0; j < 16; j++) {
            sprintf("%02x", md5[j]);
            strcat(md5_hash, "");
        }
        free(md5);

        list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        list[i].RNTI = RNTI;
        list[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        list[i].CRCFLAG = CRCFLAG;
        strcpy(list[i].MD5_hash, md5_hash);
        free(md5_hash);
    }

    return list;
}
