node* create_node(int key, char* data);
void add_item(node*, item*);
void free_list(node*);

int main(int argc, char* argv[]) {
    // Initialize the first node
    node* root = NULL;
    int num_nodes = 0;
    if (argc > 1) {
        num_nodes = atoi(argv[1]);
    }

    for (int i = 0; i < num_nodes; i++) {
        item* new_item = malloc(sizeof(item));
        // Initialize the node and add to the list
        root = create_node(i, "Initial string");
        add_item(root, *new_item);

        // Generate subsequent nodes with strings generated based on a specified template and length range
    }

    return 0;
}

node* create_node(int key, char* data) {
    node* new_node = malloc(sizeof(node));
    new_node->key = key;
    new_node->head = NULL;
    new_node->tail = NULL;
    // Add the item to the list
    add_item(new_node, *item);

    return new_node;
}

void add_item(node* parent, item* new_item) {
    if (parent->head == NULL) {
        parent->head = new_item;
        parent->tail = new_item;
    } else {
        new_item->prev = parent->tail;
        parent->tail->next = new_item;
        parent->tail = new_item;
    }
}

void free_list(node* root) {
    node* current = root;
    while (current != NULL) {
        item* temp = current->head;
        current = current->tail;
        // Free all items
        while (temp != NULL) {
            free(temp);
            temp = temp->next;
        }
    }
}
