    MD5_Update(&md5, crcFlag, 2);
    memcpy(buffer, &pStruct->CRC_INDICATION_REL8_TAG[0], len);
    MD5_Update(&md5, buffer, len);

    // Finalize MD5 hash
    MD5_Final(md5Hash, &md5);
}

char *convertBytesToHexString(unsigned char *bytes, int len) {
