typedef struct {
    char src_ip[16];
    char dst_ip[16];
    char protocol[4];  // "TCP" or "UDP"
    int port;
} PacketHeader;

PacketHeader* process_network_traffic(int N) {
    PacketHeader* packets = (PacketHeader*)malloc(N * sizeof(PacketHeader));
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        char protocol[4];
        sprintf(protocol, "%s", i % 2 == 0 ? "TCP" : "UDP");
        int port = rand() % 65536;

        // Ensure no two packets share the same destination IP address
        int dst_ip_idx;
        do {
            dst_ip_idx = rand() % 256;
            char dst_ip[16];
            sprintf(dst_ip, "%d.%d.%d.%d", dst_ip_idx / 16777216, (dst_ip_idx / 65536) % 256, (dst_ip_idx / 256) % 256, dst_ip_idx % 256);
        } while (i > 0 && memcmp(packets[i-1].dst_ip, dst_ip, sizeof(dst_ip)));

        strcpy(packets[i].src_ip, "192.168.");
        sprintf(packets[i].dst_ip, "%d.%d.%d.%d", dst_ip_idx / 16777216, (dst_ip_idx / 65536) % 256, (dst_ip_idx / 256) % 256, dst_ip_idx % 256);
        strcpy(packets[i].protocol, protocol);
        packets[i].port = port;
    }

    return packets;
}

int find_smallest(int* array, int size) {
    if (size == 0)
        return -1;  // or throw an exception

    int smallest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] < smallest)
            smallest = array[i];
    }
    return smallest;
}
