custom_memory_pool_t create_custom_memory_pool(int initial_capacity) {
    custom_memory_pool_t pool = (custom_memory_pool_t)malloc(sizeof(custom_memory_pool_t));
    pool->capacity = initial_capacity;
    pool->entries = (memory_pool_entry_t**)calloc(pool->capacity, sizeof(memory_pool_entry_t*));
    return pool;
