void add_to_custom_memory_pool(custom_memory_pool_t* pool, void* data, size_t size) {
    memory_pool_entry_t* entry = (memory_pool_entry_t*)malloc(sizeof(memory_pool_entry_t));
    entry->data = data;
    entry->size = size;
    for (int i = 0; i < pool->capacity; i++) {
        if (!pool->entries[i]) {
            pool->entries[i] = entry;
            return;
        }
    }
}

