    pthread_cond_t cond;
    int32_t ref_count;
} NFAPI_CRC_INDICATION_PDU_T_list;

NFAPI_CRC_INDICATION_PDU_T_list* create_nfa_pi_crc_indication_pdu_t_list(size_t max_size) {
    NFAPI_CRC_INDICATION_PDU_T_list *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_list));
    list->size = 0;
    list->elements = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->ref_count = 1;
    return list;
}

void nfa_pi_crc_indication_pdu_t_list_add(NFAPI_CRC_INDICATION_PDU_T_list *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= max_size) {
        NFAPI_CRC_INDICATION_PDU_T *old_element = list->elements;
        list->elements = element;
        free(old_element);
    } else {
        list->elements = realloc(list->elements, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->elements) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->elements[list->size] = *element;
    }
    list->size++;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

void nfa_pi_crc_indication_pdu_t_list_remove(NFAPI_CRC_INDICATION_PDU_T_list *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size > 0) {
        for (int i = 0; i < list->size - 1; i++) {
            list->elements[i] = list->elements[i + 1];
        }
        free(list->elements[list->size - 1]);
        list->elements = realloc(list->elements, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

void nfa_pi_crc_indication_pdu_t_list_free(NFAPI_CRC_INDICATION_PDU_T_list *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}

void nfa_pi_crc_indication_pdu_t_list_ref(NFAPI_CRC_INDICATION_PDU_T_list *list) {
    if (list != NULL) {
        list->ref_count++;
    }
}

int32_t nfa_pi_crc_indication_pdu_t_list_unref(NFAPI_CRC_INDICATION_PDU_T_list *list) {
    int32_t ret = 0;
    pthread_mutex_lock(&list->mutex);
    if (list->ref_count == 1) {
        list->ref_count--;
        if (list->size > 0) {
            for (int i = 0; i < list->size; i++) {
                free(list->elements[i]);
            }
            free(list->elements);
        } else {
            pthread_cond_destroy(&list->cond);
            pthread_mutex_destroy(&list->mutex);
        }
        ret = -1;
    } else {
        list->ref_count--;
    }
    pthread_mutex_unlock(&list->mutex);
    return ret;
}

