NFAPI_CRC_INDICATION_PDU_T* createList(int* count) {
    *count = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int crcflag = 1; // Initialize CRCFLAG value

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
