        }
        list[*count].RX_UE_INFORMATION_TAG = rand() % 100; // Random RX_UE_INFORMATION_TAG
        list[*count].RNTI = rand() % 256; // Random RNTI
        list[*count].CRC_INDICATION_REL8_TAG = rand() % 1000; // Random CRC_INDICATION_REL8_TAG
        list[*count].CRCFLAG = crcflag;
        crcflag = (crcflag + 1) % 2; // Ensure no two consecutive structures have the same CRCFLAG value

        (*count)++;
    }
    return list;
}

void validateList(NFAPI_CRC_INDICATION_PDU_T* list, int* count) {
    if (*count < 2) {
        return;
    }

    for (int i = 1; i < *count; i++) {
        if (list[i].RNTI == list[i - 1].RNTI) { // Check for consecutive duplicate RNTIs
            reassignRNTIs(list, count);
            break;
        }
    }
}

void reassignRNTIs(NFAPI_CRC_INDICATION_PDU_T* list, int* count) {
    int rntiMax = 256; // Maximum possible RNTI value

    for (int i = 1; i < *count; i++) {
        int duplicateRNTI = list[i].RNTI;
        while (list[i].RNTI == duplicateRNTI) { // Find a new unique RNTI
            list[i].RNTI = rand() % rntiMax;
            if (isConsecutiveDuplicate(list[i].RNTI, list)) {
                rntiMax--;
            }
        }
    }
}

int isConsecutiveDuplicate(int rnti, NFAPI_CRC_INDICATION_PDU_T* list) {
    for (int i = 1; i < *list_count; i++) {
        if (list[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}
