#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[3];
    int CRCFLAG;
    time_t timestamp;
    int sequence_number;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list structure with dynamic memory allocation
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned long max_size;
    time_t retention_period;
} NFAPI_CRC_INDICATION_PDU_LIST;

// Initialize the list structure with default values
NFAPI_CRC_INDICATION_PDU_LIST* nfaapi_crc_indication_pdu_list_init(size_t max_size, time_t retention_period) {
    NFAPI_CRC_INDICATION_PDU_LIST* list = (NFAPI_CRC_INDICATION_PDU_LIST*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    pthread_mutex_init(&list->lock, NULL);
    list->elements = NULL;
    list->size = 0;
    list->capacity = max_size;
    list->max_size = max_size;
    list->retention_period = retention_period;
    return list;
}

// Add an element to the list
int nfaapi_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        // Resize the array if it's full
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    // Add the element to the end of the list
    if (list->size >= list->max_size) {
        // Remove the oldest elements if the maximum size is exceeded
        for (int i = 0; i < list->size - (list->max_size - 1); i++) {
            free(list->elements[i]);
        }
        memmove(list->elements, list->elements + (list->max_size - 1), sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - (list->max_size - 1)));
        list->size -= (list->max_size - 1);
    }

    element->timestamp = time(NULL);
    element->sequence_number = list->size;
    list->elements[list->size] = element;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Enumerate the list in reverse order
int nfaapi_crc_indication_pdu_list_enum(NFAPI_CRC_INDICATION_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T** elements) {
    pthread_mutex_lock(&list->lock);

    // Create a copy of the list to avoid modifying it during iteration
    size_t copy_size = list->size;
    NFAPI_CRC_INDICATION_PDU_T* copy_elements = (NFAPI_CRC_INDICATION_PDU_T*) malloc(copy_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memmove(copy_elements, list->elements + (list->size - 1), sizeof(NFAPI_CRC_INDICATION_PDU_T) * copy_size);

    // Enumerate the list in reverse order
    for (int i = 0; i < copy_size; i++) {
        elements[i] = &copy_elements[copy_size - 1 - i];
    }

    free(copy_elements);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Filter the list based on RNTI values
int nfaapi_crc_indication_pdu_list_filter(NFAPI_CRC_INDICATION_PDU_LIST* list, unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T** filtered_elements) {
    pthread_mutex_lock(&list->lock);

    // Create a copy of the list to avoid modifying it during iteration
    size_t copy_size = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i]->RNTI == rnti) {
            copy_size++;
        }
    }

    // Create a filtered list
    NFAPI_CRC_INDICATION_PDU_T* filtered_elements_copy = (NFAPI_CRC_INDICATION_PDU_T*) malloc(copy_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memmove(filtered_elements_copy, &list->elements[0], copy_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Copy the filtered elements to the output
    for (int i = 0; i < copy_size; i++) {
        filtered_elements[i] = &filtered_elements_copy[i];
    }

    free(filtered_elements_copy);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove elements older than the retention period
int nfaapi_crc_indication_pdu_list_remove_old(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    pthread_mutex_lock(&list->lock);

    // Create a copy of the list to avoid modifying it during iteration
    size_t copy_size = 0;
    for (int i = 0; i < list->size; i++) {
        if (time(NULL) - list->elements[i]->timestamp <= list->retention_period) {
            copy_size++;
        }
    }

    // Remove the old elements
    memmove(list->elements, &list->elements[copy_size], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - copy_size));
    list->size = copy_size;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Free the list and its elements
void nfaapi_crc_indication_pdu_list_free(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
