#define MAX_LIST_SIZE 1000
#define THRESHOLD 500

typedef struct {
    int RNTI;
    int CRCFLAG;
    time_t timestamp;
    int sequence_number;
} NFAPI_CRC_INDICATION_PDU_T;

int nfaapi_crc_list_size = 0;
NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_list = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t list_cond = PTHREAD_COND_INITIALIZER;

void* allocate_nfaapi_crc_pdu(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(pdu == NULL) return NULL;
    pdu->RNTI = RNTI;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 1 or 0
    pdu->timestamp = time(NULL);
    pdu->sequence_number = nfaapi_crc_list_size + 1;
    return pdu;
}

int is_rnti_unique(int RNTI) {
    for(int i = 0; i < nfaapi_crc_list_size; i++) {
        if(nfaapi_crc_list[i]->RNTI == RNTI)
            return 0; // Not unique
    }
    return 1; // Unique
}

void remove_old_elements() {
    pthread_mutex_lock(&list_lock);
    while(nfaapi_crc_list_size > THRESHOLD) {
        free(nfaapi_crc_list[--nfaapi_crc_list_size]);
    }
    pthread_mutex_unlock(&list_lock);
    pthread_cond_signal(&list_cond);
