    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
    size_t size;
} linked_list;

void init_linked_list(linked_list* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size = 0;
}

NFAPI_CRC_INDICATION_PDU_T* find_rnti(linked_list* list, RNTI rnti_to_find) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti_to_find) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void add_element(linked_list* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL || find_rnti(list, element->rnti) == NULL) {
        element->next = list->head;
        list->head = element;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = element;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_element(linked_list* list, RNTI rnti_to_remove) {
    pthread_mutex_lock(&list->lock);
    if (list->head != NULL) {
        if (list->head->rnti == rnti_to_remove) {
            NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
            list->head = list->head->next;
            free(temp);
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = list->head;
            while (current->next != NULL) {
                if (current->next->rnti == rnti_to_remove) {
                    NFAPI_CRC_INDICATION_PDU_T* temp = current->next;
                    current->next = current->next->next;
                    free(temp);
                    break;
                }
                current = current->next;
            }
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanup(linked_list* list) {
    time_t now = time(NULL);
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if ((now - current->timestamp) > 15) {
            NFAPI_CRC_INDICATION_PDU_T* temp = current;
            current = current->next;
            free(temp);
            list->size--;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void generate_crcflag(linked_list* list) {
    size_t crcflags[256] = {0};
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        int index = (int)(current->rnti >> 8);
        if (crcflags[index] == 0) {
            current->crcflag = index;
            crcflags[index] = 1;
        } else {
            current->crcflag = (index + 1) % 256;
            crcflags[(index + 1) % 256] = 1;
        }
        current = current->next;
    }
}
