// Define the structure for network device statistics
typedef struct {
    time_t timestamp;
    uint32_t packet_count;
    uint64_t byte_count;
    char unique_id[16];
} stat_struct;

// Define the maximum size of the dynamic array
#define MAX_SIZE 1024

// Function to manage the dynamic array
void* stat_array_manager(void* arg) {
    // Initialize the dynamic array
    stat_struct** stats = (stat_struct**)malloc(MAX_SIZE * sizeof(stat_struct*));
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    int size = 0; // Current size of the array

    while (1) {
        // Handle insertion operations
        if (size >= MAX_SIZE) {
            printf("Array is full. Cannot add more statistics.\n");
            continue;
        }

        // Allocate memory for a new statistic structure
        stat_struct* stat = (stat_struct*)malloc(sizeof(stat_struct));
        pthread_mutex_lock(&lock);
        stats[size] = stat;
        size++;
        pthread_mutex_unlock(&lock);

        // Handle retrieval operations
        if (size > 0) {
            int i = rand() % size; // Randomly select a statistic for retrieval
            pthread_mutex_lock(&lock);
            stat_struct* retrieved_stat = stats[i];
            printf("Retrieved statistic: timestamp=%ld, packet_count=%d, byte_count=%llu, unique_id=%s\n", 
                   (long int)retrieved_stat->timestamp, retrieved_stat->packet_count, retrieved_stat->byte_count, retrieved_stat->unique_id);
            pthread_mutex_unlock(&lock);
        }
    }

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, stat_array_manager, NULL);
    pthread_join(thread, NULL);

    return 0;
}
