    for (int i = 0; i < N; i++) {
        if (packets[i].sequence_number > last_sequence + 1) {
            printf("Warning: missing sequence numbers from %d to %d.\n", last_sequence + 2, packets[i].sequence_number - 1);
        }
        last_sequence = packets[i].sequence_number;
