    printf("Total packets processed: %d\n", N);
    printf("Sum of all DATA_SIZE values: %zu\n", total_data_size);
    printf("Count of packets where CHECKSUM validation failed: %d\n", checksum_failures);

    return packets;
}

int calculate_checksum(const CUSTOM_PROTOCOL_PACKET_T* packet, int M) {
