typedef struct {
    char* id;
    int state;
    char** queueBuffer;
    int bufferLen;
} InterfaceConfig;

typedef struct {
    pthread_mutex_t mutex;
    InterfaceConfig* interfaces;
    int interfaceCount;
} NetworkManager;

NetworkManager* networkManagerCreate() {
    NetworkManager* manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    manager->interfaceCount = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void networkManagerDestroy(NetworkManager* manager) {
    if (manager == NULL)
        return;

    for (int i = 0; i < manager->interfaceCount; i++) {
        free(manager->interfaces[i].id);
        free(manager->interfaces[i].queueBuffer);
    }
    free(manager->interfaces);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void interfaceConfigCreate(NetworkManager* manager, char* id) {
    InterfaceConfig* config = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));
    config->id = strdup(id);
    config->state = 0;
    config->bufferLen = 128;
    config->queueBuffer = (char**)malloc(config->bufferLen * sizeof(char*));

    pthread_mutex_lock(&manager->mutex);
    manager->interfaces = (InterfaceConfig*)realloc(manager->interfaces, (manager->interfaceCount + 1) * sizeof(InterfaceConfig));
    manager->interfaces[manager->interfaceCount] = config;
    manager->interfaceCount++;
    pthread_mutex_unlock(&manager->mutex);
}

void interfaceConfigDestroy(NetworkManager* manager, char* id) {
    for (int i = 0; i < manager->interfaceCount; i++) {
        if (strcmp(manager->interfaces[i].id, id) == 0) {
            free(manager->interfaces[i].id);
            free(manager->interfaces[i].queueBuffer);
            memmove(&manager->interfaces[i], &manager->interfaces[i + 1], (manager->interfaceCount - i - 1) * sizeof(InterfaceConfig));
            manager->interfaceCount--;
            return;
        }
    }
}

void interfaceStateUpdate(NetworkManager* manager, char* id, int state) {
    for (int i = 0; i < manager->interfaceCount; i++) {
        if (strcmp(manager->interfaces[i].id, id) == 0) {
            pthread_mutex_lock(&manager->mutex);
            manager->interfaces[i].state = state;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }
}

