fn process_files(socket: &mut TcpStream) {
    let mut file = File::open("output.ll").unwrap();
    let mut writer = OpenOptions::new().read(true).write(true).open("output.ll").unwrap();

    loop {
        match socket.read_until(b"\0", 1024) {
            Ok(mut buf) => {
                if buf.is_empty() {
                    break;
                }
                let file_name = String::from_utf8_lossy(&buf[..buf.len()-1]);
                let file_contents = buf.get(..buf.len()-1).unwrap();
                process_file(file_name.clone(), file_contents);
                writer.write_all(&buf).unwrap();
            },
            Err(_) => {
                println!("Connection timed out");
                break;
            }
        }
    }

    drop(writer);
}

fn process_file(name: String, contents: &[u8]) {
    let lexer = Lexer::new();
    let parser = Parser::new();
    let llvmdir = LLVMIr::new();

    for line in contents.split(b"\n") {
        let tokens = lexer.tokenize(String::from_utf8_lossy(line).to_string());
        let result = parser.parse(&tokens);
        for (key, value) in result {
            println!("{}: {}", key, value);
            llvmdir.generate_ir();
        }
    }
}

fn main() {
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();

    loop {
        match listener.accept() {
            Ok((stream, _)) => {
                process_files(&mut stream);
            },
            Err(_) => {
                println!("Error accepting connection");
            }
        }
    }
}
