} memory_pool;

// Temperature interpolation algorithm
float interpolate_temperature(float x0, float y0, float x1, float y1, float x) {
    return (y1 - y0) * ((x - x0) / (x1 - x0)) + y0;
}

// NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate and populate list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_list(int n, memory_pool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)pool->ptr;

    for (int i = 0; i < n; i++) {
        p[i].RNTI = rand() % 10000;
        p[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        p[i].CRC_INDICATION_REL8_TAG = rand() % 10000;

        // Set CRCFLAG randomly
        p[i].CRCFLAG = (rand() & 1) ? 0 : 1;
    }
}

// Function to process temperature readings and sensor identifiers
void process_temperature(int n, memory_pool* pool, float (*temperature_readings)[], int* num_sensors) {
    for (int i = 0; i < n; i++) {
        // Interpolate temperature values within range [20, 50]
        float temperature = interpolate_temperature(0, 20, *num_sensors - 1, 50, i);

        if (temperature > 50) {
            temperature = 50;
        } else if (temperature < 20) {
            temperature = 20;
        }

        // Store interpolated temperature value in memory pool
        ((float*)pool->ptr)[i] = temperature;
    }
