        float num;
        if(scanf("%f", &num) == 1) {
            *numbers = num;
            break;
        }
    }

    int count = 0;
    while(scanf("%f", &num) == 1) {
        *(numbers + ++count) = num;
    }

    float average = calculate_average(numbers, count);

    printf("Average: %f\n", average);

    free(ue_context_tags);
    free(numbers);

    return 0;
