#define LTE_DL_FRAME_STRUCT_SIZE 1024
#define PDSCH_DATA_SIZE 256
#define CQI_VALUES_SIZE 16

typedef struct {
    DL_FRAME_HEADER header;
    PDSCH_SYMBOL symbol;
    char pdsch_data[PDSCH_DATA_SIZE];
    uint8_t cqi[CQI_VALUES_SIZE];
} LTE_DL_FRAME_STRUCT;

void* lte_dl_frame_struct_init(int num_frames) {
    // Initialize memory pool
    size_t pool_size = sizeof(LTE_DL_FRAME_STRUCT) * 100; // Start with a default pool size of 100 frames
    char* pool = malloc(pool_size);
    if (!pool) return NULL;

    int frames_allocated = 0;
    LTE_DL_FRAME_STRUCT** frames = (LTE_DL_FRAME_STRUCT**)malloc(num_frames * sizeof(LTE_DL_FRAME_STRUCT*));
    if (!frames) {
        free(pool); // Clean up the memory pool
        return NULL;
    }

    for (int i = 0; i < num_frames; i++) {
        LTE_DL_FRAME_STRUCT* frame = (LTE_DL_FRAME_STRUCT*)malloc(sizeof(LTE_DL_FRAME_STRUCT));
        if (!frame) break;

        frame->header.timestamp = i * 10;
        frame->symbol.type = PDSCH_SYMBOL_TYPE_NORMAL;
        for (int j = 0; j < CQI_VALUES_SIZE; j++) {
            frame->cqi[j] = rand() % 256; // Generate random CQI values
        }

        // Simulate channel conditions and update CQI values periodically
        if ((i + 1) % 10 == 0) { // Update every 10 frames
            for (int j = 0; j < CQI_VALUES_SIZE; j++) {
                frame->cqi[j] += rand() % 16 - 8; // Simulate channel conditions and update CQI values
            }
        }

        frame->pdsch_data = rand_bytes(PDSCH_DATA_SIZE); // Generate random PDSCH data

        frames[i] = frame;
        frames_allocated++;

        if (frames_allocated == num_frames) break;

        // Reuse memory blocks from the pool to minimize reallocations
        size_t remaining_pool_size = pool_size - (frames_allocated * sizeof(LTE_DL_FRAME_STRUCT));
        char* new_pool = realloc(pool, remaining_pool_size);
        pool = new_pool;
    }

    // Clean up partially allocated data in case of failure
    for (int i = 0; i < frames_allocated; i++) {
        free(frames[i]);
    }
    free(frames);

    return pool;
}

// Periodically check and update CQI values based on simulated channel conditions
void lte_dl_frame_struct_update_cqi(LTE_DL_FRAME_STRUCT* frame) {
    for (int j = 0; j < CQI_VALUES_SIZE; j++) {
        frame->cqi[j] += rand() % 16 - 8; // Simulate channel conditions and update CQI values
    }
}

// Log the initialization process, including start time, end time, and any errors encountered during initialization
void lte_dl_frame_struct_log_init(int num_frames) {
    printf("Initializing LTE DL frame struct with %d frames...\n", num_frames);
    // Add logging mechanism to log start time, end time, and any errors
}

