    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->messages = (LtePhyLayerControlMessage**)malloc(initial_capacity * sizeof(LtePhyLayerControlMessage*));
    arr->capacity = initial_capacity;
