// Custom memory pool
struct MemoryPool {
    void* start;
    size_t size;
    size_t capacity;
};

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n, float probability) {
    // Initialize random number generator
    srand(time(NULL));

    // Create a custom memory pool with initial capacity of 1000 elements
    struct MemoryPool pool = {malloc(1000 * sizeof(NFAPI_CRC_INDICATION_PDU_T)), 1000 * sizeof(NFAPI_CRC_INDATION_PDU_T), 1000};

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < n; i++) {
        // Randomly set CRCFLAG based on probability
        int crcflag = rand() % 2 == 0 ? 1 : (rand() % 1000 < (int)(probability * 1000)) ? 1 : 0;

        NFAPI_CRC_INDICATION_PDU_T* new_element = pool.start + i;
        new_element->RX_UE_INFORMATION_TAG = i;
        new_element->RNTI = i;
        new_element->CRC_INDICATION_REL8_TAG = i;
        new_element->CRCFLAG = crcflag;

        if (i == 0) {
            head = new_element;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->RX_UE_INFORMATION_TAG < i) {
                current = current->next;
            }
            current->next = new_element;
        }
    }

    // Monitor memory pool usage
    size_t allocated = 0;
    for (NFAPI_CRC_INDICATION_PDU_T* current = head; current != NULL; current = current->next) {
        allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    printf("Memory pool used: %zu bytes\n", allocated);

    // Log statistics
    int success_rate = (int)((n - __errno()) / n * 100.0f);
    printf("CRCFLAG randomization success rate: %d%%\n", success_rate);

    return head;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* list = create_linked_list(100, 0.5f);
    return 0;
}
