void process_nfaapi_and_find_max() {
    srand(time(NULL));
    const int N = 1000000; // adjust according to requirements
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDATION_PDU_T));

    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdu_list[i].RNTI = rand() % 100;
        pdu_list[i].CRC_INDICATION_REL8_TAG[0] = '1' + (rand() % 2);
    }

    int max_int = INT_MIN; // initialize with minimum possible integer
    int* arr = NULL;

    for (;;) {
        int num;
        if ((scanf("%d", &num) == 1) && (num > 0)) {
            if (!arr) {
                arr = (int *)malloc(1 * sizeof(int));
                arr[0] = num;
            } else {
                arr = (int *)realloc(arr, (arr[0] + 1) * sizeof(int));
                arr[arr[0]] = num;
            }
        } else if (feof(stdin)) {
            break;
        } else {
            printf("Invalid input. Please enter a positive integer.\n");
            rewind(stdin);
        }

        for (int i = 0; i <= arr[0]; i++) {
            int max = find_largest_integer(arr, i);
            if (max > max_int) {
                max_int = max;
            }
        }
    }

    printf("The largest integer is: %d\n", max_int);

    for (int i = 0; i <= arr[0]; i++) {
        free((void *)arr + i * sizeof(int));
    }
    free(arr);

    FILE* error_log = fopen("error_log.txt", "a");
    if (!error_log) {
        // handle file open error
    } else {
        fprintf(error_log, "Function executed successfully.\n");
        fclose(error_log);
    }
}

