#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;
    char event_type;
    int source_id;
    char* payload;
} Event;

typedef struct {
    Event* events;
    size_t capacity;
    size_t size;
} EventStore;

EventStore* event_store_create(size_t initial_capacity) {
    EventStore* store = malloc(sizeof(EventStore));
    store->events = calloc(initial_capacity, sizeof(Event));
    store->capacity = initial_capacity;
    store->size = 0;
    return store;
}

void event_store_free(EventStore* store) {
    for (size_t i = 0; i < store->size; i++) {
        free(store->events[i].payload);
    }
    free(store->events);
    free(store);
}

int event_store_add_event(EventStore* store, Event event) {
    if (store->size >= store->capacity) {
        // Double the capacity and realloc
        store->capacity *= 2;
        store->events = realloc(store->events, store->capacity * sizeof(Event));
    }
    store->events[store->size] = event;
    store->size++;
    return 0;
}

int event_store_update_event(EventStore* store, int source_id, const char* payload) {
    for (size_t i = 0; i < store->size; i++) {
        if (store->events[i].source_id == source_id) {
            free(store->events[i].payload);
            store->events[i].payload = strdup(payload);
            return 0;
        }
    }
    return -1; // Event not found
}

Event* event_store_get_events(EventStore* store, long start_timestamp, long end_timestamp) {
    Event* result = NULL;
    size_t count = 0;

    for (size_t i = 0; i < store->size; i++) {
        if (store->events[i].timestamp >= start_timestamp && store->events[i].timestamp <= end_timestamp) {
            result = realloc(result, (count + 1) * sizeof(Event));
            memcpy(&result[count], &store->events[i], sizeof(Event));
            count++;
        }
    }

    return result;
}

int main() {
    EventStore* store = event_store_create(10);

    // Add some events
    Event e1 = {1643723400, 'A', 1, "Payload 1"};
    Event e2 = {1643723410, 'B', 2, "Payload 2"};
    Event e3 = {1643723420, 'C', 1, "Payload 3"};

    event_store_add_event(store, e1);
    event_store_add_event(store, e2);
    event_store_add_event(store, e3);

    // Update an event
    int result = event_store_update_event(store, 1, "New Payload");
    if (result != 0) {
        printf("Error updating event\n");
    }

    // Retrieve events within a time range
    Event* retrieved_events = event_store_get_events(store, 1643723410, 1643723430);
    for (size_t i = 0; i < store->size; i++) {
        printf("%ld %c %d %s\n", retrieved_events[i].timestamp, retrieved_events[i].event_type, retrieved_events[i].source_id, retrieved_events[i].payload);
    }
    free(retrieved_events);

    event_store_free(store);

    return 0;
}

