#define MAX_NFAPI 10000
#define MAX_INPUT_SIZE 1000000
#define MAX_LOG_LENGTH 1024
#define MAX_MEMORY_USAGE 16*1024*1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int process_nfaapi_crc_and_input(int N) {
    // Initialize hash table to track RNTI occurrences
    int* rnti_table = (int*)calloc(10000, sizeof(int));
    for (int i = 0; i < 10000; i++) {
        rnti_table[i] = -1;
    }

    // Generate NFAPI CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* nfa_puds = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_NFAPI, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < MAX_NFAPI && N > 0; i++) {
        int rnti = rand() % 10000;
        while (rnti_table[rnti] >= 0 || --N <= 0) {
            rnti = rand() % 10000;
        }
        rnti_table[rnti] = i;

        nfa_puds[i].RX_UE_INFORMATION_TAG = i;
        nfa_puds[i].RNTI = rnti;
        nfa_puds[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
        nfa_puds[i].CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    // Read input integers from standard input
    int* inputs = NULL;
    int num_inputs = 0;
    FILE* input_file = fopen("input.txt", "r");
    if (input_file) {
        char buffer[32];
        while (fscanf(input_file, "%s", buffer) == 1 && num_inputs < MAX_INPUT_SIZE) {
            inputs = realloc(inputs, sizeof(int)*(num_inputs+1));
            inputs[num_inputs++] = atoi(buffer);
        }
        fclose(input_file);
    }

    // Find largest integer in the input array
    int largest_integer = find_largest_integer(inputs, num_inputs);

    // Simulate network API call with NET_ID and SESS_ID parameters
    char net_id[16];
    char sess_id[16];
    FILE* api_call_file = fopen("api_call.txt", "r");
    if (api_call_file) {
        fscanf(api_call_file, "%15s %15s", net_id, sess_id);
        fclose(api_call_file);
    }

    // Validate API parameters
    if (strlen(net_id) > 15 || strlen(sess_id) > 15) {
        return -1;
    }

    // Log function execution and results
    time_t start_time = time(NULL);
    FILE* log_file = fopen("crc_output.log", "w");
    fprintf(log_file, "Start time: %s\n", ctime(&start_time));
    fprintf(log_file, "NFAPI CRC indication PDUs generated: %d\n", i+1);
    fprintf(log_file, "Largest integer found: %d\n", largest_integer);

    // Check for uniqueness of RNTI occurrences
    int rnti_duplicates = 0;
    for (int i = 0; i < MAX_NFAPI && nfa_puds[i].RNTI >= 0; i++) {
        if (rnti_table[nfa_puds[i].RNTI] > 1) {
            rnti_duplicates++;
        }
    }

    // Print log and close files
    fprintf(log_file, "RNTI duplicates: %d\n", rnti_duplicates);
    fclose(log_file);

    return 0;
}

int find_largest_integer(int* inputs, int num_inputs) {
    int largest = inputs[0];
    for (int i = 1; i < num_inputs; i++) {
        if (inputs[i] > largest) {
            largest = inputs[i];
        }
    }
    return largest;
}
