void createNFApiCrcIndicationPduT(int n, void* memPool) {
    NFAPI_CRC_INDICATION_PDU_T* pduTList = (NFAPI_CRC_INDATION_PDU_T*)memPool->malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pduTList == NULL) {
        printf("Error: Memory allocation failed for creating NFAPI CRC INDICATION PDU T structures.\n");
