#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    int id;
    char *config;
    void *buffer;
} NME;

typedef struct {
    time_t timestamp;
    char *kpi_tags;
    void *raw_data;
} PerformanceRecord;

NME *nmes = NULL;
int nme_count = 0;

void create_nme(int id, char *config) {
    // Memory allocation for NME
    NME *new_nme = malloc(sizeof(NME));
    new_nme->id = id;
    new_nme->config = config;
    new_nme->buffer = malloc(1024); // Initial buffer size

    // Add new NME to the list
    nmes = realloc(nmes, (nme_count + 1) * sizeof(NME));
    nmes[nme_count] = *new_nme;
    nme_count++;

    return;
}

void update_nme(int id, char *kpi_tags, void *raw_data) {
    // Find NME by ID
    for (int i = 0; i < nme_count; i++) {
        if (nmes[i]->id == id) {
            // Update NME's performance record
            PerformanceRecord *record = malloc(sizeof(PerformanceRecord));
            record->timestamp = time(NULL);
            record->kpi_tags = kpi_tags;
            record->raw_data = raw_data;

            // Store the updated record in the file-based database
            int fd = open("nme_db", O_RDWR | O_CREAT, 0644);
            if (fd >= 0) {
                write(fd, &record, sizeof(PerformanceRecord));
                close(fd);
            } else {
                perror("Error opening file");
            }

            return;
        }
    }
}

void read_kpi_values() {
    int kpi_values_count = 10; // Assuming a fixed number of KPI values for now
    float *kpi_values = malloc(kpi_values_count * sizeof(float));

    // Read KPI values from standard input
    FILE *fp = fopen("stdin", "r");
    if (fp) {
        int i;
        for (i = 0; i < kpi_values_count; i++) {
            fscanf(fp, "%f\n", &kpi_values[i]);
        }
        fclose(fp);
    } else {
        perror("Error reading KPI values");
    }

    // Find the highest KPI value using a helper function
    float max_kpi = find_max_kpi(kpi_values, kpi_values_count);

    printf("Highest KPI value: %f\n", max_kpi);

    free(kpi_values);
}

float find_max_kpi(float *kpi_values, int count) {
    float max = kpi_values[0];
    for (int i = 1; i < count; i++) {
        if (kpi_values[i] > max)
            max = kpi_values[i];
    }
    return max;
}

void initialize_nme_db() {
    // Initialize the file-based database
    int fd = open("nme_db", O_RDWR | O_CREAT, 0644);
    if (fd >= 0) {
        write(fd, "NME_DB initialized.\n", 18);
        close(fd);
    } else {
        perror("Error initializing NME DB");
    }
}

void persist_nme_records() {
    // Read existing records from the file-based database
    FILE *fp = fopen("nme_db", "r");
    if (fp) {
        // Process and store the records in memory
        while (!feof(fp)) {
            PerformanceRecord record;
            fread(&record, sizeof(PerformanceRecord), 1, fp);
            // Store the record in memory...
        }
        fclose(fp);
    } else {
        perror("Error reading NME DB");
    }
}

int main() {
    create_nme(1, "config_1");
    update_nme(1, "kpi_tags_1", &raw_data);

    read_kpi_values();

    persist_nme_records();

    return 0;
}
