#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct for message
typedef struct {
    int id;
    time_t timestamp;
    int priority;
} Message;

// Define a linked list node for messages
typedef struct Node {
    Message *msg;
    struct Node* next;
} Node;

// Function to add a new message
void addMessage(Node** head, Message* newMsg) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->msg = newMsg;
    newNode->next = (*head);
    (*head) = newNode;
}

// Function to remove a message based on its ID
void removeMessage(Node** head, int id) {
    if ((*head)->msg->id == id) {
        Node* temp = (*head);
        (*head) = (*head)->next;
        free(temp);
    } else {
        Node* current = (*head);
        while (current && current->next && current->next->msg->id != id) {
            current = current->next;
        }
        if (current && current->next) {
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
        }
    }
}

// Function to list all messages sorted by priority
void listMessages(Node* head, int* count) {
    Node* current = head;
    Message* previousPriority = NULL;
    while (current) {
        if (!previousPriority || current->msg->priority > previousPriority->priority) {
            printf("Timestamp: %ld, ID: %d, Priority: %d\n", current->msg->timestamp, current->msg->id, current->msg->priority);
            previousPriority = current->msg;
        }
        current = current->next;
    }
}

// Function to update timestamps of inactive messages
void updateTimestamps(Node** head) {
    time_t currentTime = time(NULL);
    Node* current = *head;
    while (current) {
        if (difftime(currentTime, current->msg->timestamp) > 600) { // Update timestamp for inactive messages
            current->msg->timestamp = currentTime;
        }
        current = current->next;
    }
}

int main() {
    Node* head = NULL;

    Message msg1 = {1, time(NULL), 2};
    addMessage(&head, &msg1);

    Message msg2 = {2, time(NULL), 3};
    addMessage(&head, &msg2);

    removeMessage(&head, 2);

    int count;
    listMessages(head, &count);

    updateTimestamps(&head);

    return 0;
}
