#define MAX_LIST_SIZE 1000
#define RNTI_UNIQUE_CHECK 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list = NULL;
int list_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *handle_list(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    while (1) {
        pthread_mutex_lock(&lock);

        if (list_size >= MAX_LIST_SIZE) {
            printf("List size exceeded maximum limit\n");
            break;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 65536;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu->CRCFLAG = (rand() % 2) ? 1 : 0;

        int found = 0;
        for (int i = 0; i < list_size; i++) {
            if (pdu->RNTI == list[i].RNTI) {
                found = 1;
                break;
            }
        }

        if (!found) {
            list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_size + 1));
            list[list_size].RX_UE_INFORMATION_TAG = pdu->RX_UE_INFORMATION_TAG;
            list[list_size].RNTI = pdu->RNTI;
            list[list_size].CRC_INDICATION_REL8_TAG = pdu->CRC_INDICATION_REL8_TAG;
            list[list_size].CRCFLAG = pdu->CRCFLAG;
            list_size++;
        } else {
            printf("Error: RNTI already exists in the list\n");
            pthread_mutex_unlock(&lock);
            free(pdu);
            return (void *)1; // or any other value to signal error
        }

        pthread_mutex_unlock(&lock);
    }

    free(pdu);
    return NULL;
}

int main() {
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, handle_list, NULL);
    if (ret) {
        printf("Error creating thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    for (int i = 0; i < list_size; i++) {
        printf("%d %d %d %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG, list[i].CRCFLAG);
    }

    free(list);
    return 0;
}
