        // Handle memory allocation failure
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays with random values
    for (size_t i = 0; i < size; i++) {
        offsets[i] = (long) rand();
        keys[i] = (int) rand() % 100;
        records[i] = (Record*) malloc(sizeof(Record));
        if (!records[i]) {
            // Handle memory allocation failure
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; j++) {
                free(records[j]);
            }
            return NULL;
        }
        records[i]->value = rand() % 100;
    }

    // Return the initialized arrays
    return malloc(sizeof(void*) * 3);
}

// Function to iterate over populated arrays
void iterateArrays(void* ptr, size_t size) {
    long* offsets = (long*) ((char*) ptr + sizeof(void*));
    int* keys = (int*) ((char*) ptr + sizeof(void*) * 2);
    Record** records = (Record**) ((char*) ptr + sizeof(void*) * 3);

    for (size_t i = 0; i < size; i++) {
        printf("Offset: %ld, Key: %d, Value: %d\n", offsets[i], keys[i], records[i]->value);
    }
}

// Function to release allocated resources
void releaseArrays(void* ptr) {
    free(((char*) ptr + sizeof(void*) * 3));
    for (size_t i = 0; i < size; i++) {
        free(records[i]);
    }
}
