#include <string.h>

typedef struct {
    // LTE下行数据包头
    char header[16];
    // 序列号(SN)
    int sequence_number;
    // CRC校验信息
    unsigned short crc;
} DL_DATA_PDU;

// 管理动态分配的链表结构体
typedef struct _LinkedList {
    DL_DATA_PDU* data;
    struct _LinkedList* next;
} LinkedList;

// 函数：初始化和管理链表
DL_DATA_PDU* initialize_and_manage_linked_list(int N) {
    if (N < 1 || N > 10000) {
        return NULL; // 验证失败，返回错误代码
    }

    LinkedList* head = (LinkedList*)malloc(sizeof(LinkedList));
    head->data = (DL_DATA_PDU*)malloc(N * sizeof(DL_DATA_PDU));
    head->next = NULL;

    for (int i = 0; i < N; i++) {
        // 设置序列号(SN)的奇偶性
        int sn = i % 2;
        head->data[i].sequence_number = sn;
        // 设置CRC校验信息
        head->data[i].crc = (unsigned short)(sn ^ (sn >> 1));
    }

    return head->data;
}

// 释放链表中的内存
void free_linked_list(DL_DATA_PDU* data) {
    while (data != NULL) {
        DL_DATA_PDU* next = data + 1;
        free(data);
        data = next;
    }
}
