    }

    return contexts;
}

int lte_ue_context_destroy(void** contexts, int n) {
    for (int i = 0; i < n; i++) {
        if (contexts[i]) {
            free(contexts[i]);
        }
    }
    free(contexts);
    return 0;
}

void lte_ue_context_update_status(void* context) {
    LTE_UeContext* ctx = (LTE_UeContext*)context;

    // Calculate RLC Status based on successful transmissions and total transmissions
    ctx->rlc_status = (ctx->pdcp_sn > 0 ? (ctx->pdcp_sn * 100) / (ctx->pdcp_sn + 1) : -1);
}

int main() {
    int N = 5;
    void* contexts = lte_ue_context_create(N);

    // Update context status
    for (int i = 0; i < N; i++) {
        LTE_UeContext* ctx = (LTE_UeContext*)contexts[i];
        ctx->pdcp_sn = i * 10;
        lte_ue_context_update_status(contexts[i]);
    }

