typedef struct {
    char filePath[256];
    int transactionId;
    int status;
    time_t lastModified;
} LogEntry;

void addLog(LogEntry** logs, int* logCount, const char* filePath, int transactionId) {
    *logCount += 1;
    (*logs) = realloc((*logs), (*logCount) * sizeof(LogEntry));
    strcpy((*logs)[(*logCount) - 1].filePath, filePath);
    (*logs)[(*logCount) - 1].transactionId = transactionId;
    (*logs)[(*logCount) - 1].status = 0; // Initial status is "in-progress"
    (*logs)[(*logCount) - 1].lastModified = time(NULL);
}

void updateLogs(LogEntry** logs, int* logCount) {
    for (int i = 0; i < *logCount; i++) {
        if ((time(NULL) - (*logs)[i].lastModified) / 60 > 30) {
            (*logs)[i].status = 1;
        }
    }
}

void removeLog(LogEntry** logs, int* logCount, int transactionId) {
    for (int i = 0; i < *logCount; i++) {
        if ((*logs)[i].transactionId == transactionId) {
            memmove((*logs) + i, (*logs) + i + 1, sizeof(LogEntry) * (*logCount - i));
            *logCount -= 1;
            return;
        }
    }
}

void listLogs(const LogEntry* logs, int logCount) {
    for (int i = 0; i < logCount; i++) {
        printf("File Path: %s, Transaction ID: %d, Status: %d, Last Modified: %ld\n", 
               logs[i].filePath, logs[i].transactionId, logs[i].status, logs[i].lastModified);
    }
}

void exportLogs(const LogEntry* logs, int logCount) {
    FILE* csvFile = fopen("logs.csv", "w");
    if (csvFile != NULL) {
        for (int i = 0; i < logCount; i++) {
            fprintf(csvFile, "%s,%d,%d,%ld\n", logs[i].filePath, logs[i].transactionId, logs[i].status, logs[i].lastModified);
        }
        fclose(csvFile);
    }
}
