import org.apache.commons.net.ssh.*;
import ch.qos.logback.classic.*;

public class RemoteScriptExecutor {
    public static void main(String[] args) throws IOException, InterruptedException {
        // Load configuration and command-line parameters
        Properties props = new Properties();
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            props.load(fis);
        }
        System.out.println("Loading configuration...");

        String serverHost = props.getProperty("server.host");
        int serverPort = Integer.parseInt(props.getProperty("server.port"));
        String username = props.getProperty("server.username");
        String password = props.getProperty("server.password");
        String remoteScriptPath = props.getProperty("remote.script.path");
        int timeoutSeconds = Integer.parseInt(props.getProperty("timeout.seconds"));

        // Connect to the production server via SSH
        System.out.println("Connecting to " + serverHost + "...");
        try (SSHFactory factory = new SSHFactory();
             SSHPool pool = factory.getPool(new HostKeyVerifier(), true)) {
            SSHPoolConfig config = pool.getConfig();
            config.setConnectTimeout(1000);
            config.setMaxConnectionsPerHost(10);
            config.setMaxTotalConnections(50);

            // Establish a connection to the server
            Session session = pool.acquire(null, null);
            if (session != null) {
                System.out.println("Connected to " + serverHost + "...");

                // Execute the remote script and capture output
                Command command = new Command("bash", "-c", "cd /path/to/script; ./script.sh");
                command.setStdin(new ByteArrayInputStream((remoteScriptPath + "\n").getBytes()));
                ByteArrayOutputStream bos = new ByteArrayOutputStream();
                PrintStream out = new PrintStream(bos);
                PrintStream err = System.err;

                try {
                    session.executeCommand(command).setExitStatus(0);
                    out.println("Script execution started...");

                    // Capture output and error streams
                    command.getStdout().transferTo(out, bos);
                    command.getStderr().transferTo(err, bos);

                    // Log the output and error streams to the centralized logging service
                    System.out.println(bos.toString());

                } catch (IOException | InterruptedException e) {
                    System.err.println("Error executing script: " + e.getMessage());
                    bos.close();
                    err.close();
                }

                // Close the SSH session and pool
                session.close();
            } else {
                System.out.println("Failed to connect to " + serverHost + ".");
            }
        }

        // Delete local configuration file (if it exists)
        File configFile = new File("config.properties");
        if (configFile.exists()) {
            try {
                Files.deleteIfExists(configFile.toPath());
                System.out.println("Local config file deleted.");
            } catch (IOException e) {
                System.err.println("Error deleting local config file: " + e.getMessage());
            }
        }
    }
}
