#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure to represent custom messages
typedef struct {
    time_t timestamp;
    int id;
    int priority;
} Message;

// Initialize the list of messages with NULL as the head and tail
Message* message_list = NULL;
Message* last_message = NULL;

// Function to add new messages to the list
void add_message(int id, int priority) {
    // Create a new message structure
    Message* new_message = (Message*)malloc(sizeof(Message));
    if (!new_message) {
        printf("Memory allocation failed\n");
        return;
    }

    new_message->id = id;
    new_message->priority = priority;
    new_message->timestamp = time(NULL);

    // Update the list with the new message
    if (message_list == NULL) {
        message_list = new_message;
        last_message = new_message;
    } else {
        last_message->next = new_message;
        last_message = new_message;
    }
}

// Function to remove a message based on its ID
void remove_message(int id) {
    Message* current = message_list;
    Message* previous = NULL;

    while (current != NULL && current->id != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Message not found\n");
        return;
    } else if (previous == NULL) {
        message_list = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

// Function to list all messages sorted by priority level
void list_messages() {
    Message* current = message_list;

    while (current != NULL) {
        printf("ID: %d, Priority: %d, Timestamp: %ld\n", current->id, current->priority, current->timestamp);
        current = current->next;
    }
}

// Function to update timestamps of inactive messages
void update_timestamps() {
    time_t current_time = time(NULL);

    Message* current = message_list;

    while (current != NULL) {
        if ((current->timestamp + 600) < current_time) {
            // Update the timestamp and mark as active
            current->timestamp = current_time;
        }

        current = current->next;
    }
}
