    int rrc_connection;
    // DL_FRAME structure
    int dl_frame;
    // dynamically allocated PHY_VARS_eNB structure
    void* phy_vars_enb;
} LTE_DL_FRAMEINFO;

// Function to manage dynamic array of LTE_DL_FRAMEINFO structures
void manage_lte_dl_frames(LTE_DL_FRAMEINFO** frames, int* frame_count, int max_frames) {
    // Allocate memory for the dynamic array
    *frames = (LTE_DL_FRAMEINFO*)malloc(max_frames * sizeof(LTE_DL_FRAMEINFO));

    // Initialize frame count to 0
    *frame_count = 0;
}

// Function to add a new LTE_DL_FRAMEINFO structure to the dynamic array
void lte_dl_frame_add(LTE_DL_FRAMEINFO** frames, int* frame_count, int max_frames) {
    if (*frame_count < max_frames) {
        // Allocate memory for the new frame info
        frames[*frame_count] = (LTE_DL_FRAMEINFO*)malloc(sizeof(LTE_DL_FRAMEINFO));

        // Initialize frame info fields
        frames[*frame_count]->rrc_connection = 0;
        frames[*frame_count]->dl_frame = 0;
        frames[*frame_count]->phy_vars_enb = NULL;

        (*frame_count)++;
    }
}

// Function to update an existing LTE_DL_FRAMEINFO structure in the dynamic array
void lte_dl_frame_update(LTE_DL_FRAMEINFO** frames, int frame_index) {
    if (frame_index < *frame_count) {
        // Update frame info fields
        frames[frame_index]->rrc_connection = 0;
        frames[frame_index]->dl_frame = 0;

        // Reallocate memory for the updated phy_vars_enb structure
        frames[frame_index]->phy_vars_enb = realloc(frames[frame_index]->phy_vars_enb, sizeof(void*));
    }
}

// Function to retrieve an existing LTE_DL_FRAMEINFO structure from the dynamic array
LTE_DL_FRAMEINFO* lte_dl_frame_get(LTE_DL_FRAMEINFO** frames, int frame_index) {
    if (frame_index < *frame_count) {
        return &frames[frame_index][0];
    } else {
        return NULL;
    }
}

int main() {
    // Initialize dynamic array and frame count
    LTE_DL_FRAMEINFO* frames = NULL;
    int frame_count = 0;

    // Add 100,000 frames to the dynamic array
    manage_lte_dl_frames(&frames, &frame_count, 100000);

    for (int i = 0; i < 100000; i++) {
        lte_dl_frame_add(&frames, &frame_count, 100000);

        // Update frame info fields
        frames[i].rrc_connection = i;
        frames[i].dl_frame = i * 2;

        // Reallocate memory for the updated phy_vars_enb structure
        frames[i].phy_vars_enb = realloc(frames[i].phy_vars_enb, sizeof(void*));
    }

    // Retrieve a frame from the dynamic array
    LTE_DL_FRAMEINFO* retrieved_frame = lte_dl_frame_get(&frames, 50000);

    if (retrieved_frame != NULL) {
        printf("Frame RRCConnection: %d\n", retrieved_frame->rrc_connection);
        printf("Frame DL_FRAME: %d\n", retrieved_frame->dl_frame);

        // Free allocated memory
        free(retrieved_frame->phy_vars_enb);
    }

    return 0;
}
