#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the LTE_DL_FRAMEINFO structure
typedef struct {
    RRCConnection rrcConnection;
    DL_FRAME dlFrame;
    PHY_VARS_eNB *phyVars;
} LTE_DL_FRAMEINFO;

// Define the dynamic array type
typedef struct {
    int size;
    int capacity;
    LTE_DL_FRAMEINFO **frames;
} LTE_DL_FRAME_ARRAY;

// Function to initialize and allocate memory for the frame array
LTE_DL_FRAME_ARRAY* initLTE_DL_FRAME_ARRAY(int initialCapacity) {
    LTE_DL_FRAME_ARRAY* arr = (LTE_DL_FRAME_ARRAY*)malloc(sizeof(LTE_DL_FRAME_ARRAY));
    arr->size = 0;
    arr->capacity = initialCapacity;
    arr->frames = (LTE_DL_FRAMEINFO**)calloc(initialCapacity, sizeof(LTE_DL_FRAMEINFO*));
    return arr;
}

// Function to add a new frame to the array
void addFrameToArr(LTE_DL_FRAME_ARRAY* arr, LTE_DL_FRAMEINFO* frame) {
    if (arr->size == arr->capacity) {
        // Reallocate memory when capacity is reached
        int newSize = arr->capacity * 2;
        LTE_DL_FRAMEINFO** newFrames = (LTE_DL_FRAMEINFO**)realloc(arr->frames, newSize * sizeof(LTE_DL_FRAMEINFO*));
        arr->capacity = newSize;
        arr->frames = newFrames;
    }
    arr->frames[arr->size] = frame;
    arr->size++;
}

// Function to update a frame in the array
void updateFrameInArr(LTE_DL_FRAME_ARRAY* arr, int index, LTE_DL_FRAMEINFO* updatedFrame) {
    if (index < 0 || index >= arr->size) return; // Handle out-of-bounds errors
    arr->frames[index]->rrcConnection = updatedFrame->rrcConnection;
    arr->frames[index]->dlFrame = updatedFrame->dlFrame;
}

// Function to retrieve a frame from the array
LTE_DL_FRAMEINFO* getFrameFromArr(LTE_DL_FRAME_ARRAY* arr, int index) {
    if (index < 0 || index >= arr->size) return NULL; // Handle out-of-bounds errors
    return arr->frames[index];
}
