// Structure for records
typedef struct {
    int value;
} Record;

// Dynamic memory management structure
typedef struct {
    long *offsets; // Array of offset values (n)
    int *keys;      // Array of keys (m)
    Record **records;  // Array of record pointers (k)
    size_t records_count; // Current number of allocated records
    size_t total_records_capacity; // Total capacity for allocated records
} DynamicMemory;

// Function to allocate memory and initialize records
DynamicMemory *allocate_memory(int n, int m, int k) {
    DynamicMemory *memory = malloc(sizeof(DynamicMemory));
    if (memory == NULL) return NULL;

    memory->offsets = malloc(n * sizeof(long));
    if (memory->offsets == NULL) {
        free(memory);
        return NULL;
    }

    memory->keys = malloc(m * sizeof(int));
    if (memory->keys == NULL) {
        free(memory->offsets);
        free(memory);
        return NULL;
    }

    memory->records = malloc(k * sizeof(Record *));
    if (memory->records == NULL) {
        free(memory->offsets);
        free(memory->keys);
        free(memory);
        return NULL;
    }

    for (int i = 0; i < k; ++i) {
        memory->records[i] = malloc(sizeof(Record));
        if (memory->records[i] == NULL) {
            // Handle allocation failure and deallocation
            for (int j = 0; j < i; ++j) {
                free(memory->records[j]);
            }
            for (int j = 0; j < m; ++j) {
                free((void *)memory->keys);
            }
            for (int j = 0; j < n; ++j) {
                free((void *)memory->offsets);
            }
            free(memory);
            return NULL;
        }

        // Initialize record values
        memory->records[i]->value = rand() % 1001;
    }

    memory->records_count = k;
    memory->total_records_capacity = k;

    return memory;
}

// Function to free allocated memory
void free_memory(DynamicMemory *memory) {
    for (int i = 0; i < memory->records_count; ++i) {
        free(memory->records[i]);
    }

    free((void *)memory->keys);
    free((void *)memory->offsets);
    free(memory);
}

// Function to compute the sum of record values
int get_sum(DynamicMemory *memory) {
    int total = 0;
    for (int i = 0; i < memory->records_count; ++i) {
        total += memory->records[i]->value;
    }

    return total;
}

// Function to dynamically resize the memory pool and add new records
DynamicMemory *resize_memory(DynamicMemory *memory, int new_records_count) {
    if (new_records_count > memory->total_records_capacity) {
        // Handle insufficient memory availability
        return NULL;
    }

    for (int i = memory->records_count; i < new_records_count; ++i) {
        memory->records[i] = malloc(sizeof(Record));
        if (memory->records[i] == NULL) {
            // Handle allocation failure and deallocation
            for (int j = 0; j < i; ++j) {
                free(memory->records[j]);
            }
            for (int j = 0; j < memory->records_count; ++j) {
                free((void *)memory->records[j]);
            }
            for (int j = 0; j < memory->total_records_capacity; ++j) {
                free((void *)memory->keys);
            }
            for (int j = 0; j < memory->total_records_capacity; ++j) {
                free((void *)memory->offsets);
            }
            free(memory);
            return NULL;
        }

        // Initialize new record values
        memory->records[i]->value = rand() % 1001;
    }

    memory->records_count = new_records_count;
    return memory;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicMemory *memory = allocate_memory(10, 5, 20);
    if (memory == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    int sum = get_sum(memory);
    printf("Sum of record values: %d\n", sum);

    memory = resize_memory(memory, 30);
    if (memory == NULL) {
        printf("Memory reallocation failed.\n");
        return -1;
    }

    sum = get_sum(memory);
    printf("New sum of record values: %d\n", sum);

    free_memory(memory);
    return 0;
}

