DynamicCache create_cache(int initial_size) {
    DynamicCache cache = (DynamicCache)malloc(sizeof(DynamicCache));
    cache->size = initial_size;
    cache->cache = (NetworkConfig**)malloc(cache->size * sizeof(NetworkConfig*));
    for (int i = 0; i < cache->size; i++) {
        cache->cache[i] = NULL;
    }
    return cache;
}

void add_config(DynamicCache* cache, char* interface_id, int qos, int retry_policy) {
    // Search for an available slot in the cache
    for (int i = 0; i < cache->size; i++) {
        if (!cache->cache[i]) {
            NetworkConfig* config = allocate(sizeof(NetworkConfig));
            strcpy(config->interface_id, interface_id);
            config->qos = qos;
            config->retry_policy = retry_policy;
            cache->cache[i] = config;
            return;
        }
    }
}

NetworkConfig* get_config(DynamicCache* cache, char* interface_id) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->cache[i]->interface_id, interface_id) == 0) {
            return cache->cache[i];
        }
    }
    return NULL;
}

void update_config(DynamicCache* cache, char* interface_id, int qos, int retry_policy) {
    NetworkConfig* config = get_config(cache, interface_id);
    if (config) {
        config->qos = qos;
        config->retry_policy = retry_policy;
    }
}

int main() {
    DynamicCache cache = create_cache(10);

