#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    struct node* next;
    struct node* prev;
} node;

node* create_node(int key, char* name) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return NULL;

    new_node->key = key;
    new_node->next = NULL;
    new_node->prev = NULL;

    new_node->name = malloc(strlen(name) + 1);
    strcpy(new_node->name, name);

    return new_node;
}

void free_node(node* node_to_free) {
    if (!node_to_free) return;

    free(node_to_free->name);
    free(node_to_free);

    return;
}

void print_directory(node* current) {
    printf("Directory ID: %d\n", current->key);
    printf("Directory Name: %s\n", current->name);

    return;
}

node* add_directory(node** head, int key, char* name) {
    node* new_node = create_node(key, name);
    if (!new_node) return NULL;

    if (*head == NULL || key < (*head)->key) {
        new_node->next = *head;
        if (*head) (*head)->prev = new_node;
        *head = new_node;
    } else {
        node* current = *head;
        while (current && current->key > key) {
            current = current->next;
        }
        if (!current || current->key < key) {
            new_node->next = current;
            new_node->prev = current->prev;
            if (current) current->prev = new_node;
            else *head = new_node;
            current->next = new_node;
        } else {
            printf("Error: Directory ID already exists.\n");
            free_node(new_node);
            return NULL;
        }
    }

    return *head;
}

int main() {
    // Create the head of the linked list
    node* head = NULL;

    // Add directories to the list
    head = add_directory(&head, 1, "Dir1");
    head = add_directory(&head, 2, "Dir2");
    head = add_directory(&head, 3, "Dir3");

    // Traverse and print each directory's name and ID
    node* current = head;
    while (current) {
        print_directory(current);
        current = current->next;
    }

    return 0;
}
