// Pool-based memory allocation
void* nas_message_pool_alloc(size_t size) {
    static uint8_t* pool = NULL;
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static size_t pool_size = 0;

    if (pool == NULL || pool_size < size) {
        pthread_mutex_lock(&lock);
        if (pool == NULL || pool_size < size) {
            pool = realloc(pool, size * MAX_MESSAGES + sizeof(pthread_mutex_t));
            pool_size = size * MAX_MESSAGES;
        }
        pthread_mutex_unlock(&lock);
    }

    return &pool[size];
}

void nas_message_pool_free(void* ptr) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);
    if (ptr != NULL) {
        memcpy(ptr, &pool, pool_size);
        free(pool);
        pool = NULL;
        pool_size = 0;
