    for (int i = 0; i < n; i++) {
        records[i].offset = i * sizeof(record_t);
        int key = i % 1007 + 1;
        if (key > 1007) key = 5G_RNTI_RANGE_START + rand() % (5G_RNTI_RANGE_END - 5G_RNTI_RANGE_START + 1);
        records[i].key = key;
        int value = rand() % 255;
        while (value < 0 || value > 254) value = rand() % 255;
        records[i].value = value;
        if (rand() % 10000 < rnti_prob * 10000) {
            records[i].active = true;
        } else {
            records[i] = (record_t){.offset = 0, .key = -1, .value = -1};
        }
    }
    return records;
}

void free_records(record_t* records, int n) {
    free(records);
}
