    array->messages = (LTE_PHY_LAYER_CONTROL_MESSAGE**)
        calloc(initial_capacity, sizeof(LTE_PHY_LAYER_CONTROL_MESSAGE*));
    array->capacity = initial_capacity;
    array->size = 0;
    array->total_buffer_size = 0;
    return array;
