void lte_phy_layer_control_message_array_free(LTE_PHY_LAYER_CONTROL_MESSAGE_ARRAY* array) {
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i]->dl_mch_data_tag != NULL) {
            free(array->messages[i]->dl_mch_data_tag);
        }
        free(array->messages[i]);
    }
    free(array->messages);
    free(array);
}

LTE_PHY_LAYER_CONTROL_MESSAGE* lte_phy_layer_control_message_create(PHICH_CONFIGURATION phich_config, uint32_t ue_id) {
    LTE_PHY_LAYER_CONTROL_MESSAGE* message = (LTE_PHY_LAYER_CONTROL_MESSAGE*)malloc(sizeof(LTE_PHY_LAYER_CONTROL_MESSAGE));
    message->phich_config = phich_config;
    message->ue_id = ue_id;
    return message;
}

void lte_phy_layer_control_message_array_add(LTE_PHY_LAYER_CONTROL_MESSAGE_ARRAY* array, LTE_PHY_LAYER_CONTROL_MESSAGE* message) {
    if (array->size >= array->capacity) {
        array->messages = (LTE_PHY_LAYER_CONTROL_MESSAGE**)
            realloc(array->messages, (array->capacity * 2 + 1) * sizeof(LTE_PHY_LAYER_CONTROL_MESSAGE*));
        array->capacity *= 2;
    }
    array->messages[array->size++] = message;
}

void lte_phy_layer_control_message_array_delete(LTE_PHY_LAYER_CONTROL_MESSAGE_ARRAY* array, int index) {
    if (index >= array->size || index < 0) return;

    for (int i = index; i < array->size - 1; i++) {
        array->messages[i] = array->messages[i + 1];
    }
    free(array->messages[array->size - 1]->dl_mch_data_tag);
    free(array->messages[array->size - 1]);
    array->messages[--array->size] = NULL;
}

void lte_phy_layer_control_message_array_update_buffer_size(LTE_PHY_LAYER_CONTROL_MESSAGE_ARRAY* array) {
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i]->dl_mch_data_tag != NULL) {
            array->total_buffer_size += sizeof(void*);
        }
    }
}

void lte_phy_layer_control_message_array_print_stats(LTE_PHY_LAYER_CONTROL_MESSAGE_ARRAY* array) {
