#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int UE_ID;
    char RX_UE_INFORMATION_TAG[10];
    char CRC_INDICATION_REL8_TAG[10];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_from_list(List* list, Node* node) {
    if (node == NULL)
        return;

    pthread_mutex_lock(&list->lock);

    if (node->prev != NULL)
        node->prev->next = node->next;
    else
        list->head = node->next;

    if (node->next != NULL)
        node->next->prev = node->prev;
    else
        list->tail = node->prev;

    pthread_mutex_unlock(&list->lock);

    free(node);
}

void iterate_list(List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        func(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void* allocate_ue_info(int num_structures, void** ue_ids) {
    List list;
    init_list(&list);

    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->UE_ID = ue_ids[i][0];
        strcpy(data->RX_UE_INFORMATION_TAG, "Tag");
        strcpy(data->CRC_INDICATION_REL8_TAG, "Tag");
        data->CRCFLAG = true;

        add_to_list(&list, data);
    }

    return &list;
}

void deallocate_ue_info(void* list_ptr) {
    List* list = (List*)list_ptr;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        remove_from_list(list, current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    free(list);
}
