NICP_packet* initialize_network_interfaces() {
    NICP_packet* packets = (NICP_packet*)malloc(MAX_PACKETS * sizeof(NICP_packet));

    if (!packets) {
        // Handle out-of-memory condition
        printf("Error: Unable to allocate memory for NICP packets.\n");
        return NULL;
    }

    for (int i = 0; i < MAX_PACKETS; i++) {
        packets[i].interface_id = rand() % 100; // Randomly generate interface ID

        // Dynamically allocate link statistics
        packets[i].link_stats.packet_loss_rate = ((float)rand()) / RAND_MAX;
        packets[i].link_stats.latency = rand() % 1000;
        packets[i].link_stats.throughput = (float)rand() / RAND_MAX;

        // Initialize events list with default values
        for (int j = 0; j < MAX_EVENTS_PER_PACKET; j++) {
            packets[i].events[j].timestamp = time(NULL);
            packets[i].events[j].event_type = rand() % 2; // Randomly generate event type

            // Dynamically allocate memory for events list
            if (j > 0) { // Only reallocate when the list is being extended
                packets[i].events = realloc(packets[i].events, sizeof(struct NICP_packet*) * (j + 1));

                if (!packets[i].events) {
                    printf("Error: Unable to dynamically allocate memory for events.\n");
                    return NULL;
                }
            }
        }
    }

    return packets;
}

void free_network_interfaces(NICP_packet* packets) {
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packets[i].events) {
            for (int j = 0; j < MAX_EVENTS_PER_PACKET; j++) {
                if (packets[i].events[j].timestamp != 0) { // Check for valid timestamps
                    free(packets[i].events[j].timestamp); // Release dynamically allocated timestamp memory
                }
            }
            free(packets[i].events); // Release dynamically allocated events list memory
        }
    }

    free(packets); // Release the NICP packet array
}
