typedef struct {
    int interface_id;
    double packet_loss_rate;
    double latency;
    double throughput;
    time_t timestamp;
    int stale;
} link_stats;

typedef struct {
    int num_interfaces;
    link_stats **stats;
    time_t last_update;
} nicp_packet;

nicp_packet* init_nicp_packets(int num_interfaces) {
    nicp_packet *packet = (nicp_packet*)malloc(sizeof(nicp_packet));
    packet->num_interfaces = num_interfaces;
    packet->last_update = time(NULL);
    packet->stats = (link_stats**)malloc(num_interfaces * sizeof(link_stats*));

    for (int i = 0; i < num_interfaces; i++) {
        link_stats *stats = (link_stats*)malloc(sizeof(link_stats));
        stats->interface_id = i;
        stats->packet_loss_rate = (double)rand() / RAND_MAX;
        stats->latency = (double)rand() / RAND_MAX;
        stats->throughput = (double)rand() / RAND_MAX;
        stats->timestamp = time(NULL);
        stats->stale = 0;

        packet->stats[i] = stats;
    }

    return packet;
}

void update_nicp_packets(nicp_packet *packet) {
    for (int i = 0; i < packet->num_interfaces; i++) {
        link_stats *stats = packet->stats[i];
        // Update statistics based on current network conditions
        stats->packet_loss_rate += (double)rand() / RAND_MAX;
        stats->latency += (double)rand() / RAND_MAX;
        stats->throughput += (double)rand() / RAND_MAX;

        if ((time(NULL) - stats->timestamp) > 60) { // Update frequency based on current network conditions
            stats->stale = 1;
        }
    }

    packet->last_update = time(NULL);
}

void print_nicp_packets(nicp_packet *packet) {
    for (int i = 0; i < packet->num_interfaces; i++) {
        link_stats *stats = packet->stats[i];
        printf("Interface %d:\n", stats->interface_id);
        printf("Packet Loss Rate: %.2f%%\n", stats->packet_loss_rate * 100);
        printf("Latency: %.2f ms\n", stats->latency);
        printf("Throughput: %.2f Mbps\n", stats->throughput / 8.0);
        if (stats->stale) {
            printf("Statistics are stale.\n");
        } else {
            printf("Statistics are up-to-date.\n");
        }
    }
}

int main() {
    nicp_packet *packet = init_nicp_packets(5); // Initialize NICP packets for 5 interfaces
    update_nicp_packets(packet); // Update statistics based on current network conditions
    print_nicp_packets(packet); // Print updated statistics

    return 0;
}
