int* key_array = NULL;
int offset_alloc_size = 0;
int key_alloc_size = 0;

void resize_offset_array(int new_size) {
    if (new_size > offset_alloc_size) {
        int* temp = realloc(offset_array, new_size * sizeof(int));
        if (temp == NULL) {
            printf("Offset array allocation failed.\n");
            exit(1);
        }
        offset_array = temp;
        offset_alloc_size = new_size;
    }
}

void resize_key_array(int new_size) {
    if (new_size > key_alloc_size) {
        int* temp = realloc(key_array, new_size * sizeof(int));
        if (temp == NULL) {
            printf("Key array allocation failed.\n");
            exit(1);
        }
        key_array = temp;
        key_alloc_size = new_size;
    }
}

// Allocate and initialize an array of 'record' structures
typedef struct record {
    int value;
    int* key;
} record;

record* allocate_records(int num_records) {
    record* records = NULL;
    for (int i = 0; i < num_records; i++) {
        record new_record;
        new_record.value = rand() % 100; // Set random value within a specified range
        new_record.key = &key_array[rand() % key_alloc_size]; // Assign random key from key array
        if (records == NULL) {
            records = malloc(num_records * sizeof(record));
        } else {
            record* temp = realloc(records, (i + 1) * sizeof(record));
            if (temp == NULL) {
                printf("Record allocation failed.\n");
                exit(1);
            }
            records = temp;
        }
        records[i] = new_record;
    }
    return records;
}

// Utilize a thread-safe random number generator
pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;

int get_random_value(int min, int max) {
    pthread_mutex_lock(&rand_lock);
    int value = rand() % (max - min + 1) + min; // Generate a random value within the specified range
    pthread_mutex_unlock(&rand_lock);
    return value;
}

// Implement a robust cleanup routine to free all allocated memory safely
void cleanup() {
    if (offset_array != NULL) {
        free(offset_array);
        offset_array = NULL;
    }
    if (key_array != NULL) {
        free(key_array);
        key_array = NULL;
    }
    if (records != NULL) {
        for (int i = 0; i < num_records; i++) {
            record* temp = records + i;
            if (temp->key != NULL) {
                *temp->key = -1; // Mark the key as freed
            }
        }
        free(records);
    }
}

// Balance performance optimization between speed and memory usage
void optimize_allocation(int num_records, int min_size, int max_size) {
    int alloc_size = (num_records + min_size - 1) / min_size * min_size; // Calculate the optimal allocation size based on the minimum and maximum sizes
    if (alloc_size > max_size) {
        alloc_size = max_size;
    }
    return;
}

// Ensure the function handles potential integer overflow during memory calculations
void validate_memory_allocation(int num_records, int* offset) {
    if ((num_records * sizeof(record)) / sizeof(int) + key_alloc_size > INT_MAX) {
        printf("Integer overflow detected. Allocation failed.\n");
        exit(1);
    }
}

int main() {
    // Initialize the function
    srand(time(NULL)); // Seed the random number generator

    // Test cases for the dynamic memory allocation mechanism
    int num_records = 1000000; // Allocate a large number of records
    record* records = allocate_records(num_records);

    // Perform cleanup after processing the allocated records
    cleanup();

    return 0;
}

