#include <time.h>

typedef struct {
    int value;
    long* offset;
    int* key;
} record;

record* allocateMemory(int numRecords) {
    // Calculate total memory required for all data structures
    size_t totalBytes = sizeof(record) * numRecords + sizeof(long) * numRecords + sizeof(int) * numRecords;

    // Check if the calculated total bytes exceed the system limit
    if (totalBytes > 0.9 * sysconf(_SC_PAGE_SIZE)) {
        return NULL;  // Return failure indicator
    }

    record* records = (record*)malloc(totalBytes);
    long* offsets = (long*)malloc(sizeof(long) * numRecords);
    int* keys = (int*)malloc(sizeof(int) * numRecords);

    if (!records || !offsets || !keys) {
        // Free memory on failure
        free(records);
        free(offsets);
        free(keys);
        return NULL;  // Return failure indicator
    }

    // Initialize records and set random values for each record
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 1001;
        offsets[i] = i;
        keys[i] = i;
    }

    return records;
}
