#define MAX_LINE_LENGTH 256
#define MAX_CONFIG_FILE_SIZE (1024 * 1024)

static int line_number = 1;
static LOG4C_LOG_LEVEL debug_level = log4c_get_level();

char* process_config_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return NULL; // Handle error
    }

    char buffer[MAX_LINE_LENGTH];
    size_t config_size = 0;

    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        int line_length = strlen(buffer);
        if (line_length >= MAX_LINE_LENGTH - 1 || line[0] == '#') {
            continue; // Ignore comments or very long lines
        }

        if (debug_level == LOG4C_LOG_LEVEL_DEBUG) {
            log4c_log(LOG4C_LOG_LEVEL_DEBUG, "Processing line %d: '%s' of length %zu", line_number++, buffer, strlen(buffer));
        }

        char* processed_line = malloc(line_length + 1);
        strncpy(processed_line, buffer, line_length - 1);
        processed_line[line_length - 1] = '\0';
        config_size += strlen(processed_line) + 1;
    }

    fclose(file);

    if (config_size > MAX_CONFIG_FILE_SIZE) {
        free(buffer);
        return NULL; // File too large
    }

    char* config_string = malloc(config_size + 1);
    sprintf(config_string, "%s", buffer); // Convert buffer to string

    free(buffer);
    return config_string;
}

