#include <time.h>
#include <pthread.h>

#define MAX_CONCURRENT_THREADS 10
#define MIN_RNTI 1000
#define MAX_RNTI 9999

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
};

void* generate_ue_info(int rnti) {
    struct NFAPI_CRC_INDICATION_PDU_T* ue_info = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!ue_info) {
        // Log error message
        printf("Memory allocation failed for UE information.\n");
        return NULL;
    }
    ue_info->RX_UE_INFORMATION_TAG = rnti % 100; // Assign a random RX_UE_INFORMATION_TAG value
    ue_info->RNTI = rnti;
    ue_info->CRC_INDICATION_REL8_TAG = (rnti % 2) ? 1 : 0; // Assign a random CRC_INDICATION_REL8_TAG value
    srand(time(NULL)); // Set the random seed based on the current time
    ue_info->CRCFLAG = rand() & 1; // Assign a random CRCFLAG value
    return ue_info;
}

void* process_ue_info(void* ue_info) {
    struct NFAPI_CRC_INDICATION_PDU_T* info = (struct NFAPI_CRC_INDICATION_PDU_T*)ue_info;
    printf("Processing RNTI %lu with RX_UE_INFORMATION_TAG %d and CRCFLAG %d.\n", info->RNTI, info->RX_UE_INFORMATION_TAG, info->CRCFLAG);
    free(ue_info); // Free the dynamically allocated memory
}

int allocate_ue_info(int n) {
    pthread_t threads[MAX_CONCURRENT_THREADS];
    struct NFAPI_CRC_INDICATION_PDU_T** ue_infos = (struct NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(struct NFAPI_CRC_INDICATION_PDU_T*));
    if (!ue_infos) {
        // Log error message
        printf("Memory allocation failed for UE information array.\n");
        return -1;
    }
    int i = 0, rnti = MIN_RNTI;
    while (i < n && rnti <= MAX_RNTI) {
        struct NFAPI_CRC_INDICATION_PDU_T* ue_info = generate_ue_info(rnti);
        if (!ue_info) {
            // Log error message
            printf("Memory allocation failed for UE information.\n");
            return -1;
        }
        pthread_create(&threads[i], NULL, process_ue_info, (void*)ue_info);
        rnti++;
        i++;
    }
    for (int j = 0; j < i; j++) {
        pthread_join(threads[j], NULL);
    }
    free(ue_infos); // Free the dynamically allocated memory
    return 0;
}

int main() {
    int n = 100; // Number of unique RNTIs to process
    if (allocate_ue_info(n) == -1) {
        printf("Failed to allocate UE information structures.\n");
        return 1;
    }
    printf("Completed processing %d unique RNTIs.\n", n);
    return 0;
}

