typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T* nfapis = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        nfapis[i].RX_UE_INFORMATION_TAG = i;

        int rnti_range_start = 1;
        int rnti_range_end = 100;
        nfapis[i].RNTI = rand() % (rnti_range_end - rnti_range_start + 1) + rnti_range_start;

        int crcflag = rand() & 0x01; // Randomly set CRCFLAG
        nfapis[i].CRC_INDICATION_REL8_TAG = crcflag;
    }

    return nfapis;
}

void* thread_func(void* arg) {
    int n = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* nfapis = create_nfapi_crc_indication_pdu(n);

    // Example of modular logging
    printf("Thread %p: Created %d NF-API structures\n", pthread_self(), n);

    free(nfapis);

    return NULL;
}

int main() {
    int n = 10000; // Number of NFAPI_CRC_INDICATION_PDU_T to create

    pthread_t threads[n];

    for (int i = 0; i < n; i++) {
        int* arg = malloc(sizeof(int));
        *arg = i;

        pthread_create(&threads[i], NULL, thread_func, arg);
    }

    for (int i = 0; i < n; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
