#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct connection_record {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    time_t last_active;
} ConnectionRecord;

// Lock-based approach using pthread mutex
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t record_sem;

// Function to manage dynamic list of TCP connection records
void* manage_connections(void* arg) {
    // Initialize the dynamic list and its size
    ConnectionRecord** records = (ConnectionRecord**)malloc(sizeof(ConnectionRecord*) * 1000);
    int record_size = 0;

    while (1) {
        // Receive network event from message queue
        char* event_data = receive_event();

        // Process connection establishment, disconnection, or timeout event
        if (event_data == NULL) continue;
        process_event(event_data);

        // Validate IP addresses and ensure unique IP:port pairs
        validate_ip_addresses();
        check_duplicate_IP_port_pairs();

        // Update last active timestamp for each record
        update_last_active_timestamps();

        // Log events for debugging and performance analysis
        log_events();
    }

    free(records);
    return NULL;
}

// Helper functions to process network events, validate IP addresses, and handle concurrency
void process_event(char* event_data) {
    // Process connection establishment, disconnection, or timeout event
    pthread_mutex_lock(&lock);
    if (event_data == NULL) {
        // Handle disconnection or timeout event
        sem_wait(&record_sem);
        record_size--;
        pthread_mutex_unlock(&lock);
    } else {
        // Handle connection establishment event
        ConnectionRecord* new_record = (ConnectionRecord*)malloc(sizeof(ConnectionRecord));
        inet_pton(AF_INET, event_data, new_record->src_ip);
        inet_pton(AF_INET, event_data, new_record->dst_ip);
        new_record->src_port = ntohs(*(uint16_t*)event_data);
        new_record->dst_port = ntohs(*(uint16_t*)event_data + 2);
        new_record->last_active = time(NULL);

        pthread_mutex_lock(&lock);
        records[record_size++] = new_record;
        pthread_mutex_unlock(&lock);

        sem_post(&record_sem);
    }
}

void validate_ip_addresses() {
    // Validate IP addresses are within specified subnets
    for (int i = 0; i < record_size; i++) {
        if (!is_valid_IP(record[i]->src_ip) || !is_valid_IP(record[i]->dst_ip)) {
            // Handle invalid IP address
            pthread_mutex_lock(&lock);
            sem_wait(&record_sem);
            free(records[i]);
            record_size--;
            pthread_mutex_unlock(&lock);
            continue;
        }
    }
}

void check_duplicate_IP_port_pairs() {
    // Check for duplicate IP:port pairs and handle them
    for (int i = 0; i < record_size; i++) {
        for (int j = i + 1; j < record_size; j++) {
            if (strcmp(record[i]->src_ip, record[j]->src_ip) == 0 &&
                record[i]->dst_port == record[j]->dst_port) {
                // Handle duplicate IP:port pair
                pthread_mutex_lock(&lock);
                sem_wait(&record_sem);
                free(records[j]);
                record_size--;
                pthread_mutex_unlock(&lock);
            }
        }
    }
}

void update_last_active_timestamps() {
    // Update last active timestamp for each record
    time_t current_time = time(NULL);
    for (int i = 0; i < record_size; i++) {
        if ((current_time - records[i]->last_active) > TIME_THRESHOLD) {
            // Handle inactive connection
            pthread_mutex_lock(&lock);
            sem_wait(&record_sem);
            free(records[i]);
            record_size--;
            pthread_mutex_unlock(&lock);
        }
    }
}

void log_events() {
    // Log events for debugging and performance analysis
    FILE* log_file = fopen("connection_log.txt", "a");
    if (log_file == NULL) return;

    for (int i = 0; i < record_size; i++) {
        fprintf(log_file, "Connection ID: %d\nSource IP: %s\nDestination IP: %s\nSource Port: %hu\nDestination Port: %hu\nLast Active Timestamp: %ld\n\n", i + 1, records[i]->src_ip, records[i]->dst_ip, records[i]->src_port, records[i]->dst_port, records[i]->last_active);
    }

    fclose(log_file);
}

int main() {
    // Initialize the dynamic list and its size
    ConnectionRecord** records = (ConnectionRecord**)malloc(sizeof(ConnectionRecord*) * 1000);
    int record_size = 0;

    pthread_t thread;
    pthread_create(&thread, NULL, manage_connections, NULL);

    return 0;
}

