#define MAX_LINE_LENGTH 1024
#define MAX_DATA_FIELDS 1000

typedef struct {
    time_t timestamp;
    int server_id;
    char data[MAX_DATA_FIELDS];
} Event;

Event *process_log_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    size_t line_length = 0;
    char *line = NULL;
    ssize_t read = 0;

    Event *events = NULL;
    size_t event_count = 0;

    while ((read = getline(&line, &line_length, file)) != -1) {
        Event *event = (Event *)malloc(sizeof(Event));
        if (!event) {
            perror("Error allocating memory");
            fclose(file);
            return NULL;
        }

        char *token = strtok(line, " ");
        event->timestamp = strtotm(token);

        token = strtok(NULL, " ");
        event->server_id = atoi(token);

        size_t data_length = 0;
        char *data_start = line + read - strlen(token);
        for (size_t i = 0; i < MAX_DATA_FIELDS; i++) {
            if (*data_start == '\0') break;
            token = strtok(data_start, "\0");
            if (!token) break;

            double value = strtod(token, NULL);
            // Validate numeric fields
            if (isfinite(value)) {
                // Calculate average of last three numeric fields
                size_t avg_count = 3;
                double sum = 0.0;
                for (size_t j = i; j < i + avg_count && token; j++) {
                    value = strtod(token, NULL);
                    if (!isfinite(value)) {
                        avg_count = j;
                        break;
                    }
                    sum += value;
                }

                event->data[i] = (avg_count > 0) ? ((sum / avg_count) * 100.0) : -1.0;

            } else {
                // Log error and continue processing
                fprintf(stderr, "Error: invalid numeric field at line %zu\n", event_count + 1);
            }

            data_start = token;
        }

        free(line);
        line = NULL;
        line_length = 0;

        if (events) {
            events[event_count] = event;
        } else {
            events = event;
        }
        event_count++;
    }

    fclose(file);

    return events;
}

int main() {
    Event *events = process_log_file("log.txt");
    // Process and log events
    return 0;
}
