    if (!ue) {
        printf("Memory allocation failed for UE ID %d.\n", UE_ID);
        return NULL;
    }
    ue->UE_ID = UE_ID;
    strcpy(ue->SRB1_CONFIG, SRB1_CONFIG);
    *ue_ctx = ue;
    return ue;
}

void* remove_ue(void **ue_ctx, int UE_ID) {
    NRUE_CONTEXT_T *ue = (NRUE_CONTEXT_T*) *ue_ctx;
    while (*ue && ue->UE_ID != UE_ID)
        ue++;
    if (!ue) {
        printf("UE ID %d not found.\n", UE_ID);
        return NULL;
    }
    *ue_ctx = realloc(*ue_ctx, (int)sizeof(*ue_ctx) - sizeof(NRUE_CONTEXT_T));
    return *ue_ctx;
}

