#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum size of each event record's timestamp string.
#define TIMESTAMP_MAX_SIZE 32

// Define the maximum number of log entries in a linked list.
#define LOG_ENTRIES_MAX 1000

typedef struct {
    char* message;
    int priority;
} LogEntry;

typedef struct {
    int event_id;
    time_t timestamp;
    LogEntry** log_entries;
    size_t log_entries_count;
} EventRecord;

// Define the maximum number of event records in an array.
#define EVENT_RECORDS_MAX 1000

// Function to add a new log entry to the linked list, ensuring chronological order.
void add_log_entry(EventRecord* event, const char* message, int priority) {
    // Create a new log entry and add it to the end of the linked list.
    LogEntry* new_log_entry = (LogEntry*)malloc(sizeof(LogEntry));
    new_log_entry->message = strdup(message);
    new_log_entry->priority = priority;

    // Insert the new log entry at the correct position in the linked list.
    if (event->log_entries_count == 0 || 
        strptime(new_log_entry->message, "%s", "%s") <= 
        strptime(event->log_entries[event->log_entries_count-1]->message, "%s", "%s")) {
        event->log_entries = (LogEntry**)realloc(event->log_entries, sizeof(LogEntry*) * (event->log_entries_count + 1));
        event->log_entries[event->log_entries_count++] = new_log_entry;
    } else {
        // If the new log entry's timestamp is earlier than the last one,
        // insert it before the last log entry.
        LogEntry** new_log_entries = (LogEntry**)malloc(sizeof(LogEntry*) * (event->log_entries_count + 1));
        size_t i;
        for (i = 0; i < event->log_entries_count; i++) {
            new_log_entries[i] = event->log_entries[i];
        }
        new_log_entries[i++] = new_log_entry;
        free(event->log_entries);
        event->log_entries = new_log_entries;
    }
}

// Function to traverse the data structure and print log messages with a priority higher than a specified threshold.
void print_high_priority_logs(EventRecord* event, int threshold) {
    // Traverse each event record in the array.
    for (size_t i = 0; i < event->log_entries_count; i++) {
        LogEntry* log_entry = event->log_entries[i];
        if (log_entry->priority > threshold) {
            printf("Event ID: %d, Timestamp: %s, Priority: %d, Message: %s\n", 
                   event->event_id, ctime(&event->timestamp), log_entry->priority, log_entry->message);
        }
    }
}

// Function to free the memory allocated for an event record.
void free_event_record(EventRecord* event) {
    // Free each linked list of log entries.
    size_t i;
    for (i = 0; i < event->log_entries_count; i++) {
        LogEntry* log_entry = event->log_entries[i];
        free(log_entry->message);
        free(log_entry); // Free the individual log entry.
    }
    free(event->log_entries); // Free the array of linked lists.
}
