    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void populateArray(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000000;
        while (1) {
            array[i].RNTI = rand() % 65536;
            if (!findRNTI(array, i)) break;
        }
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000000;
        array[i].CRCFLAG = rand() % 2;
    }
}

int findRNTI(NFAPI_CRC_INDICATION_PDU_T* array, int index) {
    for (int i = 0; i < index; i++) {
        if (array[i].RNTI == array[index].RNTI) return 1;
    }
    return 0;
}

void freeArray(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i].CRCFLAG);
    }
    free(array);
}

NFAPI_CRC_INDICATION_PDU_T* dynamicAllocateAndPopulate(int N) {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* array = allocateArray(N);
