void init_hash_table() {
    pthread_mutex_init(&hash_table_mutex, NULL);
}

// Function to check if an RNTI is unique in the hash table
int is_rnti_unique(int rnti) {
    int index = rnti % HASH_TABLE_SIZE;
    pthread_mutex_lock(&hash_table_mutex);
    uint32_t value = hash_table[index];
    pthread_mutex_unlock(&hash_table_mutex);

    return (value == 0)? 1 : 0;
}

// Function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
