        free(polygon->vertices);
    }
    free(polygon);
}

Polygon* createPolygon(int numVertices) {
    Polygon *polygon = malloc(sizeof(Polygon));
    polygon->numVertices = numVertices;
    polygon->vertices = malloc(numVertices * sizeof(Point));
    return polygon;
}

void freeNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->RX_UE_INFORMATION_TAG != NULL) {
        free(pdu->RX_UE_INFORMATION_TAG);
    }
    free(pdu);
}

NFAPI_CRC_INDICATION_PDU_T* createNFAPI_CRC_INDICATION_PDU_T() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = strdup("default_tag");
    pdu->RNTI = 0;
    pdu->CRC_INDICATION_REL8_TAG = "REL8";
    pdu->CRCFLAG = rand() % 2;
    return pdu;
}

char* computeMD5(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    unsigned char md5[16];
    MD5((const unsigned char*) &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), md5);
    char *md5Str = malloc(33);
    for (int i = 0; i < 16; i++) {
        sprintf(&md5Str[i*2], "%02x", md5[i]);
    }
    return md5Str;
}

double areaOfPolygon(Polygon *polygon) {
    double area = 0.0;
    Point *v = polygon->vertices;
    int n = polygon->numVertices;
    for (int i = 0; i < n; i++) {
        Point p1 = v[i];
        Point p2 = v[(i+1)%n];
        area += (p2.x - p1.x) * (p2.y + p1.y);
    }
    return abs(area) / 2.0;
}

Polygon* createPolygons(int numPolygons, int maxVerticesPerPolygon) {
    Polygon **polygons = malloc(numPolygons * sizeof(Polygon*));
    for (int i = 0; i < numPolygons; i++) {
