public class ProcessAES_CBC_and_NFAAPI_CRC
{
    public static byte[] process_aes_cbc_and_nfaapi_crc(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, int N)
    {
        // Decrypt the ciphertext using AES-CBC with the provided key and IV
        Aes aes = Aes.Create();
        aes.Key = encryptionKey;
        aes.IV = initializationVector;
        ICryptoTransform decryptor = aes.CreateDecryptor();
        MemoryStream memoryStream = new MemoryStream(ciphertext);
        CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);

        byte[] decryptedBytes = new byte[cryptoStream.Length];
        int bytesRead = cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);

        // Handle padding according to the specified mode
        byte[] decryptedBytesWithoutPadding = new byte[bytesRead - 16]; // Assuming AES-CBC with PKCS7 padding
        Array.Copy(decryptedBytes, 0, decryptedBytesWithoutPadding, 0, bytesRead - 16);

        return decryptedBytesWithoutPadding;
    }
}
