NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(int max_structures, int *num_structures_alloced, int seed) {
    NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
    srand(seed);

    for (int i = 0; i < max_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            // Handle memory allocation failure
            free(structures);
            return NULL;
        }

        structure->RX_UE_INFORMATION_TAG = (uint8_t)(rand() % 256);
        structure->RNTI = (uint16_t)(rand() % 65536);
        structure->CRC_INDICATION_REL8_TAG = (uint16_t)(rand() % 65536);

        if (*num_structures_alloced < max_structures) {
            structures = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*num_structures_alloced + 1));
            if (!structures) {
                free(structure);
                return NULL;
            }
        }

        if (structures != NULL) {
            structures[*num_structures_alloced] = *structure;
        }

        (*num_structures_alloced)++;
    }

    return structures;
}

int main() {
    int max_structures = 10;
    int num_structures_alloced = 0;
    NFAPI_CRC_INDICATION_PDU_T* structures = generate_crc_indication_pdu(max_structures, &num_structures_alloced, (int)time(NULL));

    if (!structures) {
        printf("Memory allocation failed.\n");
    } else {
        for (int i = 0; i < num_structures_alloced; i++) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", structures[i].RX_UE_INFORMATION_TAG, structures[i].RNTI, structures[i].CRC_INDICATION_REL8_TAG);
