using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;

public class DataDeserializer
{
    private const int DefaultBufferSize = 4096;
    private readonly object _lockObject = new object();
    private readonly BinaryFormatter _binaryFormatter = new BinaryFormatter();
    private readonly Dictionary<string, Func<Stream, Object>> _deserializers = new Dictionary<string, Func<Stream, Object>>
    {
        { "gzip", () => GZipDeserializer() },
        { "deflate", () => DeflateDeserializer() },
        { "lzma", () => LzmaDeserializer() }
    };

    public async Task<Object> DeserializeAsync(string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        {
            await VerifyCompressionType(stream);
            return _binaryFormatter.Deserialize(stream);
        }
    }

    private Func<Stream, Object> GetDeserializer(string compressionType)
    {
        if (_deserializers.TryGetValue(compressionType, out var deserializer))
        {
            return deserializer;
        }
        throw new Exception($"Unsupported compression type: {compressionType}");
    }

    private Stream GZipDeserializer()
    {
        using (var stream = new GZipStream(File.OpenRead("path_to_file"), CompressionMode.Decompress))
        {
            // Perform the actual deserialization
        }
    }

    private Stream DeflateDeserializer()
    {
        using (var stream = new DeflateStream(File.OpenRead("path_to_file"), CompressionMode.Decompress))
        {
            // Perform the actual deserialization
        }
    }

    private Stream LzmaDeserializer()
    {
        using (var stream = new LzmaStream(File.OpenRead("path_to_file"), CompressionMode.Decompress))
        {
            // Perform the actual deserialization
        }
    }

    private async Task VerifyCompressionType(Stream stream)
    {
        using (var reader = new BinaryReader(stream))
        {
            var magicNumber = reader.ReadInt32();
            if (magicNumber != 0x12345678)
            {
                throw new Exception("Malformed file");
            }
        }
    }
}

public class LoggingBinaryFormatter : BinaryFormatter
{
    public override object Deserialize(Stream stream)
    {
        try
        {
            return base.Deserialize(stream);
        }
        catch (Exception ex)
        {
            // Log the exception and rethrow
            Console.WriteLine("Deserialization failed: " + ex.Message);
            throw;
        }
    }
}
