#define MAX_CONNECTIONS 1000
#define CONGESTION_WINDOW_SIZE_MAX 65535

typedef struct {
    int socket_id;
    char remote_ip_address[INET6_ADDRSTRLEN];
    uint16_t port_number;
    enum { ESTABLISHED, CLOSED } state;
    int client_id;
} TCP_CONNECTION;

TCP_CONNECTION* init_tcp_connections(int num_connections) {
    if (num_connections > MAX_CONNECTIONS) {
        return NULL; // error: too many connections
    }

    TCP_CONNECTION* connections = (TCP_CONNECTION*) malloc(num_connections * sizeof(TCP_CONNECTION));
    if (!connections) {
        return NULL; // error: memory allocation failed
    }

    srand(time(NULL)); // initialize random seed

    for (int i = 0; i < num_connections; i++) {
        TCP_CONNECTION* conn = &connections[i];
        conn->socket_id = socket(AF_INET6, SOCK_STREAM, 0);
        inet_pton(AF_INET6, "2001:db8::1", conn->remote_ip_address); // random IP address
        conn->port_number = rand() % CONGESTION_WINDOW_SIZE_MAX;
        conn->state = ESTABLISHED;
        conn->client_id = i;
    }

    return connections;
}

void free_tcp_connections(TCP_CONNECTION* connections, int num_connections) {
    for (int i = 0; i < num_connections; i++) {
        free(connections[i].remote_ip_address);
    }
    free(connections);
}
