import com.google.common.primitives.Ints;
import org.apache.commons.lang3.RandomUtils;
import org.apache.commons.math3.random.MersenneTwister;

public class Graph {
    private int graphSize;
    private Map<Long, Vertex> vertices = new ConcurrentHashMap<>();
    private Map<Long, List<Edge>> edges = new ConcurrentHashMap<>();

    public void generateGraph(int graphSize) {
        if (graphSize < 10 || graphSize > 10000) {
            throw new IllegalArgumentException("Invalid graph size. Must be between 10 and 10000.");
        }

        this.graphSize = graphSize;

        for (int i = 0; i < graphSize; i++) {
            long vertexId = RandomUtils.nextLong();
            Vertex vertex = new Vertex(vertexId, getRandomProperties());
            vertices.put(vertexId, vertex);

            if (i > 0) {
                long prevVertexId = Long.parseLong(String.valueOf(vertexId - 1));
                Vertex prevVertex = vertices.getOrDefault(prevVertexId, null);
                if (prevVertex != null) {
                    Edge edge = new Edge(RandomUtils.nextInt(1, 101), prevVertexId, vertexId);
                    edges.computeIfAbsent(vertexId, k -> new ArrayList<>()).add(edge);
                    edges.computeIfAbsent(prevVertexId, k -> new ArrayList<>()).add(edge);
                }
            }
        }
    }

    public Map<String, Object> getProperties(long vertexId) {
        return vertices.getOrDefault(vertexId, null).getProperties();
    }

    public double getAverageEdgeWeight() {
        int totalWeight = 0;
        for (List<Edge> edgeList : edges.values()) {
            for (Edge edge : edgeList) {
                totalWeight += edge.getWeight();
            }
        }
        return (double) totalWeight / (edges.size() * graphSize);
    }

    public Map<String, Object> getGraphSummary() {
        Map<String, Object> summary = new HashMap<>();
        summary.put("graphSize", graphSize);
        summary.put("averageEdgeWeight", getAverageEdgeWeight());
        return summary;
    }
}

class Vertex {
    private long id;
    private Map<String, Object> properties;

    public Vertex(long id, Map<String, Object> properties) {
        this.id = id;
        this.properties = properties;
    }

    public Map<String, Object> getProperties() {
        return properties;
    }
}

class Edge {
    private int weight;
    private long sourceId;
    private long targetId;

    public Edge(int weight, long sourceId, long targetId) {
        this.weight = weight;
        this.sourceId = sourceId;
        this.targetId = targetId;
    }

    public int getWeight() {
        return weight;
    }
}
