#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <deque>
#include <memory>

class LoggingManager {
public:
    // Add a new log entry with the given timestamp, log level, and message.
    void addLogEntry(const std::chrono::system_clock::time_point& timestamp, LogLevel level, const char* message) {
        std::unique_lock<std::mutex> lock(mutex);
        auto entry = std::make_unique<LogEntry>(timestamp, level, message);
        logEntries_.push_back(std::move(entry));
    }

    // Retrieve all log entries with the given timestamp.
    void getLogs(const std::chrono::system_clock::time_point& timestamp, std::function<void(const LogEntry*)> callback) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = logEntries_.begin(); it != logEntries_.end();) {
            if ((*it)->timestamp <= timestamp) {
                callback(it->get());
                it = logEntries_.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Filter logs based on the given log level.
    void getLogs(LogLevel level, std::function<void(const LogEntry*)> callback) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto& entry : logEntries_) {
            if (entry->level == level) {
                callback(entry.get());
            }
        }
    }

    // Clear all entries older than the specified duration.
    void clearOlderThan(const std::chrono::system_clock::time_point& cutoff, std::function<void()> callback = []() {}) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = logEntries_.begin();
        while (it != logEntries_.end()) {
            if ((*it)->timestamp <= cutoff) {
                it = logEntries_.erase(it);
            } else {
                ++it;
            }
        }
        callback();
    }

private:
    struct LogEntry {
        std::chrono::system_clock::time_point timestamp;
        LogLevel level;
        const char* message;

        LogEntry(const std::chrono::system_clock::time_point& timestamp, LogLevel level, const char* message)
                : timestamp(timestamp), level(level), message(message) {}

        ~LogEntry() { delete[] message; }

        const char* get() const { return message; }
    };

    enum class LogLevel { Debug, Info, Warning, Error };

    std::deque<std::unique_ptr<LogEntry>> logEntries_;
    std::mutex mutex;
};
