LTE_PHY_MEASUREMENTS_T* measurements = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_measurements = 0;
int active_threads = 0;
int total_measurements = 0;

void* measurement_thread(void* arg) {
    int i, tid;
    pthread_t thread_id = (pthread_t)arg;
    tid = thread_id - 1;

    for (i = tid; i < M && num_measurements < M; i++) {
        LTE_PHY_MEASUREMENTS_T* meas = (LTE_PHY_MEASUREMENTS_T*)malloc(sizeof(LTE_PHY_MEASUREMENTS_T));
        if (!meas) {
            printf("Memory allocation failed.\n");
            continue;
        }

        time_t timestamp = time(NULL);
        meas->TIME_STAMP = timestamp;
        meas->PLMID = i;
        meas->MEASUREMENT_FLAG = rand() % 256;

        pthread_mutex_lock(&lock);
        measurements[num_measurements] = meas;
        num_measurements++;
        pthread_mutex_unlock(&lock);

        printf("Thread %d processed measurement PLMID %u.\n", tid, i);
    }

    active_threads--;
    total_measurements += num_measurements;
    num_measurements = 0;

    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        if (pthread_create(&threads[i], NULL, measurement_thread, (void*)i)) {
            printf("Thread creation failed.\n");
            return -1;
        }
        active_threads++;
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total measurements processed: %d\n", total_measurements);

    return 0;
}
