#define MAX_TRANSACTIONS 500
#define MAX_DATE_LENGTH 20
#define MIN_TRANSACTION_AMOUNT 0.01
#define MAX_TRANSACTION_AMOUNT 100.00

typedef struct {
    char date[MAX_DATE_LENGTH];
    double amount;
} Transaction;

void process_transactions(int num_transactions) {
    // Dynamically allocate memory for arrays
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    char** dates = (char**)malloc(num_transactions * sizeof(char*));
    double* amounts = (double*)malloc(num_transactions * sizeof(double));

    // Initialize arrays
    int i;
    for(i = 0; i < num_transactions; i++) {
        transactions[i].amount = (double)rand() / RAND_MAX * (MAX_TRANSACTION_AMOUNT - MIN_TRANSACTION_AMOUNT) + MIN_TRANSACTION_AMOUNT;
        if(i % 10 == 0) { // Ensure no two consecutive transactions on the same day have identical values
            transactions[i-1].amount += 0.01; // Update previous transaction amount
        }
        sprintf(transactions[i].date, "%04d-%02d-%02d", (int)(time(NULL)) % 10000, (int)((time(NULL) / 10000) % 12), (int)(((time(NULL) / 3600) / 60) % 60));
    }

    // Group transactions by date
    int* date_counts = (int*)malloc((num_transactions + 1) * sizeof(int)); // Count of unique dates
    int max_date_count = 0;
    for(i = 0; i < num_transactions; i++) {
        if(strcmp(transactions[i].date, "") == 0) { // Error handling: invalid date format
            printf("Invalid date format\n");
            continue;
        }
        int hash_value = (int)(hash(transactions[i].date) % MAX_TRANSACTIONS);
        if(date_counts[hash_value]++ > max_date_count) {
            max_date_count = date_counts[hash_value];
        }
    }

    // Allocate memory for dates array
    char** dates_array = (char**)malloc((max_date_count + 1) * sizeof(char*));
    int* date_offsets = (int*)malloc((num_transactions + 1) * sizeof(int));

    // Initialize dates array and offsets
    for(i = 0; i <= max_date_count; i++) {
        dates_array[i] = NULL;
    }
    for(i = 0; i < num_transactions; i++) {
        int hash_value = (int)(hash(transactions[i].date) % MAX_TRANSACTIONS);
        if(date_offsets[hash_value]) { // Handle hash collisions
            while(dates[date_offsets[hash_value]]) {
                date_offsets[hash_value]++;
            }
        }
        dates[date_offsets[hash_value]++] = transactions[i].date;
    }

    // Free allocated memory
    for(i = 0; i < num_transactions; i++) {
        free(transactions[i].date);
        free(&transactions[i]);
    }
    free(transactions);
    free(dates);
    free(amounts);
    free(date_counts);
    free(dates_array);
    free(date_offsets);

    return;
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    int num_transactions = 0;
    while(num_transactions <= 0 || num_transactions > MAX_TRANSACTIONS) {
        printf("Enter the number of transactions (1-%d): ", MAX_TRANSACTIONS);
        scanf("%d", &num_transactions);
    }

    process_transactions(num_transactions);

    return 0;
}

