typedef struct {
    int PHICH_CONFIGURATION;
    int UE_ID;
    char* DL_MCH_DATA_TAG;
} lte_msg_t;

// Define function to initialize and configure dynamic array of LTE messages
int init_lte_messages(int num_msgs, int max_batch_size, float priority_level) {
    // Initialize message processing service queue
    pthread_mutex_lock(&msg_queue_mutex);
    msg_queue = (struct msg*)malloc(sizeof(struct msg)*MAX_QUEUE_SIZE);
    pthread_cond_signal(&msg_queue_cond);

    for (int i = 0; i < num_msgs; i++) {
        lte_msg_t* msg = (lte_msg_t*)malloc(sizeof(lte_msg_t));
        if (!msg) {
            // Handle memory allocation failure
            free(msg);
            return -1;
        }
        msg->PHICH_CONFIGURATION = rand() % 1000;
        msg->UE_ID = i;
        msg->DL_MCH_DATA_TAG = (char*)malloc(max_batch_size*1024); // dynamically allocate buffer for data tag
        if (!msg->DL_MCH_DATA_TAG) {
            free(msg);
            return -1;
        }
        // Add message to queue and notify processing service
        pthread_mutex_lock(&msg_queue_mutex);
        msg_queue[msg_queue_head] = *msg;
        (msg_queue_head)++;
        if (msg_queue_head >= MAX_QUEUE_SIZE) {
            msg_queue_head = 0; // wrap around
        }
        pthread_cond_signal(&msg_queue_cond);
    }

    return 0;
}

// Define function to process and send messages asynchronously
void* process_msg(void* arg) {
    struct msg* msg = (struct msg*)arg;
    // Process message based on priority level
    if (msg->priority_level > 5.0f) {
        // High-priority message, prioritize processing and sending
        pthread_mutex_lock(&msg_queue_mutex);
        send_message(msg); // send message to external service
        pthread_cond_signal(&msg_queue_cond);
        pthread_mutex_unlock(&msg_queue_mutex);
    } else {
        // Low-priority message, process in background
        pthread_create(&thread_id, NULL, process_low_priority_msg, (void*)msg);
    }
}

// Define function to monitor and adjust resource usage dynamically
int monitor_system_load() {
    float cpu_usage = get_cpu_usage();
    float mem_usage = get_mem_usage();

    // Calculate weighted average of CPU and memory consumption over last 5 minutes
    float load_avg = (cpu_usage + mem_usage) / 2.0f;

    if (load_avg > 80.0f) {
        // System is overloaded, adjust resource usage dynamically
        int max_msg_size = get_max_msg_size();
        max_msg_size /= 2; // reduce batch size to prevent overloading
    } else {
        // System is underloaded, increase batch size to improve throughput
        int max_msg_size = get_max_msg_size();
        max_msg_size *= 2; // double batch size to utilize spare resources
    }

    return load_avg;
}

// Define function to detect and log memory leaks during initialization
void* mem_leak_detector(void* arg) {
