#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 10 // maximum number of unique RNTIs
#define MAX_THREADS 5 // maximum number of concurrent threads
#define MEMORY_POOL_SIZE 1024 * 1024 // initial size of memory pool

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[16];
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// custom memory pool structure
typedef struct {
    void** blocks;
    int size;
    int free_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(int size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->size = size;
    mp->free_blocks = 0;
    mp->blocks = (void**)malloc(size * sizeof(void*));
    for (int i = 0; i < size; i++) {
        mp->blocks[i] = NULL;
    }
    return mp;
}

void free_memory_pool(MemoryPool* mp) {
    for (int i = 0; i < mp->size; i++) {
        if (mp->blocks[i] != NULL) {
            free(mp->blocks[i]);
        }
    }
    free(mp->blocks);
    free(mp);
}

// atomic operations for thread-safe access
#include <stdatomic.h>

Atomic_int rnti_count = ATOMIC_VAR_INIT(0);

void increment_rnti_count() {
    atomic_fetch_add(&rnti_count, 1);
}

int get_unique_rnti() {
    return atomic_exchange(&rnti_count, -1) + 1;
}

// function to allocate and populate NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = rnti;
        strcpy(pdu->RNTI, "unique_rnti");
        pdu->CRC_INDICATION_REL8_TAG = 0x1234;
        srand(time(NULL)); // set random seed
        pdu->CRCFLAG = rand() % 2; // randomly set CRCFLAG
    }
    return pdu;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        free(pdu);
    }
}

// main function to dynamically allocate and populate NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** create_crc_indications(int num_crc_indications, int max_threads) {
    NFAPI_CRC_INDICATION_PDU_T** crc_indications = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    MemoryPool* mp = create_memory_pool(MEMORY_POOL_SIZE);

    for (int i = 0; i < num_crc_indications; i++) {
        int rnti = get_unique_rnti();
        crc_indications[i] = create_crc_indication_pdu(rnti);

        // handle memory allocation failure
        if (crc_indications[i] == NULL) {
            printf("Memory allocation failed for RNTI %d.\n", rnti);
            continue;
        }
    }

    free_memory_pool(mp);

    return crc_indications;
}

void log_error(const char* message) {
    printf("Error: %s\n", message);
}

int main() {
    int num_crc_indications = N; // specify the number of unique RNTIs
    int max_threads = MAX_THREADS; // specify the maximum number of concurrent threads

    NFAPI_CRC_INDICATION_PDU_T** crc_indications = create_crc_indications(num_crc_indications, max_threads);

    for (int i = 0; i < num_crc_indications; i++) {
        printf("RNTI %d: RX_UE_INFORMATION_TAG = %d, RNTI = %s, CRC_INDICATION_REL8_TAG = 0x%x, CRCFLAG = %d\n", 
               crc_indications[i]->RX_UE_INFORMATION_TAG, crc_indications[i]->RX_UE_INFORMATION_TAG, crc_indications[i]->RNTI, crc_indications[i]->CRC_INDICATION_REL8_TAG, crc_indications[i]->CRCFLAG);
    }

    for (int i = 0; i < num_crc_indications; i++) {
        free_crc_indication_pdu(crc_indications[i]);
    }

    free(crc_indications);

    return 0;
}
