// Structure to represent a network interface configuration
typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    void* routing_rules;
} NetworkConfig;

// Dynamic collection of network configurations
typedef struct {
    int size;
    NetworkConfig** configs;
} NetworkConfigCollection;

// Function to initialize a new network configuration collection
NetworkConfigCollection* network_config_collection_init() {
    NetworkConfigCollection* coll = (NetworkConfigCollection*)malloc(sizeof(NetworkConfigCollection));
    coll->size = 0;
    coll->configs = NULL;
    return coll;
}

// Function to add a new network configuration to the collection
int network_config_collection_add(NetworkConfigCollection* coll, char* ip_address, char* subnet_mask, char* gateway) {
    // Allocate memory for the new configuration
    NetworkConfig* config = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    strcpy(config->ip_address, ip_address);
    strcpy(config->subnet_mask, subnet_mask);
    strcpy(config->gateway, gateway);
    config->routing_rules = NULL;

    // Reallocate array to store configurations if necessary
    if (coll->size == 0) {
        coll->configs = (NetworkConfig**)malloc(sizeof(NetworkConfig*) * 2);
    } else if (coll->size == (int)(sizeof(coll->configs) / sizeof(coll->configs[0]))) {
        int newSize = coll->size * 2;
        coll->configs = (NetworkConfig**)realloc(coll->configs, sizeof(NetworkConfig*) * newSize);
    }

    // Add the new configuration to the collection
    coll->configs[coll->size] = config;
    coll->size++;

    return 0;
}

// Function to remove a network configuration from the collection
int network_config_collection_remove(NetworkConfigCollection* coll, int index) {
    if (index >= coll->size || index < 0) {
        return -1; // Invalid index
    }

    // Free memory allocated for the removed configuration
    free(coll->configs[index]->routing_rules);
    free(coll->configs[index]);

    // Reallocate array to store configurations without the removed one
    NetworkConfig** newConfigs = (NetworkConfig**)malloc(sizeof(NetworkConfig*) * (coll->size - 1));
    int j = 0;
    for (int i = 0; i < coll->size; i++) {
        if (i != index) {
            newConfigs[j] = coll->configs[i];
            j++;
        }
    }

    // Update the collection's configuration array
    free(coll->configs);
    coll->configs = newConfigs;
    coll->size--;

    return 0;
}

// Function to update a network configuration in the collection
int network_config_collection_update(NetworkConfigCollection* coll, int index, char* ip_address, char* subnet_mask, char* gateway) {
    if (index >= coll->size || index < 0) {
        return -1; // Invalid index
    }

    NetworkConfig* config = coll->configs[index];
    strcpy(config->ip_address, ip_address);
    strcpy(config->subnet_mask, subnet_mask);
    strcpy(config->gateway, gateway);

    return 0;
}

