#define MAX_FLOW_STATISTICS 1000
#define MAX_FLOOD_ID_LENGTH 32

typedef struct TrafficFlowStatistics {
    char flow_id[MAX_FLOOD_ID_LENGTH];
    int bytes_transmitted;
    int bytes_received;
} TrafficFlowStatistics;

TrafficFlowStatistics *flow_statistics = NULL;
int num_flow_statistics = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = fopen("traffic_flow_log.txt", "a");

void add_flow_statistic(TrafficFlowStatistics **statistics, char *flow_id) {
    pthread_mutex_lock(&mutex);
    *statistics = realloc(*statistics, (num_flow_statistics + 1) * sizeof(TrafficFlowStatistics));
    if (*statistics == NULL) {
        fprintf(log_file, "Error: unable to allocate memory for new flow statistic\n");
        return;
    }
    strcpy((*statistics)[num_flow_statistics].flow_id, flow_id);
    (*statistics)[num_flow_statistics].bytes_transmitted = 0;
    (*statistics)[num_flow_statistics].bytes_received = 0;
    num_flow_statistics++;
    pthread_mutex_unlock(&mutex);
}

void update_flow_statistic(TrafficFlowStatistics **statistics, char *flow_id, int bytes_transmitted, int bytes_received) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_flow_statistics; i++) {
        if (strcmp((*statistics)[i].flow_id, flow_id) == 0) {
            (*statistics)[i].bytes_transmitted += bytes_transmitted;
            (*statistics)[i].bytes_received += bytes_received;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    fprintf(log_file, "Error: flow statistic not found for update\n");
    pthread_mutex_unlock(&mutex);
}

TrafficFlowStatistics *get_flow_statistic(TrafficFlowStatistics **statistics, char *flow_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_flow_statistics; i++) {
        if (strcmp((*statistics)[i].flow_id, flow_id) == 0) {
            pthread_mutex_unlock(&mutex);
            return &(*statistics)[i];
        }
    }
    fprintf(log_file, "Error: flow statistic not found\n");
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* periodic_stats_update(void *ptr) {
    while (1) {
        // Update statistics based on recent network activity reports
        // ...

        sleep(60); // Update every minute
    }
    return NULL;
}

int main() {
    pthread_t update_thread;
    pthread_create(&update_thread, NULL, periodic_stats_update, NULL);

    // Example usage:
    add_flow_statistic(&flow_statistics, "Flow1");
    update_flow_statistic(&flow_statistics, "Flow1", 1000, 800);
    TrafficFlowStatistics *stat = get_flow_statistic(&flow_statistics, "Flow1");
    if (stat != NULL) {
        printf("Bytes transmitted: %d\nBytes received: %d\n", stat->bytes_transmitted, stat->bytes_received);
    }

    pthread_join(update_thread, NULL);

    return 0;
}
