void process_nfaapi_cqi_indication_and_max_value(int N, int* input_size, float** cqi_data) {
    // Generate NFAPI CQI Indication Structures
    NFAPI_CQI_INDICATION_PDU_T* nfa_cqis = (NFAPI_CQI_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CQI_INDICATION_PDU_T));

    if (!nfa_cqis) {
        printf("Memory allocation failed. Exiting.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        nfa_cqis[i].RX_UE_INFORMATION_TAG = i;
        nfa_cqis[i].RNTI = rand() % 100 + 1;
        nfa_cqis[i].CQIFLAG = (float)rand() / RAND_MAX;
        nfa_cqis[i].SNR = (float)rand() / RAND_MAX + 5.0f; // random SNR value
    }

    // Read Input Data
    float* input_data = *cqi_data;
    for (int i = 0; i < *input_size && i < MAX_INPUT_SIZE; i++) {
        scanf("%f", &input_data[i]);
    }

    if (*input_size > MAX_INPUT_SIZE) {
        printf("Input size exceeded maximum limit. Truncated input.\n");
    }

    // Compute the Average SNR
    float average_snr = compute_average_snr(input_data, *input_size);

    // Find and Print the Largest SNR
    float max_snr = find_max_snr(input_data, *input_size);

    // Resource Management
    free(nfa_cqis);
}

float compute_average_snr(float* data, int size) {
    if (size == 0) {
        return NAN;
    }

    float sum = 0.0f;

    for (int i = 0; i < size; i++) {
        sum += data[i];
    }

    return sum / size;
}

float find_max_snr(float* data, int size) {
    if (size == 0) {
        return -1.0f;
    }

    float max = data[0];

    for (int i = 1; i < size; i++) {
        if (data[i] > max) {
            max = data[i];
        }
    }

    return max;
}
