#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure representing a control message
typedef struct {
    int phich_configuration;
    char ue_id[256];
    void* dl_mch_data_tag;
} phy_layer_control_message_t;

// Structure representing a named semaphore
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int value;
    char name[256];
} named_semaphore_t;

// Dynamic array of LTE PHY Layer Control Messages
phy_layer_control_message_t* lte_messages = NULL;
int num_lte_messages = 0;

// Dynamic collection of named semaphores
named_semaphore_t** named_semaphores = NULL;
int num_named_semaphores = 0;

void init_lte_phy_layer() {
    // Initialize dynamic array and collection
    lte_messages = (phy_layer_control_message_t*)malloc(10 * sizeof(phy_layer_control_message_t));
    num_lte_messages = 0;
    named_semaphores = (named_semaphore_t**)malloc(10 * sizeof(named_semaphore_t*));
    num_named_semaphores = 0;
}

void free_lte_phy_layer() {
    // Free dynamic array and collection
    for (int i = 0; i < num_lte_messages; i++) {
        free(lte_messages[i].dl_mch_data_tag);
    }
    free(lte_messages);
    for (int i = 0; i < num_named_semaphores; i++) {
        pthread_mutex_destroy(&named_semaphores[i]->mutex);
        pthread_cond_destroy(&named_semaphores[i]->cond);
        free(named_semaphores[i]);
    }
    free(named_semaphores);
}

phy_layer_control_message_t* create_lte_message(int phich_config, char* ue_id) {
    // Allocate and initialize control message
    phy_layer_control_message_t* msg = (phy_layer_control_message_t*)malloc(sizeof(phy_layer_control_message_t));
    msg->phich_configuration = phich_config;
    strcpy(msg->ue_id, ue_id);
    msg->dl_mch_data_tag = NULL;

    // Add to dynamic array and update count
    lte_messages = realloc(lte_messages, (num_lte_messages + 1) * sizeof(phy_layer_control_message_t));
    lte_messages[num_lte_messages] = msg;
    num_lte_messages++;

    return msg;
}

void delete_lte_message(int idx) {
    // Find and free control message
    phy_layer_control_message_t* msg = &lte_messages[idx];
    if (msg->dl_mch_data_tag != NULL) {
        free(msg->dl_mch_data_tag);
    }
    free(msg);

    // Update dynamic array and count
    memmove(&lte_messages[idx], &lte_messages[idx + 1], (num_lte_messages - idx - 1) * sizeof(phy_layer_control_message_t));
    num_lte_messages--;
}

named_semaphore_t* create_named_semaphore(char* name, int initial_value) {
    // Allocate and initialize named semaphore
    named_semaphore_t* sem = (named_semaphore_t*)malloc(sizeof(named_semaphore_t));
    strcpy(sem->name, name);
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    // Add to dynamic collection and update count
    named_semaphores = realloc(named_semaphores, (num_named_semaphores + 1) * sizeof(named_semaphore_t*));
    named_semaphores[num_named_semaphores] = sem;
    num_named_semaphores++;

    return sem;
}

void delete_named_semaphore(char* name) {
    // Find and free named semaphore
    for (int i = 0; i < num_named_semaphores; i++) {
        if (strcmp(named_semaphores[i]->name, name) == 0) {
            pthread_mutex_destroy(&named_semaphores[i]->mutex);
            pthread_cond_destroy(&named_semaphores[i]->cond);
            free(named_semaphores[i]);
            memmove(&named_semaphores[i], &named_semaphores[i + 1], (num_named_semaphores - i - 1) * sizeof(named_semaphore_t*));
            num_named_semaphores--;
            return;
        }
    }
}

int main() {
    // Initialize LTE PHY layer
    init_lte_phy_layer();

    // Create and configure semaphores
    create_named_semaphore("semaphore_1", 5);
    create_named_semaphore("semaphore_2", 10);

    // Create control messages
    phy_layer_control_message_t* msg1 = create_lte_message(0, "UE1");
    phy_layer_control_message_t* msg2 = create_lte_message(1, "UE2");

    // Perform semaphore operations
    pthread_mutex_lock(&named_semaphores[0]->mutex);
    pthread_cond_signal(&named_semaphores[0]->cond);

    pthread_mutex_unlock(&named_semaphores[0]->mutex);

    // Delete control messages and semaphores
    delete_lte_message(1);
    delete_named_semaphore("semaphore_2");

    // Free LTE PHY layer resources
    free_lte_phy_layer();

    return 0;
}
