void add_cell_id(NetworkEventLogEntry* entry, int cell_id) {
    CellId* new_cell_id = (CellId*)malloc(sizeof(CellId));
    if (!new_cell_id) return;
    new_cell_id->id = cell_id;
    new_cell_id->next = entry->cell_ids;
    entry->cell_ids = new_cell_id;
}

void free_log_entry(NetworkEventLogEntry* entry) {
    CellId* current = entry->cell_ids;
    while (current) {
        CellId* next = current->next;
        free(current);
        current = next;
    }
    free(entry);
}

