void* allocate_list(int n) {
    return malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int populate_list(void* list, int n) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = ((NFAPI_CRC_INDICATION_PDU_T*)list) + i;
        pdu->RX_UE_INFORMATION_TAG = i % 100; // Ensure valid NID
        pdu->RNTI = rand() % (1 << 15); // Randomize RNTI values
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        // Validate RX_UE_INFORMATION_TAG and handle duplicate RNTI values
        for (int j = 0; j < i; j++) {
            if (((NFAPI_CRC_INDICATION_PDU_T*)list) + j ->RX_UE_INFORMATION_TAG == pdu->RX_UE_INFORMATION_TAG &&
                ((NFAPI_CRC_INDICATION_PDU_T*)list) + j ->RNTI == pdu->RNTI) {
                // Handle duplicate RNTI values gracefully (e.g., reassign a new RNTI)
                pdu->RNTI = rand() % (1 << 15);
            }
        }

        if (pdu->RX_UE_INFORMATION_TAG > 100) { // Ensure valid NID
            return -1; // Error: invalid NID
        }
    }

    return 0; // Success
}

int serialize_list(void* list, int n) {
    FILE* file = fopen("nfa_pi_crc_indication_pdu_t.dat", "wb");
    if (!file) {
        return -1; // Error: unable to open file for writing
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);

    fclose(file);
    return 0; // Success
}

void free_list(void* list) {
    free(list);
}

int main() {
    int n = 100000;
    void* list = allocate_list(n);
    if (!list) {
        printf("Memory allocation failed.\n");
        return -1; // Error: memory allocation failed
    }

    int result = populate_list(list, n);
    if (result < 0) {
        printf("Error populating the list: invalid NID.\n");
        free_list(list);
        return -1; // Error: error populating the list
    }

    int serialization_result = serialize_list(list, n);
    if (serialization_result < 0) {
        printf("Error serializing the list.\n");
    } else {
        printf("Serialized the list successfully.\n");
    }

    free_list(list);

    return 0; // Success
}
