#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/time.h>

// Custom memory allocator for optimized cache utilization
void* my_malloc(size_t size) {
    return malloc(size);
}

void my_free(void* ptr) {
    free(ptr);
}

// HTTP_REQUEST structure to store request headers, body data, and status code
typedef struct {
    char** headers;
    unsigned int header_count;
    char* body_data;
    int status_code;
} HTTP_REQUEST;

// Cache entry structure with TTL, cache hit/miss counters, and eviction status
typedef struct {
    HTTP_REQUEST* request;
    time_t created_at;
    time_t ttl;
    int hits;
    int misses;
    int evicted;
} CACHE_ENTRY;

// Cache management function to initialize, insert, retrieve, and manage cache entries
void* http_request_cache_init(unsigned int capacity) {
    // Initialize custom memory allocator
    my_malloc = malloc;
    my_free = free;

    // Allocate memory for the cache array
    void** cache_array = (void**)my_malloc(sizeof(void*) * capacity);

    // Initialize cache entry counters and eviction status
    int hits = 0, misses = 0, evictions = 0;

    return cache_array;
}

int http_request_cache_insert(void* cache_array, HTTP_REQUEST* request, time_t ttl) {
    // Find the least recently used (LRU) entry in the cache array
    CACHE_ENTRY* lru_entry = NULL;
    for (void** ptr = (void**)cache_array; *ptr != NULL; ++ptr) {
        if (lru_entry == NULL || (*ptr)->created_at < lru_entry->created_at)
            lru_entry = *ptr;
    }

    // Check if the cache is full
    if (lru_entry && lru_entry->request) {
        // Evict the LRU entry to make space for the new request
        my_free(lru_entry);
    }

    // Insert the new request into the cache array
    *ptr = my_malloc(sizeof(CACHE_ENTRY));
    (*ptr)->request = request;
    (*ptr)->created_at = time(NULL);
    (*ptr)->ttl = ttl;
    (*ptr)->hits = 0;
    (*ptr)->misses = 0;
    (*ptr)->evicted = 0;

    return 0; // Successful insertion
}

int http_request_cache_retrieve(void* cache_array, HTTP_REQUEST** request) {
    // Find the least recently used (LRU) entry in the cache array
    CACHE_ENTRY* lru_entry = NULL;
    for (void** ptr = (void**)cache_array; *ptr != NULL; ++ptr) {
        if (lru_entry == NULL || (*ptr)->created_at < lru_entry->created_at)
            lru_entry = *ptr;
    }

    // Check if the cache is empty
    if (!lru_entry) {
        return -1; // Cache miss, request not found
    }

    // Update the hit counter and refresh the TTL
    ++lru_entry->hits;
    time_t current_time = time(NULL);
    if (current_time > lru_entry->created_at + lru_entry->ttl) {
        // Evict the entry due to TTL expiration
        my_free(lru_entry);
        return -1; // Cache miss, request expired
    }

    *request = lru_entry->request;

    return 0; // Successful retrieval
}

void http_request_cache_log(void* cache_array, int hits, int misses, int evictions) {
    printf("Cache Hits: %d\n", hits);
    printf("Cache Misses: %d\n", misses);
    printf("Cache Evictions: %d\n", evictions);
}
