#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum number of frames
#define MAX_FRAMES 10000

// Structure to hold frame information
typedef struct {
    // Frame header information
    char dl_frame_header[50];

    // PDSCH symbol information
    int pdsch_symbol;

    // PUCCH symbol information
    int pucch_symbol;

    // PDSCH data
    char pdusch_data[1024];

    // CQI value
    int cq_index;

    // PUSCH QPSK modulation
    int pusch_qpsk_modulation;
} LTE_DL_FRAME_STRUCT;

// Function to initialize the dynamic array of frames
LTE_DL_FRAME_STRUCT** lte_dl_frame_init(int max_frames) {
    // Check if the requested maximum number of frames exceeds the default limit
    if (max_frames > MAX_FRAMES) {
        printf("Maximum frame limit exceeded. Using the default limit.\n");
        max_frames = MAX_FRAMES;
    }

    // Initialize the dynamic array with a starting size
    LTE_DL_FRAME_STRUCT** lte_dl_frame_array = (LTE_DL_FRAME_STRUCT**)malloc(max_frames * sizeof(LTE_DL_FRAME_STRUCT*));

    for (int i = 0; i < max_frames; i++) {
        lte_dl_frame_array[i] = (LTE_DL_FRAME_STRUCT*)malloc(sizeof(LTE_DL_FRAME_STRUCT));

        // Initialize frame information
        strcpy(lte_dl_frame_array[i]->dl_frame_header, "DL Frame Header");
        lte_dl_frame_array[i]->pdsch_symbol = rand() % 100;
        lte_dl_frame_array[i]->pucch_symbol = rand() % 200;
        for (int j = 0; j < 1024; j++) {
            lte_dl_frame_array[i]->pdusch_data[j] = 'A' + rand() % 26;
        }
        lte_dl_frame_array[i]->cq_index = rand() % 16;
        lte_dl_frame_array[i]->pusch_qpsk_modulation = rand() % 4;
    }

    // Initialize the frame counter
    int frame_count = 0;

    // Define a function to generate and add new frames
    void add_frame(LTE_DL_FRAME_STRUCT** lte_dl_frame_array, int max_frames) {
        if (frame_count < max_frames) {
            lte_dl_frame_array[frame_count] = (LTE_DL_FRAME_STRUCT*)malloc(sizeof(LTE_DL_FRAME_STRUCT));

            // Initialize frame information
            strcpy(lte_dl_frame_array[frame_count]->dl_frame_header, "DL Frame Header");
            lte_dl_frame_array[frame_count]->pdsch_symbol = rand() % 100;
            lte_dl_frame_array[frame_count]->pucch_symbol = rand() % 200;
            for (int j = 0; j < 1024; j++) {
                lte_dl_frame_array[frame_count]->pdusch_data[j] = 'A' + rand() % 26;
            }
            lte_dl_frame_array[frame_count]->cq_index = rand() % 16;
            lte_dl_frame_array[frame_count]->pusch_qpsk_modulation = rand() % 4;

            frame_count++;
        } else {
            printf("Maximum number of frames reached.\n");
        }
    }

    // Define a function to log the generation of each frame
    void log_frame(LTE_DL_FRAME_STRUCT** lte_dl_frame_array, int frame_id) {
        time_t current_time = time(NULL);

        printf("Frame %d generated at %s\n", frame_id, asctime(localtime(&current_time)));
    }

    // Function to dynamically adjust the maximum frame limit
    void adjust_max_frames(LTE_DL_FRAME_STRUCT** lte_dl_frame_array, int new_max_frames) {
        if (new_max_frames > 0 && new_max_frames <= MAX_FRAMES) {
            max_frames = new_max_frames;

            // Reallocate memory for the dynamic array
            lte_dl_frame_array = (LTE_DL_FRAME_STRUCT**)realloc(lte_dl_frame_array, new_max_frames * sizeof(LTE_DL_FRAME_STRUCT*));
        } else if (new_max_frames > MAX_FRAMES) {
            printf("Maximum frame limit exceeded. Using the default limit.\n");
        }
    }

    // Function to deallocate memory for the dynamic array
    void lte_dl_frame_deinit(LTE_DL_FRAME_STRUCT** lte_dl_frame_array, int max_frames) {
        for (int i = 0; i < max_frames; i++) {
            free(lte_dl_frame_array[i]);
        }

        free(lte_dl_frame_array);
    }

    return lte_dl_frame_array;
}
