#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure for the dynamic data structure
typedef struct {
    int value;
} Record;

// Structure to represent the memory pool
typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity, used;
} MemoryPool;

// Function to initialize the memory pool with a specified capacity
MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    mp->offsets = malloc(sizeof(long) * capacity);
    mp->keys = malloc(sizeof(int) * capacity);
    mp->records = malloc(sizeof(Record*) * capacity);
    mp->capacity = capacity;
    mp->used = 0;
    return mp;
}

// Function to free the memory pool
void free_memory_pool(MemoryPool* mp) {
    if (mp == NULL) return;
    free(mp->offsets);
    free(mp->keys);
    free(mp->records);
    free(mp);
}

// Function to allocate a new record and update the memory pool
Record* alloc_record(MemoryPool* mp) {
    Record* r = &((Record*)malloc(sizeof(Record)));
    r->value = rand() % 1001; // Initialize with a unique random number
    mp->records[mp->used] = r;
    mp->keys[mp->used] = rand(); // Assign a random key for record allocation
    mp->offsets[mp->used]++] = (long)(mp->used);
    return r;
}

// Function to deallocate a record and update the memory pool
void free_record(MemoryPool* mp, int index) {
    if (index < 0 || index >= mp->used) return; // Check for valid index
    Record* r = mp->records[index];
    mp->keys[index] = -1; // Mark key as invalid
    mp->offsets[index] = -1; // Mark offset as invalid
    free(r);
    mp->used--;
}

// Function to print memory usage statistics
void print_memory_usage(MemoryPool* mp) {
    printf("Memory Pool Statistics:\n");
    printf("Capacity: %zu\n", mp->capacity);
    printf("Used: %d\n", mp->used);
    printf("Total Memory Used: %zu bytes\n", mp->used * sizeof(Record));
}

int main() {
    srand(time(NULL)); // Initialize random number generator
    size_t capacity = 1000; // Initial memory pool capacity
    MemoryPool* mp = init_memory_pool(capacity);

    for (int i = 0; i < 10; i++) { // Allocate and deallocate records
        Record* r = alloc_record(mp);
        printf("Allocated record: %d\n", r->value);
        free_record(mp, i);
    }

    print_memory_usage(mp); // Print memory usage statistics

    free_memory_pool(mp);

    return 0;
}
