int init_and_config_mac_rx_pdu(size_t initial_capacity, size_t sdu_buffer_size) {
    pthread_mutex_init(&mutex, NULL);

    mac_rx_pdu = (MAC_RX_PDU*)malloc(initial_capacity * sizeof(MAC_RX_PDU));
    for (size_t i = 0; i < initial_capacity; i++) {
        mac_rx_pdu[i].sdusize = 0;
        mac_rx_pdu[i].sduBuffers = malloc_array(1, sdu_buffer_size);
    }

    pthread_cond_init(&cond, NULL);

    return 0;
}

void insert_mac_rx_pdu(MAC_RX_PDU* pdu) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < mac_rx_pdu_capacity; i++) {
        if (mac_rx_pdu[i].header.valid) {
            // Find the first available slot
            size_t index;
            for (index = 0; ; index++) {
                if (!mac_rx_pdu[index].header.valid)
                    break;
            }
            mac_rx_pdu[index] = *pdu;
            pthread_cond_signal(&cond);
            return;
        }
    }
    // If the array is full, allocate more space and reinsert
    size_t new_capacity = mac_rx_pdu_capacity * 2;
    MAC_RX_PDU* new_array = (MAC_RX_PDU*)realloc(mac_rx_pdu, new_capacity * sizeof(MAC_RX_PDU));
    for (size_t i = initial_capacity; i < new_capacity; i++) {
        new_array[i].header.valid = false;
    }
    mac_rx_pdu = new_array;
    mac_rx_pdu_capacity = new_capacity;
    insert_mac_rx_pdu(pdu);
}

int get_mac_rx_pdu(size_t index, MAC_RX_PDU* pdu) {
    pthread_mutex_lock(&mutex);
    if (index >= mac_rx_pdu_capacity)
        return -1; // Out of bounds
    *pdu = mac_rx_pdu[index];
    return 0;
}

