void lte_phy_layer_control_message_init(LTE_PHY_LAYER_CONTROL_MESSAGE** messages, uint32_t* num_messages) {
    *num_messages = 0;
}

int lte_phy_layer_control_message_create_single(LTE_PHY_LAYER_CONTROL_MESSAGE** messages, uint32_t* num_messages, PHICH_CONFIGURATION phich_config, uint32_t ue_id, char* dl_mch_data_tag) {
    LTE_PHY_LAYER_CONTROL_MESSAGE* new_message;

    if (*num_messages >= BATCH_PROCESSING_LIMIT) {
        // Handle batch processing limit exceeded
        return -1;
    }

    new_message = (LTE_PHY_LAYER_CONTROL_MESSAGE*)malloc(sizeof(LTE_PHY_LAYER_CONTROL_MESSAGE));
    if (!new_message) {
        // Handle memory allocation failure
        return -2;
    }

    new_message->phich_config = phich_config;
    new_message->ue_id = ue_id;
    new_message->dl_mch_data_tag = (char*)malloc(strlen(dl_mch_data_tag) + 1);
    if (!new_message->dl_mch_data_tag) {
        free(new_message);
        return -3;
    }
    strcpy(new_message->dl_mch_data_tag, dl_mch_data_tag);

    (*messages)[(*num_messages)++] = new_message;

    return 0;
}

int lte_phy_layer_control_message_create_batch(LTE_PHY_LAYER_CONTROL_MESSAGE** messages, uint32_t* num_messages, PHICH_CONFIGURATION phich_config[], uint32_t ue_ids[], char* dl_mch_data_tags[], uint32_t num_elements) {
    if (*num_messages + num_elements > BATCH_PROCESSING_LIMIT) {
        // Handle batch processing limit exceeded
        return -1;
    }

    for (uint32_t i = 0; i < num_elements; i++) {
        LTE_PHY_LAYER_CONTROL_MESSAGE* new_message;

        new_message = (LTE_PHY_LAYER_CONTROL_MESSAGE*)malloc(sizeof(LTE_PHY_LAYER_CONTROL_MESSAGE));
        if (!new_message) {
            // Handle memory allocation failure
            return -2;
        }

        new_message->phich_config = phich_config[i];
        new_message->ue_id = ue_ids[i];
        new_message->dl_mch_data_tag = (char*)malloc(strlen(dl_mch_data_tags[i]) + 1);
        if (!new_message->dl_mch_data_tag) {
            free(new_message);
            return -3;
        }
        strcpy(new_message->dl_mch_data_tag, dl_mch_data_tags[i]);

        (*messages)[(*num_messages)++] = new_message;
    }

    return 0;
}

void lte_phy_layer_control_message_free(LTE_PHY_LAYER_CONTROL_MESSAGE** messages, uint32_t num_messages) {
    for (uint32_t i = 0; i < num_messages; i++) {
        free((*messages)[i]->dl_mch_data_tag);
        free((*messages)[i]);
    }
}
