int profile_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_profile(Profile* new_profile) {
    pthread_mutex_lock(&lock);
    if (profile_count < MAX_PROFILES) {
        profiles[profile_count] = new_profile;
        profile_count++;
    }
    pthread_mutex_unlock(&lock);
}

Profile* get_profile(const char* email) {
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i]->email, email) == 0) {
            return profiles[i];
        }
    }
    return NULL;
}

void remove_profile(const char* email) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i]->email, email) == 0) {
            free(profiles[i]);
            for (int j = i + 1; j < profile_count; j++) {
                profiles[j - 1] = profiles[j];
            }
            profile_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* cache_thread(void* arg) {
    // Cache invalidation logic
    return NULL;
}

