    uint32_t crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to manage the dynamic list of NFAPI CRC indication PDUs
typedef struct {
    int size; // current size of the list
    int capacity; // allocated memory for the list
    NFAPI_CRC_INDICATION_PDU_T* data; // pointer to the dynamically allocated array
    pthread_mutex_t lock; // fine-grained locking mechanism
} NFAPI_CRC_INDICATION_PDU_MANAGER;

// Function to initialize the NFAPI CRC indication PDU manager
NFAPI_CRC_INDICATION_PDU_MANAGER*
nfapi_crc_indication_pdu_manager_init(int initial_capacity) {
    NFAPI_CRC_INDICATION_PDU_MANAGER* manager;
    // Allocate memory for the manager structure and initialize it
    manager = (NFAPI_CRC_INDICATION_PDU_MANAGER*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_MANAGER));
    if (!manager) {
        return NULL; // error: unable to allocate memory
    }
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->data) {
        free(manager); // error: unable to allocate memory for the list
        return NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add an NFAPI CRC indication PDU to the manager
int
nfapi_crc_indication_pdu_manager_add(NFAPI_CRC_INDICATION_PDU_MANAGER* manager,
                                       NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Check if the list needs to be resized
    if (manager->size >= manager->capacity) {
        // Resize the list by allocating new memory and copying existing data
        int new_capacity = manager->capacity * 2; // simple exponential growth strategy
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            return -1; // error: unable to allocate memory for the list
        }
        pthread_mutex_lock(&manager->lock);
        memcpy(new_data, manager->data, manager->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(manager->data);
        manager->data = new_data;
        manager->capacity = new_capacity;
        pthread_mutex_unlock(&manager->lock);
    }
    // Add the pdu to the end of the list
    memcpy(&manager->data[manager->size], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size++;
    return 0; // success
}

// Function to remove an NFAPI CRC indication PDU from the manager
int
nfapi_crc_indication_pdu_manager_remove(NFAPI_CRC_INDICATION_PDU_MANAGER* manager,
                                          int index) {
    if (index < 0 || index >= manager->size) {
        return -1; // error: invalid index
    }
    pthread_mutex_lock(&manager->lock);
    // Copy the last pdu to the removed position and decrement the size
    memcpy(&manager->data[index], &manager->data[manager->size - 1],
           sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size--;
    pthread_mutex_unlock(&manager->lock);
    return 0; // success
}

// Function to calculate the CRC value of the NFAPI CRC indication PDUs and compare it with stored CRC flags
void
nfapi_crc_indication_pdu_manager_verify(NFAPI_CRC_INDICATION_PDU_MANAGER* manager) {
    int i;
    pthread_mutex_lock(&manager->lock);
    for (i = 0; i < manager->size; i++) {
        // Calculate the CRC value and compare it with the stored CRC flag
        uint32_t calculated_crc = calculate_crc(manager->data[i]);
        if (calculated_crc != manager->data[i].crcFlag) {
            printf("Error: CRC mismatch detected at index %d\n", i);
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    // Initialize the NFAPI CRC indication PDU manager
    NFAPI_CRC_INDICATION_PDU_MANAGER* manager = nfapi_crc_indication_pdu_manager_init(10);

    // Add some NFAPI CRC indication PDUs to the manager
    NFAPI_CRC_INDICATION_PDU_T pdu1;
    NFAPI_CRC_INDICATION_PDU_T pdu2;
    // ...
    int result = nfapi_crc_indication_pdu_manager_add(manager, pdu1);
    if (result != 0) {
        printf("Error: unable to add the PDU\n");
    }
    result = nfapi_crc_indication_pdu_manager_add(manager, pdu2);
    if (result != 0) {
        printf("Error: unable to add the PDU\n");
    }

    // Remove some NFAPI CRC indication PDUs from the manager
    int index_to_remove;
    result = nfapi_crc_indication_pdu_manager_remove(manager, index_to_remove);
    if (result != 0) {
        printf("Error: unable to remove the PDU\n");
    }

    // Verify the integrity of the NFAPI CRC indication PDUs
    nfapi_crc_indication_pdu_manager_verify(manager);

    return 0;
}
