typedef struct {
    int bandwidth;
    float subcarrierSpacing;
    float frequencyOffset;
} LTEConfig;

typedef struct {
    LTEConfig* configs;
    size_t capacity;
    size_t length;
} LTEConfigList;

LTEConfigList* lte_config_list_init(size_t initialCapacity) {
    LTEConfigList* list = (LTEConfigList*)malloc(sizeof(LTEConfigList));
    list->configs = (LTEConfig*)calloc(initialCapacity, sizeof(LTEConfig));
    list->capacity = initialCapacity;
    list->length = 0;
    return list;
}

void lte_config_list_free(LTEConfigList* list) {
    free(list->configs);
    free(list);
}

int lte_config_list_add_config(LTEConfigList* list, int bandwidth, float subcarrierSpacing, float frequencyOffset) {
    if (list->length >= list->capacity) {
        // Resize the list if necessary
        size_t newCapacity = list->capacity * 2;
        LTEConfigList* newList = lte_config_list_init(newCapacity);
        for (size_t i = 0; i < list->length; ++i) {
            newList->configs[i] = list->configs[i];
        }
        free(list->configs);
        list = newList;
    }

    // Check if the bandwidth already exists
    for (size_t i = 0; i < list->length; ++i) {
        if (list->configs[i].bandwidth == bandwidth) {
            printf("Error: Bandwidth %d already exists in the configuration list.\n", bandwidth);
            return -1;
        }
    }

    // Add the new configuration
    list->configs[list->length].bandwidth = bandwidth;
    list->configs[list->length].subcarrierSpacing = subcarrierSpacing;
    list->configs[list->length].frequencyOffset = frequencyOffset;
    ++list->length;

    return 0;
}

int lte_config_list_update_config(LTEConfigList* list, int oldBandwidth, int newBandwidth, float newSubcarrierSpacing, float newFrequencyOffset) {
    for (size_t i = 0; i < list->length; ++i) {
        if (list->configs[i].bandwidth == oldBandwidth) {
            // Update the configuration
            list->configs[i].bandwidth = newBandwidth;
            list->configs[i].subcarrierSpacing = newSubcarrierSpacing;
            list->configs[i].frequencyOffset = newFrequencyOffset;
            return 0;
        }
    }

    printf("Error: Configuration with bandwidth %d not found in the list.\n", oldBandwidth);
    return -1;
}
