#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_STRING_LENGTH 1024
#define MEMORY_LIMIT 10000000

typedef struct Record {
    int key;
    long offset;
    double timestamp;
    char *data;
} Record;

typedef struct Collection {
    Record **records;
    int count;
    pthread_mutex_t mutex;
    size_t allocated;
} Collection;

Collection *create_collection() {
    Collection *collection = malloc(sizeof(Collection));
    collection->records = NULL;
    collection->count = 0;
    collection->allocated = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void add_record(Collection *collection, int key, long offset, double timestamp, char *data) {
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->timestamp = timestamp;
    record->data = data;

    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= MAX_RECORDS || collection->allocated + sizeof(Record) + strlen(data) > MEMORY_LIMIT) {
        free_record(collection, key);
        free(record);
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    record->data = realloc(record->data, strlen(data) + 1);
    if (!record->data) {
        free(record);
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    collection->records = realloc(collection->records, (collection->count + 1) * sizeof(Record *));
    collection->records[collection->count] = record;
    collection->count++;
    collection->allocated += sizeof(Record) + strlen(data);

    pthread_mutex_unlock(&collection->mutex);
}

void free_record(Collection *collection, int key) {
    for (int i = 0; i < collection->count; i++) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]->data);
            free(collection->records[i]);
            memmove(&collection->records[i], &collection->records[i + 1], (collection->count - i - 1) * sizeof(Record *));
            collection->count--;
            return;
        }
    }
}

void cleanup_records(Collection *collection, int threshold) {
    for (int i = 0; i < collection->count; i++) {
        Record *record = collection->records[i];
        if ((int)(clock() - record->timestamp) / CLOCKS_PER_SEC > threshold) {
            free(record->data);
            free(record);
            memmove(&collection->records[i], &collection->records[i + 1], (collection->count - i - 1) * sizeof(Record *));
            collection->count--;
        }
    }
}

void log_operation(int operation, int key, char *message) {
