void add_device(uint32_t device_id, const char* sensor_type, int sampling_rate) {
    if(device_count < MAX_DEVICES) {
        DeviceInfo* device = &device_pool[device_count];
        device->device_id = device_id;
        strcpy(device->sensor_type, sensor_type);
        device->sampling_rate = sampling_rate;
        device->buffer_size = BUFFER_SIZE;

        // Initialize Hamming Code for error correction
        hamming_code_init();

        device_count++;
    } else {
        printf("Maximum number of devices reached\n");
    }
}

// Handle incoming data from a device
void handle_data(DeviceInfo* device, char* data) {
    // Perform error correction using Hamming Code
