}

// Release resources when a device is removed or disconnected
void remove_device(uint32_t device_id) {
    for(int i = 0; i < device_count; i++) {
        if(device_pool[i].device_id == device_id) {
            free(device_pool[i].buffer);
            memset(&device_pool[i], 0, sizeof(DeviceInfo));
            break;
        }
    }

    // Update device count
    device_count--;
}

