NFAPI_CRC_INDICATION_PDU_T* nfaPiCrcIndicationPduListCreate(int N) {
    srand(time(NULL)); // Seed the random number generator

    // Check for memory allocation failure
    if (!N) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* head = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

