typedef struct {
    char status;
    long offset;
    int key;
    double weight;
} record;

record* initRecords(long max_records, long max_offset, int min_key, int max_key) {
    long total_bytes = sizeof(record) * (max_records + 1);
    void* records_mem = malloc(total_bytes);

    if (!records_mem) {
        // handle allocation failure
        return NULL;
    }

    record* records = (record*) records_mem;
    for (long i = 0; i < max_records; i++) {
        records[i].status = ' ';
        records[i].offset = rand() % max_offset;
        records[i].key = min_key + (rand() % (max_key - min_key));
        records[i].weight = (double) rand() / RAND_MAX;
    }

    return records;
}

void sortRecords(record* records, long num_records) {
    qsort(records, num_records, sizeof(record), compareRecords);
}

int compareRecords(const void* a, const void* b) {
    record* rec1 = *(record*)a;
    record* rec2 = *(record*)b;

    return rec1->key - rec2->key;
}
