char* renderNfarxScripts(NFAPI_CRC_INDATION_PDU_T* puds, size_t count) {
    // Initialize the hash map for RNTI uniqueness check
    hashmap_t* rnti_map = hashmap_create(1000);

    char html[4096];
    sprintf(html, "<script>\n");

    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = puds[i];

        // Perform RNTI uniqueness check and log any invalid operations
        hashmap_put(rnti_map, pdu.rnti);
        if (!hashmap_get(rnti_map, pdu.rnti)) {
            printf("RNTI duplicate detected: %s\n", pdu.rnti);
            continue;
        }

        sprintf(html + strlen(html), "document.getElementById('%d').innerHTML = '%x';\n", i, pdu.rx_ue_info_tag);

        // Append CRC indication script tag
        sprintf(html + strlen(html), "document.getElementById('%d').innerHTML += '%x';\n", i, pdu.crc_flag);
    }

    hashmap_destroy(rnti_map);

    sprintf(html + strlen(html), "</script>\n");
    return strdup(html);
}

