    if (message_count >= MAX_MESSAGES) {
        // Handle full queue by dropping messages or reinitializing the queue
        printf("Message queue is full! Dropping message...\n");
        return;
    }

    // Allocate memory for a new message
    LTE_PHY_Control_Message* new_message = (LTE_PHY_Control_Message*)malloc(sizeof(LTE_PHY_Control_Message));
    if (!new_message) {
        // Handle memory allocation failure
        printf("Memory allocation failed! Message not added.\n");
        return;
    }

    new_message->phichConfiguration = phichConfiguration;
    new_message->ueId = ueId;
    new_message->dlMchDataTag = dlMchDataTag;

    // Enqueue the message and update the count
    messages[message_count] = *new_message;
    message_count++;

    pthread_mutex_unlock(&mutex);
}

void process_messages() {
    while (true) {
        pthread_mutex_lock(&mutex);

        if (message_count > 0) {
            int batch_size = MIN(message_count, BATCH_SIZE);
            for (int i = 0; i < batch_size; i++) {
                // Process a batch of messages
                process_message(&messages[i]);
            }

            message_count -= batch_size;
            pthread_mutex_unlock(&mutex);

            // Monitor and adjust resource usage dynamically based on system load
            monitor_system_load();
        } else {
            // No messages to process, sleep for a short duration
            usleep(1000);
        }
    }
}

void process_message(LTE_PHY_Control_Message* message) {
    // Implement message processing logic here
    printf("Processing message with PHICH configuration %d and UE ID %u...\n", message->phichConfiguration, message->ueId);
}

int main() {
    ltePHYControlMessageHandler();

    // Example usage: Add messages to the queue
    add_message(1, 1000, "MCH_DATA_TAG_1");
    add_message(2, 2000, "MCH_DATA_TAG_2");

    return 0;
}
