#include <pthread.h>

// Define the structure for a network connection object
typedef struct {
    int sock;
    int timeout;
    char* buffer;
} conn_t;

// Define the structure to manage dynamic list of connections
typedef struct {
    conn_t* connections;
    int size;
    pthread_mutex_t lock;
} conn_list_t;

// Function to initialize the connection list
conn_list_t* conn_list_init() {
    conn_list_t* list = (conn_list_t*)malloc(sizeof(conn_list_t));
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new connection to the list
int conn_list_add(conn_list_t* list, int sock, int timeout) {
    conn_t* conn = (conn_t*)malloc(sizeof(conn_t));
    conn->sock = sock;
    conn->timeout = timeout;
    conn->buffer = NULL;

    pthread_mutex_lock(&list->lock);
    if(list->size >= 10000) { // Assuming a maximum size of 10,000 connections
        printf("Error: Connection list is full.\n");
        return -1;
    }
    list->connections[list->size] = conn;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove a connection from the list
int conn_list_remove(conn_list_t* list, int sock) {
    for(int i = 0; i < list->size; i++) {
        if(list->connections[i]->sock == sock) {
            free(list->connections[i]->buffer);
            free(list->connections[i]);
            memmove(&list->connections[i], &list->connections[i+1], (list->size - i - 1) * sizeof(conn_t*));
            list->size--;
            return 0;
        }
    }
    printf("Error: Connection not found.\n");
    return -1;
}

// Function to handle incoming data for a connection
void conn_read_data(conn_list_t* list, int sock, char* buffer, int size) {
    pthread_mutex_lock(&list->lock);
    for(int i = 0; i < list->size; i++) {
        if(list->connections[i]->sock == sock) {
            // Handle incoming data for the connection
            // ...
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to shutdown a connection
void conn_shutdown(conn_list_t* list, int sock) {
    pthread_mutex_lock(&list->lock);
    for(int i = 0; i < list->size; i++) {
        if(list->connections[i]->sock == sock) {
            // Shutdown the socket and remove the connection from the list
            shutdown(list->connections[i]->sock, SHUT_RDWR);
            conn_list_remove(list, sock);
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to free resources allocated for the connection list
void conn_list_free(conn_list_t* list) {
    for(int i = 0; i < list->size; i++) {
        if(list->connections[i]->buffer != NULL)
            free(list->connections[i]->buffer);
        free(list->connections[i]);
    }
    free(list->connections);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage:
int main() {
    conn_list_t* list = conn_list_init();
    // Add connections to the list
    int sock1 = socket(AF_INET, SOCK_STREAM, 0);
    int sock2 = socket(AF_INET, SOCK_STREAM, 0);
    if(conn_list_add(list, sock1, 10) && conn_list_add(list, sock2, 5)) {
        printf("Error adding connections.\n");
    }
    // Handle incoming data for a connection
    char buffer[1024];
    int size = read(sock1, buffer, sizeof(buffer));
    if(size > 0)
        conn_read_data(list, sock1, buffer, size);
    // Shutdown a connection
    conn_shutdown(list, sock2);
    // Free resources allocated for the connection list
    conn_list_free(list);
    return 0;
}
