typedef struct {
    // Supported modulation types (e.g., QPSK, 16QAM, etc.)
    enum {QPSK, QAM16} modulationType;
    // Bandwidth settings (e.g., 1.4 MHz, 3.0 MHz, etc.)
    uint32_t bandwidth;
    // Dynamically allocated buffer for packet data
    void** packetDataBuffers;
    // Number of buffers allocated
    size_t numBuffers;
    // Optional features:
    // Buffer over-provisioning flag (1 = enabled)
    int8_t bufferOverprovisioningEnabled;
    // Adaptive bandwidth scaling factor (0.0 - 1.0)
    float adaptiveBandwidthScalingFactor;
} LTE_PHY_TX_RX_STREAMS;

void initLTEPHYTXRXStreams(LTE_PHY_TX_RX_RX_STREAMS** streams, size_t numStreams) {
    for(size_t i = 0; i < numStreams; i++) {
        streams[i]->modulationType = QPSK;
        streams[i]->bandwidth = 1.4e6; // Initial bandwidth setting
        streams[i]->packetDataBuffers = (void**)malloc(sizeof(void*) * 16); // Initialize with 16 buffers
        streams[i]->numBuffers = 0;
        streams[i]->bufferOverprovisioningEnabled = 0;
        streams[i]->adaptiveBandwidthScalingFactor = 0.5; // Initial scaling factor
    }
}

void configureLTEPHYTXRXStreams(LTE_PHY_TX_RX_RX_STREAMS* stream, int8_t modulationType, uint32_t bandwidth) {
    stream->modulationType = modulationType;
    stream->bandwidth = bandwidth;
    // Reallocate buffer sizes based on new modulation type and bandwidth
    if(modulationType == QAM16 || bandwidth > 1.4e6) {
        size_t newSize = ceil(bandwidth / 1000.0); // Estimate buffer size based on bandwidth and modulation type
        void** newBuffers = (void*)realloc(stream->packetDataBuffers, sizeof(void*) * newSize);
        if(newBuffers != NULL) {
            stream->packetDataBuffers = newBuffers;
            stream->numBuffers = newSize;
        }
    }
}

void updateLTEPHYTXRXStreams(LTE_PHY_TX_RX_RX_STREAMS* stream, int8_t modulationType, uint32_t bandwidth) {
    configureLTEPHYTXRXStreams(stream, modulationType, bandwidth);
    // Update adaptive bandwidth scaling factor based on network load
    if(bandwidth > 1.4e6) {
        stream->adaptiveBandwidthScalingFactor += (bandwidth - 1.4e6) / 1000.0;
    }
}

void releaseLTEPHYTXRXStreams(LTE_PHY_TX_RX_RX_STREAMS** streams, size_t numStreams) {
    for(size_t i = 0; i < numStreams; i++) {
        free(streams[i]->packetDataBuffers);
        // Free dynamically allocated memory
    }
}
