    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_array(int N, int* seed) {
    NFAPI_CRC_INDICATION_PDU_T* crc_array = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    FILE* log_file = fopen("error.log", "a");

    if (log_file == NULL) {
        printf("Error opening log file\n");
        return NULL;
    }

    srand(*seed);
    int crcflag = rand() % 2; // Initialize random CRC flag
    int i;

    for (i = 0; i < N; i++) {
        crc_array = realloc(crc_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));

        if (crc_array == NULL) {
            fprintf(log_file, "Memory allocation failed at index %d\n", i);
            fclose(log_file);
            return NULL;
        }

        crc_array[i].RX_UE_INFORMATION_TAG = rand() % 256; // Initialize random RX UE information tag
        crc_array[i].RNTI = rand() % 65536; // Initialize random RNTI
        crc_array[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Initialize random CRC indication REL8 tag

        if (i > 0 && crc_array[i-1].CRCflag == crc_array[i].CRCflag) {
            crcflag = 1 - crcflag;
            i--; // Backtrack to previous index and change CRC flag
        }
    }

    pthread_mutex_unlock(&mutex);
    fclose(log_file);
    return crc_array;
}
