void ue_capability_request_list_manager(struct UECapabilityRequestList* list) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int request_count = 0;

    // Dynamic memory allocation for each structure
    struct UECapabilityRequest* request;

    while (1) {
        // Concurrent access handling using a mutex
        pthread_mutex_lock(&lock);

        // Allocate memory for the new request
        request = (struct UECapabilityRequest*)malloc(sizeof(struct UECapabilityRequest));
        if (!request) {
            LOG_ERROR("Memory allocation failed.");
            return;
        }

        // Add the new request to the list and increment count
        list->requests[request_count] = request;
        request_count++;

        // Logging mechanism for recording operations performed on the UECapabilityRequest list
        LOG_INFO("New request added: %p", request);

        pthread_mutex_unlock(&lock);
    }
}

void ue_capability_request_list_free(struct UECapabilityRequestList* list) {
    int i;

    for (i = 0; i < list->request_count; i++) {
        free(list->requests[i]);
    }

    // Clear the request array
    memset(list->requests, 0, sizeof(struct UECapabilityRequest*) * list->request_count);

    list->request_count = 0;
}
