// Custom RandomValueGenerator class
class RandomValueGenerator {
public:
    int minRange;
    int maxRange;

    void setRandomRange(int min, int max) {
        if (min > max) {
            printf("Error: Minimum value cannot be greater than maximum value.\n");
            exit(1);
        }
        this->minRange = min;
        this->maxRange = max;
    }

    void displayCurrentRange() {
        printf("Current random value range: %d to %d\n", minRange, maxRange);
    }

    int generateRandomValue() {
        if (this->minRange > this->maxRange) {
            // Handle overflow/underflow
            if ((rand() & 0x80000000) != 0) {
                // Overflow
                printf("Warning: Random value overflowed. Range adjusted to 1 to %d.\n", RAND_MAX);
                return rand();
            } else {
                // Underflow
                printf("Warning: Random value underflowed. Range adjusted to 1 to %d.\n", RAND_MAX);
                return (rand() & 0x7fffffff);
            }
        }
        return rand() % ((this->maxRange - this->minRange) + 1) + this->minRange;
    }
};

// Function to initialize record system
void* initializeRecords(int numRecords, long startOffset, int startKey, RandomValueGenerator& rng) {
    // Calculate total memory required for records
    size_t totalBytes = sizeof(long) * numRecords + sizeof(int) * numRecords + sizeof(record) * numRecords;

    // Allocate memory for records
    void* recordMemory = malloc(totalBytes);
    if (recordMemory == NULL) {
        printf("Error: Insufficient memory to allocate %zu bytes.\n", totalBytes);
        return NULL;
    }

    // Initialize records
    long* offsets = (long*) ((char*) recordMemory + startOffset * sizeof(long));
    int* keys = (int*) ((char*) recordMemory + (startOffset + numRecords) * sizeof(long) + startKey * sizeof(int));
    record* recs = (record*) ((char*) recordMemory + (startOffset + numRecords) * sizeof(long) + (startKey + numRecords) * sizeof(int));

    // Initialize records with random values
    for (int i = 0; i < numRecords; i++) {
        recs[i].value = rng.generateRandomValue();
    }

    return recordMemory;
}

// Define the 'record' structure
struct record {
    int value;
};
