int init_list(int n) {
    if (n <= 0) return -1; // invalid number of nodes
    for (int i = 0; i < n; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) return -2; // memory allocation failed
        node->data.RX_UE_INFORMATION_TAG = rand();
        node->data.RNTI = rand();
        node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand();
        node->next = NULL;
        if (head == NULL) head = node;
        else {
            Node* temp = head;
            while (temp->next != NULL) temp = temp->next;
            temp->next = node;
        }
    }
    return 0; // successful initialization
}

int insert_node(int rnti, int rx_ue_info_tag, Node** tail) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // memory allocation failed
    new_node->data.RNTI = rnti;
    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand();
    new_node->next = NULL;
    if (*tail == NULL) *tail = new_node;
    else {
        (*tail)->next = new_node;
        *tail = new_node;
    }
    return 0; // successful insertion
}

int delete_node(int rnti, Node** head_ref, Node** tail_ref) {
    Node* temp = *head_ref;
    Node* prev = NULL;
    while (temp != NULL && temp->data.RNTI != rnti) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL) return -1; // node not found
    if (prev == NULL) {
        *head_ref = temp->next;
    } else {
        prev->next = temp->next;
    }
    if (*tail_ref == temp) *tail_ref = temp->next;
    free(temp);
    return 0; // successful deletion
}

int search_node(int rnti, Node* head) {
    Node* temp = head;
    while (temp != NULL && temp->data.RNTI != rnti) {
        temp = temp->next;
    }
    if (temp == NULL) return -1; // node not found
    return 0; // node found
}

