typedef struct {
    int ue_id;
    int phich_configuration;
} LTE_PHY_Layer_Control_Message;

typedef struct {
    LTE_PHY_Layer_Control_Message* messages;
    size_t capacity;
    size_t used;
} Dynamic_Array;

Dynamic_Array* dynamic_array_create(size_t initial_capacity) {
    Dynamic_Array* array = (Dynamic_Array*)malloc(sizeof(Dynamic_Array));
    array->messages = (LTE_PHY_Layer_Control_Message*)calloc(initial_capacity, sizeof(LTE_PHY_Layer_Control_Message));
    array->capacity = initial_capacity;
    array->used = 0;
    return array;
}

void dynamic_array_free(Dynamic_Array* array) {
    free(array->messages);
    free(array);
}

int dynamic_array_append(Dynamic_Array* array, LTE_PHY_Layer_Control_Message message) {
    if (array->used >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PHY_Layer_Control_Message* new_messages = (LTE_PHY_Layer_Control_Message*)realloc(array->messages, new_capacity * sizeof(LTE_PHY_Layer_Control_Message));
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->used] = message;
    array->used++;
    return 0;
}

int dynamic_array_iterate(const Dynamic_Array* array, void (*callback)(LTE_PHY_Layer_Control_Message*)) {
    for (size_t i = 0; i < array->used; ++i) {
        callback(array->messages[i]);
    }
    return 0;
}
