    // Dynamically allocate memory for the request list
    ue_capability_requests = (UECapabilityRequest **)malloc(MAX_BUFFER_SIZE * sizeof(UECapabilityRequest *));
    if (!ue_capability_requests) {
        printf("Error: Unable to allocate memory for UE capability requests.\n");
        return;
