    int attempts = 0;
    while (1) {
        // Initialize each request structure
        UECapabilityRequest *request = (UECapabilityRequest *)malloc(sizeof(UECapabilityRequest));
        if (!request) {
            if (attempts < max_attempts) {
                // Retry allocation with exponential backoff
                printf("Error: Unable to allocate memory for UE capability request (%d/%d attempts).\n", attempts + 1, max_attempts);
                usleep(backoff * 1000); // in microseconds
                continue;
            } else {
                printf("Error: Maximum attempts reached. Aborting.\n");
                return;
            }
        }

        // Initialize the request structure
        request->rrc_ue_id = rand() % 100; // configurable seed for randomization
        request->features = (char *)malloc(strlen("bandwidth-part,measurement-config,mobility-management") + 1);
        strcpy(request->features, "bandwidth-part,measurement-config,mobility-management");

        // Add the request to the list
        ue_capability_requests[num_requests++] = request;
    }
}

