// Define a node structure for the doubly-linked list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Initialize the linked list with an empty head and tail
Node* init_list() {
    return NULL;
}

// Insert a new node at the beginning of the linked list
void insert_head(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = *head;
    node->prev = NULL;

    if (*head != NULL)
        (*head)->prev = node;
    *head = node;
}

// Delete a node with the given RNTI from the linked list
void delete_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = *head;
    while (current != NULL) {
        if (memcmp(&current->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            if (current->next != NULL)
                current->next->prev = current->prev;
            else
                (*head) = current->next;

            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                (*head) = current->next;

            free(current);
            return;
        }
        current = current->next;
    }
}

// Find and return the first node with a specific RX_UE_INFORMATION_TAG in the linked list
Node* find_tag(Node* head, NFAPI_CRC_INDICATION_PDU_T tag) {
    Node* current = head;
    while (current != NULL) {
        if (memcmp(&current->data.RX_UE_INFORMATION_TAG, &tag, sizeof(tag)) == 0)
            return current;
        current = current->next;
    }
    return NULL;
}

// Scan the linked list for nodes with CRCFLAG set to 1 and remove them
void scan_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.CRCFLAG == 1) {
            Node* temp = current->next;
            free(current);
            *head = temp;
            return;
        }
        current = current->next;
    }
}

// Periodically scan the linked list and remove nodes with CRCFLAG set to 1
void periodic_scan(Node** head, pthread_t thread_id) {
    while (1) {
        // Scan the list and remove nodes with CRCFLAG set to 1
        scan_list(head);

        // Sleep for a period of time before scanning again
        sleep(1);
    }
}

// Main function to test the linked list implementation
int main() {
    Node* head = init_list();

    // Create a new thread to periodically scan the linked list and remove nodes with CRCFLAG set to 1
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, periodic_scan, &head);

    return 0;
}
