typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_linked_list(int num_records, int rnti_range_start, int rnti_range_end) {
    // Initialize the head of the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Loop through each record
    for (int i = 0; i < num_records; i++) {
        // Create a new NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields
        current->RX_UE_INFORMATION_TAG = i;
        current->RNTI = (rand() % ((rnti_range_end - rnti_range_start) + 1)) + rnti_range_start;
        current->CRC_INDICATION_REL8_TAG = rand();
        current->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        // Check for consecutive duplicate RNTIs
        if (i > 0 && head != NULL) {
            NFAPI_CRC_INDICATION_PDU_T* prev = head;
            while (prev->next != NULL) {
                prev = prev->next;
            }
            if (current->RNTI == prev->RNTI) {
                // Adjust the RNTI to be non-consecutive
                current->RNTI = (rand() % ((rnti_range_end - rnti_range_start) + 1)) + rnti_range_start;
            }
        }

        // Add the new record to the linked list
        if (head == NULL) {
            head = current;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = current;
        }

        // Free the previous record
        if (i > 0) {
            free(head);
            head = current;
        }
    }

    return head;
}

// Function to persist each 'record' in a file-based database
void persist_linked_list(NFAPI_CRC_INDICATION_PDU_T* linked_list, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        // Handle error
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = linked_list;
    while (current != NULL) {
        fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&current->RNTI, sizeof(int), 1, file);
        fwrite(&current->CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
        fwrite(&current->CRCFLAG, sizeof(int), 1, file);

        current = current->next;
    }

    fclose(file);
}

// Function to load linked list from a file-based database
NFAPI_CRC_INDICATION_PDU_T* load_linked_list(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle error
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* linked_list = NULL;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;

    while (fread(&RX_UE_INFORMATION_TAG, sizeof(int), 1, file) == 1 &&
           fread(&RNTI, sizeof(int), 1, file) == 1 &&
           fread(&CRC_INDICATION_REL8_TAG, sizeof(int), 1, file) == 1 &&
           fread(&CRCFLAG, sizeof(int), 1, file) == 1) {
        NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (linked_list == NULL) {
            linked_list = current;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = linked_list;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = current;
        }
    }

    fclose(file);

    return linked_list;
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    int num_records = 1000; // Adjust as needed
    int rnti_range_start = 1;
    int rnti_range_end = 100;

    NFAPI_CRC_INDICATION_PDU_T* linked_list = create_and_populate_linked_list(num_records, rnti_range_start, rnti_range_end);

    char filename[] = "linked_list.dat";
    persist_linked_list(linked_list, filename);

    free(linked_list);

    return 0;
}
