#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <semaphore.h>

#define MAX_RECORDS 10000000
#define INT_MAX 2147483647

typedef struct {
    int value;
} record_t;

record_t* init_records(int num_records) {
    record_t* records = (record_t*) malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Error: failed to allocate memory for records.\n");
        return NULL;
    }

    sem_t semaphore;
    if (sem_init(&semaphore, 0, 1) != 0) {
        printf("Error: failed to initialize semaphore.\n");
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        int value = rand() % INT_MAX;
        while (i > 0 && value == records[i - 1].value) {
            value = rand() % INT_MAX;
        }
        records[i].value = value;
    }

    sem_destroy(&semaphore);

    return records;
}

int find_largest(int* values, int num_values) {
    int max_value = INT_MIN;
    for (int i = 0; i < num_values; i++) {
        if (values[i] > max_value) {
            max_value = values[i];
        }
    }
    return max_value;
}

void persist_records(record_t* records, int num_records) {
    FILE* file = fopen("records.txt", "w");
    if (!file) {
        printf("Error: failed to open file for writing.\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d\n", records[i].value);
    }

    fclose(file);
}

void load_records(record_t** loaded_records, int* num_loaded_records) {
    FILE* file = fopen("records.txt", "r");
    if (!file) {
        printf("Error: failed to open file for reading.\n");
        return;
    }

    *loaded_records = (record_t*) malloc(1 * sizeof(record_t));
    *num_loaded_records = 0;

    record_t* current_record = NULL;
    int current_value = 0;

    while (fscanf(file, "%d", &current_value) == 1) {
        if (*num_loaded_records >= 10000000) {
            printf("Error: too many records loaded.\n");
            return;
        }

        *loaded_records = realloc(*loaded_records, (*num_loaded_records + 1) * sizeof(record_t));
        (*loaded_records)[*num_loaded_records].value = current_value;
        (*num_loaded_records)++;
    }

    fclose(file);
}

int main() {
    int num_records;
    scanf("%d", &num_records);

    record_t* records = init_records(num_records);
    if (!records) {
        return 1;
    }

    persist_records(records, num_records);

    load_records(&records, &num_records);

    printf("Largest value: %d\n", find_largest(records->value, num_records));

    free(records);

    return 0;
}
