#include "custom_log.h"

#define REQUEST_ID_MAX 64
#define TIMESTAMP_LENGTH 32
#define CLIENT_IP_ADDRESS_LENGTH 16
#define METHOD_MAX 8
#define URI_MAX 256
#define HTTP_VERSION_MAX 10
#define HEADERS_MAX 1024
#define STATUS_CODE_MAX 5

typedef struct {
    char id[REQUEST_ID_MAX];
    time_t timestamp;
    struct in_addr client_ip_address;
    char method[METHOD_MAX];
    char uri[URI_MAX];
    char http_version[HTTP_VERSION_MAX];
    char* headers;
    int status_code;
} HttpRequest;

void* my_malloc(size_t size) {
    return malloc(size);
}

void* my_calloc(size_t nmemb, size_t size) {
    return calloc(nmemb, size);
}

void my_free(void* ptr) {
    free(ptr);
}

HttpRequest* request_new() {
    HttpRequest* request = (HttpRequest*)my_malloc(sizeof(HttpRequest));
    if (!request) {
        custom_log_error("Failed to allocate memory for request");
        return NULL;
    }
    request->timestamp = time(NULL);
    inet_aton("127.0.0.1", &request->client_ip_address);
    strcpy(request->method, "GET");
    strcpy(request->uri, "/");
    strcpy(request->http_version, "HTTP/1.1");
    request->headers = NULL;
    request->status_code = 200;
    return request;
}

void request_free(HttpRequest* request) {
    if (!request) {
        custom_log_error("Cannot free a null request");
        return;
    }
    my_free(request);
}

HttpRequest* request_clone(HttpRequest* original) {
    HttpRequest* clone = (HttpRequest*)my_malloc(sizeof(HttpRequest));
    if (!clone) {
        custom_log_error("Failed to allocate memory for request clone");
        return NULL;
    }
    strcpy(clone->id, original->id);
    clone->timestamp = original->timestamp;
    clone->client_ip_address = original->client_ip_address;
    strcpy(clone->method, original->method);
    strcpy(clone->uri, original->uri);
    strcpy(clone->http_version, original->http_version);
    if (original->headers) {
        clone->headers = strdup(original->headers);
    }
    clone->status_code = original->status_code;
    return clone;
}

void request_log(HttpRequest* request, enum LogLevel level) {
    custom_log(level, "Request ID: %s, Timestamp: %ld, Client IP: %s, Method: %s, URI: %s, HTTP Version: %s, Status Code: %d", 
               request->id, (long int)request->timestamp, inet_ntoa(request->client_ip_address), request->method, request->uri, request->http_version, request->status_code);
}
