#define MAX_NODES 10000
#define MIN_STRING_LENGTH 10
#define MAX_STRING_LENGTH 50

typedef struct node {
    int key;
    char *data;
    struct item *head;
} Node;

typedef struct item {
    char *str;
    struct item *prev;
    struct item *next;
} Item;

Node* initialize_node(int key, const char* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->data = strdup(data);
    node->head = NULL;
    return node;
}

void populate_nodes(Node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        Node* node = initialize_node(i, rand_str());
        if (i > 0) {
            nodes[i-1]->head->next = node;
            node->prev = nodes[i-1]->head;
            node->head = NULL;
        } else {
            nodes[0] = node;
        }
    }
}

char* rand_str() {
    char* str = (char*)malloc((rand() % (MAX_STRING_LENGTH - MIN_STRING_LENGTH + 1)) + MIN_STRING_LENGTH);
    for (int i = 0; i < strlen(str); i++) {
        str[i] = (char)(rand() % 26 + 'a');
    }
    str[strlen(str)] = '\0';
    return str;
}

void import_csv(Node** nodes, const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Node* node = initialize_node(atoi(strtok(line, ",")), strtok(NULL, ","));
        // Add the node to the linked list
    }
}

void export_json(Node** nodes, const char* path) {
    FILE* file = fopen(path, "w");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    for (int i = 0; i < MAX_NODES; i++) {
        fprintf(file, "{\"key\": %d, \"data\": \"%s\"}\n", nodes[i]->key, nodes[i]->data);
    }
}

int main(int argc, char** argv) {
    if (argc != 5) {
        printf("Usage: ./program <num_nodes> <min_string_length> <max_string_length> <csv_path>\n");
        return 1;
    }

    int num_nodes = atoi(argv[1]);
    int min_string_length = atoi(argv[2]);
    int max_string_length = atoi(argv[3]);
    const char* csv_path = argv[4];

    Node* nodes[MAX_NODES];
    for (int i = 0; i < MAX_NODES; i++) {
        nodes[i] = NULL;
    }

    populate_nodes(nodes, num_nodes);
    import_csv(nodes, csv_path);
    export_json(nodes, "output.json");

    return 0;
}
