} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int N, int NID, int* valid_NIDs, int num_valid_NIDs) {
    if (N <= 0) return NULL;

    srand(time(NULL)); // seed random number generator

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        sprintf(list[i].RX_UE_INFORMATION_TAG, "RX_UE_INFO_%d", i);
        list[i].RNTI = i % num_valid_NIDs;

        // ensure RNTI values are unique
        int j;
        for (j = 0; j < i; j++) {
            if (list[j].RNTI == list[i].RNTI) {
                list[i].RNTI = (list[i].RNTI + 1) % num_valid_NIDs;
                break;
            }
        }

        // set CRCFLAG randomly
        int crcflag = rand() % 2;

        // set NID
        list[i].RX_UE_INFORMATION_TAG[16] = (char)(NID % 256);
        if (!valid_NIDs || valid_NIDs[0] == NID) {
            printf("Processing element %d, NID: %d, RNTI: %d, CRCFLAG: %d\n", i+1, NID, list[i].RNTI, crcflag);
        } else {
            printf("Processing element %d, NID: %d, RNTI: %d, CRCFLAG: %d (filtered out)\n", i+1, NID, list[i].RNTI, crcflag);
        }
    }

    return list;
}
