#include <string.h>
#include <pthread.h>

#define MAX_PDU_COUNT 1024
#define LOG_BUFFER_SIZE 256
#define CRC_ALGORITHM "CRC-32"

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pdu_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pdu_available = PTHREAD_COND_INITIALIZER;
int pdu_count = 0;
NFAPI_CRC_INDICATION_PDU_T* pdus[MAX_PDU_COUNT];
int log_id = 0;

void crc_indication_pdu_manager_init() {
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        pdus[i] = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_manager_allocate() {
    pthread_mutex_lock(&pdu_lock);
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        if (pdus[i] == NULL) {
            pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_cond_signal(&pdu_available);
            pdu_count++;
            break;
        }
    }
    pthread_mutex_unlock(&pdu_lock);

    return pdus[pdu_count - 1];
}

void crc_indication_pdu_manager_deallocate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pdu_lock);
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        if (pdus[i] == pdu) {
            free(pdu);
            pdus[i] = NULL;
            pdu_count--;
            break;
        }
    }
    pthread_mutex_unlock(&pdu_lock);

    log_id++;
}

void crc_indication_pdu_manager_log_event(int event_type, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    char log_buffer[LOG_BUFFER_SIZE];
    sprintf(log_buffer, "Event %d: PDU allocated/deallocated. ID: %d, CRC Flag: %x", event_type, log_id, pdu->crc_indication_rel8.crcflag);
    printf("%s\n", log_buffer);
}

int crc_indication_pdu_manager_calculate_checksum() {
    int checksum = 0;
    for (int i = 0; i < pdu_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pdus[i];
        checksum += pdu->crc_indication_rel8.crcflag;
    }
    return checksum;
}

void crc_indication_pdu_manager_iterate_over_pdus(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = 0; i < pdu_count; i++) {
        callback(pdus[i]);
    }
}
