int nfaapi_crc_indication_pdu_array_thread_safe_insert(NFAPI_CRC_INDICATION_PDU_T** arr, int new_rnti, int new_crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* p = realloc(*arr, (++(*sz)) * sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (p == NULL) return -1; // Handle out-of-memory error
    p[(*sz) - 1].RNTI = new_rnti;
    p[(*sz) - 1].CRCFLAG = new_crcflag;
    for (int i = 0; i < *sz; ++i) {
        if (p[i].RNTI == new_rnti)
            return -2; // RNTI already exists
    }
    *arr = p;
    return 1; // Successful insertion
}

void nfaapi_crc_indication_pdu_array_thread_safe_update(NFAPI_CRC_INDICATION_PDU_T** arr, int rnti, int new_crcflag) {
