        if (arr[i]->RNTI == rnti)
            arr[i]->CRCFLAG = new_crcflag;
    }
}

void nfaapi_crc_indication_pdu_array_thread_safe_free(NFAPI_CRC_INDICATION_PDU_T** arr, size_t sz) {
