#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MEM_POOL_SIZE 1024
#define ENTRY_COUNT 1000
#define NAME_MAX_LENGTH 50
#define AGE_RANGE_MIN 18
#define AGE_RANGE_MAX 65

typedef struct {
    char* name;
    int age;
    double salary;
} entry_t;

entry_t* mem_pool = NULL;
sem_t sem_mem_pool_empty, sem_mem_pool_full;
pthread_mutex_t mutex_mem_pool;
int entries_count = 0;

void init_entry(entry_t* entry) {
    entry->age = (rand() % (AGE_RANGE_MAX - AGE_RANGE_MIN)) + AGE_RANGE_MIN;
}

entry_t* get_entry_from_pool() {
    pthread_mutex_lock(&mutex_mem_pool);
    if (!sem_trywait(&sem_mem_pool_empty)) {
        sem_wait(&sem_mem_pool_empty);
    }
    entry_t* entry = mem_pool + entries_count++;
    return entry;
}

void release_entry_to_pool(entry_t* entry) {
    pthread_mutex_lock(&mutex_mem_pool);
    mem_pool[entries_count - 1] = *entry;
    if (sem_post(&sem_mem_pool_full)) {
        sem_post(&sem_mem_pool_empty);
    }
    pthread_mutex_unlock(&mutex_mem_pool);
}

int main() {
    // Initialize memory pool
    mem_pool = (entry_t*)malloc(MEM_POOL_SIZE * sizeof(entry_t));
    for (int i = 0; i < MEM_POOL_SIZE; i++) {
        mem_pool[i].name = malloc(NAME_MAX_LENGTH + 1);
        init_entry(&mem_pool[i]);
    }
    sem_init(&sem_mem_pool_empty, 0, MEM_POOL_SIZE);
    sem_init(&sem_mem_pool_full, 0, 0);
    pthread_mutex_init(&mutex_mem_pool, 0);

    // Read input and process entries
    int n;
    scanf("%d", &n);
    int* arr = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, largest_integer_finder, arr);

    // Process entries
    entry_t* entry = get_entry_from_pool();
    while (entry) {
        printf("Enter age and salary for %s: ", entry->name);
        scanf("%d%lf", &entry->age, &entry->salary);
        free(entry->name);
        release_entry_to_pool(entry);
        entry = get_entry_from_pool();
    }

    // Update database
    pthread_join(thread_id, NULL);

    // Free memory
    for (int i = 0; i < entries_count; i++) {
        free(mem_pool[i].name);
    }
    free(mem_pool);
    free(arr);

    return 0;
}

void* largest_integer_finder(void* arg) {
    int* arr = arg;
    pthread_mutex_lock(&mutex_mem_pool);
    entry_t* entry = get_entry_from_pool();
    while (entry) {
        pthread_mutex_unlock(&mutex_mem_pool);
        int max = 0;
        for (int i = 0; i < entries_count; i++) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        printf("Largest integer: %d\n", max);
        pthread_mutex_lock(&mutex_mem_pool);
        release_entry_to_pool(entry);
    }
    return NULL;
}
