typedef struct {
    LTE_PHY_Layer_Control_Message** messages;
    size_t capacity;
    pthread_mutex_t mutex;
} LTE_PHY_Layer_Control_Message_Array;

LTE_PHY_Layer_Control_Message_Array message_array = {0};

void lte_phy_layer_control_message_array_init(size_t initial_capacity) {
    message_array.messages = (LTE_PHY_Layer_Control_Message**)malloc(initial_capacity * sizeof(LTE_PHY_Layer_Control_Message*));
    message_array.capacity = initial_capacity;
}

void lte_phy_layer_control_message_array_destroy() {
    for (size_t i = 0; i < message_array.capacity; i++) {
        if (message_array.messages[i] != NULL) {
            free(message_array.messages[i]->dl_mch_data_tag);
            free(message_array.messages[i]);
        }
    }
    free(message_array.messages);
}

LTE_PHY_Layer_Control_Message* lte_phy_layer_control_message_create(int phich_config, uint32_t ue_id) {
    LTE_PHY_Layer_Control_Message* message = (LTE_PHY_Layer_Control_Message*)malloc(sizeof(LTE_PHY_Layer_Control_Message));
    message->phich_config = phich_config;
    message->ue_id = ue_id;
    message->dl_mch_data_tag = NULL;
    return message;
}

void lte_phy_layer_control_message_destroy(LTE_PHY_Layer_Control_Message* message) {
    if (message != NULL && message->dl_mch_data_tag != NULL) {
        free(message->dl_mch_data_tag);
    }
    free(message);
}

int lte_phy_layer_control_message_array_append(LTE_PHY_Layer_Control_Message** new_message) {
    pthread_mutex_lock(&message_array.mutex);

    if (message_array.capacity <= message_array.messages[0]) {
        // Resizing the array
        message_array.messages = (LTE_PHY_Layer_Control_Message**)realloc(message_array.messages, (message_array.capacity * 2 + 1) * sizeof(LTE_PHY_Layer_Control_Message*));
        message_array.capacity *= 2;
    }

    message_array.messages[message_array.capacity - 1] = new_message;

    pthread_mutex_unlock(&message_array.mutex);

    return 0;
}

int lte_phy_layer_control_message_array_remove(size_t index) {
    pthread_mutex_lock(&message_array.mutex);

    if (index >= message_array.capacity || message_array.messages[index] == NULL) {
        pthread_mutex_unlock(&message_array.mutex);
        return -1; // Invalid index
    }

    for (size_t i = index; i < message_array.capacity - 1; i++) {
        message_array.messages[i] = message_array.messages[i + 1];
    }
    free(message_array.messages[message_array.capacity - 1]);
    message_array.messages[message_array.capacity - 1] = NULL;
    message_array.capacity--;

    pthread_mutex_unlock(&message_array.mutex);

    return 0;
}

int lte_phy_layer_control_message_array_modify(size_t index, int phich_config, uint32_t ue_id) {
    pthread_mutex_lock(&message_array.mutex);

    if (index >= message_array.capacity || message_array.messages[index] == NULL) {
        pthread_mutex_unlock(&message_array.mutex);
        return -1; // Invalid index
    }

    message_array.messages[index]->phich_config = phich_config;
    message_array.messages[index]->ue_id = ue_id;

    pthread_mutex_unlock(&message_array.mutex);

    return 0;
}

int main() {
    lte_phy_layer_control_message_array_init(10);

    LTE_PHY_Layer_Control_Message* new_message1 = lte_phy_layer_control_message_create(123, 456789);
    LTE_PHY_Layer_Control_Message* new_message2 = lte_phy_layer_control_message_create(789, 012345);

    lte_phy_layer_control_message_array_append(&new_message1);
    lte_phy_layer_control_message_array_append(&new_message2);

    // Modify a message
    lte_phy_layer_control_message_array_modify(0, 1234, 56789);

    // Remove a message
    lte_phy_layer_control_message_array_remove(1);

    return 0;
}

