} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for record
typedef struct {
    int value;
    bool active;
    time_t timestamp;
} Record;

// Function to manage dynamic memory allocation
void manage_memory(int threshold) {
    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc = malloc(threshold * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize and validate CRCFLAG
    srand(time(NULL));
    for (int i = 0; i < threshold; i++) {
        nfaapi_crc[i].CRCFLAG = rand() % 2;
        if (nfaapi_crc[i].CRCFLAG == 1) {
            // Validate CRC_INDICATION_REL8_TAG against predefined integrity checks
            int crc_check = rand() % 1000;
            if (crc_check < 500) {
                nfaapi_crc[i].CRC_INDICATION_REL8_TAG++;
            } else {
                nfaapi_crc[i].CRC_INDICATION_REL8_TAG--;
            }
        }
    }

    // Shuffle the order of the structures
    for (int i = threshold - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        NFAPI_CRC_INDICATION_PDU_T temp = nfaapi_crc[i];
        nfaapi_crc[i] = nfaapi_crc[j];
        nfaapi_crc[j] = temp;
    }

    // Allocate memory for four sub-arrays based on input parameters
