// Define linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define linked list
Node* head = NULL;
int max_size = 1000; // set maximum size for the linked list
int current_size = 0;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Function to add a node to the linked list
void add_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        printf("Failed to add node\n");
        return;
    }
    if (current_size >= max_size) {
        printf("Linked list is full, cannot add more nodes\n");
        return;
    }
    current_size++;
    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

// Function to delete a node from the linked list
void delete_node(NFAPI_CRC_INDICATION_PDU_T data) {
    if (head == NULL) {
        printf("Linked list is empty, cannot delete nodes\n");
        return;
    }
    Node* temp = head;
    while (temp->next != NULL && temp->data.RX_UE_INFORMATION_TAG != data.RX_UE_INFORMATION_TAG) {
        temp = temp->next;
    }
    if (temp->next == NULL || temp->data.RX_UE_INFORMATION_TAG != data.RX_UE_INFORMATION_TAG) {
        printf("Node not found in linked list\n");
        return;
    }
    current_size--;
    Node* next_node = temp->next;
    temp->next = temp->next->next;
    free(next_node);
}

// Function to serialize the linked list
void serialize_list(FILE* file) {
    Node* temp = head;
    while (temp != NULL) {
        fwrite(&temp->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        temp = temp->next;
    }
}

// Function to deserialize the linked list
void deserialize_list(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_node(data);
    }
}

int main() {
    // Initialize random number generator for CRCFLAG
    srand(time(NULL));

    // Create linked list with some nodes
    for (int i = 0; i < 5; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand();
        data.RNTI = rand();
        data.CRC_INDICATION_REL8_TAG = rand();
        data.CRCFLAG = rand() % 2;
        add_node(data);
    }

    // Serialize linked list to file
    FILE* file = fopen("linked_list.bin", "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        return -1;
    }
    serialize_list(file);
    fclose(file);

    // Deserialize linked list from file
    file = fopen("linked_list.bin", "rb");
    if (file == NULL) {
        printf("Failed to open file for reading\n");
        return -1;
    }
    deserialize_list(file);
    fclose(file);

    // Delete all nodes in the linked list
    Node* temp = head;
    while (temp != NULL) {
        Node* next_node = temp->next;
        free(temp);
        temp = next_node;
    }

    return 0;
}
