    NFAPI_CRC_INDICATION_PDU_T* nfaapi_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        nfaapi_array[i].RX_UE_INFORMATION_TAG = i + 1;
        nfaapi_array[i].RNTI = i + 1;
        for (int j = 0; j < 4; j++) {
            nfaapi_array[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
    }

    int max_int = -1;
    int* input_array = NULL;
    int input_length = 0;

    while (fscanf(input, "%d", &max_int) == 1) {
        if (input_length >= N) {
            break;
        }
        input_array = (int*)realloc(input_array, (input_length + 1) * sizeof(int));
        input_array[input_length++] = max_int;
    }

    for (int i = 0; i < N - input_length; i++) {
        int avg = 0;
        for (int j = 0; j < input_length; j++) {
            avg += input_array[j];
        }
        avg /= input_length;
        for (int j = 0; j < 4; j++) {
            nfaapi_array[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
    }

    free(input_array);

    int largest_int = -1;
    if (input_length > 0) {
        for (int i = 0; i < input_length; i++) {
            if (input_array[i] > largest_int) {
                largest_int = input_array[i];
            }
        }
    }

