NFAPI_CRC_INDICATION_PDU_T **list = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t capacity = 0;
size_t size = 0;

void add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&mutex);

    // Check if the list needs to be resized
    if (size == capacity) {
        capacity *= 2; // Double the capacity
        list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(list, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    }

    // Validate the element before adding it to the list
    if (element->tag == RX_UE_INFORMATION_TAG_INVALID ||
        element->rnti < 0 || element->rnti > RNTI_MAX ||
        element->crc_tag == CRC_INDICATION_REL8_TAG_INVALID) {
        // Handle error recovery mechanism here
        pthread_mutex_unlock(&mutex);
        return;
    }

    list[size] = element;
    size++;

    pthread_mutex_unlock(&mutex);
}

