    long* offsets = (long*)malloc(num_records * sizeof(long));

    // Initialize random seed
    srand(time(NULL));

    // Generate records
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100;
        offsets[i] = rand();
    }

    // Initialize CRC indication pdu array
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_records; i++) {
        crc_indications[i].key = keys[i];
        crc_indications[i].offset = offsets[i];
        crc_indications[i].CRCFLAG = rand() % 2;
    }

    // Persist records to file
    FILE* file = fopen("records.json", "w");
    if (file) {
        fprintf(file, "[");
        for (int i = 0; i < num_records; i++) {
            fprintf(file, "{\"key\":%d,\"offset\":%ld,\"CRCFLAG\":%d}", crc_indications[i].key, crc_indications[i].offset, crc_indications[i].CRCFLAG);
            if (i < num_records - 1) {
                fprintf(file, ",");
            }
        }
        fprintf(file, "]");
        fclose(file);
    } else {
        // Handle file error
        printf("Error writing to file\n");
    }

    // Clean up
    free(keys);
    free(offsets);
    for (int i = 0; i < num_records; i++) {
        free(&crc_indications[i]);
    }
    free(crc_indications);

    return crc_indications;
}
