import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class FeedbackProcessor {

    private static final int MAX_FEEDBACK_PER_BATCH = 5000;
    private static final long COOLDOWN_MILLIS = 30 * 1000; // 30 seconds

    private BlockingQueue<FeedbackEntry> positiveQueue = new LinkedBlockingQueue<>();
    private BlockingQueue<FeedbackEntry> negativeQueue = new LinkedBlockingQueue<>();
    private BlockingQueue<FeedbackEntry> neutralQueue = new LinkedBlockingQueue<>();

    private FeedbackAnalyzer feedbackAnalyzer;
    private long lastStrategyChange = System.currentTimeMillis();

    public void processUserFeedback(List<FeedbackEntry> feedbackEntries) {
        for (FeedbackEntry entry : feedbackEntries) {
            analyzeAndCategorize(entry);
        }
    }

    private void analyzeAndCategorize(FeedbackEntry entry) {
        if (shouldUseStrategy1()) {
            // strategy 1 logic
            if (entry.getFeedbackType() == FeedbackType.POSITIVE) {
                positiveQueue.add(entry);
            } else if (entry.getFeedbackType() == FeedbackType.NEGATIVE) {
                negativeQueue.add(entry);
            } else {
                neutralQueue.add(entry);
            }
        } else {
            // strategy 2 logic
            // ...
        }

        if (positiveQueue.size() + negativeQueue.size() + neutralQueue.size() >= MAX_FEEDBACK_PER_BATCH) {
            submitBatchForAnalysis();
        }
    }

    private boolean shouldUseStrategy1() {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastStrategyChange < COOLDOWN_MILLIS) {
            return true; // stick with current strategy for now
        }

        double positiveRatio = getPositiveFeedbackRatio();
        double negativeRatio = getNegativeFeedbackRatio();

        if (positiveRatio > 0.5 && negativeRatio > 0.3) {
            return true;
        } else {
            lastStrategyChange = currentTime; // change strategy and update cooldown timer
            System.out.println("Switching to alternative processing strategy.");
            return false;
        }
    }

    private double getPositiveFeedbackRatio() {
        // implement logic to calculate positive feedback ratio based on historical data
        return 0.4;
    }

    private double getNegativeFeedbackRatio() {
        // implement logic to calculate negative feedback ratio based on historical data
        return 0.2;
    }

    private void submitBatchForAnalysis() {
        List<FeedbackEntry> batch = new ArrayList<>();
        while (positiveQueue.size() + negativeQueue.size() > MAX_FEEDBACK_PER_BATCH / 2) {
            batch.add(positiveQueue.take());
            batch.add(negativeQueue.take());
        }
        batch.addAll(neutralQueue);
        feedbackAnalyzer.analyze(batch);
    }
}

class FeedbackEntry {
    private int userId;
    private FeedbackType feedbackType;
    private String metadata;

    // getters and setters
}

enum FeedbackType {
    POSITIVE,
    NEGATIVE,
    NEUTRAL
}
