            rnti = rand() % curr_max_rnti + 1;
        }
        list[list_size].RNTI = rnti;

        list[list_size].CRC_INDICATION_REL8_TAG[0] = (rand() & 1);

        if (find_duplicate_rnti(list, list_size, list[list_size].RNTI)) {
            printf("Duplicate RNTI detected. Aborting.\n");
            free(list);
            return;
