dynamic_array_t* init_dynamic_array(size_t initial_capacity) {
    dynamic_array_t* array = (dynamic_array_t*)malloc(sizeof(dynamic_array_t));
    if (!array) return NULL;

    array->messages = (lte_phy_message_t*)calloc(initial_capacity, sizeof(lte_phy_message_t));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void resize_dynamic_array(dynamic_array_t* array, size_t new_capacity) {
    if (new_capacity <= array->count) return;

    lte_phy_message_t* messages = (lte_phy_message_t*)realloc(array->messages, new_capacity * sizeof(lte_phy_message_t));
    if (!messages) {
        fprintf(stderr, "Failed to resize dynamic array\n");
        return;
    }

    array->capacity = new_capacity;
    free(messages);
}

void destroy_dynamic_array(dynamic_array_t* array) {
    if (array) {
        for (size_t i = 0; i < array->count; i++) {
            free(array->messages[i].phich_configuration);
        }
        free(array->messages);
        free(array);
