#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

void* record_array = NULL;
int array_size = 0;
int array_capacity = 1000000; // initial capacity
Record* current_end = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("duplicate_keys.log", "w");

// Function to manage memory allocation for a dynamic array of record structures
Record** allocate_records(int new_size) {
    Record** new_array = realloc(record_array, sizeof(Record*) * new_size);
    if (!new_array) {
        return NULL;
    }
    record_array = new_array;
    array_capacity = new_size;
    return &record_array[0];
}

// Function to shuffle the records array
void* shuffle_records(int num_threads) {
    // Initialize random seed for reproducibility
    srand(time(NULL));

    int* indices = malloc(array_size * sizeof(int));
    if (!indices) {
        return NULL;
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, shuffle_thread, &indices);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(indices);
    return record_array;
}

void* shuffle_thread(void* arg) {
    int* indices = (int*)arg;
    int start = rand() % array_size;
    int end = rand() % (array_size - start + 1);
    for (int i = start; i <= end; i++) {
        Record temp = record_array[indices[i]];
        indices[i] = indices[i-1];
        indices[i-1] = temp;
    }
}

// Function to add a new record to the array, handling duplicates and memory allocation
Record** append_record(Record* new_rec) {
    pthread_mutex_lock(&lock);

    // Check for duplicate key
    Record* current = record_array;
    for (int i = 0; i < array_size; i++) {
        if (current[i].key == new_rec->key) {
            fprintf(log_file, "Duplicate key %d found at index %d.\n", new_rec->key, i);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    // Resize the array if necessary
    if (array_size >= array_capacity / 2) {
        Record** new_array = allocate_records(array_capacity * 2);
        if (!new_array) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        array_size *= 2;
        record_array = new_array;
    }

    // Add the new record to the end of the array
    record_array[array_size] = *new_rec;
    array_size++;
    pthread_mutex_unlock(&lock);
    return &record_array[0];
}

int main() {
    // Initialize the records array with initial capacity
    record_array = allocate_records(array_capacity);

    // Add new records to the array, handling duplicates and memory allocation
    Record* rec1 = (Record*)malloc(sizeof(Record));
    *rec1 = (Record){0, 1, 10};
    Record** result = append_record(rec1);
    if (!result) {
        return -1;
    }

    // Shuffle the records array using threads
    int num_threads = 4;
    void* shuffled_records = shuffle_records(num_threads);
    free(rec1);

    // Process the shuffled records array
    for (int i = 0; i < array_size; i++) {
        printf("%ld %d %d\n", record_array[i].offset, record_array[i].key, record_array[i].value);
    }

    return 0;
}

