// Function to dynamically manage and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void* crc_indication_pdu_manager(int num_structures, int default_crcflag) {
    // Initialize the memory pool with a configurable initial size
    size_t initial_pool_size = 1024;
    void* memory_pool = malloc(initial_pool_size);

    // Track total number of structures processed and errors encountered during allocation
    int total_structures = 0;
    int allocation_errors = 0;

    // Initialize the linked list head
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    // Create a real-time log file for creation metrics and errors
    FILE* log_file = fopen("crc_indication_pdu_log.txt", "w");

    // Monitor memory pool usage and allocation rates
    size_t total_allocated = 0;
    size_t peak_usage = 0;

    // Initialize the real-time alerting mechanism
    pthread_mutex_t validation_lock = PTHREAD_MUTEX_INITIALIZER;
    int validation_errors = 0;

    // Create the linked list of NFAPI_CRC_INDICATION_PDU_T structures under varying load conditions
    for (int i = 0; i < num_structures; i++) {
        // Allocate a new structure from the memory pool
        void* new_pdu = malloc(initial_pool_size);
        if (!new_pdu) {
            allocation_errors++;
            printf("Error allocating memory for NFAPI_CRC_INDICATION_PDU_T structure: %d\n", allocation_errors);
            continue;
        }

        total_allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Initialize the new structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)new_pdu;
        pdu->RX_UE_INFORMATION_TAG = i % 256; // Randomly assign a valid RX_UE_INFORMATION_TAG
        pdu->RNTI = i % 65536; // Randomly assign a valid RNTI
        strcpy(pdu->CRC_INDICATION_REL8_TAG, " CRC_INDICATION_REL8_TAG"); // Assign the CRC_INDICATION_REL8_TAG

        // Set the CRCFLAG based on the configurable default
        pdu->CRCFLAG = default_crcflag;

        // Validate the integrity of each RX_UE_INFORMATION_TAG before inclusion
        if (pdu->RX_UE_INFORMATION_TAG != i) {
            pthread_mutex_lock(&validation_lock);
            validation_errors++;
            printf("Validation failure: %d\n", validation_errors);
            pthread_mutex_unlock(&validation_lock);
        } else {
            // Add the new structure to the linked list
            if (!head) head = pdu;
            if (current) current->next = pdu;
            current = pdu;

            // Log detailed creation metrics, including total number of structures processed and errors encountered during allocation
            fprintf(log_file, "Created NFAPI_CRC_INDICATION_PDU_T structure %d with RX_UE_INFORMATION_TAG 0x%x and CRCFLAG 0x%x\n", i, pdu->RX_UE_INFORMATION_TAG, pdu->CRCFLAG);

            // Monitor memory pool usage and allocation rates
            size_t current_usage = total_allocated;
            if (current_usage > peak_usage) peak_usage = current_usage;

            // Real-time alerting mechanism to notify of any validation failures
            if (validation_errors > 0) {
                pthread_mutex_lock(&validation_lock);
                printf("Validation error: %d\n", validation_errors);
                pthread_mutex_unlock(&validation_lock);
            }
        }

        total_structures++;
    }

    // Log creation metrics and errors at the end of the function
    fprintf(log_file, "Total NFAPI_CRC_INDICATION_PDU_T structures processed: %d\n", total_structures);
    fprintf(log_file, "Total allocation errors: %d\n", allocation_errors);

    fclose(log_file);

    return head;
}
