    // Initialize the hash table
    int* rnti_hash = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 0; i <= N; i++) {
        rnti_hash[i] = -1;
    }

    // Generate and store NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        int rnti = rand() % (N + 1);
        while (rnti_hash[rnti] == -1) {
            rnti = rand() % (N + 1);
        }
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rnti;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand();
        rnti_hash[rnti] = i;
    }

    // Read integers from standard input and store them in a dynamically allocated array
    int* input_array = (int*)malloc(1000000 * sizeof(int));
    for (int i = 0; i < 1000000; i++) {
        scanf("%d", &input_array[i]);
    }

    // Implement helper function to find and print the largest integer in the array
    int find_largest_integer() {
        int max_val = input_array[0];
        for (int i = 1; i < 1000000; i++) {
            if (input_array[i] > max_val) {
                max_val = input_array[i];
            }
        }
        printf("The largest integer is: %d\n", max_val);
