    // Dynamically allocate memory for multiple arrays
    long** offset_arrays = (long**)malloc(N * sizeof(long*));
    int* key_arrays = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        offset_arrays[i] = (long*)malloc(10000 * sizeof(long));
        key_arrays[i] = i;
    }

    // Populate the 'record' array with unique 'int' values
    int* record_array = (int*)malloc(N * sizeof(int));
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        record_array[i] = rand() % 10000;
    }

    return pdu_list;
}

int main() {
    int N = 10;
    generate_and_manage_nfaapi_pdu_list(N);
    return 0;
