int nfaPiCrcIndicationPduListAdd(NFAPI_CRC_INDICATION_PDU_T *pdu, int maxListSize) {
    if (maxListSize < 1) {
        printf("Invalid maximum list size. Defaulting to %d.\n", MAX_LIST_SIZE);
        return -1;
    }
