                custom_routing_rules_array[j] = custom_routing_rule;
            }

            config->num_custom_routing_rules = batch_size;
            config->custom_routing_rules = custom_routing_rules_array;
        }
    }

    pthread_mutex_unlock(&mutex);

    return memory_pool;
}

