// Custom sorting algorithm for shuffling
void* swap(void* a, void* b) {
    NFAPI_CRC_INDICATION_PDU_T* x = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDATION_PDU_T* y = (NFAPI_CRC_INDATION_PDU_T*)b;

