        // Validate unique RNTIs
        pthread_mutex_lock(&lock);
        if (!list[i]) {
            list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!list[i]) {
                free(list);
                return NULL;
            }
            // Initialize structure
            list[i]->RX_UE_INFORMATION_TAG = rand() % 256;
            list[i]->RNTI = rand() % 0x10000;
            list[i]->CRCFLAG = rand() & 1;

            // Shuffle the list
            qsort(list, i + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*), swap);
        } else {
            pthread_mutex_unlock(&lock);
            // Log duplicate RNTI and index if found
            printf("Duplicate RNTI %x at index %d.\n", list[i]->RNTI, i);
        }
        pthread_mutex_unlock(&lock);
    }

    return list;
