int phy_layer_message_create(PhyLayerMessages* messages, int phich_configuration, int ue_id, char* dl_mch_data_tag) {
    // Allocate memory for the new message and its buffer
    PhyLayerControlMessage* message = (PhyLayerControlMessage*)malloc(sizeof(PhyLayerControlMessage));
    message->phich_configuration = phich_configuration;
    message->ue_id = ue_id;
    message->dl_mch_data_tag = dl_mch_data_tag;

    // Resize the dynamic array if necessary
    if (messages->size == messages->last_used_index + 1) {
        messages->size *= 2;
        PhyLayerControlMessage** new_messages = (PhyLayerControlMessage**)malloc(messages->size * sizeof(PhyLayerControlMessage*));
        memcpy(new_messages, messages->messages, (messages->last_used_index + 1) * sizeof(PhyLayerControlMessage*));
        free(messages->messages);
        messages->messages = new_messages;
    }

    // Add the new message to the dynamic array
    if (messages->size == 0 || messages->last_used_index >= messages->size - 1) {
        messages->messages = (PhyLayerControlMessage**)realloc(messages->messages, (messages->size + 1) * sizeof(PhyLayerControlMessage*));
        messages->messages[messages->size++] = message;
    } else {
        messages->last_used_index++;
        messages->messages[messages->last_used_index] = message;
    }

    return messages->size - 1;
}

