} Record;

Record* manage_dynamic_records(int num_records) {
    // Initialize the record array with a default capacity
    Record* records = (Record*) malloc(num_records * sizeof(Record));

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    int current_capacity = num_records;
    int size = 0;

    // Create a mutex to synchronize access to the record array
    pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        Record new_record;

        if (rand() % 2 == 0) {
            // For demonstration purposes, create a duplicate key every other time
            int duplicate_key = rand() % 10000;
            bool found_duplicate = false;

            pthread_mutex_lock(&records_mutex);

            for (int j = 0; j < size; j++) {
                if (records[j].key == duplicate_key) {
                    printf("Duplicate key detected at index %d with value %d.\n", j, records[j].value);
                    found_duplicate = true;
                    break;
                }
            }

            pthread_mutex_unlock(&records_mutex);

            if (!found_duplicate) {
                // If the record does not exist in the array yet, add it
                records[size] = new_record;
                size++;
            } else {
                // If a duplicate is detected, stop adding more records
                printf("Record with key %d already exists.\n", duplicate_key);
                break;
            }
        } else {
            // Add random records to the array without duplicates
            for (int j = 0; j < size; j++) {
                if (records[j].key == new_record.key) {
                    printf("Record with key %d already exists.\n", new_record.key);
                    break;
                }
            }

            if (j == size) {
                records[size] = new_record;
                size++;
            }
        }
    }

    pthread_mutex_unlock(&records_mutex);

    // Return a pointer to the first element of the shuffled records array
    return &records[0];
}

typedef struct {
    long timestamp;
    int event_type;
    union {
        int integer_value;
        char string_value[];
    } event_data;
} NetworkEvent;

NetworkEvent* initialize_and_populate_network_events(int max_events, int seed) {
    // Create an array of network events with the specified maximum size
    NetworkEvent* events = (NetworkEvent*) malloc(max_events * sizeof(NetworkEvent));

    if (!events) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    int unique_event_count = 0;

    for (int i = 0; i < max_events; i++) {
        NetworkEvent new_event;

        // Initialize the event type and timestamp
        srand(seed);
        new_event.event_type = rand() % 5;  // Randomly select one of five event types

        if (new_event.event_type == 0) {  // Handle an integer value
            new_event.event_data.integer_value = rand();
        } else {
            new_event.event_data.string_value = (char*) malloc(20);
            sprintf(new_event.event_data.string_value, "Event %d", i);
        }

        // Check for duplicate events
        bool found_duplicate = false;

        pthread_mutex_lock(&events_mutex);

        for (int j = 0; j < unique_event_count; j++) {
            if (memcmp(&events[j], &new_event, sizeof(NetworkEvent)) == 0) {
                found_duplicate = true;
                break;
            }
        }

        pthread_mutex_unlock(&events_mutex);

        if (!found_duplicate) {
            // If the event does not exist in the array yet, add it
            events[unique_event_count] = new_event;
            unique_event_count++;
        } else {
            // If a duplicate is detected, stop adding more records
            printf("Duplicate event detected.\n");
            break;
        }
    }

    // Return a pointer to the first element of the shuffled network events array
    return &events[0];
}
