typedef struct {
    int timestamp;
    int id;
    double value;
} Entry;

void init_entry_array(Entry** array, size_t* count) {
    *array = NULL;
    *count = 0;
}

int add_entry(Entry*** array, size_t* count, size_t new_size) {
    if (*count >= new_size) {
        // Reallocate memory
        Entry** temp = (Entry**) realloc(*array, sizeof(Entry*) * new_size);
        if (!temp) return -1; // Memory allocation failure
        *array = temp;
        *count = new_size;
    }
    return 0; // Success
}

int generate_entry(int* timestamp_range, Entry** array, size_t count) {
    for (size_t i = 0; i < count; i++) {
        Entry new_entry = {rand() % TIMESTAMP_RANGE + 1, rand(), 0.0};
        // Perform necessary checks for constraints and integrity
        if (add_entry(&array, &count, count * 2) == -1) return -1; // Memory allocation failure
        array[count - 1] = &new_entry;
    }
    return 0; // Success
}

void print_entries(Entry* array, size_t count) {
    for (size_t i = 0; i < count; i++) {
        Entry entry = array[i];
        printf("Timestamp: %d, ID: %d, Value: %.2f\n", 
              entry.timestamp, entry.id, entry.value);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t entry_count = 0;
    Entry* entries[MAX_ENTRY_COUNT] = {NULL};

    while (1) {
        int result = generate_entry(&TIMESTAMP_RANGE, &entries[entry_count], entry_count);
        if (result == -1) break; // Memory allocation failure
        entry_count++;
    }

    print_entries(entries, entry_count);

    return 0;
}

