#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} record_t;

record_t** records = NULL;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* init_records(int max_records) {
    records = (record_t**)malloc(max_records * sizeof(record_t*));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < max_records; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
        if (!records[i]) {
            free(records);
            return NULL;
        }
    }

    return records;
}

void add_record(int key, long offset) {
    pthread_mutex_lock(&lock);
    record_t** new_records = (record_t**)realloc(records, (num_records + 1) * sizeof(record_t*));
    if (!new_records) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    records = new_records;

    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    if (!new_record) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_record->key = key;
    new_record->offset = offset;

    records[num_records] = new_record;
    num_records++;

    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key) {
            free(records[i]);
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(record_t*));
            num_records--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void release_records() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
    records = NULL;
    num_records = 0;
    pthread_mutex_unlock(&lock);
}
