typedef struct {
    char flow_id[16];
    int packet_counter;
    float data_rate;
    char ip_addr[20];
    char subnet_mask[20];
    char gateway[20];
    void* custom_routing_rules;
} NetworkConfiguration;

typedef struct {
    NetworkConfiguration** configurations;
    int size;
} ConfigurationManager;

void init_configuration_manager(ConfigurationManager* manager, int initial_size) {
    manager->configurations = (NetworkConfiguration**)malloc(initial_size * sizeof(NetworkConfiguration*));
    manager->size = initial_size;
}

int add_network_config(ConfigurationManager* manager, char* flow_id, int packet_counter, float data_rate, char* ip_addr, char* subnet_mask, char* gateway, void* custom_routing_rules) {
    if (manager->size == 0) {
        manager->configurations = (NetworkConfiguration**)malloc(1 * sizeof(NetworkConfiguration*));
        manager->size = 1;
    } else if (manager->size <= 10 && manager->size % 2 == 0) {
        int new_size = manager->size * 2;
        void** temp_configs = (void**)realloc(manager->configurations, new_size * sizeof(NetworkConfiguration*));
        manager->configurations = (NetworkConfiguration**)temp_configs;
        manager->size = new_size;
    }

    NetworkConfiguration* new_config = (NetworkConfiguration*)malloc(sizeof(NetworkConfiguration));
    strcpy(new_config->flow_id, flow_id);
    new_config->packet_counter = packet_counter;
    new_config->data_rate = data_rate;
    strcpy(new_config->ip_addr, ip_addr);
    strcpy(new_config->subnet_mask, subnet_mask);
    strcpy(new_config->gateway, gateway);
    new_config->custom_routing_rules = custom_routing_rules;

    manager->configurations[manager->size - 1] = new_config;
    return manager->size - 1;
}

void remove_network_config(ConfigurationManager* manager, int config_id) {
    if (config_id < 0 || config_id >= manager->size) {
        printf("Invalid configuration ID\n");
        return;
    }

    free(manager->configurations[config_id]->custom_routing_rules);
    free(manager->configurations[config_id]);
    for (int i = config_id; i < manager->size - 1; i++) {
        manager->configurations[i] = manager->configurations[i + 1];
    }
    manager->size--;
}

void update_network_config(ConfigurationManager* manager, int config_id, char* flow_id, int packet_counter, float data_rate, char* ip_addr, char* subnet_mask, char* gateway, void* custom_routing_rules) {
    if (config_id < 0 || config_id >= manager->size) {
        printf("Invalid configuration ID\n");
        return;
    }

    manager->configurations[config_id]->packet_counter = packet_counter;
    manager->configurations[config_id]->data_rate = data_rate;
    strcpy(manager->configurations[config_id]->ip_addr, ip_addr);
    strcpy(manager->configurations[config_id]->subnet_mask, subnet_mask);
    strcpy(manager->configurations[config_id]->gateway, gateway);
    free((void*)manager->configurations[config_id]->custom_routing_rules);
    manager->configurations[config_id]->custom_routing_rules = custom_routing_rules;
}

int main() {
    ConfigurationManager manager;
    init_configuration_manager(&manager, 10);

    add_network_config(&manager, "flow1", 0, 1.0f, "192.168.1.1", "255.255.255.0", "192.168.1.254", (void*)malloc(1024));
    add_network_config(&manager, "flow2", 10, 2.5f, "192.168.2.1", "255.255.255.0", "192.168.2.254", (void*)malloc(2048));

    update_network_config(&manager, 0, "new_flow_id", 15, 3.5f, "10.1.1.1", "255.255.255.0", "10.1.1.254", (void*)malloc(4096));
    remove_network_config(&manager, 1);

    return 0;
}
