#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int sessionID;
    char connectionState;
    float bandwidthUsage;
} UserSession;

// Function to initialize and manage dynamic array of UserSession structures
void* userSessions = NULL;
int userSessionCount = 0;
int userSessionCapacity = 1; // Initial capacity

// Function to resize the dynamic array when needed
void resizeArray(int newSize) {
    void* newArray = realloc(userSessions, newSize * sizeof(UserSession));
    if (newArray == NULL) {
        printf("Error: Memory allocation failed!\n");
        exit(-1);
    }
    userSessions = newArray;
    userSessionCapacity = newSize;
}

// Function to add a new UserSession structure
void addUserSession(int sessionID, char connectionState, float bandwidthUsage) {
    if (userSessionCount >= userSessionCapacity) {
        resizeArray(userSessionCapacity * 2); // Double the capacity when full
    }

    UserSession* session = &((UserSession*)userSessions)[userSessionCount++];
    session->sessionID = sessionID;
    session->connectionState = connectionState;
    if (bandwidthUsage > 0 && bandwidthUsage <= 10000.0) { // Validate and clamp bandwidth usage
        session->bandwidthUsage = bandwidthUsage;
    } else {
        printf("Error: Invalid bandwidth usage! (1 Mbps to 10 Gbps)\n");
        return; // Abort adding the new UserSession if invalid
    }
}

// Function to serialize a UserSession structure for storage or transfer purposes
int serializeUserSession(const void* userSessionData, char* serializedData) {
    const UserSession* session = (const UserSession*)userSessionData;
    sprintf(serializedData, "{\"sessionID\": %d, \"connectionState\": \"%c\", \"bandwidthUsage\": %.2f}",
            session->sessionID, session->connectionState, session->bandwidthUsage);
    return strlen(serializedData);
}

int main() {
    addUserSession(1, 'A', 5000.0); // Initial user sessions
    addUserSession(2, 'B', 8000.0);

    char serializedUserSession[100];
    int serializedLength = serializeUserSession(&((UserSession*)userSessions)[0], serializedUserSession);
    printf("Serialized User Session: %s (%d bytes)\n", serializedUserSession, serializedLength);

    return 0;
}

