        int new_capacity = cm->capacity * 2; // Double the capacity
        NetworkConfig** new_configs = realloc(cm->configs, sizeof(NetworkConfig*) * new_capacity);
        if (new_configs == NULL) return -1; // Memory allocation failure
        cm->configs = new_configs;
        cm->capacity = new_capacity;
    }

    // Add the new configuration to the collection
    cm->configs[cm->num_configs] = config;
    cm->num_configs++;

    return 0; // Success
}

// Delete a network interface configuration from the collection
int config_manager_delete_config(ConfigManager* cm, char* mac_address) {
    int i;
    for (i = 0; i < cm->num_configs; i++) {
        if (strcmp(cm->configs[i]->mac_address, mac_address) == 0) {
            // Shift remaining configurations to fill the gap
            memmove(&cm->configs[i], &cm->configs[i + 1], sizeof(NetworkConfig*) * (cm->num_configs - i - 1));

            // Reclaim memory allocated for the deleted configuration
            free(cm->configs[i]->log_buffer);
            free(cm->configs[i]);
            cm->configs[i] = NULL;

            // Adjust the collection's capacity and number of configurations
            cm->num_configs--;
            if (cm->num_configs < cm->capacity / 2) { // Halve the capacity if necessary
                int new_capacity = cm->capacity / 2;
                NetworkConfig** new_configs = realloc(cm->configs, sizeof(NetworkConfig*) * new_capacity);
                if (new_configs == NULL) return -1; // Memory allocation failure
                cm->configs = new_configs;
                cm->capacity = new_capacity;
            }

            return 0; // Success
        }
    }

    return -2; // Configuration not found
}

// Modify a network interface configuration in the collection
int config_manager_modify_config(ConfigManager* cm, char* mac_address, NetworkConfig* new_config) {
    int i;
    for (i = 0; i < cm->num_configs; i++) {
        if (strcmp(cm->configs[i]->mac_address, mac_address) == 0) {
            // Update the configuration with the new values
            memcpy(&cm->configs[i], new_config, sizeof(NetworkConfig));

            return 0; // Success
        }
    }

    return -2; // Configuration not found
}

// Clear expired log entries based on a configurable retention policy
int config_manager_clear_logs(ConfigManager* cm) {
    int i;
    for (i = 0; i < cm->num_configs; i++) {
        if (cm->configs[i]->buffer_size > 0) { // Check if the buffer is not empty
            // Implement a simple log retention policy: keep logs for at most 30 days
            time_t current_time = time(NULL);
            char* log_entry = (char*)cm->configs[i]->log_buffer;
            while (*log_entry != '\0') {
                if (difftime(current_time, *(time_t*)log_entry) > 2592000) { // 30 days in seconds
                    // Expired log entry, shift remaining logs to fill the gap
                    memmove(log_entry, log_entry + 1, strlen(log_entry));
                    break;
                }
                log_entry = strchr(log_entry, '\n');
                if (log_entry == NULL) break; // No more log entries
                *log_entry = '\0'; // Null-terminate the log entry
            }
        }
    }

    return 0; // Success
}

// Helper function to periodically clear expired log entries
void* config_manager_garbage_collection(void* arg) {
    ConfigManager* cm = (ConfigManager*)arg;
    while (1) { // Run indefinitely
        sleep(86400); // Clear logs every 24 hours
        config_manager_clear_logs(cm);
    }

    return NULL; // Successful termination
}

// Initialize the configuration manager and start garbage collection
int main() {
    ConfigManager* cm = config_manager_init();
    pthread_t thread;
    pthread_create(&thread, NULL, config_manager_garbage_collection, cm);

    // Example usage: add and modify configurations, delete a configuration
    NetworkConfig* config1 = malloc(sizeof(NetworkConfig));
    config1->mac_address = "00:11:22:33:44:55";
    config1->ip_address = "192.168.0.1";
    config1->buffer_size = 1024;
    config1->log_buffer = malloc(config1->buffer_size);

    NetworkConfig* config2 = malloc(sizeof(NetworkConfig));
    config2->mac_address = "00:44:55:66:77:88";
    config2->ip_address = "192.168.0.2";
    config2->buffer_size = 2048;
    config2->log_buffer = malloc(config2->buffer_size);

    config_manager_add_config(cm, config1);
    config_manager_add_config(cm, config2);

    NetworkConfig* modified_config = malloc(sizeof(NetworkConfig));
    modified_config->mac_address = "00:11:22:33:44:55";
    modified_config->ip_address = "192.168.0.3";
    modified_config->buffer_size = 1024;
    modified_config->log_buffer = malloc(modified_config->buffer_size);

    config_manager_modify_config(cm, modified_config->mac_address, modified_config);

    config_manager_delete_config(cm, "00:44:55:66:77:88");

    return 0; // Successful termination
}

