// Function to manage memory allocation and initialization
void* allocate_memory(int max_offsets, int min_value, int max_value) {
    // Allocate memory for offset array
    offset_t* offsets = (offset_t*)malloc(max_offsets * sizeof(offset_t));

    if (!offsets) {
        printf("Error: Unable to allocate memory for offset array.\n");
        return NULL;
    }

    // Initialize offset array with random values
    for (int i = 0; i < max_offsets; i++) {
        offsets[i].offset_value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for key array, same size as offset array
    key_t* keys = (key_t*)malloc(max_offsets * sizeof(key_t));

    if (!keys) {
        printf("Error: Unable to allocate memory for key array.\n");
        free(offsets);
        return NULL;
    }

    // Initialize key array with default values
    for (int i = 0; i < max_offsets; i++) {
        keys[i].key_value = 0;
    }

    // Allocate memory for record array, size determined by max_offsets and 2
    record_t* records = (record_t*)malloc(max_offsets * 2 * sizeof(record_t));

    if (!records) {
        printf("Error: Unable to allocate memory for record array.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record array with random values
    for (int i = 0; i < max_offsets * 2; i++) {
        records[i].record_value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Return pointers to allocated memory blocks and error status
    return ((void*)offsets, keys, records);
}
