NFAPI_CRC_INDICATION_PDU_T* nfaPiCrcIndicationPduTs[NFAPI_CRC_INDICATION_PDU_T_MAX] = {0};

pthread_mutex_t nfaPiMutex = PTHREAD_MUTEX_INITIALIZER;
int nfaPiPoolSize = 100;
int nfaPiCurrentUsage = 0;

void* nfaPiMalloc(size_t size) {
    void* p = malloc(size);
    if (!p) {
        printf("Memory allocation failed\n");
    }
    return p;
}

void nfaPiFree(void* p, size_t size) {
    free(p);
}

int nfaPiCreateNFAPI_CRC_INDICATION_PDU_T(int RNTI, char* RX_UE_INFORMATION_TAG, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)nfaPiMalloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!p) return -1;

    strcpy(p->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);
    p->RNTI = RNTI;
    p->CRCFLAG = CRCFLAG;
    p->CRC_INDICATION_REL8_TAG[0] = '\0';

    pthread_mutex_lock(&nfaPiMutex);
    if (nfaPiCurrentUsage >= nfaPiPoolSize) {
        printf("Memory pool overflow\n");
        pthread_mutex_unlock(&nfaPiMutex);
        nfaPiFree(p, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return -1;
    }

    nfaPiCurrentUsage++;
    pthread_mutex_unlock(&nfaPiMutex);

    if (strlen(RX_UE_INFORMATION_TAG) > 64 || RNTI < 0 || CRCFLAG < 0 || CRCFLAG > 255) {
        printf("Invalid RX_UE_INFORMATION_TAG or RNTI/CRCFLAG\n");
        nfaPiFree(p, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return -1;
    }

    nfaPiCrcIndicationPduTs[nfaPiCurrentUsage-1] = p;
    printf("NFAPI_CRC_INDICATION_PDU_T created successfully\n");
    return 0;
}

int main() {
    // Call the function with sample data
    NFAPI_CRC_INDICATION_PDU_T* p = nfaPiCreateNFAPI_CRC_INDICATION_PDU_T(1, "abc", 0);

    return 0;
}
