int init_lte_phy_layer_control_messages(int num_messages, int* phich_configurations, uint16_t* ue_ids, char*** dl_mch_data_tags) {
    lte_phy_layer_control_message** messages = (lte_phy_layer_control_message**)malloc(num_messages * sizeof(lte_phy_layer_control_message*));
    if (messages == NULL) return -1;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int current_index = 0;
    for (int i = 0; i < num_messages; i++) {
        lte_phy_layer_control_message* message = (lte_phy_layer_control_message*)malloc(sizeof(lte_phy_layer_control_message));
        if (message == NULL) return -1;

        pthread_mutex_lock(&mutex);
        message->phich_configuration = phich_configurations[i];
        message->ue_id = ue_ids[i];
        message->dl_mch_data_tag = (char*)custom_allocator(1024); // dynamic buffer allocation
        if (message->dl_mch_data_tag == NULL) return -1;

        printf("Created message %d with PHICH configuration %d and UE ID %u\n", current_index, message->phich_configuration, message->ue_id);
        current_index++;

        pthread_mutex_unlock(&mutex);
    }

    free(messages);
    return 0;
}

void destroy_lte_phy_layer_control_messages(lte_phy_layer_control_message** messages, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
        free(messages[i]->dl_mch_data_tag);
        free(messages[i]);
    }
