typedef struct {
    float sum;
    int count;
    int windowSize;
} MovingAverage;

// Function to process temperature measurements from a sensor network
void processSensorReadings(int numReadings, SensorReading readings[], int *uniqueIds, int numUniqueIds) {
    // Initialize internal data structures based on the number of unique sensor IDs and total number of measurements
    int* idSet = (int*)malloc(numUniqueIds * sizeof(int));
    for (int i = 0; i < numUniqueIds; i++) idSet[i] = -1;

    float* temperatures = (float*)malloc(numReadings * sizeof(float));
    char* qualityFlags = (char*)malloc(numReadings * sizeof(char));

    // Filter out low-quality measurements using a configurable threshold
    int highQualityCount = 0;
    for (int i = 0; i < numReadings; i++) {
        if (readings[i].quality == 'H') {
            temperatures[highQualityCount] = readings[i].temp;
            qualityFlags[highQualityCount] = readings[i].quality;
            highQualityCount++;
        }
    }

    // Compute the moving average of temperature readings over a specified window size
    MovingAverage* movingAverages = (MovingAverage*)malloc(numUniqueIds * sizeof(MovingAverage));
    for (int i = 0; i < numUniqueIds; i++) {
        movingAverages[i].sum = temperatures[0];
        movingAverages[i].count = 1;
        movingAverages[i].windowSize = 5;
    }

    // Implement comprehensive error handling for memory allocation failures and arithmetic operations
    for (int i = 0; i < highQualityCount; i++) {
        int uniqueIdIndex = -1;
        for (int j = 0; j < numUniqueIds; j++) {
            if (uniqueIds[j] == readings[i].id) {
                uniqueIdIndex = j;
                break;
            }
        }
        if (uniqueIdIndex != -1) {
            movingAverages[uniqueIdIndex].sum += temperatures[i];
            movingAverages[uniqueIdIndex].count++;
        } else {
            printf("Error: Unknown sensor ID %d\n", readings[i].id);
        }
    }

    // Optimize the function to reduce cache misses, considering both sequential and random access patterns
    for (int i = 0; i < numUniqueIds; i++) {
        if (movingAverages[i].count > movingAverages[i].windowSize) {
            float sum = movingAverages[i].sum;
            int count = movingAverages[i].count;
            movingAverages[i].sum = 0;
            movingAverages[i].count = 1;
            for (int j = 0; j < count - 1; j++) {
                sum -= temperatures[(i * movingAverages[i].windowSize) + j];
                movingAverages[i].sum += temperatures[(i * movingAverages[i].windowSize) + j + 1];
                movingAverages[i].count++;
            }
        }
    }

    // Integrate the function with an external sensor network API, ensuring compatibility and efficient data transfer
    printf("Average temperature readings: ");
    for (int i = 0; i < numUniqueIds; i++) {
        if (uniqueIds[i] != -1) {
            float averageTemp = movingAverages[i].sum / movingAverages[i].count;
            printf("%.2f ", averageTemp);
        }
    }
    printf("\n");

    // Free dynamically allocated memory
    free(idSet);
    free(temperatures);
    free(qualityFlags);
    for (int i = 0; i < numUniqueIds; i++) {
        if (uniqueIds[i] != -1) {
            free(&movingAverages[i]);
        }
    }
    free(movingAverages);
}

int main() {
    // Initialize sensor readings and quality flags
    SensorReading readings[] = {
        {1, 25.0f, 'H'},
        {2, 20.5f, 'L'},
        {3, 28.0f, 'H'},
        {4, 22.8f, 'L'},
        {1, 27.0f, 'H'},
        {2, 23.1f, 'H'},
    };

    // Simulate the number of unique sensor IDs and total number of measurements
    int numUniqueIds = 3;
    int* uniqueIds = (int*)malloc(numUniqueIds * sizeof(int));
    for (int i = 0; i < numUniqueIds; i++) {
        uniqueIds[i] = readings[i].id;
    }

    // Call the function to process temperature measurements from a sensor network
    int numReadings = sizeof(readings) / sizeof(readings[0]);
    processSensorReadings(numReadings, readings, uniqueIds, numUniqueIds);

    return 0;
}

