// Structure to represent NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure for the linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to initialize a new node with random CRC flag
Node* initNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->data.CRCFLAG = rand() % 2; // Set CRC flag randomly
    newNode->next = NULL;
    return newNode;
}

// Function to add a new entry to the linked list
void addEntry(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = initNode(data);
    if (!*head) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = newNode;
    }
}

// Function to update an existing entry based on RNTI
void updateEntry(Node** head, int RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = *head;
    while (current && current->data.RNTI != RNTI) {
        current = current->next;
    }
    if (!current) printf("Error: RNTI not found\n");
    else current->data = data;
}

// Function to remove an entry by RNTI
void removeEntry(Node** head, int RNTI) {
    Node* previous = NULL;
    Node* current = *head;
    while (current && current->data.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }
    if (!current) printf("Error: RNTI not found\n");
    else if (previous) previous->next = current->next;
    else *head = current->next;
    free(current);
}

// Function to print the linked list
void printList(Node* head) {
    Node* current = head;
    while (current) {
        printf("RNTI: %d, CRC Flag: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator
    Node* head = NULL;

    // Add some entries to the list
    addEntry(&head, (NFAPI_CRC_INDICATION_PDU_T){1, 10, 0});
    addEntry(&head, (NFAPI_CRC_INDICATION_PDU_T){2, 20, 1});
    addEntry(&head, (NFAPI_CRC_INDICATION_PDU_T){3, 30, 0});

    // Print the initial list
    printList(head);

    // Update an entry
    updateEntry(&head, 20, (NFAPI_CRC_INDICATION_PDU_T){2, 25, 1});
    printf("Updated list:\n");
    printList(head);

    // Remove an entry
    removeEntry(&head, 30);
    printf("Removed entry: RNTI 30\n");
    printf("Updated list:\n");
    printList(head);

    return 0;
}
