public class DataProcessor
{
    private readonly Dictionary<string, object> _cache = new();
    private readonly BinaryFormatter _formatter = new();

    public void LoadAndDeserialize(string filePath)
    {
        try
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            {
                byte[] buffer = new byte[4096];
                long bytesRead = 0;
                while ((bytesRead += fileStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    MemoryStream ms = new MemoryStream();
                    using (GZipStream gzip = new GZipStream(ms, CompressionMode.Decompress))
                    {
                        gzip.Write(buffer, 0, (int)buffer.Length);
                    }
                    object data = _formatter.Deserialize(ms);
                    string key = Regex.Match(filePath, @"^.*\/(\w+)$").Groups[1].Value;
                    _cache.Add(key, data);

                    if (_cache.Count >= 100)
                    {
                        FlushCache();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
        }

        Stopwatch stopwatch = Stopwatch.StartNew();
        while (stopwatch.ElapsedMilliseconds < 5000)
        {
            // wait for the timeout
        }
        stopwatch.Stop();

        if (stopwatch.ElapsedMilliseconds >= 5000)
        {
            LogError("Deserialization took too long");
        }
    }

    private void FlushCache()
    {
        foreach ((string key, object value) in _cache.ToArray())
        {
            // flush cache to disk or database
        }
        _cache.Clear();
    }

    private void LogError(Exception ex)
    {
        // log the error using your preferred logging mechanism
    }
}
