#define MAX_ALLOCATED 1000 // configurable limit on maximum number of structures

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int total_allocated = 0;
int total_processed = 0;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER; // thread-safe lock for concurrent access

// Function to allocate and populate structures
NFAPI_CRC_INDICATION_PDU_T** allocate_and_populate(int num_structures) {
    NFAPI_CRC_INDICATION_PDU_T** allocated_structures;
    int i;

    if (num_structures > MAX_ALLOCATED) {
        printf("Error: Exceeding the maximum allowed number of structures.\n");
        return NULL;
    }

    pthread_mutex_lock(&allocation_lock);

    // Dynamically allocate memory for array of NFAPI_CRC_INDICATION_PDU_T structures
    allocated_structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!allocated_structures) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    total_allocated += num_structures;

    for (i = 0; i < num_structures; i++) {
        allocated_structures[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!allocated_structures[i]) {
            printf("Error: Memory allocation failed.\n");
            for (int j = 0; j < i; j++) {
                free(allocated_structures[j]);
            }
            free(allocated_structures);
            pthread_mutex_unlock(&allocation_lock);
            return NULL;
        }

        // Initialize structure fields with random CRCFLAG values
        allocated_structures[i]->RX_UE_INFORMATION_TAG = rand();
        allocated_structures[i]->RNTI = rand();
        allocated_structures[i]->CRCFLAG = (rand() % 2);

        total_processed++;
    }

    pthread_mutex_unlock(&allocation_lock);
    return allocated_structures;
}

// Function to serialize allocated structures into binary format
int serialize(NFAPI_CRC_INDICATION_PDU_T** structures, char* file_path) {
    FILE* file = fopen(file_path, "wb");
    if (!file) {
        printf("Error: Unable to open file for writing.\n");
        return -1;
    }

    for (int i = 0; i < total_allocated; i++) {
        // Serialize only successfully allocated and processed structures
        if (structures[i]) {
            fwrite(&structures[i]->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
            fwrite(&structures[i]->RNTI, sizeof(int), 1, file);
            fwrite(&structures[i]->CRCFLAG, sizeof(int), 1, file);
        }
    }

    fclose(file);
    return 0;
}

// Function to deserialize binary data into array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** deserialize(char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        printf("Error: Unable to open file for reading.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** deserialized_structures;

    int num_structures = 0;
    while (fread(&num_structures->RX_UE_INFORMATION_TAG, sizeof(int), 1, file) == 1) {
        num_structures++;
    }

    fclose(file);

    deserialized_structures = allocate_and_populate(num_structures);
    for (int i = 0; i < num_structures; i++) {
        // Validate deserialization
        assert(deserialized_structures[i]->RX_UE_INFORMATION_TAG != -1);
    }

    return deserialized_structures;
}
