    size_t memory_size;
    int num_elements;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->memory_block = malloc(size);
    if (!pool->memory_block) {
        free(pool);
        return NULL;
    }
    pool->memory_size = size;
    pool->num_elements = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void* allocate_element(MemoryPool* pool, size_t size) {
    void* element = (void*)((size_t)pool->memory_block + (pool->num_elements * size));
    if (!element) {
        // Handle out-of-memory condition
        printf("Out of memory!\n");
        return NULL;
    }
    return element;
}

void deallocate_element(MemoryPool* pool, void* element) {
    // Update the number of elements and reset the pointer
    pool->num_elements--;
    ((size_t*)element)[0] = 0; // Zero out the memory to prevent leaks
}

LTE_PHY_RX_FRAME_INFO_T* create_lte_phy_rx_frame_info(MemoryPool* pool) {
    LTE_PHY_RX_FRAME_INFO_T* frame_info = allocate_element(pool, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (!frame_info) return NULL;
    // Validate the structure
    return frame_info;
}

