#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define RECORDS_PER_POOL 128
#define POOL_SIZE 1024
#define MAX_RECORDS 10000

typedef struct {
    long offset;
    int key;
    int field;
} record;

record *records = NULL;
int records_size = 0;
int records_max_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = fopen("app.log", "a");

void record_log(record *r) {
    fprintf(log_file, "[%ld] Created record: key=%d, field=%d\n", r->offset, r->key, r->field);
    fflush(log_file);
}

record *create_records(int num_records) {
    int pool_size = (num_records / RECORDS_PER_POOL + 1) * POOL_SIZE;
    void *pool = malloc(pool_size);

    record *records_pool = (record *)pool;
    for (int i = 0; i < pool_size / sizeof(record); i++) {
        records_pool[i].offset = rand();
        do {
            records_pool[i].key = rand() % INT_MAX;
        } while (records_size && find_key(&records[0], records_size, records_pool[i].key));
        records_pool[i].field = (records_pool[i].offset & 1) ? rand() : -rand();
    }

    record *new_records = NULL;
    int new_size = 0;

    if (records) {
        pthread_mutex_lock(&lock);
        try {
            for (int i = 0; i < records_size; i++) {
                if (find_key(records, records_size, records_pool[i].key)) {
                    i--;
                    continue;
                }
                record *r = &records[i];
                new_records = realloc(new_records, (new_size + 1) * sizeof(record));
                new_records[new_size++] = *r;
            }
        } catch (...) {
            free(pool);
            return NULL;
        } finally {
            pthread_mutex_unlock(&lock);
        }
    }

    for (int i = 0; i < pool_size / sizeof(record); i++) {
        record *r = &records_pool[i];
        if (!new_records || new_size >= records_max_size) {
            r->field = rand();
            record_log(r);
            return r;
        }
        new_records = realloc(new_records, (new_size + 1) * sizeof(record));
        new_records[new_size++] = *r;
    }

    free(pool);
    for (int i = 0; i < new_size; i++) {
        if (!find_key(records_pool, pool_size / sizeof(record), new_records[i].key)) {
            return NULL;
        }
    }

    return records;
}

void destroy_records() {
    pthread_mutex_lock(&lock);
    try {
        for (int i = 0; i < records_size; i++) {
            record *r = &records[i];
            r->field = -1;
        }
    } catch (...) {
        return;
    } finally {
        pthread_mutex_unlock(&lock);
    }
}

int find_key(record *records, int size, int key) {
    for (int i = 0; i < size; i++) {
        if (records[i].key == key) {
            return i;
        }
    }
    return -1;
}
