}

void *aligned_alloc(size_t size, int alignment) {
    size_t aligned_size = (size + alignment - 1) / alignment * alignment;
    void *ptr = valloc(aligned_size);
    if (!ptr) {
        printf("Error: unable to allocate memory.\n");
        exit(1);
    }
    return ptr;
}

