std::vector<Record> allocateAndInitializeRecords(int maxRecords, int minThreshold, int maxThreshold) {
    std::vector<Record> records;

    // Calculate the number of records based on input parameters
    int numRecords = (maxRecords > 0) ? static_cast<int>(std::rand() / (RAND_MAX / maxRecords)) : 0;

    if (numRecords < minThreshold) {
        numRecords = minThreshold;
    } else if (numRecords > maxThreshold) {
        numRecords = maxThreshold;
    }

    // Allocate and initialize the record array
    records.resize(numRecords);

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> dis(0, 100);

    for (int i = 0; i < numRecords; ++i) {
        Record& record = records[i];
        record.value = dis(gen);
    }

    return records;
}

