    std::vector<int> keys(numKeys);

    for (int i = 0; i < numKeys; ++i) {
        keys[i] = static_cast<int>(std::rand() % 100);
    }

    return {offsetValues, keys};
}

// Function to validate memory usage and prevent resource exhaustion
void validateMemoryUsage(const std::vector<std::pair<long, int>>& arrays, const std::vector<Record>& records) {
    // Check if memory usage stays within specified bounds
    if (arrays.size() + records.size() > maxAllowedMemoryUsage) {
        throw std::runtime_error("Memory usage exceeded maximum allowed limit.");
    }
}

