    srand(time(NULL));
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < n; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        do {
            (*list)[i].RNTI = rand() % 1000 + 1;
        } while (findDuplicateRNTI(*list, i));
    }

    return 0;
}

int findDuplicateRNTI(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if ((*list)[i].RNTI == (*list)[j].RNTI)
                return 1;
        }
    }
    return 0;
}

void freeNFAPIList(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    free(list);
}
