int lte_rrc_pdu_array_manager(int max_size, int* num_elements) {
    // Allocate memory for the array and its metadata
    *num_elements = 0;
    LTE_RRC_PDU** arr = (LTE_RRC_PDU**)malloc(max_size * sizeof(LTE_RRC_PDU*));

    if (!arr) {
        return -1; // Memory allocation failed
    }

    // Initialize the first element to prevent garbage values
    arr[0] = (LTE_RRC_PDU*)malloc(sizeof(LTE_RRC_PDU));
    memset(arr[0], 0, sizeof(LTE_RRC_PDU));

    // Function for managing array operations:
    int lte_rrc_pdu_array_ops(int operation) {
        int i;
        switch (operation) {
            case ADD_ELEMENT:
                if (*num_elements < max_size) {
                    LTE_RRC_PDU* new_pdu = (LTE_RRC_PDU*)malloc(sizeof(LTE_RRC_PDU));
                    arr[*num_elements] = new_pdu;
                    *num_elements += 1;
                } else {
                    // Truncate the array when exceeding the maximum size
                    for (i = max_size - 1; i >= 0; i--) {
                        free(arr[i]);
                    }
                    *num_elements = max_size;
                }
                break;

            case REMOVE_ELEMENT:
                if (*num_elements > 0) {
                    for (i = 0; i < *num_elements - 1; i++) {
                        arr[i] = arr[i + 1];
                    }
                    free(arr[*num_elements - 1]);
                    *num_elements -= 1;
                } else {
                    // Return error if no elements to remove
                    return -2;
                }
                break;

            case GET_ELEMENT:
                if (*num_elements > 0) {
                    return arr[*num_elements - 1];
                } else {
                    // Return NULL if the array is empty
                    return NULL;
                }
                break;

            default:
                // Return error for invalid operations
                return -3;
        }

        return 0; // Successful operation
    }
