#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a record structure
typedef struct {
    int key;
    long offset;
} Record;

// Function to generate random numbers with unique frequency tracking
int generate_random(int min, int max) {
    static int last_value = -1;
    static int freq[100] = {0};
    for (int i = 0; i < 100; i++) {
        if (freq[i] > 0 && rand() % 100 == i) {
            return i;
        }
    }
    srand((unsigned) time(NULL));
    for (int i = 0; i < 100; i++) {
        if (rand() % 100 == i) {
            freq[i]++;
            return i;
        }
    }
    return last_value + 1;
}

// Function to create and persist records
void* create_records(void* arg) {
    int num_records = *(int*)arg;
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        records[i].key = generate_random(1, 100);
        records[i].offset = (long)rand() % 2147483647;
    }
    // Validate offset values
    long* offsets = (long*)malloc(num_records * sizeof(long));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = records[i].offset;
    }
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (offsets[i] == offsets[j]) {
                printf("Duplicate offset found!\n");
                exit(1);
            }
        }
    }
    free(offsets);

    // Integrate with external data storage system
    FILE* file = fopen("records.txt", "w+");
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }
    fclose(file);
    free(records);
    return NULL;
}

// Function to handle errors and retries
void* handle_errors(void* arg) {
    int num_records = *(int*)arg;
    while (1) {
        void* result = create_records(arg);
        if (result != NULL) {
            free(result);
            break;
        }
    }
    return NULL;
}

// Main function
int main(int argc, char** argv) {
    int num_records = atoi(argv[1]);

    // Start a separate thread to handle record creation and persistence
    pthread_t thread;
    pthread_create(&thread, NULL, &handle_errors, &num_records);
    pthread_join(thread, NULL);

    return 0;
}
