#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure to represent LTE UE Context Information PDU
typedef struct {
    int ue_id;
    pthread_mutex_t rnti_lock; // Lock for updating RNTIs
    pthread_rwlock_t snr_mcs_lock; // Lock for reading SNRs and MCSes
    int* rntis;
    float** snrs;
    int** mcses;
} lte_ue_context;

// Structure to represent dynamic list of LTE UE contexts
typedef struct {
    lte_ue_context* contexts;
    pthread_mutex_t lock; // Lock for updating the context list
    size_t size;
    size_t capacity;
} lte_ue_context_list;

// Function to initialize an LTE UE context list
lte_ue_context_list* init_lte_ue_context_list(size_t initial_capacity) {
    lte_ue_context_list* list = malloc(sizeof(lte_ue_context_list));
    list->contexts = malloc(initial_capacity * sizeof(lte_ue_context));
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

// Function to add a new LTE UE context to the dynamic list
int add_lte_ue_context(lte_ue_context_list* list, int ue_id) {
    if (list->size >= list->capacity) {
        // Reallocate memory with double capacity
        list->contexts = realloc(list->contexts, 2 * list->capacity * sizeof(lte_ue_context));
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_init(&list->contexts[list->size].rnti_lock, NULL);
        pthread_rwlock_init(&list->contexts[list->size].snr_mcs_lock, NULL);
        list->capacity *= 2;
    }

    // Initialize new context
    lte_ue_context* new_ctx = &list->contexts[list->size++];
    new_ctx->ue_id = ue_id;
    new_ctx->rntis = malloc(sizeof(int));
    new_ctx->snrs = malloc(sizeof(float*));
    new_ctx->mcses = malloc(sizeof(int*));

    return 0; // Success
}

// Function to update the RNTIs of an existing LTE UE context
int update_rnti(lte_ue_context_list* list, int ue_id, int rnti) {
    pthread_mutex_lock(&list->contexts[ue_id].rnti_lock);
    // Update the RNTI here
    pthread_mutex_unlock(&list->contexts[ue_id].rnti_lock);

    return 0; // Success
}

// Function to retrieve context information based on UE ID
int get_context_info(lte_ue_context_list* list, int ue_id) {
    pthread_rwlock_rdlock(&list->contexts[ue_id].snr_mcs_lock);
    // Read SNRs and MCSes here
    pthread_rwlock_unlock(&list->contexts[ue_id].snr_mcs_lock);

    return 0; // Success
}

// Function to destroy an LTE UE context list
void free_lte_ue_context_list(lte_ue_context_list* list) {
    for (size_t i = 0; i < list->size; i++) {
        pthread_mutex_unlock(&list->contexts[i].rnti_lock);
        pthread_rwlock_destroy(&list->contexts[i].snr_mcs_lock);
        free(list->contexts[i].rntis);
        free(list->contexts[i].snrs);
        free(list->contexts[i].mcsecs);
    }

    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
