typedef struct {
    uint64_t ue_id;
    int num_pdus;
    struct MAC_PDU_T** pdus;
} MAC_RX_CONTEXT;

void init_mac_rx_context_list(int size, MAC_RX_CONTEXT** list) {
    *list = (MAC_RX_CONTEXT*)calloc(size, sizeof(MAC_RX_CONTEXT));
}

int insert_pdu(MAC_RX_CONTEXT* ctx, uint64_t ue_id, struct MAC_PDU_T* pdu) {
    int i;
    for (i = 0; i < ctx->num_pdus; i++) {
        if (ctx->pdus[i]->ue_id == ue_id) {
            // PDU already exists for this UE_ID
            return -1;
        }
    }
    ctx->pdus = (struct MAC_PDU_T**)realloc(ctx->pdus, (ctx->num_pdus + 1) * sizeof(struct MAC_PDU_T*));
    ctx->pdus[ctx->num_pdus] = pdu;
    ctx->num_pdus++;
    return 0;
}

int remove_pdu(MAC_RX_CONTEXT* ctx, uint64_t ue_id) {
    int i;
    for (i = 0; i < ctx->num_pdus; i++) {
        if (ctx->pdus[i]->ue_id == ue_id) {
            // Found PDU to be removed
            memmove(&ctx->pdus[i], &ctx->pdus[i + 1], (ctx->num_pdus - i - 1) * sizeof(struct MAC_PDU_T*));
            ctx->num_pdus--;
            return 0;
        }
    }
    // PDU not found
    return -1;
}

void free_mac_rx_context_list(MAC_RX_CONTEXT** list, int size) {
    int i;
    for (i = 0; i < size; i++) {
        if ((*list)[i].num_pdus > 0) {
            // Free PDUs first
            int j;
            for (j = 0; j < (*list)[i].num_pdus; j++) {
                free((*list)[i].pdus[j]);
            }
            free((*list)[i].pdus);
        }
    }
    free(*list);
}
