    int* keys = (int*)malloc(num_keys * sizeof(int));

    // Initialize the arrays
    for (size_t i = 0; i < num_keys; ++i) {
        offsets[i] = i * (long)num_keys;
        keys[i] = i;
    }

    Record* head = NULL;

    // Allocate memory for and initialize an array of 'record' structures
    size_t max_records = 100;  // You can adjust this number as needed
    Record** records = (Record**)malloc(max_records * sizeof(Record*));

    // Initialize the array with null pointers
    for (size_t i = 0; i < max_records; ++i) {
        records[i] = NULL;
    }

    size_t total_records = 0;

    // Populate the 'record' structures with random integer values
    for (int i = 0; i < num_keys; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->key = get_unique_key(num_keys);
        record->offset = offsets[i];
        records[total_records++] = record;
    }

    // Free the arrays
    free(offsets);
    free(keys);

    return head;
}

void record_free(Record* head) {
    while (head != NULL) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
}

int get_unique_key(int max_key) {
    // Generate random integer values
    srand(time(NULL));
    int key;

    do {
        key = rand() % max_key;
    } while (key == 0);

    return key;
