int create_nfapi_crc_indication_pdu_array(size_t n, uint32_t seed, size_t max_memory_threshold) {
    if (n == 0 || seed > UINT_MAX || max_memory_threshold == 0) {
        return -1; // Invalid configuration
    }

    NFAPI_CRC_INDICATION_PDU_T* puds = NULL;
    size_t total_elements = 0;

    for (size_t i = 0; i < n; i++) {
        size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        size_t max_memory_usage = i * element_size + sizeof(puds);

        if (max_memory_usage > max_memory_threshold) {
            // Reached memory threshold, reduce the number of elements
            total_elements = max_memory_threshold / element_size;
            break;
        }

        puds = realloc(puds, (total_elements + 1) * element_size);
        if (!puds) {
            // Memory allocation failed, log error and return -1
            fprintf(stderr, "Memory allocation failure\n");
            free(puds);
            return -1;
        }

        total_elements++;

        puds[total_elements - 1].RX_UE_INFORMATION_TAG = ...; // Initialize structure fields
        puds[total_elements - 1].RNTI = ...;
        puds[total_elements - 1].CRC_INDICATION_REL8_TAG = ...;

        // Randomly generate CRCFLAG based on the provided seed
        srand(seed);
        puds[total_elements - 1].CRCFLAG = rand();
    }

    if (puds) {
        for (size_t i = 0; i < total_elements; i++) {
            printf("Struct %zu: RX_UE_INFORMATION_TAG=0x%x, RNTI=%u, CRC_INDICATION_REL8_TAG=0x%x, CRCFLAG=%u\n",
                   i, puds[i].RX_UE_INFORMATION_TAG, puds[i].RNTI, puds[i].CRC_INDICATION_REL8_TAG, puds[i].CRCFLAG);
        }
    }

    return total_elements;
}
