typedef struct {
    uint64_t ue_id;
    int num_pdu;
    MAC_PDU_T** pdus;
} MAC_RX_CONTEXT;

void init_mac_rx_context_list(int num_ue_ids, int max_pdu_size) {
    // Initialize the list of UE_IDs
    MAC_RX_CONTEXT* ue_ids = (MAC_RX_CONTEXT*)malloc(num_ue_ids * sizeof(MAC_RX_CONTEXT));

    // Initialize each UE_ID with a dynamic number of associated PDUs
    for (int i = 0; i < num_ue_ids; i++) {
        ue_ids[i].num_pdu = 0;
        ue_ids[i].pdus = (MAC_PDU_T**)malloc(max_pdu_size * sizeof(MAC_PDU_T*));
    }

    // Initialize the list of MAC_RX_CONTEXT structures
    MAC_RX_CONTEXT* mac_rx_context_list = (MAC_RX_CONTEXT*)malloc(num_ue_ids * sizeof(MAC_RX_CONTEXT));

    for (int i = 0; i < num_ue_ids; i++) {
        mac_rx_context_list[i] = ue_ids[i];
    }

    // Free the allocated memory
    free(ue_ids);
}

void add_pdu_to_ue_id(uint64_t ue_id, MAC_PDU_T* pdu) {
    // Find the corresponding UE_ID in the list
    MAC_RX_CONTEXT* ue_id_entry = NULL;
    for (int i = 0; i < num_ue_ids; i++) {
        if (ue_id == mac_rx_context_list[i].ue_id) {
            ue_id_entry = &mac_rx_context_list[i];
            break;
        }
    }

    // Add the PDU to the UE_ID's list
    if (ue_id_entry != NULL && ue_id_entry->num_pdu < max_pdu_size) {
        ue_id_entry->pdus[ue_id_entry->num_pdu++] = pdu;
    } else {
        // Handle error: PDU limit exceeded for this UE_ID
        printf("Error: PDU limit exceeded for UE_ID %lu\n", ue_id);
    }
}

void remove_pdu_from_ue_id(uint64_t ue_id, MAC_PDU_T* pdu) {
    // Find the corresponding UE_ID in the list
    MAC_RX_CONTEXT* ue_id_entry = NULL;
    for (int i = 0; i < num_ue_ids; i++) {
        if (ue_id == mac_rx_context_list[i].ue_id) {
            ue_id_entry = &mac_rx_context_list[i];
            break;
        }
    }

    // Remove the PDU from the UE_ID's list
    if (ue_id_entry != NULL && ue_id_entry->num_pdu > 0) {
        for (int i = 0; i < ue_id_entry->num_pdu; i++) {
            if (ue_id_entry->pdus[i] == pdu) {
                memmove(ue_id_entry->pdus + i, ue_id_entry->pdus + i + 1, (ue_id_entry->num_pdu - i - 1) * sizeof(MAC_PDU_T*));
                ue_id_entry->num_pdu--;
                break;
            }
        }
    } else {
        // Handle error: PDU not found for UE_ID
        printf("Error: PDU not found for UE_ID %lu\n", ue_id);
    }
}

void free_mac_rx_context_list() {
    for (int i = 0; i < num_ue_ids; i++) {
        if (mac_rx_context_list[i].num_pdu > 0) {
            for (int j = 0; j < mac_rx_context_list[i].num_pdu; j++) {
                free(mac_rx_context_list[i].pdus[j]);
            }
            free(mac_rx_context_list[i].pdus);
        }
    }

    free(mac_rx_context_list);
}
