void process_nfaapi_and_find_max() {
    FILE *error_log = fopen("error_log.txt", "w");

    if (fopen == NULL) {
        fprintf(error_log, "Error opening error log file.\n");
        return;
    }

    int N = 0;
    // Read RNTI values from external data source
    int RNTIs[MAX_ALLOCATED_MEMORY];

    // Initialize the memory pool for dynamic allocation
    void *memory_pool = malloc(MAX_ALLOCATED_MEMORY);

    NFAPI_CRC_INDICATION_PDU_T* nda = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*MAX_ALLOCATED_MEMORY);

    // Ensure each generated structure has a unique RNTI
    int rnti_index = 0;
    for (int i = 0; i < N; i++) {
        if (RNTIs[i] > N) {
            break;
