        nda[rnti_index].RX_UE_INFORMATION_TAG = 1;
        nda[rnti_index].RNTI = RNTIs[i];
        srand(time(NULL));
        nda[rnti_index].CRC_INDICATION_REL8_TAG = rand() % 2;
        nda[rnti_index].CRCFLAG = (rand() % 2) ? 1 : 0;

        rnti_index++;
    }

    // Read sequence of integers from standard input
    int n;
    scanf("%d", &n);

    int numbers[n];

    for (int i = 0; i < n; i++) {
        scanf("%d", &numbers[i]);
    }

    // Determine and return the largest integer in the array
    int max_integer = find_largest_integer(numbers, n);

    fclose(error_log);
}

int find_largest_integer(int* numbers, int n) {
    if (n == 0) {
        return -1;
    } else {
        int max = numbers[0];
        for (int i = 1; i < n; i++) {
            if (numbers[i] > max) {
                max = numbers[i];
            }
        }
        return max;
    }
}
